#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// MLX91219 sensitivity (mV/A)
#define MLX91219_SENSITIVITY 40.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the ADS1115
int ads1115_init()
{
    // Configuration register value
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write the configuration register
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t ads1115_read_adc()
{
    // Start a single conversion
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char read_buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    // Combine the two bytes to get the 16-bit ADC value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Function to calculate the current from the ADC value
float calculate_current(int16_t adc_value)
{
    // Convert ADC value to voltage (assuming +/-4.096V range)
    float voltage = (adc_value * 4.096) / 32768.0;

    // Calculate current using the MLX91219 sensitivity
    float current = (voltage - 2.048) / (MLX91219_SENSITIVITY / 1000.0);

    return current;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init() != 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = ads1115_read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        // Calculate current
        float current = calculate_current(adc_value);

        // Log current to console
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

