#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 4
#define FLAME_SENSOR_2 5
#define BUZZER 27

// Define I2C address for ADS1115
#define ADS1115_ADDR 0x48

// Define ADC channel for temperature sensor
#define TEMP_SENSOR_CHANNEL 0

// Define temperature thresholds
#define TEMP_THRESHOLD 60.0
#define TEMP_HYSTERESIS 55.0

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_flame_time_1 = 0;
static volatile unsigned long last_flame_time_2 = 0;
static volatile int flame_detected_1 = 0;
static volatile int flame_detected_2 = 0;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int read_flame_sensor(int gpio);
float read_temperature();
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void flame_detected_callback_1(int gpio, int level, unsigned int tick, void *user);
void flame_detected_callback_2(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to read flame sensor with debouncing
int read_flame_sensor(int gpio) {
    unsigned long current_time = gpioTick();
    if (gpio == FLAME_SENSOR_1) {
        if (flame_detected_1 == 0 && (current_time - last_flame_time_1) > DEBOUNCE_TIME * 1000) {
            flame_detected_1 = 1;
            last_flame_time_1 = current_time;
            return 1; // Flame detected
        } else if (flame_detected_1 == 1 && (current_time - last_flame_time_1) > DEBOUNCE_TIME * 1000) {
            flame_detected_1 = 0;
            return 0; // No flame
        } else {
            return 0; // Debouncing
        }
    } else if (gpio == FLAME_SENSOR_2) {
        if (flame_detected_2 == 0 && (current_time - last_flame_time_2) > DEBOUNCE_TIME * 1000) {
            flame_detected_2 = 1;
            last_flame_time_2 = current_time;
            return 1; // Flame detected
        } else if (flame_detected_2 == 1 && (current_time - last_flame_time_2) > DEBOUNCE_TIME * 1000) {
            flame_detected_2 = 0;
            return 0; // No flame
        } else {
            return 0; // Debouncing
        }
    }
    return 0; // Should not reach here
}

// Function to read temperature from ADS1115
float read_temperature() {
    unsigned char config[3];
    short adc_value;
    float voltage, temperature;
    int result;

    // Configure ADS1115 for single-shot mode, AIN0, ±4.096V, 128 SPS
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-shot, AIN0, ±4.096V, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (Default)

    result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        log_event("Error writing to I2C device.");
        return -100.0; // Indicate error
    }

    // Wait for conversion to complete (at least 8.5ms)
    gpioDelay(10); // Wait 10ms

    // Read ADC value
    unsigned char read_buffer[2];
    result = i2cReadDevice(i2c_handle, (char *)read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        log_event("Error reading from I2C device.");
        return -100.0; // Indicate error
    }

    adc_value = (read_buffer[0] << 8) | read_buffer[1];

    // Convert ADC value to voltage (assuming 3.3V reference)
    voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to temperature (linear mapping 0V-3.3V to 20°C-80°C)
    temperature = 20.0 + (voltage / 3.3) * 60.0;

    return temperature;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER, 1); // Set GPIO HIGH
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER, 0); // Set GPIO LOW
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Callback function for flame sensor 1
void flame_detected_callback_1(int gpio, int level, unsigned int tick, void *user) {
    if (level == 0) { // Falling edge detected
        read_flame_sensor(FLAME_SENSOR_1);
    }
}

// Callback function for flame sensor 2
void flame_detected_callback_2(int gpio, int level, unsigned int tick, void *user) {
    if (level == 0) { // Falling edge detected
        read_flame_sensor(FLAME_SENSOR_2);
    }
}

