    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);

    // Set pull-up resistors for flame sensors
    gpioSetPullUpDown(FLAME_SENSOR_1, PI_PUD_UP);
    gpioSetPullUpDown(FLAME_SENSOR_2, PI_PUD_UP);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register callback functions for flame sensors
    gpioSetAlertFuncEx(FLAME_SENSOR_1, flame_detected_callback_1, NULL);
    gpioSetAlertFuncEx(FLAME_SENSOR_2, flame_detected_callback_2, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read flame sensors
        flame1 = read_flame_sensor(FLAME_SENSOR_1);
        flame2 = read_flame_sensor(FLAME_SENSOR_2);

        // Read temperature
        temperature = read_temperature();

        if (temperature < -90.0) {
            // Error reading temperature, already logged in read_temperature()
        } else {
            // Check for fire condition
            if (flame1 && flame2 && temperature > TEMP_THRESHOLD) {
                log_event("Fire detected!");
                activate_buzzer();
                gpioDelay(2000); // Buzzer on for 2 seconds
                deactivate_buzzer();
            } else if (flame1 && flame2) {
                log_event("Flame detected!");
            } else if (temperature > TEMP_THRESHOLD) {
                char temp_str[50];
                snprintf(temp_str, sizeof(temp_str), "Temperature: %.2f\u00b0C", temperature);
                log_event(temp_str);
            } else if (temperature < TEMP_HYSTERESIS) {
                // Temperature below hysteresis, do nothing
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_buzzer();
    gpioSetAlertFuncEx(FLAME_SENSOR_1, NULL, NULL); // Deregister callback
    gpioSetAlertFuncEx(FLAME_SENSOR_2, NULL, NULL); // Deregister callback
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

