        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI command (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return ((double)adc_value / ADC_RESOLUTION) * VREF;
}

// Convert voltage to current
double voltage_to_current(double voltage, double sensitivity) {
    return (voltage / 1000.0) * (1000.0 / sensitivity);
}

// Control the cooling fan
int control_fan(double current, double threshold) {
    if (current > threshold) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
    return 0;
}

// Log data to file
int log_data(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage, sensitivity);

        control_fan(current, threshold);
        log_data(current);

        sleep(1); // Sample once per second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

