    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip logging this iteration
        }
        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        log_data(flame_detected, temperature);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close log file
    fclose(log_file);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

