#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define I2C addresses for the two microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define the register to read from (0x00)
#define ADC_REG 0x00

// Define the sampling interval (100ms)
#define SAMPLE_INTERVAL 100

// Define microphone sensitivity and reference pressure
#define MIC_SENSITIVITY -38.0 // dBV/Pa
#define REF_PRESSURE 20e-6    // Pa

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_microphone(int i2c_handle);
double convert_to_db(int raw_value);
double calculate_average(double db1, double db2);
void log_data(double average_db);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close the log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read data from a microphone
int read_microphone(int i2c_handle) {
    char buf[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, ADC_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to convert raw ADC value to dB
double convert_to_db(int raw_value) {
    // Convert raw value to voltage (assuming 16-bit ADC and 3.3V reference)
    double voltage = (double)raw_value / 65535.0 * 3.3;

    // Convert voltage to pressure (using microphone sensitivity)
    double pressure = pow(10, (voltage - 0.19) / 20.0); // 0.19V is the voltage at 1 Pa

    // Convert pressure to dB
    double db = 20 * log10(pressure / REF_PRESSURE);

    return db;
}

// Function to calculate the average dB value
double calculate_average(double db1, double db2) {
    return (db1 + db2) / 2.0;
}

// Function to log the data to a file
void log_data(double average_db) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, average_db);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both microphones
    i2c_handle1 = i2cOpen(1, MIC1_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, MIC2_ADDR, 0); // Bus 1, address 0x49, no flags
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read data from both microphones
        int raw_value1 = read_microphone(i2c_handle1);
        int raw_value2 = read_microphone(i2c_handle2);

        // Convert raw values to dB
        double db1 = (raw_value1 != -1) ? convert_to_db(raw_value1) : -999.0;
        double db2 = (raw_value2 != -1) ? convert_to_db(raw_value2) : -999.0;

        // Calculate the average dB value
        double average_db = calculate_average(db1, db2);

        // Log the data
        log_data(average_db);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

