#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CE0 8
#define SPI_CE1 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC parameters
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define ADC_MAX_VALUE 1023 // MCP3008 is 10-bit

// Define RMS threshold
#define RMS_THRESHOLD 0.7

// Define sampling parameters
#define SAMPLE_INTERVAL_MS 1
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_MS)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold audio data
typedef struct {
    float mic1_rms;
    float mic2_rms;
} AudioData;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_rms(int *samples, int num_samples);
void control_led(int on);
void log_data(AudioData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the RMS value
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Function to log data to a CSV file
void log_data(AudioData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, data.mic1_rms, data.mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize system
    if (initialize()) {
        return 1;
    }

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_index = 0;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC values
        int mic1_value = read_adc(ADC_CHANNEL_1);
        int mic2_value = read_adc(ADC_CHANNEL_2);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Store samples
        mic1_samples[sample_index] = mic1_value;
        mic2_samples[sample_index] = mic2_value;

        sample_index++;

        // Process data after collecting enough samples
        if (sample_index == NUM_SAMPLES) {
            // Calculate RMS values
            float mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
            float mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

            // Normalize RMS values
            mic1_rms /= ADC_MAX_VALUE;
            mic2_rms /= ADC_MAX_VALUE;

            // Check threshold and control LED
            if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
                control_led(1); // Turn on LED
                gpioDelay(500);  // Keep LED on for 500ms
                control_led(0); // Turn off LED
            }

            // Log data
            AudioData data = {mic1_rms, mic2_rms};
            log_data(data);

            // Reset sample index
            sample_index = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

