#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10 // Hz
#define SLEEP_TIME (1.0 / SAMPLE_RATE)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_adc(int channel);
float convert_to_current(int raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    // ADS1115 configuration register values
    unsigned char config[3];
    int16_t raw_value;

    // Configure ADS1115 for single-ended reading on the specified channel
    config[0] = 0x01; // Configuration register address
    config[1] = 0x40 | (channel << 1); // Single-ended, 4.096V, 128 SPS, start single conversion
    config[2] = 0x83; // Disable comparator, non-latching, alert/ready pin

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // 10 ms

    // Read the conversion result
    unsigned char read_buffer[2];
    if (i2cReadDevice(i2c_handle, (char *)read_buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    raw_value = (read_buffer[0] << 8) | read_buffer[1];

    // Sign extend if necessary
    if (raw_value & 0x8000) {
        raw_value |= 0xFFFF0000;
    }

    return raw_value;
}

// Convert raw ADC value to current (0-100A)
float convert_to_current(int raw_value) {
    // Assuming 0.5V to 4.5V corresponds to 0-100A
    // and 5V supply for the Raspberry Pi
    float voltage = (raw_value / 32767.0) * 5.0; // Assuming 16-bit ADC
    float current = (voltage - 0.5) * (100.0 / 4.0);
    return current;
}

// Update circular buffer with new current reading
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from the circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control the warning LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_adc(ADC_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED
        control_led(average_current);

        // Print current and average current (for debugging)
        printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);

        // Sleep for a short period
        gpioDelay(SLEEP_TIME * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

