#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define ID_REG 0x12
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define CLEAR_L 0x14
#define CLEAR_H 0x15
#define RED_L 0x16
#define RED_H 0x17
#define GREEN_L 0x18
#define GREEN_H 0x19
#define BLUE_L 0x1A
#define BLUE_H 0x1B
#define CSV_FILE "color_log.csv"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int write_csv_header();
int write_csv_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    // Set integration time
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, ATIME_REG, 0xFF);
        if (status == 0) break;
        fprintf(stderr, "Error writing ATIME register (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write ATIME register after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Set gain
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, CONTROL_REG, 0x01);
        if (status == 0) break;
        fprintf(stderr, "Error writing CONTROL register (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write CONTROL register after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Power on and enable ADC
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, ENABLE_REG, 0x03);
        if (status == 0) break;
        fprintf(stderr, "Error writing ENABLE register (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write ENABLE register after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(3000); // Wait 3ms after power-on

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 0;
    int status;
    char buf[8];

    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, CLEAR_L, buf, 8);
        if (status == 8) break;
        fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// Function to write CSV header
int write_csv_header() {
    csv_file = fopen(CSV_FILE, "r");
    if (csv_file == NULL) {
        // File doesn't exist, create it and write the header
        csv_file = fopen(CSV_FILE, "w");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file for writing: %s\n", CSV_FILE);
            return -1;
        }
        fprintf(csv_file, "timestamp,clear,red,green,blue\n");
    } else {
        fclose(csv_file);
    }
    return 0;
}

// Function to write CSV data
int write_csv_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file for appending: %s\n", CSV_FILE);
        return -1;
    }

    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fclose(csv_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, ID_REG);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if ((sensor_id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    if (write_csv_header() != 0) {
        fprintf(stderr, "Failed to write CSV header\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
