// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define MOISTURE1_CHANNEL 0
#define MOISTURE2_CHANNEL 1
#define LOG_FILE "moisture_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
void log_data(float moisture1, float moisture2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to CSV file
void log_data(float moisture1, float moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE_0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Moisture sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture values from sensors
        int adc_value1 = read_mcp3008(MOISTURE1_CHANNEL);
        int adc_value2 = read_mcp3008(MOISTURE2_CHANNEL);

        if (adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
        } else {
            // Convert ADC values to moisture percentages
            float moisture1 = map_adc_to_moisture(adc_value1);
            float moisture2 = map_adc_to_moisture(adc_value2);

            if (moisture1 == -1.0 || moisture2 == -1.0) {
                fprintf(stderr, "Error: Failed to map ADC values to moisture\n");
            } else {
                // Log the data
                log_data(moisture1, moisture2);
                printf("Moisture 1: %.2f%%, Moisture 2: %.2f%%\n", moisture1, moisture2);
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

