#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define SENSITIVITY 0.1 // V/A
#define OFFSET 0.05 // V
#define VREF 3.3 // Reference voltage
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void overcurrent_protection(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int motor_shutdown_pin;
    float overcurrent_threshold;
    float sensitivity;
    float offset;
    float vref;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    MOTOR_SHUTDOWN_PIN,
    OVERCURRENT_THRESHOLD,
    SENSITIVITY,
    OFFSET,
    VREF
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to current
float adc_to_current(int adc_value) {
    float voltage = ((float)adc_value / 1023.0) * VREF;
    float current = (voltage - OFFSET) / SENSITIVITY;
    return current;
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle overcurrent protection
void overcurrent_protection(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected: %.2f A\n", current);
        fprintf(log_file, "Overcurrent detected: %.2f A\n", current);
        fflush(log_file);
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Disable motor
        gpioDelay(1000); // Wait 1 second
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Enable motor
        printf("Motor re-enabled\n");
        fprintf(log_file, "Motor re-enabled\n");
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Enable motor initially

    // Open log file
    log_file = fopen("current_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float current = adc_to_current(adc_value);
            log_current(current);
            overcurrent_protection(current);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    cleanup();
    return 0;
}

