#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define PRESSURE_SCALE_FACTOR 500.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure_sensor(uint16_t *raw_pressure);
double convert_to_kPa(uint16_t raw_pressure);
char* get_iso8601_timestamp();
int log_pressure_data(const char *timestamp, double pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    double pressure_scale_factor;
    const char *log_file_name;
} config_t;

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure sensor with retries
int read_pressure_sensor(uint16_t *raw_pressure) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, PRESSURE_REGISTER);
        if (result >= 0) {
            *raw_pressure = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw pressure to kPa
double convert_to_kPa(uint16_t raw_pressure) {
    return ((double)raw_pressure / 65535.0) * PRESSURE_SCALE_FACTOR;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log pressure data to file
int log_pressure_data(const char *timestamp, double pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure;
        if (read_pressure_sensor(&raw_pressure) == 0) {
            double pressure_kPa = convert_to_kPa(raw_pressure);
            char *timestamp = get_iso8601_timestamp();

            if (timestamp != NULL) {
                if (log_pressure_data(timestamp, pressure_kPa) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to get timestamp.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure sensor.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

