#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int channel);
float convert_pressure(int adc_value);
float convert_temperature(int adc_value);
void control_led(float pressure);
void display_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_ads1115(int channel) {
    int config;
    int retries = 0;
    int result;

    // Configure ADS1115 for single-ended read
    switch (channel) {
        case 0:
            config = 0x4003; // Single-ended AIN0, +/-6.144V, 128 SPS, Disable comparator
            break;
        case 1:
            config = 0x5003; // Single-ended AIN1, +/-6.144V, 128 SPS, Disable comparator
            break;
        default:
            fprintf(stderr, "Invalid ADC channel: %d\n", channel);
            return -1;
    }

    // Write configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, buf, 3);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write error (config), retrying (%d/%d): %d\n", retries + 1, MAX_RETRIES, result);
        gpioDelay(10000); // 10ms delay
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write config register after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(10000); // Wait for conversion (at least 8ms for 128 SPS)

    // Read conversion register
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, (char[]){CONVERSION_REG}, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (conv reg), retrying (%d/%d): %d\n", retries + 1, MAX_RETRIES, result);
            gpioDelay(10000);
            retries++;
            continue;
        }

        char read_buf[2];
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result == 2) {
            int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
            return adc_value;
        } else {
            fprintf(stderr, "I2C read error (conv reg), retrying (%d/%d): %d\n", retries + 1, MAX_RETRIES, result);
            gpioDelay(10000);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read conversion register after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Convert ADC value to pressure (kPa)
float convert_pressure(int adc_value) {
    float voltage = (float)adc_value * 4.096f / 32768.0f; // Assuming 16-bit ADC
    return voltage * 400.0f / 5.0f;
}

// Convert ADC value to temperature (°C)
float convert_temperature(int adc_value) {
    float voltage = (float)adc_value * 4.096f / 32768.0f; // Assuming 16-bit ADC
    return (voltage - 1.0f) * 100.0f;
}

// Control the warning LED
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Display pressure and temperature data
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int pressure_adc = read_ads1115(0);
        int temperature_adc = read_ads1115(1);

        if (pressure_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying in 1 second...\n");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        float pressure = convert_pressure(pressure_adc);
        float temperature = convert_temperature(temperature_adc);

        display_data(pressure, temperature);
        control_led(pressure);

        gpioDelay(1000000); // 1 second delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

