#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SAMPLE_RATE 1 // Hz
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define VREF 4.096 // ADS1115 Vref
#define SENSITIVITY 0.1 // V/kPa
#define OFFSET 0.5 // V

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double pressure_min;
    double pressure_max;
    double vref;
    double sensitivity;
    double offset;
} Config;

// Function prototypes
int init_i2c(int bus, int addr);
int read_ads1115(int handle, int channel);
double convert_to_voltage(int raw_value, double vref);
double convert_to_pressure(double voltage, double sensitivity, double offset);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read from ADS1115
int read_ads1115(int handle, int channel) {
    // Configure ADS1115 for single-ended reading on the specified channel
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40 | (channel << 1); // Start single conversion, AINx, +/-4.096V
    config[2] = 0x83; // 128 SPS, disable comparator

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char buf[2];
    if (i2cReadI2CBlockData(handle, CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    // Combine the two bytes to get the 16-bit raw value
    int16_t raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Convert raw ADC value to voltage
double convert_to_voltage(int raw_value, double vref) {
    // ADS1115 is a 16-bit ADC, so the full range is 2^15
    double voltage = (raw_value / 32767.0) * vref;
    return voltage;
}

// Convert voltage to pressure (kPa)
double convert_to_pressure(double voltage, double sensitivity, double offset) {
    double pressure = (voltage - offset) / sensitivity;
    return pressure;
}

// Log pressure reading to file
int log_pressure(double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_ads1115(i2c_handle, 0); // Channel 0
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to voltage
        double voltage = convert_to_voltage(raw_value, VREF);

        // Convert to pressure
        double pressure = convert_to_pressure(voltage, SENSITIVITY, OFFSET);

        // Validate pressure range
        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            // Log pressure reading
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        // Wait for the next sample
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

