#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HUMIDITY_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define VREF 5.0
#define HUMIDITY_SLOPE 0.0315
#define HUMIDITY_INTERCEPT 0.824
#define BETA 3950.0
#define R0 10000.0
#define T0 298.15
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize();
int read_mcp3208(int channel);
float adc_to_voltage(int adc_value);
SensorData calculate_humidity_and_temperature(float voltage_humidity, float voltage_temperature);
int log_data(SensorData data);
int send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0) * VREF;
}

// Function to calculate humidity and temperature from voltage readings
SensorData calculate_humidity_and_temperature(float voltage_humidity, float voltage_temperature) {
    SensorData data;

    // Calculate humidity
    data.humidity = (voltage_humidity - HUMIDITY_INTERCEPT) / HUMIDITY_SLOPE;
    if (data.humidity < 0.0) data.humidity = 0.0;
    if (data.humidity > 100.0) data.humidity = 100.0;

    // Calculate temperature (using Steinhart-Hart equation for simplicity)
    float Rt = R0 * (VREF / voltage_temperature - 1.0);
    float inv_T = 1.0/T0 + (1.0/BETA) * log(Rt/R0);
    float T = 1.0/inv_T;
    data.temperature = T - 273.15; // Convert to Celsius

    return data;
}

// Function to log data to a file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.humidity, data.temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to send an email alert using ssmtp
int send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold at %s. Current humidity: %.2f%%\" | ssmtp %s", timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Failed to execute ssmtp command\n");
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Humidity and temperature monitoring started...\n");

    while (!terminate) {
        // Read ADC values
        int adc_humidity = read_mcp3208(HUMIDITY_CHANNEL);
        int adc_temperature = read_mcp3208(TEMPERATURE_CHANNEL);

        if (adc_humidity == -1 || adc_temperature == -1) {
            fprintf(stderr, "Failed to read ADC values, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC values to voltages
        float voltage_humidity = adc_to_voltage(adc_humidity);
        float voltage_temperature = adc_to_voltage(adc_temperature);

        // Calculate humidity and temperature
        SensorData data = calculate_humidity_and_temperature(voltage_humidity, voltage_temperature);

        // Log data
        log_data(data);

        // Check humidity threshold and send email alert
        if (data.humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(data.humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", data.humidity, data.temperature);

        sleep(5); // Read every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

