#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 8

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3208(int channel);
float adc_to_temperature(int adc_value);
int log_temperature(float temperature);
void signal_handler(int sig);
int gpio_init(void);
void gpio_release(void);

// SPI initialization function
int spi_init(void) {
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting max speed Hz");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error getting max speed Hz");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Assert CS line
    if (gpio_line) {
        int ret = gpiod_line_set_value(gpio_line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line value (CS low)");
            return -1;
        }
    }

    // Perform SPI transfer
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 1) {
        perror("Error during SPI transfer");
        if (gpio_line) {
            int gpio_ret = gpiod_line_set_value(gpio_line, 1);
            if (gpio_ret < 0) {
                perror("Error setting GPIO line value (CS high)");
            }
        }
        return -1;
    }

    // De-assert CS line
    if (gpio_line) {
        int ret = gpiod_line_set_value(gpio_line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line value (CS high)");
            return -1;
        }
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / 4095.0;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// Function to log temperature data to a file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file exists and is empty
    FILE *fp = fopen(LOG_FILE, "r");
    int is_new_file = 0;
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        is_new_file = 1;
    } else {
        fclose(fp);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (is_new_file) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    int ret = gpiod_line_request_output(gpio_line, "tmp36_reader", 1); // Request line as output and set initial value to high (inactive)
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
        return -1;
    }

    return 0;
}

// GPIO release function
void gpio_release(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed, continuing without GPIO control.\n");
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        gpio_release();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC value: %d, retrying in 1 second.\n", adc_value);
            sleep(1);
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Validate temperature range
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of range: %.2fC, retrying in 1 second.\n", temperature);
            sleep(1);
            continue;
        }

        // Log temperature data
        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Error logging temperature data.\n");
        }

        printf("Temperature: %.2fC\n", temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpio_release();

    printf("Exiting.\n");
    return 0;
}

