    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

