#define ERROR_FLAG_OK 0
#define ERROR_FLAG_READ_ERROR 1
#define ERROR_FLAG_SENSOR_ABSENT 2
#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t ir;
    uint16_t red;
} sensor_data_t;

// Function prototypes
int init_si1172();
int read_si1172(sensor_data_t *data);
void log_data(sensor_data_t data, int error_flag);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1172 sensor
int init_si1172() {
    // Placeholder for Si1172 initialization sequence
    // Replace with actual initialization commands from the datasheet
    // This is a simplified example
    char init_data[] = {0x01, 0x02, 0x03}; // Example initialization data
    int result;

    for (int i = 0; i < sizeof(init_data); ++i) {
        result = i2cWriteByteData(i2c_handle, CMD_REG, init_data[i]);
        if (result != 0) {
            fprintf(stderr, "Error writing to Si1172 during initialization: %d\n", result);
            return -1;
        }
        gpioDelay(1000); // Small delay after each write
    }

    return 0;
}

// Read data from the Si1172 sensor
int read_si1172(sensor_data_t *data) {
    char buffer[4];
    int result;

    // Trigger measurement by writing to the command register
    result = i2cWriteByte(i2c_handle, CMD_REG);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return ERROR_FLAG_READ_ERROR;
    }
    gpioDelay(1000); // Small delay after triggering measurement

    // Read 4 bytes from the FIFO register
    result = i2cReadI2CBlockData(i2c_handle, FIFO_REG, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return ERROR_FLAG_READ_ERROR;
    }

    // Extract IR and RED values from the buffer
    data->ir = (buffer[0] << 8) | buffer[1];
    data->red = (buffer[2] << 8) | buffer[3];

    return ERROR_FLAG_OK;
}

