        gpioTerminate();
        return 1;
    }

    // Initialize the Si1172 sensor
    if (init_si1172() != 0) {
        fprintf(stderr, "Si1172 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,HR (bpm),SpO2 (%%),error_flag\n");
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    int error_flag;

    // Main loop
    while (!terminate) {
        error_flag = read_si1172(&sensor_data);
        log_data(sensor_data, error_flag);
        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    return 0;
}

