#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define MEASURE_CMD_MSB (MEASURE_CMD >> 8)
#define MEASURE_CMD_LSB (MEASURE_CMD & 0xFF)
#define DATA_LENGTH 6

// Calibration parameters (replace with actual values from sensor EEPROM)
#define SENSITIVITY 0.01  // Example sensitivity
#define OFFSET 0.0       // Example offset

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
sensor_data_t convert_data(const unsigned char *data);
int log_data(sensor_data_t data);
void display_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement function
int trigger_measurement() {
    char cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert data function
sensor_data_t convert_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    // Extract raw pressure and temperature values (adjust based on sensor datasheet)
    int raw_pressure = (data[0] << 8) | data[1];
    int raw_temperature = (data[3] << 8) | data[4];

    // Apply calibration formulas (replace with actual formulas from datasheet)
    sensor_data.pressure = raw_pressure * SENSITIVITY + OFFSET;
    sensor_data.temperature = raw_temperature * SENSITIVITY + OFFSET;

    return sensor_data;
}

// Log data function
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Display data function
void display_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data.temperature, data.pressure);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Initialize I2C
        if (initialize_i2c() != 0) {
            fprintf(stderr, "I2C initialization failed. Retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed. Retrying in 5 seconds...\n");
            i2cClose(i2c_handle);
            sleep(5);
            continue;
        }

        // Wait for conversion (adjust delay based on sensor datasheet)
        gpioDelay(100000); // 100ms

        // Read sensor data
        unsigned char data[DATA_LENGTH];
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor data read failed. Retrying in 5 seconds...\n");
            i2cClose(i2c_handle);
            sleep(5);
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Display data
        display_data(sensor_data);

        // Close I2C connection
        i2cClose(i2c_handle);

        // Wait before next sample
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

