#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Global variables
int spi_handle;
double gain = 1.0; // Default gain

// Function prototypes
int read_mcp3008(int channel);
int *subtract_audio_streams(int *stream1, int *stream2, int length);
void print_csv(int *data, int length);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to subtract two audio streams
int *subtract_audio_streams(int *stream1, int *stream2, int length) {
    int *result = malloc(length * sizeof(int));
    if (result == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < length; i++) {
        result[i] = (int)((stream1[i] - stream2[i]) * gain);
    }

    return result;
}

// Function to print data in CSV format
void print_csv(int *data, int length) {
    for (int i = 0; i < length; i++) {
        printf("%d", data[i]);
        if (i < length - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        printf("Using gain: %f\n", gain);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read audio data from microphones
        int mic1_value = read_mcp3008(MCP3008_CHANNEL_0);
        int mic2_value = read_mcp3008(MCP3008_CHANNEL_1);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error: Failed to read from microphones\n");
            continue; // Skip to the next iteration
        }

        // Subtract audio streams
        int *subtracted_stream = subtract_audio_streams(&mic1_value, &mic2_value, 1);
        if (subtracted_stream == NULL) {
            fprintf(stderr, "Error: Failed to subtract audio streams\n");
            continue; // Skip to the next iteration
        }

        // Print CSV output
        print_csv(subtracted_stream, 1);

        // Free allocated memory
        free(subtracted_stream);

        // Delay for a short period
        gpioDelay(1000); // 1 ms
    }

    // Cleanup (this part will not be reached in the infinite loop)
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

