void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to read temperature from file
float read_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open temperature file %s, using default 25.0°C\n", TEMP_FILE);
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Warning: Invalid temperature in file %s, using default 25.0°C\n", TEMP_FILE);
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

// Function to compensate voltage with temperature
float compensate_voltage(int raw_adc, float temperature) {
    float voltage = (float)raw_adc * 3.3 / 1024.0;
    return voltage + (temperature - 25.0) * 0.001;
}

