    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_adc = -1;
        int retries = 0;

        // Retry reading ADC value up to MAX_RETRIES times
        while (retries < MAX_RETRIES) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break; // Success
            } else {
                fprintf(stderr, "Error: Invalid ADC value: %d, retrying (%d/%d)\n", raw_adc, retries + 1, MAX_RETRIES);
                fprintf(log_file, "Error: Invalid ADC value: %d, retrying (%d/%d)\n", raw_adc, retries + 1, MAX_RETRIES);
                fflush(log_file);
                gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer during retries
                gpioDelay(100); // Small delay before retry
                retries++;
            }
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
            fprintf(log_file, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
            fflush(log_file);
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            gpioDelay(500); // Wait before next iteration
            continue; // Skip to next iteration
        }

        float temperature = read_temperature();
        float compensated_voltage = compensate_voltage(raw_adc, temperature);
        int flame_detected = is_flame_detected(compensated_voltage);

        control_buzzer(flame_detected);
        log_data(raw_adc, (float)raw_adc * 3.3 / 1024.0, compensated_voltage, temperature, flame_detected);

        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    fclose(log_file);
    gpioTerminate();

    return 0;
}

