int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Config byte
    tx[2] = 0x00; // Padding

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        pigpio_error(result); // Log the error
        return -1; // Indicate error
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

