        fprintf(stderr, "Error: Failed to open water_levels.json\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket to JSON file
    fprintf(json_file, "[\n");
    fflush(json_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
