#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_frequency;
    char *email_recipient;
    char *msmtp_config;
} Config;

// Global variables
int spi_handle;
FILE *log_file;
Config config;

// Function prototypes
int read_adc(int channel);
float calculate_moisture(int raw_value, int min_raw, int max_raw);
void log_data(float moisture_percent);
void send_email_alert(float moisture_percent);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], Config *config);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (max_raw == min_raw) {
        fprintf(stderr, "Error: Invalid calibration values (max_raw == min_raw)\n");
        return -1.0;
    }

    float moisture_percent = 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0);
    if (moisture_percent < 0.0) moisture_percent = 0.0;
    if (moisture_percent > 100.0) moisture_percent = 100.0;
    return moisture_percent;
}

// Function to log data to file
void log_data(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Plant moisture is below threshold!\\nTimestamp: %s\\nMoisture: %.2f%%\" | msmtp -C %s %s",
             timestamp, moisture_percent, config.msmtp_config, config.email_recipient);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command: %s\n", strerror(errno));
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], Config *config) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:f:e:s:")) != -1) {
        switch (opt) {
            case 'c':
                config->spi_channel = atoi(optarg);
                break;
            case 'a':
                config->adc_channel = atoi(optarg);
                break;
            case 'm':
                config->min_raw = atoi(optarg);
                break;
            case 'M':
                config->max_raw = atoi(optarg);
                break;
            case 't':
                config->moisture_threshold = atoi(optarg);
                break;
            case 'f':
                config->logging_frequency = atoi(optarg);
                break;
            case 'e':
                config->email_recipient = strdup(optarg);
                break;
            case 's':
                config->msmtp_config = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -c <spi_channel> -a <adc_channel> -m <min_raw> -M <max_raw> -t <moisture_threshold> -f <logging_frequency> -e <email_recipient> -s <msmtp_config>\n", argv[0]);
                return 1;
        }
    }

    // Validate required arguments
    if (config->email_recipient == NULL || config->msmtp_config == NULL) {
        fprintf(stderr, "Error: Email recipient and msmtp config file are required.\n");
        return 1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize configuration with default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    config.email_recipient = NULL;
    config.msmtp_config = NULL;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &config) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int raw_value = read_adc(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", config.logging_frequency);
            sleep(config.logging_frequency);
            continue;
        }

        float moisture_percent = calculate_moisture(raw_value, config.min_raw, config.max_raw);
        if (moisture_percent < 0.0) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage, retrying in %d seconds...\n", config.logging_frequency);
            sleep(config.logging_frequency);
            continue;
        }

        log_data(moisture_percent);

        if (moisture_percent < config.moisture_threshold) {
            send_email_alert(moisture_percent);
        }

        sleep(config.logging_frequency);
    }

    return 0;
}

