// Define pressure range
#define MIN_PRESSURE 10.0  // kPa
#define MAX_PRESSURE 150.0 // kPa

// Define voltage range
#define MIN_VOLTAGE 0.5   // V
#define MAX_VOLTAGE 4.5   // V

// Define ADC range
#define MIN_ADC 0
#define MAX_ADC 1023

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float min_pressure;
    float max_pressure;
    float min_voltage;
    float max_voltage;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    MIN_PRESSURE,
    MAX_PRESSURE,
    MIN_VOLTAGE,
    MAX_VOLTAGE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log pressure
        log_pressure(pressure);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    return (float)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Voltage out of range: %f\n", voltage);
        return -1.0; // Indicate an error
    }

    return (voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

// Function to log pressure with ISO 8601 timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

