#define PART_ID_REG 0xFF
#define EXPECTED_PART_ID 0x15
#define MODE_CONFIG_REG 0x06
#define RESET_COMMAND 0x40
#define SPO2_CONFIG_REG 0x08
#define SPO2_CONFIG_VALUE 0x27
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define LED_PA_VALUE 0x24
#define FIFO_DATA_REG 0x07
#define FIFO_SAMPLE_RATE 100 // Hz
#define SAMPLE_INTERVAL 1 // seconds
#define SPO2_THRESHOLD 95.0
#define HR_THRESHOLD 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int red[3];
    int ir[3];
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_spo2(const int *red, const int *ir);
int calculate_heart_rate(const int *ir);
void log_data(float spo2, int heart_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the MAX30102 sensor
int initialize_sensor() {
    int part_id;

    // Verify sensor presence
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 Part ID: 0x%02X\n", part_id);

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, RESET_COMMAND) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode\n");
        return -1;
    }

    // Configure SPO2 settings
    if (i2cWriteByteData(i2c_handle, SPO2_CONFIG_REG, SPO2_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error configuring SPO2 settings\n");
        return -1;
    }

    // Set LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, LED1_PA_REG, LED_PA_VALUE) < 0) {
        fprintf(stderr, "Error setting LED1 PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LED2_PA_REG, LED_PA_VALUE) < 0) {
        fprintf(stderr, "Error setting LED2 PA\n");
        return -1;
    }

    return 0;
}

// Read sensor data from the FIFO
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }

    // Extract red and IR values (3 bytes each)
    data->red[0] = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    data->ir[0] = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];

    return 0;
}

// Calculate SpO2 using the ratio-of-ratios method (simplified)
float calculate_spo2(const int *red, const int *ir) {
    // This is a placeholder.  A real implementation would use a more
    // sophisticated algorithm.
    float ratio = (float)ir[0] / (float)red[0];
    return 110.0 - (ratio * 10.0); // Dummy SpO2 calculation
}

// Calculate heart rate via peak detection on the IR signal (simplified)
int calculate_heart_rate(const int *ir) {
    // This is a placeholder.  A real implementation would use a more
    // sophisticated peak detection algorithm.
    return 70 + (ir[0] % 30); // Dummy heart rate calculation
}

// Log data to file
void log_data(float spo2, int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, SpO2: %.2f, HR: %d\n", timestamp, spo2, heart_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    if (spo2 < SPO2_THRESHOLD || heart_rate > HR_THRESHOLD) {
        fprintf(log_file, "%s, ALERT: SpO2: %.2f, HR: %d\n", timestamp, spo2, heart_rate);
        fflush(log_file);
    }
}

int main() {
    sensor_data_t sensor_data;
    float spo2;
    int heart_rate;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate SpO2 and heart rate
            spo2 = calculate_spo2(sensor_data.red, sensor_data.ir);
            heart_rate = calculate_heart_rate(sensor_data.ir);

            // Log data
            log_data(spo2, heart_rate);

            printf("SpO2: %.2f, HR: %d\n", spo2, heart_rate);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Clean up and exit
    cleanup();
    return 0;
}

