#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define RELAY_GPIO 17
#define REED_GPIO 27
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_DELAY_MS 50
#define TRIGGER_THRESHOLD_PERCENT 80
#define POLLING_INTERVAL_MS 200
#define RELAY_DURATION_S 3
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static double baseline_threshold = 0.0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_ads1115(int fd);
double calculate_baseline(int fd, int num_samples, int delay_ms);
double calculate_threshold(double baseline, int percent);
int control_relay(struct gpiod_line *line, int value);
int read_reed_sensor(struct gpiod_line *line);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Helper function to get current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

// I2C initialization function
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, REED_GPIO);
    if (!reed_line) {
        perror("Error getting reed sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(relay_line);
        relay_line = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_control", 0) < 0) {
        perror("Error requesting relay GPIO line for output");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(relay_line);
        relay_line = NULL;
        gpiod_line_release(reed_line);
        reed_line = NULL;
        return -1;
    }

    if (gpiod_line_request_input(reed_line, "door_control") < 0) {
        perror("Error requesting reed sensor GPIO line for input");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(relay_line);
        relay_line = NULL;
        gpiod_line_release(reed_line);
        reed_line = NULL;
        gpiod_line_release(relay_line);
        relay_line = NULL;
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int fd) {
    unsigned char config[3];
    int16_t raw_value;

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, single conversion
    config[0] = CONFIG_REG;
    config[1] = 0x43; // 0b01000011
    config[2] = 0x83; // 0b10000011

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    config[0] = CONVERSION_REG;
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];

    // The ADS1115 is a 16-bit ADC, but only 15 bits are used.  The sign bit is bit 15.
    // The value is right-aligned, so we need to sign-extend it.
    if (raw_value & 0x8000) {
        raw_value |= 0xFFFF0000; // Sign extend
    }

    return raw_value;
}

// Function to calculate the baseline
double calculate_baseline(int fd, int num_samples, int delay_ms) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int raw_value = read_ads1115(fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADS1115 in baseline calculation\n");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        usleep(delay_ms * 1000); // Delay in microseconds
    }
    return sum / num_samples;
}

// Function to calculate the trigger threshold
double calculate_threshold(double baseline, int percent) {
    return baseline * (percent / 100.0);
}

// Function to control the relay
int control_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting relay value");
        return -1;
    }
    return 0;
}

// Function to read the reed sensor
int read_reed_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading reed sensor value");
        return -1;
    }
    return value;
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    long long timestamp = get_timestamp_ms();
    fprintf(fp, "%lld: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // De-energize relay
    if (relay_line) {
        control_relay(relay_line, 0);
    }

    // Release GPIO lines
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (reed_line) {
        gpiod_line_release(reed_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Calculate baseline
    double baseline = calculate_baseline(i2c_fd, NUM_BASELINE_SAMPLES, BASELINE_DELAY_MS);
    if (baseline < 0) {
        fprintf(stderr, "Baseline calculation failed. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("Baseline: %.2f\n", baseline);

    // Calculate trigger threshold
    baseline_threshold = calculate_threshold(baseline, TRIGGER_THRESHOLD_PERCENT);
    printf("Threshold: %.2f\n", baseline_threshold);

    // Main loop
    while (!terminate) {
        int raw_value = read_ads1115(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADS1115 in main loop\n");
            log_event("Error reading ADS1115");
        } else {
            printf("Raw value: %d\n", raw_value);

            if (raw_value < baseline_threshold) {
                printf("Threshold exceeded!\n");
                log_event("Threshold exceeded");

                // Energize relay
                if (control_relay(relay_line, 1) < 0) {
                    log_event("Error controlling relay");
                } else {
                    log_event("Relay energized");
                    sleep(RELAY_DURATION_S);

                    // De-energize relay
                    if (control_relay(relay_line, 0) < 0) {
                        log_event("Error controlling relay");
                    } else {
                        log_event("Relay de-energized");

                        // Read reed sensor
                        int reed_value = read_reed_sensor(reed_line);
                        if (reed_value < 0) {
                            log_event("Error reading reed sensor");
                        } else {
                            if (reed_value == 0) {
                                log_event("Door opened");
                                printf("Door opened\n");
                            } else {
                                log_event("Door not opened");
                                printf("Door not opened\n");
                            }
                        }
                    }
                }
            }
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Poll every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

