#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL_SEC 5

// Global variables for signal handling
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs0_line = NULL;
static struct gpiod_line *cs1_line = NULL;
static struct gpiod_line *cs2_line = NULL;

// Function prototypes
int spi_init(int bus, int device, int speed);
int read_mcp3008(int spi_fd, int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
int gpio_init(int chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);

// SPI initialization function
int spi_init(int bus, int device, int speed) {
    char spi_device_path[20];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device_path, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = 0; // CPOL=0, CPHA=0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// MCP3008 reading function
int read_mcp3008(int spi_fd, int chip_select_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    // Activate chip select
    if (chip_select_pin == CS0_PIN) {
        gpio_set_value(cs0_line, 0);
    } else if (chip_select_pin == CS1_PIN) {
        gpio_set_value(cs1_line, 0);
    } else if (chip_select_pin == CS2_PIN) {
        gpio_set_value(cs2_line, 0);
    } else {
        fprintf(stderr, "Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        // Deactivate chip select
        if (chip_select_pin == CS0_PIN) {
            gpio_set_value(cs0_line, 1);
        } else if (chip_select_pin == CS1_PIN) {
            gpio_set_value(cs1_line, 1);
        } else if (chip_select_pin == CS2_PIN) {
            gpio_set_value(cs2_line, 1);
        }
        return -1;
    }

    // Deactivate chip select
    if (chip_select_pin == CS0_PIN) {
        gpio_set_value(cs0_line, 1);
    } else if (chip_select_pin == CS1_PIN) {
        gpio_set_value(cs1_line, 1);
    } else if (chip_select_pin == CS2_PIN) {
        gpio_set_value(cs2_line, 1);
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Data logging function
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// GPIO initialization function
int gpio_init(int chip, int pin) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip);

    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "soil_moisture_logger", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (pin == CS0_PIN) {
        cs0_line = line;
    } else if (pin == CS1_PIN) {
        cs1_line = line;
    } else if (pin == CS2_PIN) {
        cs2_line = line;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(0, CS0_PIN) < 0 ||
        gpio_init(0, CS1_PIN) < 0 ||
        gpio_init(0, CS2_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a+");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (keep_running) {
        int sensor1_value = -1, sensor2_value = -1, sensor3_value = -1;

        // Read sensor values
        sensor1_value = read_mcp3008(spi_fd, CS0_PIN, 0);
        sensor2_value = read_mcp3008(spi_fd, CS1_PIN, 0);
        sensor3_value = read_mcp3008(spi_fd, CS2_PIN, 0);

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpiod_line_release(cs0_line);
    gpiod_line_release(cs1_line);
    gpiod_line_release(cs2_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

