    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip);

    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "soil_moisture_logger", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (pin == CS0_PIN) {
        cs0_line = line;
    } else if (pin == CS1_PIN) {
        cs1_line = line;
    } else if (pin == CS2_PIN) {
        cs2_line = line;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(0, CS0_PIN) < 0 ||
        gpio_init(0, CS1_PIN) < 0 ||
        gpio_init(0, CS2_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a+");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (keep_running) {
        int sensor1_value = -1, sensor2_value = -1, sensor3_value = -1;

        // Read sensor values
        sensor1_value = read_mcp3008(spi_fd, CS0_PIN, 0);
        sensor2_value = read_mcp3008(spi_fd, CS1_PIN, 0);
        sensor3_value = read_mcp3008(spi_fd, CS2_PIN, 0);

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpiod_line_release(cs0_line);
    gpiod_line_release(cs1_line);
    gpiod_line_release(cs2_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

