#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_ADC_VALUE 200
#define WET_ADC_VALUE 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"

// Global variables
static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (channel %d), retries remaining: %d\n", channel, retries - 1);
            log_message("Error: SPI read failed");
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI read failed after multiple retries (channel %d)\n", channel);
    log_message("Error: SPI read failed after multiple retries");
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    float moisture = (float)(adc_value - DRY_ADC_VALUE) / (float)(WET_ADC_VALUE - DRY_ADC_VALUE) * 100.0;

    // Clamp moisture percentage to 0-100%
    if (moisture < 0.0) {
        moisture = 0.0;
    } else if (moisture > 100.0) {
        moisture = 100.0;
    }

    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    const char *message = (state == 1) ? "Pump activated" : "Pump deactivated";
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        log_message("Error: SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    printf("Soil moisture monitoring and irrigation system started.\n");
    printf("Threshold: %d%%, Duration: %d s, Sleep Interval: %d s\n", threshold, duration, sleep_interval);

    // Main loop
    while (!terminate) {
        // Read soil moisture from VH400 sensor (MCP3008 CH0)
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping irrigation cycle\n");
            log_message("Error: Failed to read ADC value, skipping irrigation cycle");
            gpioDelay(sleep_interval * 1000); // Sleep before next check
            continue;
        }

        // Convert ADC value to moisture percentage
        float moisture = adc_to_moisture(adc_value);

        // Log moisture reading
        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
        log_message(log_buffer);

        // Check if irrigation is needed
        if (moisture < threshold) {
            printf("Moisture level below threshold (%.2f%% < %d%%), activating pump for %d seconds\n", moisture, threshold, duration);
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Moisture level below threshold (%.2f%% < %d%%), activating pump for %d seconds", moisture, threshold, duration);
            log_message(log_message_buffer);

            // Activate pump
            control_pump(1);
            gpioDelay(duration * 1000); // Pump for specified duration

            // Deactivate pump
            control_pump(0);
        }

        // Sleep before next check
        gpioDelay(sleep_interval * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

