#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_ALPHA 0.1
#define THRESHOLD_MULTIPLIER 1.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema = 0.0;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_ema(int new_value, double current_ema);
double calculate_threshold(double ema);
int detect_peak(int raw_value, double ema, double threshold);
int log_event(int raw_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate EMA
double calculate_ema(int new_value, double current_ema) {
    return EMA_ALPHA * new_value + (1 - EMA_ALPHA) * current_ema;
}

// Function to calculate threshold
double calculate_threshold(double ema) {
    return ema * THRESHOLD_MULTIPLIER;
}

// Function to detect peak
int detect_peak(int raw_value, double ema, double threshold) {
    return (raw_value > threshold) ? 1 : 0;
}

// Function to log event
int log_event(int raw_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %d\n", buf, raw_value) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_mcp3008(ADC_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Calculate EMA
        ema = calculate_ema(raw_value, ema);

        // Calculate threshold
        double threshold = calculate_threshold(ema);

        // Detect peak
        if (detect_peak(raw_value, ema, threshold)) {
            // Log event
            if (log_event(raw_value) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
            printf("Peak detected: %d\n", raw_value);
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

