#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    struct i2c_msg messages[2];
    struct i2c_rdwr_ioctl_data ioctl_data;
    unsigned char buf[2];
    int ret;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl (I2C_SLAVE)");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Dummy read
        messages[0].addr = PCF8591_ADDR;
        messages[0].flags = 0; // Read
        messages[0].len = 1;
        messages[0].buf = buf;

        // Actual read
        messages[1].addr = PCF8591_ADDR;
        messages[1].flags = I2C_M_RD; // Read
        messages[1].len = 1;
        messages[1].buf = buf + 1;

        ioctl_data.msgs = messages;
        ioctl_data.nmsgs = 2;

        // Send control byte and read data
        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            perror("ioctl (I2C_RDWR)");
            close(i2c_fd);
            return 1;
        }

        // Print the analog value
        printf("%d\n", buf[1]);

        // Wait 100ms
        usleep(100000);
    }

    // Close I2C bus
    if (close(i2c_fd) < 0) {
        perror("close");
        return 1;
    }

    return 0;
}

