#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define MOTOR_SHUTDOWN_PIN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Sensor characteristics
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY_V_PER_GAUSS 0.0014 // 1.4 mV/Gauss = 0.0014 V/Gauss
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int initialize();
float read_ads1115();
float voltage_to_gauss(float voltage);
void update_circular_buffer(float gauss);
float calculate_rolling_average();
void handle_threshold_event(float average);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int motor_shutdown_pin;
    float threshold_gauss;
    int buffer_size;
    int sample_rate_hz;
} Config;

Config config = {
    I2C_BUS,
    ADS1115_ADDR,
    MOTOR_SHUTDOWN_PIN,
    THRESHOLD_GAUSS,
    BUFFER_SIZE,
    SAMPLE_RATE_HZ
};

int main() {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (initialize() != 0) {
        syslog(LOG_ERR, "Initialization failed. Exiting.");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float voltage = read_ads1115();
        if (voltage >= 0.0) {
            float gauss = voltage_to_gauss(voltage);
            update_circular_buffer(gauss);
            float average = calculate_rolling_average();
            handle_threshold_event(average);

            syslog(LOG_INFO, "Voltage: %.3f V, Magnetic Field: %.3f Gauss, Average: %.3f Gauss", voltage, gauss, average);
        } else {
            syslog(LOG_ERR, "Invalid voltage reading.");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(config.motor_shutdown_pin, PI_OUTPUT);
    gpioWrite(config.motor_shutdown_pin, 0); // Ensure motor is initially off

    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "I2C open failed: %d", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, single conversion, 125 SPS
    // Configuration register: 0x01 (CONFIG)
    // 0x8383: 1100001110000011
    //  OS   = 1    (Start single conversion)
    //  MUX  = 000  (AIN0 single-ended)
    //  PGA  = 011  (FSR = +/-4.096V)
    //  MODE = 0    (Single-shot mode)
    //  DR   = 100  (125 SPS)
    //  COMP_MODE = 0 (Traditional comparator)
    //  COMP_POL  = 0 (Active low)
    //  COMP_LAT  = 0 (Non-latching comparator)
    //  COMP_QUE  = 011 (Disable comparator)
    char config_data[3];
    config_data[0] = 0x01; // Configuration register address
    config_data[1] = 0xC3; // MSB of configuration
    config_data[2] = 0x83; // LSB of configuration

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        syslog(LOG_ERR, "ADS1115 configuration failed: %d", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

float read_ads1115() {
    // Read conversion register (0x00)
    char reg = 0x00;
    char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        syslog(LOG_ERR, "I2C write (register select) failed: %d", result);
        return -1.0;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        syslog(LOG_ERR, "I2C read failed: %d", result);
        return -1.0;
    }

    // Convert the 16-bit data to voltage
    int16_t raw_value = (data[0] << 8) | data[1];
    float voltage = (float)raw_value * VCC / 32768.0;

    return voltage;
}

float voltage_to_gauss(float voltage) {
    if (voltage < 0.0 || voltage > VCC) {
        syslog(LOG_ERR, "Voltage out of range: %.3f", voltage);
        return -1.0; // Indicate an error
    }
    return (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY_V_PER_GAUSS;
}

void update_circular_buffer(float gauss) {
    magnetic_field_buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % config.buffer_size;
    if (buffer_count < config.buffer_size) {
        buffer_count++;
    }
}

float calculate_rolling_average() {
    if (buffer_count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / buffer_count;
}

void handle_threshold_event(float average) {
    if (average > config.threshold_gauss) {
        syslog(LOG_WARNING, "Threshold exceeded: %.3f Gauss > %.3f Gauss", average, config.threshold_gauss);
        gpioWrite(config.motor_shutdown_pin, 1); // Activate motor shutdown
    } else {
        gpioWrite(config.motor_shutdown_pin, 0); // Deactivate motor shutdown
    }
}

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(config.motor_shutdown_pin, 0); // Ensure motor is off
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

