#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1.0 // seconds
#define BLINK_PERIOD 0.05 // seconds (50ms on, 50ms off)

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int *raw_value);
double convert_to_gauss(int raw_value);
void control_led(int on);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double default_threshold;
} AppConfig;

AppConfig config = {I2C_BUS, ADS1115_ADDR, LED_GPIO, DEFAULT_THRESHOLD};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_value;
    double gauss_value;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            gauss_value = convert_to_gauss(raw_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss_value);

            if (gauss_value > threshold) {
                blink_led();
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V gain, continuous conversion, single-shot mode
    char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x43; // 0b01000011
    config_data[2] = 0x83; // 0b10000011

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int *raw_value) {
    char reg = CONVERSION_REG;
    char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device for conversion read: %d\n", result);
        return 1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int raw_value) {
    // Assuming 4.096V gain and 16-bit ADC
    double voltage = (raw_value * 4.096) / 32768.0;
    return (voltage - 1.65) / 0.001;
}

// Control LED (on/off)
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Blink LED for 1 second
void blink_led() {
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < BLINK_DURATION) {
        control_led(1);
        gpioDelay(BLINK_PERIOD * 1000); // Convert seconds to milliseconds
        control_led(0);
        gpioDelay(BLINK_PERIOD * 1000);
    }
}

// Signal handler for SIGINT/SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

