#define MQTT_TOPIC_SOIL "soil_moisture"
#define MQTT_TOPIC_CONTROL "pump_control"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
static int spi_handle;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int signum);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", RELAY_GPIO);
    }
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(message->topic, MQTT_TOPIC_CONTROL) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                control_relay(1); // Turn pump on
                syslog(LOG_INFO, "Received pump_on command");
            } else if (strcmp(payload, "pump_off") == 0) {
                control_relay(0); // Turn pump off
                syslog(LOG_INFO, "Received pump_off command");
            } else {
                syslog(LOG_WARNING, "Unknown command: %s", payload);
            }
        }
    }
}

