            syslog(LOG_ERR, "Failed to calculate moisture");
            sleep(5);
            continue;
        }

        // Control pump based on moisture level
        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_relay(1); // Turn pump on
            pump_state = 1;
            syslog(LOG_INFO, "Moisture below threshold, turning pump on (%.2f%%)", moisture);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_relay(0); // Turn pump off
            pump_state = 0;
