#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(float moisture_percentage);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < MAX_RETRIES; ++i) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d): %d\n", i + 1, MAX_RETRIES, result);
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Moisture level low (%.2f%%). Turning pump ON.\n", moisture_percentage);
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Moisture level OK (%.2f%%). Turning pump OFF.\n", moisture_percentage);
    }
}

// Function to log data with timestamp
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(60000); // Wait 60 seconds before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control the water pump
        control_pump(moisture_percentage);

        // Log the data
        log_data(moisture_percentage);

        // Wait 60 seconds
        gpioDelay(60000);
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

