        float co2_ppm = adc_to_co2(adc_value);

        // Control the fan
        control_fan((int)co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);

        // Log the data
        log_data(co2_ppm, fan_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

