// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_sensors(int sensor_values[NUM_SENSORS]);
int map_to_valve_position(float average);
void set_valve_position(int position);
void log_data(int sensor_values[NUM_SENSORS], float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00; // Don't care

    char rx_buffer[3];

    int result = spiXfer(spi_handle, (char *)spi_data, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to average sensor readings
float average_sensors(int sensor_values[NUM_SENSORS]) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_values[i] != -1) {
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to map average reading to valve position
int map_to_valve_position(float average) {
    if (average == -1.0) {
        return 0; // Default to 0% if no valid readings
    }

    // Inverse mapping: higher average -> lower valve position
    int position = (int)((1.0 - (average / 1023.0)) * 100.0);
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    return position;
}

// Function to set valve position using PWM
void set_valve_position(int position) {
    gpioPWM(VALVE_GPIO, position);
}

// Function to log data to file
void log_data(int sensor_values[NUM_SENSORS], float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2], average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor_values[NUM_SENSORS];

        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] == -1) {
                fprintf(stderr, "Warning: Failed to read sensor %d\n", i);
            }
        }

        // Calculate average
        float average = average_sensors(sensor_values);

        // Map to valve position
        int valve_position = map_to_valve_position(average);

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(sensor_values, average, valve_position);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    set_valve_position(0); // Close valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

