#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_BUS 0
#define SPI_DEVICE 0
#define PWM_CHANNEL 0
#define PWM_PERIOD 1000000 // 1ms period (1kHz)
#define CONFIG_FILE "theremin_config.txt"
#define DEFAULT_MIN_DISTANCE 20.0
#define DEFAULT_MAX_DISTANCE 200.0
#define DEFAULT_MIN_FREQUENCY 220.0
#define DEFAULT_MAX_FREQUENCY 880.0
#define DEFAULT_MIN_LDR 0
#define DEFAULT_MAX_LDR 1023
#define DEFAULT_DUTY_CYCLE 500000 // 50% duty cycle
#define TIMEOUT_US 500000 // 0.5 seconds timeout

// Global variables
static volatile int keep_running = 1;
static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *trig_line, *echo_line, *pwm_line;
static double min_distance = DEFAULT_MIN_DISTANCE;
static double max_distance = DEFAULT_MAX_DISTANCE;
static double min_frequency = DEFAULT_MIN_FREQUENCY;
static double max_frequency = DEFAULT_MAX_FREQUENCY;
static int min_ldr = DEFAULT_MIN_LDR;
static int max_ldr = DEFAULT_MAX_LDR;
static int last_valid_duty_cycle = DEFAULT_DUTY_CYCLE;
static int last_valid_frequency = 440; // A4

// Function prototypes
double read_distance();
int read_ldr();
double map_distance_to_frequency(double distance);
int map_ldr_to_duty_cycle(int ldr_value);
void set_pwm_frequency(int frequency);
void set_pwm_duty_cycle(int duty_cycle);
void save_config();
void load_config();
void signal_handler(int sig);
int init_gpio();
int init_spi();
void cleanup();

// Function to read distance from HC-SR04 sensor
double read_distance() {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;
    double distance;

    // Trigger the sensor
    if (gpiod_line_set_value(trig_line, 1) < 0) {
        perror("Error setting TRIG high");
        return -1.0;
    }
    usleep(10); // 10us trigger pulse
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("Error setting TRIG low");
        return -1.0;
    }

    // Measure the echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go high with timeout
    int timeout = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            perror("Error reading ECHO value");
            return -1.0;
        }
        if (value == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if (end_ns - start_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for ECHO high\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go low with timeout
    timeout = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            perror("Error reading ECHO value");
            return -1.0;
        }
        if (value == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if (end_ns - start_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for ECHO low\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    distance = (double)pulse_width_ns / 1000000000.0 * 34300.0 / 2.0;

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 configuration: single-ended, channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < min_distance) {
        return min_frequency;
    }
    if (distance > max_distance) {
        return max_frequency;
    }
    return min_frequency + (distance - min_distance) * (max_frequency - min_frequency) / (max_distance - min_distance);
}

// Function to map LDR value to PWM duty cycle
int map_ldr_to_duty_cycle(int ldr_value) {
    if (ldr_value < min_ldr) {
        return 0;
    }
    if (ldr_value > max_ldr) {
        return PWM_PERIOD;
    }
    return (int)(((double)(ldr_value - min_ldr) / (max_ldr - min_ldr)) * PWM_PERIOD);
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM period file");
        return;
    }
    dprintf(fd, "%d", PWM_PERIOD);
    close(fd);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM duty_cycle file");
        return;
    }
    dprintf(fd, "%d", duty_cycle);
    close(fd);
}

// Function to save configuration to file
void save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening config file for writing");
        return;
    }
    fprintf(fp, "min_distance=%.2f\n", min_distance);
    fprintf(fp, "max_distance=%.2f\n", max_distance);
    fprintf(fp, "min_frequency=%.2f\n", min_frequency);
    fprintf(fp, "max_frequency=%.2f\n", max_frequency);
    fprintf(fp, "min_ldr=%d\n", min_ldr);
    fprintf(fp, "max_ldr=%d\n", max_ldr);
    fclose(fp);
}

// Function to load configuration from file
void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file for reading, using defaults");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "min_distance=", 13) == 0) {
            sscanf(line, "min_distance=%lf", &min_distance);
        } else if (strncmp(line, "max_distance=", 13) == 0) {
            sscanf(line, "max_distance=%lf", &max_distance);
        } else if (strncmp(line, "min_frequency=", 14) == 0) {
            sscanf(line, "min_frequency=%lf", &min_frequency);
        } else if (strncmp(line, "max_frequency=", 14) == 0) {
            sscanf(line, "max_frequency=%lf", &max_frequency);
        } else if (strncmp(line, "min_ldr=", 8) == 0) {
            sscanf(line, "min_ldr=%d", &min_ldr);
        } else if (strncmp(line, "max_ldr=", 8) == 0) {
            sscanf(line, "max_ldr=%d", &max_ldr);
        }
    }
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Initialize GPIO lines
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trig_line = gpiod_chip_get_line(gpio_chip, TRIG_PIN);
    if (!trig_line) {
        perror("Error getting TRIG line");
        return -1;
    }

    echo_line = gpiod_chip_get_line(gpio_chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting ECHO line");
        return -1;
    }

    pwm_line = gpiod_chip_get_line(gpio_chip, PWM_PIN);
    if (!pwm_line) {
        perror("Error getting PWM line");
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        perror("Error requesting TRIG line as output");
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("Error requesting ECHO line as input");
        return -1;
    }

    if (gpiod_line_request_output(pwm_line, "theremin", 0) < 0) {
        perror("Error requesting PWM line as output");
        return -1;
    }

    return 0;
}

// Initialize SPI interface
int init_spi() {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode and bits per word
    unsigned int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    unsigned int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Disable PWM
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd >= 0) {
        dprintf(fd, "0");
        close(fd);
    }

    // Release GPIO lines
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (pwm_line) gpiod_line_release(pwm_line);

    // Close GPIO chip
    if (gpio_chip) gpiod_chip_close(gpio_chip);

    // Close SPI device
    if (spi_fd >= 0) close(spi_fd);

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Load configuration
    load_config();

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        cleanup();
        return 1;
    }

    // Enable PWM
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        cleanup();
        return 1;
    }
    dprintf(fd, "1");
    close(fd);

    set_pwm_frequency(440); // Initial frequency
    set_pwm_duty_cycle(last_valid_duty_cycle); // Initial duty cycle

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read distance
        double distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, using last valid value.\n");
            distance = last_valid_frequency; // Use last valid frequency
        } else {
            last_valid_frequency = (int)distance; // Update last valid frequency
        }

        // Read LDR
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR, using last valid duty cycle.\n");
            ldr_value = last_valid_duty_cycle; // Use last valid duty cycle
        } else {
            last_valid_duty_cycle = ldr_value; // Update last valid duty cycle
        }

        // Map distance to frequency
        double frequency = map_distance_to_frequency(distance);

        // Map LDR to duty cycle
        int duty_cycle = map_ldr_to_duty_cycle(ldr_value);

        // Set PWM frequency and duty cycle
        set_pwm_frequency((int)frequency);
        set_pwm_duty_cycle(duty_cycle);

        // Print current state
        printf("Distance: %.2f cm, Frequency: %.2f Hz, LDR: %d, Duty Cycle: %d\n", distance, frequency, ldr_value, duty_cycle);

        usleep(50000); // 50ms delay
    }

    // Save configuration before exiting
    save_config();

    // Cleanup resources
    cleanup();

    return 0;
}

