#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define SENSOR_ABSENT_THRESHOLD 5
#define SENSOR_ABSENT_READS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(const char *timestamp, int adc_value, float ppm, const char *status);
void signal_handler(int signal);
int is_sensor_absent(int *readings, int num_readings);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int count, result;

    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode + channel
    tx[2] = 0x00;

    for (count = 0; count < 3; count++) {
        if (spiXfer(spi_handle, tx, rx, 3) == 0) {
            result = ((rx[1] & 0x03) << 8) | rx[2];
            return result;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            gpioDelay(100); // 100 ms delay
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries.\n");
    return -1; // Indicate error
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to log data to file
void log_data(const char *timestamp, int adc_value, float ppm, const char *status) {
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %.2f, %s\n", timestamp, adc_value, ppm, status);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check if the sensor is absent
int is_sensor_absent(int *readings, int num_readings) {
    int absent_count = 0;
    for (int i = 0; i < num_readings; i++) {
        if (readings[i] == 0 || readings[i] == 1023) {
            absent_count++;
        }
    }
    return (absent_count >= SENSOR_ABSENT_THRESHOLD);
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int adc_value;
    float ppm;
    const char *status;
    int sensor_readings[SENSOR_ABSENT_READS];
    int sensor_read_index = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to PPM
        ppm = adc_to_ppm(adc_value);

        // Get timestamp
        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

