    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_values[NUM_SENSORS];
    int pump_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        int pump_needed = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                sensor_values[i] = -1; // Mark as invalid
            } else {
                if (sensor_values[i] < MOISTURE_THRESHOLD) {
                    pump_needed = 1;
                }
            }
        }

        if (pump_needed && !pump_state) {
            control_pump(1);
            pump_state = 1;
        } else if (!pump_needed && pump_state) {
            control_pump(0);
            pump_state = 0;
        }

        log_data(sensor_values, pump_state);
        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

