float map_pot_to_speed(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Error: Potentiometer value out of range: %d\n", pot_value);
        return 0.0;
    }

    // Normalize potentiometer value to range [0, 1]
    float normalized_value = (float)pot_value / 1023.0;

    // Apply logarithmic scaling
    float speed_factor = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * log10(normalized_value * 9.0 + 1.0) / log10(10.0);

    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Error: Invalid speed value: %d\n", speed);
        return;
    }

    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to set motor direction using GPIO
void set_motor_direction(int motor, int direction) {
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Error: Invalid direction value: %d\n", direction);
        return;
    }

    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to move a motor at a given speed and direction
void move_motor(int motor, int direction, int speed) {
    set_motor_direction(motor, direction);
    set_motor_speed(motor, speed);
}

// Function to implement the motion profile
void motion_profile() {
    int pot1_value, pot2_value;
    float speed_factor1, speed_factor2;
    int speed1, speed2;

    // Accelerate Motor 1 forward
    for (int i = MIN_SPEED; i <= MAX_SPEED; i++) {
        pot1_value = read_potentiometer(POT1_CHANNEL);
        if (pot1_value == -1) {
            fprintf(stderr, "Error reading potentiometer 1, using default speed\n");
            speed_factor1 = 1.0; // Use default speed if reading fails
        } else {
            speed_factor1 = map_pot_to_speed(pot1_value);
        }
        speed1 = MIN_SPEED + (int)((i - MIN_SPEED) * speed_factor1 / MAX_SPEED);
        move_motor(1, 1, speed1); // Forward
        gpioDelay(10000); // 10ms delay
    }

    // Hold speed for 2 seconds
    gpioDelay(2000000);

    // Decelerate Motor 1
    for (int i = MAX_SPEED; i >= MIN_SPEED; i--) {
        pot1_value = read_potentiometer(POT1_CHANNEL);
        if (pot1_value == -1) {
            fprintf(stderr, "Error reading potentiometer 1, using default speed\n");
            speed_factor1 = 1.0; // Use default speed if reading fails
        } else {
            speed_factor1 = map_pot_to_speed(pot1_value);
        }
        speed1 = MIN_SPEED + (int)((i - MIN_SPEED) * speed_factor1 / MAX_SPEED);
        move_motor(1, 1, speed1); // Forward
        gpioDelay(10000); // 10ms delay
    }

    // Accelerate Motor 2 backward
    for (int i = MIN_SPEED; i <= MAX_SPEED; i++) {
        pot2_value = read_potentiometer(POT2_CHANNEL);
        if (pot2_value == -1) {
            fprintf(stderr, "Error reading potentiometer 2, using default speed\n");
            speed_factor2 = 1.0; // Use default speed if reading fails
        } else {
            speed_factor2 = map_pot_to_speed(pot2_value);
        }
        speed2 = MIN_SPEED + (int)((i - MIN_SPEED) * speed_factor2 / MAX_SPEED);
        move_motor(2, 0, speed2); // Backward
        gpioDelay(10000); // 10ms delay
    }

    // Hold speed for 2 seconds
    gpioDelay(2000000);

    // Decelerate Motor 2
    for (int i = MAX_SPEED; i >= MIN_SPEED; i--) {
        pot2_value = read_potentiometer(POT2_CHANNEL);
        if (pot2_value == -1) {
            fprintf(stderr, "Error reading potentiometer 2, using default speed\n");
            speed_factor2 = 1.0; // Use default speed if reading fails
        } else {
            speed_factor2 = map_pot_to_speed(pot2_value);
        }
        speed2 = MIN_SPEED + (int)((i - MIN_SPEED) * speed_factor2 / MAX_SPEED);
        move_motor(2, 0, speed2); // Backward
        gpioDelay(10000); // 10ms delay
    }

    // Pause for 5 seconds
    gpioDelay(5000000);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        motion_profile();
    }

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

