// Global variables
int spi_handle;
double ambient_level = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calibrate_ambient_level();
int check_noise_threshold(int sample, double threshold);
void control_led(int state);
