// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate ambient noise level
double calibrate_ambient_level() {
    double sum = 0.0;
    int num_samples = 0;
    time_t start_time = time(NULL);

    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_DURATION);

    while (time(NULL) - start_time < CALIBRATION_DURATION) {
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read ADC value during calibration.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += sample;
        num_samples++;
        gpioDelay(10000); // 10 ms delay
    }

    if (num_samples > 0) {
        return sum / num_samples;
    } else {
        fprintf(stderr, "Error: No samples collected during calibration.\n");
        return -1.0; // Indicate calibration failure
    }
}

// Function to check if the sound level exceeds the threshold
int check_noise_threshold(int sample, double threshold) {
    return (sample > ambient_level * threshold) ? 1 : 0;
}

