    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate ambient noise level
    ambient_level = calibrate_ambient_level();
    if (ambient_level < 0) {
        fprintf(stderr, "Error: Ambient level calibration failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Ambient noise level: %.2f\n", ambient_level);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            break; // Exit loop on error
        }

        if (check_noise_threshold(sample, NOISE_THRESHOLD)) {
            control_led(1); // Turn LED on
            gpioDelay(100000); // 100 ms delay (debounce)
            control_led(0); // Turn LED off
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

