#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the VCC and V_quiescent values
#define VCC 3.3
#define V_QUIESCENT 1.65

// Define the sensitivity of the DRV5055VA sensor (V/mT)
#define SENSITIVITY 0.025

// Define the magnetic field range (mT)
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;

// Function prototypes
double read_sensor(int gpio);
double calculate_magnetic_field(double voltage);
void log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value from a GPIO pin
double read_sensor(int gpio) {
    int value;
    struct gpiod_line *line;

    if (gpio == SENSOR1_GPIO) {
        line = sensor1_line;
    } else if (gpio == SENSOR2_GPIO) {
        line = sensor2_line;
    } else if (gpio == SENSOR3_GPIO) {
        line = sensor3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
        return -1.0; // Indicate an error
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1.0; // Indicate an error
    }

    return (double)value;
}

// Function to calculate the magnetic field strength in millitesla
double calculate_magnetic_field(double voltage) {
    return (voltage - V_QUIESCENT) / SENSITIVITY * 1000.0; // Convert to mT
}

// Function to log the sensor data to a file
void log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    FILE *fp;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written immediately
    fclose(fp);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines for each sensor
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_GPIO);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        if (sensor1_line) gpiod_line_release(sensor1_line);
        if (sensor2_line) gpiod_line_release(sensor2_line);
        if (sensor3_line) gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as inputs
    if (gpiod_line_request_input(sensor1_line, "hall-effect-sensor") < 0 ||
        gpiod_line_request_input(sensor2_line, "hall-effect-sensor") < 0 ||
        gpiod_line_request_input(sensor3_line, "hall-effect-sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        double sensor1_voltage, sensor2_voltage, sensor3_voltage;
        double sensor1_mT, sensor2_mT, sensor3_mT;

        // Read sensor values
        sensor1_voltage = read_sensor(SENSOR1_GPIO);
        sensor2_voltage = read_sensor(SENSOR2_GPIO);
        sensor3_voltage = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_voltage < 0 || sensor2_voltage < 0 || sensor3_voltage < 0) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            // Continue to the next iteration
            gpiod_sleep(0.1); // Sleep for 100ms
            continue;
        }

        // Calculate magnetic field strengths
        sensor1_mT = calculate_magnetic_field(sensor1_voltage * VCC);
        sensor2_mT = calculate_magnetic_field(sensor2_voltage * VCC);
        sensor3_mT = calculate_magnetic_field(sensor3_voltage * VCC);

        // Check for out-of-range magnetic field values
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.2f mT\n", sensor1_mT);
        }
        if (sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field out of range: %.2f mT\n", sensor2_mT);
        }
        if (sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field out of range: %.2f mT\n", sensor3_mT);
        }

        // Log the data
        log_data(sensor1_mT, sensor2_mT, sensor3_mT);

        // Sleep for 100 milliseconds
        gpiod_sleep(0.1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor3_line);
    gpiod_chip_close(chip);

    return 0;
}

