#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    if (pump_state == 1) {
        log_event("Pump turned ON.");
    } else {
        log_event("Pump turned OFF.");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    fprintf(log_file, "%s", buf);
    fflush(log_file);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
            log_event(log_message);

            if (moisture_percentage < MOISTURE_THRESHOLD && pump_state == 0) {
                control_pump(1);
                pump_state = 1;
            } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state == 1) {
                control_pump(0);
                pump_state = 0;
            }
        } else {
            log_event("Error reading ADC value.");
        }

        sleep(60); // Check every 60 seconds
    }

    // Clean up
    spiClose(spi_handle);
    control_pump(0); // Ensure pump is off on exit
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated.");

    return 0;
}

