#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_CHANNELS 3
#define LOG_FILE "sensor_data.csv"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
int log_data(int channel0, int channel1, int channel2);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS_PER_WORD;
    unsigned int speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode + channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

