    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read ADC values from channels 0, 1, and 2
        channel0_value = read_mcp3008(0);
        channel1_value = read_mcp3008(1);
        channel2_value = read_mcp3008(2);

        if (channel0_value < 0 || channel1_value < 0 || channel2_value < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data to file
        if (log_data(channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
        }

        // Control GPIO based on sensor readings (example)
        if (channel0_value > 500) {
            gpiod_line_set_value(gpio_line, 1); // Set GPIO HIGH
        } else {
            gpiod_line_set_value(gpio_line, 0); // Set GPIO LOW
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpio_cleanup();

    return 0;
}

