#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, cleaning up...\n");
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("Connection failed");
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("Disconnected unexpectedly");
    }
}

// Callback function for when a message is received on the subscribed topic
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic: %s\n", message->topic);
        printf("Payload: %s\n", (char *)message->payload);

        cJSON *json = cJSON_Parse((char *)message->payload);
        if (json == NULL) {
            const char *error_ptr = cJSON_GetErrorPtr();
            if (error_ptr != NULL) {
                log_error(error_ptr);
            }
            cJSON_Delete(json);
            return;
        }

        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (cJSON_IsBool(led_state)) {
            int state = cJSON_IsTrue(led_state);
            gpioWrite(GPIO_PIN, state);
            printf("LED set to: %s\n", state ? "ON" : "OFF");
        } else {
            log_error("Invalid JSON format: led_state must be a boolean");
        }

        cJSON_Delete(json);
    } else {
        printf("Empty message received\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client instance");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker with exponential backoff
    int rc = 0;
    int reconnect_delay = 1;
    while (running) {
        rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            break;
        } else {
            log_error("Connection failed, retrying...");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
        }
    }

    if (!running) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start the MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up and disconnect
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    printf("Exiting cleanly\n");
    return 0;
}

