    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client instance");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker with exponential backoff
    int rc = 0;
    int reconnect_delay = 1;
    while (running) {
        rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            break;
        } else {
            log_error("Connection failed, retrying...");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
        }
    }

    if (!running) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start the MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up and disconnect
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    printf("Exiting cleanly\n");
    return 0;
}

