#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Signal handler for SIGINT and SIGTERM
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

// Function to get the current timestamp in ISO 8601 format
static int get_timestamp(char *timestamp, size_t timestamp_size)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (strftime(timestamp, timestamp_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }
    return 0;
}

// Function to log the vibration event to a file
static int log_vibration_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s Vibration detected!\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure the data is written to disk
    return 0;
}

// Function to print the vibration event to the console
static void print_vibration_event(const char *timestamp)
{
    printf("%s Vibration detected!\n", timestamp);
}

// Function to initiate a system shutdown
static void initiate_shutdown()
{
    if (system("sudo shutdown -h now") != 0) {
        perror("Error initiating shutdown");
    }
}

// Function to handle the vibration event
static void handle_vibration_event()
{
    char timestamp[32];

    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return;
    }

    if (log_vibration_event(timestamp) != 0) {
        fprintf(stderr, "Failed to log vibration event.\n");
    }

    print_vibration_event(timestamp);
    initiate_shutdown();
}

int main()
{
    struct gpiod_line_event event;
    int ret;

    // Set up signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for falling edge events
    ret = gpiod_line_request(line, "vibration-monitor", GPIOD_LINE_REQUEST_EVENTS_FALLING_EDGE);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        ret = gpiod_line_event_wait(line, NULL); // Wait for a falling edge
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error waiting for GPIO event");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Error reading GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            handle_vibration_event();
        }
    }

    // Clean up resources
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

