#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
static int init_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line, "flame_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
static int read_flame_sensor(void)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    return value;
}

// Function to log the event to a file
static int log_event(int state)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, GPIO_PIN, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print an alarm message
static void print_alarm(void)
{
    printf("Flame detected!\n");
}

// Function to cleanup GPIO resources
static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void)
{
    int flame_detected;

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (log_event(flame_detected) != 0) {
            fprintf(stderr, "Error logging event, exiting.\n");
            break;
        }

        if (flame_detected == 1) {
            print_alarm();
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup_gpio();
    return EXIT_SUCCESS;
}

