// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", i + 1);
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_mcp4725(float voltage) {
    if (voltage < 0.0 || voltage > 3.3) {
        fprintf(stderr, "Error: DAC voltage out of range: %.2f\n", voltage);
        return -1;
    }

    int dac_value = (int)(voltage / 3.3 * 4095.0);

    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write DAC value command
    tx_buffer[1] = (dac_value >> 4) & 0xFF;
    tx_buffer[2] = (dac_value << 4) & 0xFF;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (i2cWriteDevice(i2c_handle, tx_buffer, 3) == 0) {
            return 0;
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d). Retrying...\n", i + 1);
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(TMP36_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map temperature to DAC voltage
        float voltage = DAC_MIN + (temperature - TEMP_MIN) * (DAC_MAX - DAC_MIN) / (TEMP_MAX - TEMP_MIN);

        // Write to DAC
        if (write_mcp4725(voltage) != 0) {
            fprintf(stderr, "Error: Failed to write to DAC\n");
        }

        // Log data
        log_data(adc_value, temperature, voltage);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500ms = 0.5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

