#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the number of relays
#define NUM_RELAYS 4

// Define the delay between relay activations (in seconds)
#define DELAY_SECONDS 1

// Define the delay between relay activations (in nanoseconds)
#define DELAY_NANOSECONDS 0

// Define the number of cycles to run
#define NUM_CYCLES -1 // -1 for infinite cycles

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0); // Set to LOW (inactive)
        }
    }

    // Release all GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines for each relay
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Request the GPIO lines for output
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "relay_sequencer", 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines before exiting
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to activate and deactivate the relays
    int cycle_count = 0;
    while (NUM_CYCLES == -1 || cycle_count < NUM_CYCLES) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            // Activate the relay
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error setting GPIO line value");
                signal_handler(SIGTERM); // Simulate a signal to clean up
                return 1;
            }
            printf("Relay %d activated\n", i + 1);

            // Wait for the specified delay
            struct timespec delay = {DELAY_SECONDS, DELAY_NANOSECONDS};
            nanosleep(&delay, NULL);

            // Deactivate the relay
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error setting GPIO line value");
                signal_handler(SIGTERM); // Simulate a signal to clean up
                return 1;
            }
            printf("Relay %d deactivated\n", i + 1);

            // Wait for the specified delay
            nanosleep(&delay, NULL);
        }
        cycle_count++;
    }

    // Clean up and exit (this part might not be reached if NUM_CYCLES is not -1)
    signal_handler(SIGTERM);

    return 0;
}

