            continue;
        }

        int rain_level = convert_to_rain_level(adc_value);
        control_motor(rain_level);
        log_rain_reading(rain_level);

        gpioDelay(1000); // Poll every 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
