    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set motor control pins as output
    gpioSetMode(motor_state.in1, PI_OUTPUT);
    gpioSetMode(motor_state.in2, PI_OUTPUT);
