#include <string.h>

// Constants
#define CLAP_THRESHOLD 700
#define LED_GPIO 16
#define DEBOUNCE_DELAY 50 // milliseconds
#define LED_ON_TIME 500   // milliseconds

// Global variables
static volatile int running = 1;
static int pi;

// Function prototypes
int initialize_gpio();
int read_adc();
void control_led(int on);
void log_detection();
void debounce();
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int clap_threshold;
    int led_gpio;
    int debounce_delay;
    int led_on_time;
} Config;

Config config = {CLAP_THRESHOLD, LED_GPIO, DEBOUNCE_DELAY, LED_ON_TIME};

int main() {
    // Initialize pigpio
    pi = initialize_gpio();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Continuing.\n");
            gpioDelay(10); // Small delay to prevent busy-waiting
            continue;
        }

        if (adc_value > config.clap_threshold) {
            log_detection();
            control_led(1); // Turn LED on
            gpioDelay(config.led_on_time * 1000); // Wait for LED on time
            control_led(0); // Turn LED off
            debounce();
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up before exiting
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    gpioSetMode(26, PI_INPUT); // Ensure GPIO26 is in input mode

    for (i = 9; i >= 0; i--) {
        gpioSetMode(26, PI_OUTPUT);
        gpioWrite(26, (i > 4) ? 1 : 0); // Set bit
        gpioSetMode(26, PI_INPUT);
        gpioDelay(1); // Small delay
        adc_value |= (gpioRead(26) << i);
    }

    return adc_value;
}

// Control the LED
void control_led(int on) {
    gpioWrite(config.led_gpio, on);
}

// Log clap detection with timestamp
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Clap detected!\n", timestamp);
}

// Debounce function
void debounce() {
    gpioDelay(config.debounce_delay * 1000); // Convert ms to microseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

