#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200.0
#define A 26.0
#define B -6.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
