#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pump_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
int control_pump(int on);
int log_data(float moisture_percentage, int pump_status);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0);
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// Function to control the water pump
int control_pump(int on) {
    int ret;
    if (on) {
        ret = gpiod_line_set_value(pump_line, 1);
    } else {
        ret = gpiod_line_set_value(pump_line, 0);
    }
    if (ret < 0) {
        perror("Error setting pump value");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float moisture_percentage, int pump_status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    pump_line = gpiod_chip_get_line(gpio_chip, PUMP_GPIO);
    if (!pump_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(pump_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    int pump_on = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 60 seconds.\n");
            sleep(60);
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d. Skipping this reading.\n", adc_value);
            sleep(60);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control pump based on moisture level
        if (moisture_percentage < MOISTURE_THRESHOLD && !pump_on) {
            if (control_pump(1) == 0) {
                pump_on = 1;
            }
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_on) {
            if (control_pump(0) == 0) {
                pump_on = 0;
            }
        }

        // Log data
        log_data(moisture_percentage, pump_on);

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    fclose(log_file);
    gpiod_line_release(pump_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return 0;
}

