#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"

// Global variables for signal handling
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float calculate_magnetic_field(int adc_value);
int log_data(FILE *fp, float magnetic_field);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);
int setup_spi(void);
void cleanup_spi(void);
int setup_logging(void);
void cleanup_logging(void);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    gpiod_line_set_value(gpio_line, 0); // CS low
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        gpiod_line_set_value(gpio_line, 1); // CS high
        return -1;
    }
    gpiod_line_set_value(gpio_line, 1); // CS high

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate magnetic field function
float calculate_magnetic_field(int adc_value) {
    // Vout_mV = adc_value * 3300 / 1023
    // B (mT) = (Vout_mV - 1650) / 100
    // Integer arithmetic: B = (adc_value * 3300 - 165000) / 100
    return (float)(adc_value * 3300 - 165000) / 100.0f;
