    signal(SIGINT, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
