#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define ADC_CHANNEL 0
#define VREF 3.3f
#define SENSITIVITY 0.1f // 100mV/A = 0.1A/V
#define LOG_FILE "current_log.txt"

// Global variables (to be cleaned up by signal handler)
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int spi_init(const char *device);
int gpio_init(int chip, int line);
int read_adc(int spi_fd, int channel);
float adc_to_current(int adc_value, float vref, float sensitivity);
int log_current(FILE *fp, float current);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device) {
    int fd;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode (CPOL=0, CPHA=0)
    unsigned char mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word (8 bits)
    unsigned char bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed (1 MHz)
    unsigned int speed = 1000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int gpio_init(int chip, int line) {
    struct gpiod_chip *chip_ptr;
    struct gpiod_line *line_ptr;
    int ret;

    chip_ptr = gpiod_chip_open_by_number(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line_ptr = gpiod_chip_get_line(chip_ptr, line);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    ret = gpiod_line_request_output(line_ptr, "current_monitor", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        gpiod_line_release(line_ptr);
        return -1;
    }

    gpio_chip = chip_ptr;
    gpio_line = line_ptr;

    return 0;
}

// ADC reading function
int read_adc(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Current calculation function
float adc_to_current(int adc_value, float vref, float sensitivity) {
    float voltage = (float)adc_value / 1023.0f * vref;
    return voltage / sensitivity;
}

// Logging function
int log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    float current;
    int adc_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_LINE) < 0) {
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        // Calculate current
        current = adc_to_current(adc_value, VREF, SENSITIVITY);

        // Log current
        if (log_current(log_file, current) < 0) {
            fprintf(stderr, "Error logging current, retrying in 1 second...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

