#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define log file name
#define LOG_FILE "current_log.txt"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel)
{
    unsigned char tx[3];
    unsigned char rx[3];
    int handle;
    int count;

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Don't care

    // Open SPI channel
    handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }

    // Transfer data
    count = spiXfer(handle, tx, rx, 3);
    if (count != 3) {
        fprintf(stderr, "Error during SPI transfer: %d\n", count);
        spiClose(handle);
        return -1;
    }

    // Close SPI channel
    spiClose(handle);

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value)
{
    return (float)adc_value * 5.0 / 1023.0;
}

// Function to convert voltage to current
float voltage_to_current(float voltage)
{
    return (voltage - 2.5) * (50.0 / 2.5);
}

// Function to log current reading to file
int log_current(float current)
{
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Write timestamp and current reading to file
    fprintf(fp, "%s %.2f A\n", timestamp, current);

    // Flush file buffer
    fflush(fp);

    // Close file
    fclose(fp);

    return 0;
}

int main()
{
    int adc_value;
    float voltage;
    float current;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(100000); // Wait 100ms
            continue;
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(adc_value);

        // Check for out-of-range voltage
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        } else {
            // Convert voltage to current
            current = voltage_to_current(voltage);

            // Log current reading
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current reading\n");
            }
        }

        // Wait 100ms
        gpioDelay(100000);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

