#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Debounce samples
#define DEBOUNCE_SAMPLES 5

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_line_t;

// Global variables for GPIO lines
gpio_line_t sensor1_line, sensor2_line;

// Function prototypes
int read_sensor(gpio_line_t *line);
int debounce_sensor(gpio_line_t *line);
void log_sensor_state(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line.line) {
        gpiod_line_release(sensor1_line.line);
    }
    if (sensor2_line.line) {
        gpiod_line_release(sensor2_line.line);
    }

    // Close GPIO chip
    if (sensor1_line.chip) {
        gpiod_chip_close(sensor1_line.chip);
    }
    if (sensor2_line.chip) {
        gpiod_chip_close(sensor2_line.chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(gpio_line_t *line) {
    int value = gpiod_line_get_value(line->line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", gpiod_line_get_name(line->line));
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(gpio_line_t *line) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = read_sensor(line);
        if (value < 0) return -1; // Propagate error
        sum += value;
        usleep(2000); // 2 ms delay
    }
    return (sum >= (DEBOUNCE_SAMPLES / 2)) ? 1 : 0; // Return majority value
}

// Function to log the sensor state
