#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(int channel, int baud);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// SPI setup function
int spi_setup(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI channel 0, 1MHz, mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    count = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (count != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", count);
        return -1; // Indicate error
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2]; // Extract 10-bit value
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to log data to file
int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    printf("%s,%.2f\n", timestamp, moisture_level);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spi_setup(SPI_CHANNEL, SPI_BAUD);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds.\n", READ_DELAY);
            sleep(READ_DELAY);
            continue; // Retry
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

