#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>
#include <syslog.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam/"
#define DEBOUNCE_DELAY_MS 200

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
}

int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char filepath[256];
    char command[512];
    int status;
    pid_t pid;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y-%m-%dT%H:%M:%SZ.jpg", timeinfo);
    snprintf(filepath, sizeof(filepath), "%s%s", IMAGE_DIR, filename);

    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --encoding jpeg --immediate", filepath, IMAGE_WIDTH, IMAGE_HEIGHT);

    syslog(LOG_INFO, "Capturing image: %s", filepath);

    pid = fork();

    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        // execl only returns on error
        syslog(LOG_ERR, "execl failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) == 0) {
                syslog(LOG_INFO, "Image capture successful.");
                return 0;
            } else {
                syslog(LOG_ERR, "Image capture failed with exit status %d.", WEXITSTATUS(status));
                return -1;
            }
        } else {
            syslog(LOG_ERR, "Image capture process terminated abnormally.");
            return -1;
        }
    }
}

int main() {
    int current_state = 0;
    int previous_state = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 ms

    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting motion detector...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Check if the image directory exists, create it if it doesn't
    struct stat st = {0};
    if (stat(IMAGE_DIR, &st) == -1) {
        if (mkdir(IMAGE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create image directory: %s", strerror(errno));
            gpioTerminate();
            closelog();
            return 1;
        }
        syslog(LOG_INFO, "Image directory created: %s", IMAGE_DIR);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            syslog(LOG_INFO, "Motion detected!");
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state == 1) { // Only capture if still high after debounce
                if (capture_image() == 0) {
                    syslog(LOG_INFO, "Image captured successfully.");
                } else {
                    syslog(LOG_ERR, "Image capture failed.");
                }
            }

            previous_state = current_state;
        }

        nanosleep(&sleep_time, NULL);
    }

    syslog(LOG_INFO, "Shutting down pigpio...");
    gpioTerminate();
    syslog(LOG_INFO, "Exiting...");
    closelog();

    return 0;
}

