#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)

// Structure to hold camera information
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int frame_count;
} camera_t;

// Global camera instance
camera_t camera = {0};

// Signal handler function
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (camera.fd > 0) {
        close(camera.fd);
    }
    if (camera.buffer != NULL) {
        munmap(camera.buffer, camera.buffer_size);
    }
    exit(0);
}

// Function to initialize the camera
int init_camera(const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the device
    camera.fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (camera.fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check capabilities
    if (ioctl(camera.fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(camera.fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        close(camera.fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        close(camera.fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera.fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(camera.fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera.fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(camera.fd);
        return -1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera.fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(camera.fd);
        return -1;
    }

    camera.buffer_size = buf.length;
    camera.buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera.fd, buf.m.offset);
    if (camera.buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(camera.fd);
        return -1;
    }

    // Queue the buffer
    if (ioctl(camera.fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera.fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame() {
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;
    char filename[20];

    // Prepare file descriptor set for select()
    FD_ZERO(&fds);
    FD_SET(camera.fd, &fds);

    // Set timeout to 2 seconds
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    // Wait for buffer to be ready
    int r = select(camera.fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        perror("Error in select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera.fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Save frame to file
    snprintf(filename, sizeof(filename), "image_%04d.pgm", ++camera.frame_count);
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        // Requeue the buffer before returning
        if (ioctl(camera.fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error requeuing buffer");
        }
        return -1;
    }

    // Write PGM header
    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);

    // Write image data
    if (fwrite(camera.buffer, 1, IMAGE_SIZE, fp) != IMAGE_SIZE) {
        perror("Error writing image data");
        fclose(fp);
        // Requeue the buffer before returning
        if (ioctl(camera.fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error requeuing buffer");
        }
        return -1;
    }

    fclose(fp);

    // Requeue buffer
    if (ioctl(camera.fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        return -1;
    }

    return 0;
}

// Function to release camera resources
void release_camera() {
    if (camera.fd > 0) {
        close(camera.fd);
    }
    if (camera.buffer != NULL) {
        munmap(camera.buffer, camera.buffer_size);
    }
}

int main(int argc, char *argv[]) {
    const char *device_name = DEFAULT_DEVICE;

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera(device_name) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    printf("Camera initialized successfully\n");

    // Capture frames continuously
    while (1) {
        if (capture_frame() < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break; // Exit loop on capture failure
        }
    }

    // Release camera resources
    release_camera();

    printf("Program finished\n");

    return 0;
}

