int video_fd = -1;
void *buffers[4] = {NULL};
size_t buffer_sizes[4] = {0};

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the V4L2 device
int init_v4l2(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
        buffer_sizes[i] = buf.length;

        if (ioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *buffer = buffers[buf.index];
    *buffer_size = buffer_sizes[buf.index];

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to fragment a frame
int fragment_frame(void *frame, size_t frame_size, uint32_t frame_index, header_t *headers, void **fragments, size_t *fragment_sizes, uint32_t *total_fragments) {
    size_t offset = 0;
    *total_fragments = 0;

    while (offset < frame_size) {
        size_t payload_size = (frame_size - offset > MAX_FRAGMENT_SIZE) ? MAX_FRAGMENT_SIZE : frame_size - offset;
        size_t fragment_size = HEADER_SIZE + payload_size;

        headers[*total_fragments].frame_index = frame_index;
        headers[*total_fragments].fragment_index = *total_fragments;
        headers[*total_fragments].total_fragments = 0; // Will be set after all fragments are created
        headers[*total_fragments].payload_size = payload_size;

        fragments[*total_fragments] = malloc(fragment_size);
        if (fragments[*total_fragments] == NULL) {
            fprintf(stderr, "Error allocating memory for fragment\n");
            return -1;
        }

        memcpy(fragments[*total_fragments], &headers[*total_fragments], HEADER_SIZE);
        memcpy((char*)fragments[*total_fragments] + HEADER_SIZE, (char*)frame + offset, payload_size);

        fragment_sizes[*total_fragments] = fragment_size;
        offset += payload_size;
        (*total_fragments)++;
    }

    // Set total_fragments in the headers
    for (int i = 0; i < *total_fragments; i++) {
        headers[i].total_fragments = *total_fragments;
    }

    return 0;
}

// Function to send a fragment
int send_fragment(int socket_fd, struct sockaddr_in server_addr, void *fragment, size_t fragment_size) {
    if (sendto(socket_fd, fragment, fragment_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending fragment: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to clean up resources
void cleanup(int fd, void **buffers, size_t num_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (fd != -1) {
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (size_t i = 0; i < num_buffers; i++) {
            if (buffers[i] != NULL) {
                munmap(buffers[i], buffer_sizes[i]);
            }
        }
        close(fd);
    }
}

int main(int argc, char *argv[]) {
    int socket_fd;
    struct sockaddr_in server_addr;
    in_addr_t server_ip;
    int server_port;
    void *frame_buffer = NULL;
    size_t frame_buffer_size = 0;
    header_t headers[MAX_FRAGMENTS];
    void *fragments[MAX_FRAGMENTS];
    size_t fragment_sizes[MAX_FRAGMENTS];
    uint32_t frame_index = 0;

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = inet_addr(argv[1]);
    if (server_ip == INADDR_NONE) {
        fprintf(stderr, "Invalid IP address: %s\n", argv[1]);
        return 1;
    }

    server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[2]);
        return 1;
    }

    // Initialize V4L2
    if (init_v4l2(&video_fd) < 0) {
        return 1;
    }

    // Create UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup(video_fd, buffers, 4);
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = server_ip;
    server_addr.sin_port = htons(server_port);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!stop_flag) {
        // Capture frame
        if (capture_frame(video_fd, &frame_buffer, &frame_buffer_size) < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }

        // Fragment frame
        uint32_t total_fragments;
        if (fragment_frame(frame_buffer, frame_buffer_size, frame_index, headers, fragments, fragment_sizes, &total_fragments) < 0) {
            fprintf(stderr, "Error fragmenting frame, exiting...\n");
            break;
        }

        // Send fragments
        for (int i = 0; i < total_fragments; i++) {
            if (send_fragment(socket_fd, server_addr, fragments[i], fragment_sizes[i]) < 0) {
                fprintf(stderr, "Error sending fragment, exiting...\n");
                break;
            }
            free(fragments[i]);
        }

        frame_index++;
    }

    // Clean up
    cleanup(video_fd, buffers, 4);
    close(socket_fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

