#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define OUTPUT_FILE "image.jpg"

static int fd = -1;
static struct buffer {
    void   *start;
    size_t  length;
} *buffers;
static unsigned int n_buffers = 0;
static FILE *fp = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (fd != -1) {
        stop_capturing();
    }
    if (buffers != NULL) {
        unmap_buffers();
    }
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(0);
}

// Function to check if a capability is supported
int is_capability_supported(int fd, unsigned int capability) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return 0;
    }
    return (cap.capabilities & capability) == capability;
}

// Function to initialize the V4L2 device
int init_device(const char *device_name) {
    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    if (!is_capability_supported(fd, V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!is_capability_supported(fd, V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_name);
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

// Function to set the image format
int set_image_format(int fd, unsigned int width, unsigned int height, unsigned int pixel_format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    return req.count;
}

// Function to map the buffers
int map_buffers(int fd, unsigned int num_buffers, struct buffer *buffers) {
    struct v4l2_buffer buf;
    for (unsigned int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }
    return 0;
}

// Function to queue the buffers
int queue_buffers(int fd, unsigned int num_buffers) {
    struct v4l2_buffer buf;
    for (unsigned int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }
    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to stop capturing
int stop_capturing() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers() {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
            return -1;
        }
    }
    free(buffers);
    buffers = NULL;
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

// Function to write the image to a file
int write_image_to_file(const char *filename, const void *data, size_t size) {
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    if (fwrite(data, 1, size, fp) != size) {
        perror("fwrite");
        fclose(fp);
        fp = NULL;
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        fp = NULL;
        return -1;
    }
    fp = NULL;
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(DEVICE_NAME) == -1) {
        return EXIT_FAILURE;
    }

    // Set the image format to MJPEG
    if (set_image_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT, V4L2_PIX_FMT_MJPEG) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    n_buffers = request_buffers(fd, NUM_BUFFERS);
    if (n_buffers == 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the buffers
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (buffers == NULL) {
        perror("calloc");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    if (map_buffers(fd, n_buffers, buffers) == -1) {
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue the buffers
    if (queue_buffers(fd, n_buffers) == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    // Dequeue a buffer
    if (dequeue_buffer(fd, &buf) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the buffer contains data
    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: No data received in the buffer\n");
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the image to a file
    if (write_image_to_file(OUTPUT_FILE, buffers[buf.index].start, buf.bytesused) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Enqueue the buffer
    if (enqueue_buffer(fd, &buf) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop capturing
    if (stop_capturing() == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffers
    if (unmap_buffers() == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the device
    if (close(fd) == -1) {
        perror("close");
        return EXIT_FAILURE;
    }

    printf("Image captured and saved to %s\n", OUTPUT_FILE);

    return EXIT_SUCCESS;
}

