    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to stop capturing
int stop_capturing() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers() {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
            return -1;
        }
    }
    free(buffers);
    buffers = NULL;
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

// Function to write the image to a file
int write_image_to_file(const char *filename, const void *data, size_t size) {
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    if (fwrite(data, 1, size, fp) != size) {
        perror("fwrite");
        fclose(fp);
        fp = NULL;
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        fp = NULL;
        return -1;
    }
    fp = NULL;
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(DEVICE_NAME) == -1) {
        return EXIT_FAILURE;
    }

    // Set the image format to MJPEG
    if (set_image_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT, V4L2_PIX_FMT_MJPEG) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    n_buffers = request_buffers(fd, NUM_BUFFERS);
    if (n_buffers == 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the buffers
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (buffers == NULL) {
        perror("calloc");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    if (map_buffers(fd, n_buffers, buffers) == -1) {
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue the buffers
    if (queue_buffers(fd, n_buffers) == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    // Dequeue a buffer
    if (dequeue_buffer(fd, &buf) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the buffer contains data
    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: No data received in the buffer\n");
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the image to a file
    if (write_image_to_file(OUTPUT_FILE, buffers[buf.index].start, buf.bytesused) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Enqueue the buffer
    if (enqueue_buffer(fd, &buf) == -1) {
        stop_capturing();
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop capturing
    if (stop_capturing() == -1) {
        unmap_buffers();
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffers
    if (unmap_buffers() == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the device
    if (close(fd) == -1) {
        perror("close");
        return EXIT_FAILURE;
    }

    printf("Image captured and saved to %s\n", OUTPUT_FILE);

    return EXIT_SUCCESS;
}

