#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_UP_BUTTON_PIN 8
#define PAN_DOWN_BUTTON_PIN 9
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7

// Define PWM parameters
#define PWM_PERIOD_NS 20000000 // 20 ms (50 Hz)
#define MIN_PULSE_WIDTH_NS 1000000 // 1 ms
#define MAX_PULSE_WIDTH_NS 2000000 // 2 ms
#define DUTY_CYCLE_RANGE 900 // 1000 - 50

// Define servo position limits
#define MIN_POSITION 25
#define MAX_POSITION 125

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo_line;
static struct gpiod_line *tilt_servo_line;
static struct gpiod_line *pan_up_button_line;
static struct gpiod_line *pan_down_button_line;
static struct gpiod_line *tilt_up_button_line;
static struct gpiod_line *tilt_down_button_line;

static volatile int pan_position = 75;
static volatile int tilt_position = 75;

// Function prototypes
int set_servo_pulse_width(struct gpiod_line *line, int duty_cycle);
int handle_button_press(struct gpiod_line *line, int *position);
void signal_handler(int sig);

// Function to set the servo pulse width using software PWM
int set_servo_pulse_width(struct gpiod_line *line, int duty_cycle) {
    int ret;
    struct timespec on_time, off_time;

    // Calculate pulse width based on duty cycle
    long pulse_width_ns = MIN_PULSE_WIDTH_NS + (long)((long)duty_cycle * DUTY_CYCLE_RANGE / 1000);

    // Set on time
    on_time.tv_sec = 0;
    on_time.tv_nsec = pulse_width_ns;

    // Set off time
    off_time.tv_sec = 0;
    off_time.tv_nsec = PWM_PERIOD_NS - pulse_width_ns;

    // Set line value to 1 (HIGH)
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value to 1: %s\n", strerror(-ret));
        return ret;
    }
    nanosleep(&on_time, NULL);

    // Set line value to 0 (LOW)
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value to 0: %s\n", strerror(-ret));
        return ret;
    }
    nanosleep(&off_time, NULL);

    return 0;
}

// Function to handle button press and update servo position
int handle_button_press(struct gpiod_line *line, int *position) {
    int ret;
    int value;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting line value: %s\n", strerror(-ret));
        return ret;
    }
    value = ret;

    // Check if the button is pressed (active low)
    if (value == 0) {
        // Debounce delay
        usleep(50000); // 50 ms

        // Update position based on the button
        if (line == pan_up_button_line) {
            *position += 5;
        } else if (line == pan_down_button_line) {
            *position -= 5;
        } else if (line == tilt_up_button_line) {
            *position += 5;
        } else if (line == tilt_down_button_line) {
            *position -= 5;
        }

        // Clamp position to valid range
        if (*position < MIN_POSITION) {
            *position = MIN_POSITION;
        } else if (*position > MAX_POSITION) {
            *position = MAX_POSITION;
        }
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO resources
    if (pan_servo_line) {
        gpiod_line_release(pan_servo_line);
    }
    if (tilt_servo_line) {
        gpiod_line_release(tilt_servo_line);
    }
    if (pan_up_button_line) {
        gpiod_line_release(pan_up_button_line);
    }
    if (pan_down_button_line) {
        gpiod_line_release(pan_down_button_line);
    }
    if (tilt_up_button_line) {
        gpiod_line_release(tilt_up_button_line);
    }
    if (tilt_down_button_line) {
        gpiod_line_release(tilt_down_button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get lines for pan servo
    pan_servo_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    if (!pan_servo_line) {
        fprintf(stderr, "Error getting pan servo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get lines for tilt servo
    tilt_servo_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    if (!tilt_servo_line) {
        fprintf(stderr, "Error getting tilt servo line: %s\n", strerror(errno));
        gpiod_line_release(pan_servo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get lines for pan buttons
    pan_up_button_line = gpiod_chip_get_line(chip, PAN_UP_BUTTON_PIN);
    if (!pan_up_button_line) {
        fprintf(stderr, "Error getting pan up button line: %s\n", strerror(errno));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    pan_down_button_line = gpiod_chip_get_line(chip, PAN_DOWN_BUTTON_PIN);
    if (!pan_down_button_line) {
        fprintf(stderr, "Error getting pan down button line: %s\n", strerror(errno));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get lines for tilt buttons
    tilt_up_button_line = gpiod_chip_get_line(chip, TILT_UP_BUTTON_PIN);
    if (!tilt_up_button_line) {
        fprintf(stderr, "Error getting tilt up button line: %s\n", strerror(errno));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    tilt_down_button_line = gpiod_chip_get_line(chip, TILT_DOWN_BUTTON_PIN);
    if (!tilt_down_button_line) {
        fprintf(stderr, "Error getting tilt down button line: %s\n", strerror(errno));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(pan_servo_line, "pan_servo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting pan servo line for output: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(tilt_servo_line, "tilt_servo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting tilt servo line for output: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for input with pull-up
    ret = gpiod_line_request_input(pan_up_button_line, "pan_up_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting pan up button line for input: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_set_flags(pan_up_button_line, GPIOD_LINE_FLAG_BIAS_PULL_UP);

    ret = gpiod_line_request_input(pan_down_button_line, "pan_down_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting pan down button line for input: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_set_flags(pan_down_button_line, GPIOD_LINE_FLAG_BIAS_PULL_UP);

    ret = gpiod_line_request_input(tilt_up_button_line, "tilt_up_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting tilt up button line for input: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_set_flags(tilt_up_button_line, GPIOD_LINE_FLAG_BIAS_PULL_UP);

    ret = gpiod_line_request_input(tilt_down_button_line, "tilt_down_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting tilt down button line for input: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_set_flags(tilt_down_button_line, GPIOD_LINE_FLAG_BIAS_PULL_UP);

    // Main loop
    while (1) {
        // Set servo pulse widths
        ret = set_servo_pulse_width(pan_servo_line, pan_position);
        if (ret < 0) {
            fprintf(stderr, "Error setting pan servo pulse width: %s\n", strerror(-ret));
            break;
        }

        ret = set_servo_pulse_width(tilt_servo_line, tilt_position);
        if (ret < 0) {
            fprintf(stderr, "Error setting tilt servo pulse width: %s\n", strerror(-ret));
            break;
        }

        // Handle button presses
        ret = handle_button_press(pan_up_button_line, &pan_position);
        if (ret < 0) {
            fprintf(stderr, "Error handling pan up button press: %s\n", strerror(-ret));
            break;
        }

        ret = handle_button_press(pan_down_button_line, &pan_position);
        if (ret < 0) {
            fprintf(stderr, "Error handling pan down button press: %s\n", strerror(-ret));
            break;
        }

        ret = handle_button_press(tilt_up_button_line, &tilt_position);
        if (ret < 0) {
            fprintf(stderr, "Error handling tilt up button press: %s\n", strerror(-ret));
            break;
        }

        ret = handle_button_press(tilt_down_button_line, &tilt_position);
        if (ret < 0) {
            fprintf(stderr, "Error handling tilt down button press: %s\n", strerror(-ret));
            break;
        }

        // Sleep for 50 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    signal_handler(SIGINT);

    return 0;
}

