        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

