    ret = gpiod_line_request_output(pan_servo_line, "pan_servo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting pan servo line for output: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(tilt_servo_line, "tilt_servo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting tilt servo line for output: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
        gpiod_line_release(pan_down_button_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for input with pull-up
    ret = gpiod_line_request_input(pan_up_button_line, "pan_up_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting pan up button line for input: %s\n", strerror(-ret));
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(pan_up_button_line);
