        ret = set_servo_pulse_width(pan_servo_line, pan_position);
        if (ret < 0) {
            fprintf(stderr, "Error setting pan servo pulse width: %s\n", strerror(-ret));
            break;
        }

        ret = set_servo_pulse_width(tilt_servo_line, tilt_position);
        if (ret < 0) {
            fprintf(stderr, "Error setting tilt servo pulse width: %s\n", strerror(-ret));
            break;
