#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/select.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables for signal handling
static volatile int keep_running = 1;
static int fd = -1;
static buffer *buffers = NULL;
static unsigned int n_buffers = 0;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Function to initialize the camera
int init_camera(int *fd, struct v4l2_capability *cap, struct v4l2_format *fmt, struct v4l2_requestbuffers *req, buffer **buffers, unsigned int *n_buffers) {
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(*fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = IMAGE_WIDTH;
    fmt->fmt.pix.height = IMAGE_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    req->count = 4; // Request 4 buffers
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (req->count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    *buffers = calloc(req->count, sizeof(buffer));
    if (!*buffers) {
        fprintf(stderr, "Out of memory\n");
        close(*fd);
        return -1;
    }

    *n_buffers = req->count;

    for (unsigned int i = 0; i < *n_buffers; ++i) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            close(*fd);
            free(*buffers);
            return -1;
        }

        (*buffers)[i].length = buf.length;
        (*buffers)[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);

        if ((*buffers)[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            close(*fd);
            free(*buffers);
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd, buffer *buffers, unsigned int n_buffers) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd, buffer *buffers, unsigned int n_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to close the camera
int close_camera(int fd, buffer *buffers) {
    if (fd != -1) {
        close(fd);
    }
    if (buffers != NULL) {
        free(buffers);
    }
    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb24, int width, int height) {
    int i, j;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            int y1 = yuyv[0];
            int u = yuyv[1] - 128;
            int y2 = yuyv[2];
            int v = yuyv[3] - 128;

            int r1 = y1 + 1.164 * v;
            int g1 = y1 - 0.392 * u - 0.813 * v;
            int b1 = y1 + 2.017 * u;

            int r2 = y2 + 1.164 * v;
            int g2 = y2 - 0.392 * u - 0.813 * v;
            int b2 = y2 + 2.017 * u;

            r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
            g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
            b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

            r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
            g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
            b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

            rgb24[0] = r1;
            rgb24[1] = g1;
            rgb24[2] = b1;
            rgb24[3] = r2;
            rgb24[4] = g2;
            rgb24[5] = b2;

            yuyv += 4;
            rgb24 += 6;
        }
    }
}

// Function to apply box blur
void box_blur(const unsigned char *input, unsigned char *output, int width, int height, int radius) {
    int i, j, x, y, r, g, b, total_r, total_g, total_b, count;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            total_r = 0;
            total_g = 0;
            total_b = 0;
            count = 0;

            for (x = i - radius; x <= i + radius; x++) {
                for (y = j - radius; y <= j + radius; y++) {
                    int px = x;
                    int py = y;

                    // Clamp coordinates to image boundaries
                    if (px < 0) px = 0;
                    if (px >= height) px = height - 1;
                    if (py < 0) py = 0;
                    if (py >= width) py = width - 1;

                    total_r += input[(px * width + py) * 3];
                    total_g += input[(px * width + py) * 3 + 1];
                    total_b += input[(px * width + py) * 3 + 2];
                    count++;
                }
            }

            r = total_r / count;
            g = total_g / count;
            b = total_b / count;

            output[(i * width + j) * 3] = r;
            output[(i * width + j) * 3 + 1] = g;
            output[(i * width + j) * 3 + 2] = b;
        }
    }
}

// Function to write JPEG image
int write_jpeg(const char *filename, const unsigned char *image, int width, int height, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output JPEG file: %s\n", strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *yuyv_frame = NULL;
    unsigned char *rgb24_frame = NULL;
    unsigned char *blurred_frame = NULL;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;
    fd_set fds;
    struct timeval tv;
    int r;

    // Allocate memory for frames
    yuyv_frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 2);
    rgb24_frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    blurred_frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);

    if (!yuyv_frame || !rgb24_frame || !blurred_frame) {
        fprintf(stderr, "Out of memory\n");
        goto cleanup;
    }

    // Initialize camera
    if (init_camera(&fd, &cap, &fmt, &req, &buffers, &n_buffers) < 0) {
        goto cleanup;
    }

    // Start streaming
    if (start_streaming(fd, buffers, n_buffers) < 0) {
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Capture a single frame
    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "Select interrupted by signal\n");
                break;
            }
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            goto cleanup;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        }

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            goto cleanup;
        }

        // Copy the frame data
        memcpy(yuyv_frame, buffers[buf.index].start, buf.bytesused);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            goto cleanup;
        }

        // Process the frame
        yuyv_to_rgb24(yuyv_frame, rgb24_frame, IMAGE_WIDTH, IMAGE_HEIGHT);
        box_blur(rgb24_frame, blurred_frame, IMAGE_WIDTH, IMAGE_HEIGHT, 2);

        // Generate filename
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        // Write JPEG
        if (write_jpeg(filename, blurred_frame, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_QUALITY) < 0) {
            goto cleanup;
        }

        printf("Captured and saved %s\n", filename);
        break; // Capture only one frame
    }

cleanup:
    // Stop streaming
    if (fd != -1) {
        stop_streaming(fd, buffers, n_buffers);
    }

    // Close camera
    close_camera(fd, buffers);

    // Free memory
    if (yuyv_frame) free(yuyv_frame);
    if (rgb24_frame) free(rgb24_frame);
    if (blurred_frame) free(blurred_frame);

    return 0;
}

