#define DEVICE_NAME "/dev/video0"

// Function to handle errors and exit
void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to print camera information
void print_camera_info(struct v4l2_capability *cap) {
    printf("Driver: %s\n", cap->driver);
    printf("Card: %s\n", cap->card);
    printf("Bus info: %s\n", cap->bus_info);
    printf("Version: %u.%u.%u\n", (cap->version >> 16) & 0xFF, (cap->version >> 8) & 0xFF, cap->version & 0xFF);
    printf("Capabilities: 0x%08x\n", cap->capabilities);
}

// Function to print frame size
void print_frame_size(struct v4l2_frmsizeenum *frmsize) {
    printf("    Width: %d, Height: %d\n", frmsize->discrete.width, frmsize->discrete.height);
}

// Function to print frame interval
void print_frame_interval(struct v4l2_frmivalenum *frmival) {
    printf("        Frame rate: %d/%d (%.2f fps)\n", frmival->discrete.numerator, frmival->discrete.denominator, (double)frmival->discrete.numerator / (double)frmival->discrete.denominator);
}

// Function to check if autofocus is supported
int is_autofocus_supported(int fd) {
    struct v4l2_queryctrl queryctrl;
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == -1) {
        if (errno == EINVAL) {
            return 0; // Autofocus control not supported
        } else {
            perror("VIDIOC_QUERYCTRL (autofocus)");
            return -1; // Error
        }
    }

    return (queryctrl.flags & V4L2_CTRL_FLAG_DISABLED) == 0; // Autofocus is enabled
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    int autofocus_supported = 0;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        error_exit("VIDIOC_QUERYCAP");
    }

    print_camera_info(&cap);

    // Check if the device supports frame size enumeration
    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMESIZES)) {
        printf("The device does not support frame size enumeration.\n");
    } else {
        printf("Supported resolutions:\n");
        frmsize.index = 0;
        frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed

        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) != -1) {
            if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                print_frame_size(&frmsize);
            }
            frmsize.index++;
        }
        if (errno != EINVAL) {
            perror("VIDIOC_ENUM_FRAMESIZES");
        }
    }

    // Check if the device supports frame interval enumeration
    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMEINTERVALS)) {
        printf("The device does not support frame interval enumeration.\n");
    } else {
        printf("Supported frame rates:\n");
        frmival.index = 0;
        frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed
        frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed

        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) != -1) {
            if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                printf("  Resolution: %d x %d\n", frmsize.discrete.width, frmsize.discrete.height);
                frmival.width = frmsize.discrete.width;
                frmival.height = frmsize.discrete.height;
                frmival.index = 0;

                while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) != -1) {
                    print_frame_interval(&frmival);
                    frmival.index++;
                }
                if (errno != EINVAL) {
                    perror("VIDIOC_ENUM_FRAMEINTERVALS");
                }
            }
            frmsize.index++;
        }
        if (errno != EINVAL) {
            perror("VIDIOC_ENUM_FRAMESIZES");
        }
    }

    // Check if autofocus is supported
    int autofocus_result = is_autofocus_supported(fd);
    if (autofocus_result == 1) {
        printf("Autofocus is supported.\n");
        autofocus_supported = 1;
    } else if (autofocus_result == 0) {
        printf("Autofocus is not supported.\n");
    } else {
        fprintf(stderr, "Error checking autofocus support.\n");
    }

    // Close the device
    close(fd);

    return 0;
}

