#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo limits
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500

// Define button states
#define BUTTON_PRESSED 0  // Active-low button

// Define movement increments
#define MOVEMENT_INCREMENT 10

// Global variables for servo positions
int pan_position = SERVO_CENTER_PULSE_WIDTH;
int tilt_position = SERVO_CENTER_PULSE_WIDTH;

// Function prototypes
void signal_handler(int signal);
void update_servo_position(int *position, int button_pin, int increment);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to update servo position based on button input
void update_servo_position(int *position, int button_pin, int increment) {
    if (gpioRead(button_pin) == BUTTON_PRESSED) {
        *position += increment;
        if (*position < SERVO_MIN_PULSE_WIDTH) {
            *position = SERVO_MIN_PULSE_WIDTH;
        } else if (*position > SERVO_MAX_PULSE_WIDTH) {
            *position = SERVO_MAX_PULSE_WIDTH;
        }
        gpioServo(PAN_SERVO_PIN, pan_position);
        gpioServo(TILT_SERVO_PIN, tilt_position);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo positions
    gpioServo(PAN_SERVO_PIN, pan_position);
    gpioServo(TILT_SERVO_PIN, tilt_position);

    // Print startup message
    printf("Pan-Tilt Control System\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Up Button: GPIO%d, Down Button: GPIO%d, Left Button: GPIO%d, Right Button: GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Initial Pan Position: %d, Tilt Position: %d\n", pan_position, tilt_position);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        update_servo_position(&pan_position, LEFT_BUTTON_PIN, -MOVEMENT_INCREMENT);
        update_servo_position(&pan_position, RIGHT_BUTTON_PIN, MOVEMENT_INCREMENT);
        update_servo_position(&tilt_position, UP_BUTTON_PIN, MOVEMENT_INCREMENT);
        update_servo_position(&tilt_position, DOWN_BUTTON_PIN, -MOVEMENT_INCREMENT);
        gpioDelay(50000); // 50 ms delay
    }

    return 0;
}

