#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define MOTION_CAPTURES_DIR "motion_captures"
#define LOG_FILE "motion_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold configuration data
typedef struct {
    char server_ip[INET_ADDRSTRLEN];
    int server_port;
} Config;

// Function prototypes
int initialize_gpio();
int capture_image(char *filename);
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port);
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

// Logging function
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Capture image using libcamera-still
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s/%s -w %d -h %d -q %d",
             MOTION_CAPTURES_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return 1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit code %d\n", WEXITSTATUS(status));
        return 1;
    }

    return 0;
}

// Send data to server using libcurl
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    snprintf(json_payload, sizeof(json_payload), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://");
        char url[256];
        snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            log_message("Data sent successfully");
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : 1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    Config config;
    strncpy(config.server_ip, argv[1], INET_ADDRSTRLEN - 1);
    config.server_ip[INET_ADDRSTRLEN - 1] = '\0'; // Ensure null termination
    config.server_port = atoi(argv[2]);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Create motion_captures directory if it doesn't exist
    if (mkdir(MOTION_CAPTURES_DIR, 0777) == -1) {
        if (errno != EEXIST) {
            perror("Failed to create motion_captures directory");
            fclose(log_file);
            return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_motion_time = 0;
    int motion_detected = 0;

    log_message("Program started");

    while (program_running) {
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value == 1 && !motion_detected) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_TIME) {
                char timestamp[64];
                struct tm *t = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

                char filename[128];
                snprintf(filename, sizeof(filename), "%s.jpg", timestamp);

                if (capture_image(filename) == 0) {
                    log_message("Image captured");
                    if (send_data(filename, timestamp, 1, GPIO_PIN, config.server_ip, config.server_port) == 0) {
                        log_message("Data sent");
                    } else {
                        log_message("Failed to send data");
                    }
                } else {
                    log_message("Failed to capture image");
                }

                last_motion_time = now;
                motion_detected = 1;
            }
        } else if (sensor_value == 0 && motion_detected) {
            motion_detected = 0;
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    gpioTerminate();
    log_message("Program terminated");
    fclose(log_file);

    return 0;
}

