#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT_MS 2000

// Global variables (minimize usage)
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_gpio(void);
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);
char* generate_filename(char *filename, size_t filename_size);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, exiting...");
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_EVENTS;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP; // Optional: Use pull-up resistor

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read GPIO value
int read_gpio(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Capture image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d -q %d --timeout %d --nopreview",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, IMAGE_TIMEOUT_MS);

    log_event(command);

    int status = system(command);
    if (status == -1) {
        perror("Error executing libcamera-still");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Generate timestamped filename
char* generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, "%Y%m%d_%H%M%S_%3N.jpg", timeinfo);
    return filename;
}

// Log event to file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Starting motion capture program...");

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_event("GPIO initialized successfully");

    // Main loop
    while (!terminate) {
        int value = read_gpio();
        if (value < 0) {
            log_event("Error reading GPIO, exiting...");
            break;
        }

        if (value == 0) { // Assuming active low
            log_event("Motion detected!");

            // Debounce
            usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Generate filename
            char filename[64];
            generate_filename(filename, sizeof(filename));
            char filepath[128];
            snprintf(filepath, sizeof(filepath), "%s/%s", IMAGE_DIR, filename);

            // Capture image
            if (capture_image(filepath) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Image captured: %s", filepath);
                log_event(log_message);
            } else {
                log_event("Image capture failed");
            }

            // Wait for a while before checking again
            sleep(1); // Avoid excessive triggering
        }

        usleep(10000); // Check every 10ms
    }

    // Cleanup and exit
    cleanup();
    log_event("Exiting program.");
    return 0;
}

