#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <unistd.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROPPED_SIZE (CROP_WIDTH * CROP_HEIGHT * 2)
#define OUTPUT_FILE "cropped.yuv"

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (fd != -1) {
        if (buffer != NULL) {
            munmap(buffer, buffer_size);
        }
        close(fd);
    }
    exit(EXIT_SUCCESS);
}

// Function to initialize the V4L2 device
static int init_device(const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = FIELD;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a single frame
static int capture_frame(void) {
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error in select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Verify frame details
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("Error getting format");
        return -1;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT || fmt.fmt.pix.pixelformat != PIXEL_FORMAT) {
        fprintf(stderr, "Error: Frame format does not match requested format\n");
        return -1;
    }

    return 0;
}

// Function to crop the frame
static void crop_frame(const void *input_buffer, void *output_buffer, int input_width, int input_height, int crop_x, int crop_y, int crop_width, int crop_height) {
    const unsigned char *input = (const unsigned char *)input_buffer;
    unsigned char *output = (unsigned char *)output_buffer;
    int i, j;

    for (i = 0; i < crop_height; i++) {
        for (j = 0; j < crop_width; j++) {
            // Copy 4 bytes (Y0, U, Y1, V) to avoid color corruption
            output[(i * crop_width + j) * 4] = input[((crop_y + i) * input_width + (crop_x + j)) * 2];
            output[(i * crop_width + j) * 4 + 1] = input[((crop_y + i) * input_width + (crop_x + j)) * 2 + 1];
            output[(i * crop_width + j) * 4 + 2] = input[((crop_y + i) * input_width + (crop_x + j)) * 2 + 2];
            output[(i * crop_width + j) * 4 + 3] = input[((crop_y + i) * input_width + (crop_x + j)) * 2 + 3];
        }
    }
}

// Function to save the cropped frame to a file
static int save_frame(const void *buffer, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, size, fp);
    if (bytes_written != size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(DEVICE_NAME) == -1) {
        return EXIT_FAILURE;
    }

    // Capture a single frame
    if (capture_frame() == -1) {
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the cropped frame
    void *cropped_buffer = malloc(CROPPED_SIZE);
    if (cropped_buffer == NULL) {
        perror("Error allocating memory for cropped frame");
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    crop_frame(buffer, cropped_buffer, WIDTH, HEIGHT, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT);

    // Save the cropped frame to a file
    if (save_frame(cropped_buffer, CROPPED_SIZE, OUTPUT_FILE) == -1) {
        free(cropped_buffer);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Clean up
    free(cropped_buffer);
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
    }
    if (munmap(buffer, buffer_size) == -1) {
        perror("Error unmapping buffer");
    }
    if (close(fd) == -1) {
        perror("Error closing device");
    }

    printf("Frame captured and saved to %s\n", OUTPUT_FILE);

    return EXIT_SUCCESS;
}

