#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <termios.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define neutral angle and PWM range
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int angle_to_pulse_width(int angle);
int set_servo_angle(int gpio, int angle);
void handle_input(int key);
void signal_handler(int signal);
void cleanup();

// Function to convert angle to pulse width
int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate error
    }
    return MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
}

// Function to set servo angle using pigpio
int set_servo_angle(int gpio, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width == -1) {
        return -1; // Propagate error
    }

    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width for GPIO %d.\n", gpio);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to handle user input
void handle_input(int key) {
    switch (key) {
        case 'w': // Up
            tilt_angle += 5;
            if (tilt_angle > MAX_ANGLE) tilt_angle = MAX_ANGLE;
            break;
        case 's': // Down
            tilt_angle -= 5;
            if (tilt_angle < MIN_ANGLE) tilt_angle = MIN_ANGLE;
            break;
        case 'a': // Left
            pan_angle -= 5;
            if (pan_angle < MIN_ANGLE) pan_angle = MIN_ANGLE;
            break;
        case 'd': // Right
            pan_angle += 5;
            if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
            break;
        case 'q': // Quit
            cleanup();
            exit(0);
            break;
        default:
            return; // Ignore other keys
    }

    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
        fprintf(stderr, "Error setting pan servo angle.\n");
    }
    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        fprintf(stderr, "Error setting tilt servo angle.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    cleanup();
    exit(0);
}

// Cleanup function to reset servos and terminate pigpio
void cleanup() {
    printf("Cleaning up and exiting...\n");
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set initial servo positions to neutral
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set terminal to non-blocking mode
    struct termios tty;
    tcgetattr(STDIN_FILENO, &tty);
    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_cc[VMIN] = 1;      // Read at least 1 character
    tty.c_cc[VTIME] = 0;     // No timeout
    tcsetattr(STDIN_FILENO, TCSANOW, &tty);

    printf("Pan-Tilt Camera Control\n");
    printf("Use 'w', 'a', 's', 'd' to move, 'q' to quit.\n");

    // Main loop
    while (1) {
        int key = getchar();
        handle_input(key);
        gpioDelay(100); // Delay to prevent excessive CPU usage
    }

    return 0;
}

