#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the water flow sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 19

// Calibration factor for the YF-S201 sensor (pulses per liter)
#define PULSES_PER_LITER 450.0

// I2C address of the HD44780 LCD
#define LCD_ADDR 0x27

// LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int sensor1_pulses = 0;
volatile int sensor2_pulses = 0;
volatile int sensor3_pulses = 0;

double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void sensor1_isr(int gpio, int level, uint32_t tick, void *user);
void sensor2_isr(int gpio, int level, uint32_t tick, void *user);
void sensor3_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulses);
void update_lcd(double flow_rate1, double flow_rate2, double flow_rate3, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void lcd_string(const char *str);
void lcd_clear();

// Interrupt service routine for sensor 1
void sensor1_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        sensor1_pulses++;
    }
}

// Interrupt service routine for sensor 2
void sensor2_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        sensor2_pulses++;
    }
}

// Interrupt service routine for sensor 3
void sensor3_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        sensor3_pulses++;
    }
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulses)
{
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to update the LCD display
void update_lcd(double flow_rate1, double flow_rate2, double flow_rate3, double total_volume)
{
    char buffer[32];

    lcd_clear();

    // Display flow rates
    snprintf(buffer, sizeof(buffer), "S1:%.2f LPM", flow_rate1);
    lcd_string(buffer);
    lcd_send_command(0xC0); // Move cursor to the second line
    snprintf(buffer, sizeof(buffer), "S2:%.2f LPM", flow_rate2);
    lcd_string(buffer);

    // Display total volume
    lcd_send_command(0x80); // Move cursor to the first line
    snprintf(buffer, sizeof(buffer), "Vol:%.2f L", total_volume);
    lcd_string(buffer);
    lcd_send_command(0xC0); // Move cursor to the second line
    snprintf(buffer, sizeof(buffer), "S3:%.2f LPM", flow_rate3);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR3_GPIO, RISING_EDGE, 0, NULL, NULL);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// LCD initialization function
int lcd_init()
{
    // Initialize I2C
    i2c_handle = i2cOpen(1, LCD_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD (4-bit mode)
    gpioDelay(50000); // Wait 50ms
    lcd_send_command(0x33); // Initialize
    gpioDelay(5000);  // Wait 5ms
    lcd_send_command(0x33); // Initialize
    gpioDelay(100);   // Wait 100us
    lcd_send_command(0x32); // 4-bit mode
    gpioDelay(100);   // Wait 100us
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    gpioDelay(100);   // Wait 100us
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    gpioDelay(100);   // Wait 100us
    lcd_send_command(0x06); // Increment cursor, no shift
    gpioDelay(100);   // Wait 100us
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);  // Wait 2ms

    return 0;
}

// LCD send command function
void lcd_send_command(unsigned char command)
{
    char data_u, data_l;
    unsigned char data_t[4];
	data_u = (command&0xF0);
	data_l = ((command<<4)&0xF0);
	data_t[0] = data_u|0x0C;  //en=1, rs=0
	data_t[1] = data_u|0x08;  //en=0, rs=0
	data_t[2] = data_l|0x0C;  //en=1, rs=0
	data_t[3] = data_l|0x08;  //en=0, rs=0
	i2cWriteDevice(i2c_handle, data_t, 4);
}

// LCD send data function
void lcd_send_data(unsigned char data)
{
    char data_u, data_l;
    unsigned char data_t[4];
	data_u = (data&0xF0);
	data_l = ((data<<4)&0xF0);
	data_t[0] = data_u|0x0D;  //en=1, rs=1
	data_t[1] = data_u|0x09;  //en=0, rs=1
	data_t[2] = data_l|0x0D;  //en=1, rs=1
	data_t[3] = data_l|0x09;  //en=0, rs=1
	i2cWriteDevice(i2c_handle, data_t, 4);
}

// LCD string function
void lcd_string(const char *str)
{
    int i;
    for (i = 0; str[i] != 0; i++)
    {
        lcd_send_data(str[i]);
    }
}

// LCD clear function
void lcd_clear()
{
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);        // Wait 2ms
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the water flow sensors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set up interrupts for the water flow sensors
    gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, sensor1_isr, NULL);
    gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, sensor2_isr, NULL);
    gpioSetISRFuncEx(SENSOR3_GPIO, RISING_EDGE, 0, sensor3_isr, NULL);

    // Initialize LCD
    if (lcd_init() != 0)
    {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Calculate flow rates
        double flow_rate1 = calculate_flow_rate(sensor1_pulses);
        double flow_rate2 = calculate_flow_rate(sensor2_pulses);
        double flow_rate3 = calculate_flow_rate(sensor3_pulses);

        // Calculate total volume
        total_volume += (flow_rate1 + flow_rate2 + flow_rate3) / 3.0 / 60.0; // Average flow rate per second

        // Log data to the console
        printf("Sensor 1: %.2f LPM, Sensor 2: %.2f LPM, Sensor 3: %.2f LPM, Total Volume: %.2f L\n",
               flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Update LCD display
        update_lcd(flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Reset pulse counters
        sensor1_pulses = 0;
        sensor2_pulses = 0;
        sensor3_pulses = 0;

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

