        double flow_rate3 = calculate_flow_rate(sensor3_pulses);

        // Calculate total volume
        total_volume += (flow_rate1 + flow_rate2 + flow_rate3) / 3.0 / 60.0; // Average flow rate per second

        // Log data to the console
        printf("Sensor 1: %.2f LPM, Sensor 2: %.2f LPM, Sensor 3: %.2f LPM, Total Volume: %.2f L\n",
               flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Update LCD display
        update_lcd(flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Reset pulse counters
        sensor1_pulses = 0;
        sensor2_pulses = 0;
        sensor3_pulses = 0;

        // Wait for 1 second
        sleep(1);
    }

    return 0;
