    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused
    pulse_count++;
}

// Calculate wind speed
float calculate_wind_speed(int pulses)
{
    return (float)pulses * 0.5; // m/s
}

// Read wind direction from MCP3008
int read_wind_direction(int spi_handle)
{
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_wind_direction\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Check for sensor absent conditions
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: Wind vane sensor reading is stuck at %d\n", adc_value);
    }

    // Map ADC value to degrees (0-359)
