#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27

// Define the I2C bus and address for the LCD1602 display
#define I2C_BUS 1
#define I2C_ADDR 0x27

// Define the calibration factor for the YF-S201 sensor (pulses per liter)
#define CALIBRATION_FACTOR 7.5

// Define the number of pulses to consider the sensor absent
#define ABSENT_THRESHOLD 10

// Global variables for pulse counts and I2C handle
volatile int sensor1_pulses = 0;
volatile int sensor2_pulses = 0;
volatile int sensor3_pulses = 0;
int i2c_handle;

// Function prototypes
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void sensor3_callback(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate1, float flow_rate2, float flow_rate3);
void signal_handler(int signal);
int lcd_init();
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void lcd_string(const char *str);
void lcd_clear();

// Structure to hold sensor data
typedef struct {
    int gpio;
    volatile int *pulses;
    void (*callback)(int, int, uint32_t);
} sensor_t;

// Array of sensor structures
sensor_t sensors[] = {
    {SENSOR1_GPIO, &sensor1_pulses, sensor1_callback},
    {SENSOR2_GPIO, &sensor2_pulses, sensor2_callback},
    {SENSOR3_GPIO, &sensor3_pulses, sensor3_callback}
};

int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].gpio, PI_INPUT);
        gpioSetPullUpDown(sensors[i].gpio, PI_PUD_UP);
    }

    // Set up interrupt handlers for each sensor
    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetAlertFuncEx(sensors[i].gpio, sensors[i].callback, NULL) != 0) {
            fprintf(stderr, "Failed to set alert function for GPIO %d\n", sensors[i].gpio);
            gpioTerminate();
            return 1;
        }
    }

    // Initialize I2C communication with the LCD1602 display
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the LCD display
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Reset pulse counts
        sensor1_pulses = 0;
        sensor2_pulses = 0;
        sensor3_pulses = 0;

        // Wait for 1 second
        time_sleep(1.0);

        // Calculate flow rates
        float flow_rate1 = calculate_flow_rate(sensor1_pulses);
        float flow_rate2 = calculate_flow_rate(sensor2_pulses);
        float flow_rate3 = calculate_flow_rate(sensor3_pulses);

        // Display flow rates on the LCD
        display_flow_rate(flow_rate1, flow_rate2, flow_rate3);
    }

    return 0;
}

