#include <signal.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip4"
#define SENSOR_LINE 4
#define LED_LINE 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void control_led(struct gpiod_line *line, int state);
void log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control the LED
void control_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

// Function to log an event with timestamp
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s, trying gpiochip0\n", GPIOCHIP);
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip gpiochip0: %s\n", strerror(errno));
            return 1;
        }
    }

    // Get GPIO lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "proximity_sensor";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "proximity_led";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(sensor_line, &input_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(led_line, &output_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int last_sensor_value = 1; // Initialize to HIGH (no object detected)
    while (1) {
        int sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            // Handle sensor read error, maybe exit or retry
            fprintf(stderr, "Sensor read error, exiting...\n");
            break;
        }

        // Detect falling edge (object detected)
        if (sensor_value == 0 && last_sensor_value == 1) {
            control_led(led_line, 1); // Turn LED ON
            log_event("Object detected");
            gpiod_line_set_value(led_line, 1);
            gpiod_line_set_value(led_line, 0); // Turn LED OFF
        }

        last_sensor_value = sensor_value;
        gpiod_line_delay(100); // Poll every 100 ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

