#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22
#define COMMAND_REG 0x30
#define ALS_FORCE_CMD 0x06
#define PS_FORCE_CMD 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    uint8_t hw_key;
    uint8_t ch_list;
} sensor_config_t;

// Function to write a byte to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the sensor
int init_sensor() {
    uint8_t part_id;

    // Verify PART_ID
    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading PART_ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure sensor
    sensor_config_t config = {0x17, 0x77}; // HW_KEY and CH_LIST

    if (write_register(i2c_handle, HW_KEY_REG, config.hw_key) != 0) return -1;
    if (write_register(i2c_handle, CH_LIST_REG, config.ch_list) != 0) return -1;

    return 0;
}

// Function to read sensor data
int read_sensor_data(int *proximity, int *ambient_light) {
    uint8_t ps1_low, ps1_high, als_vis_low, als_vis_high;

    // Trigger ALS measurement
    if (write_register(i2c_handle, COMMAND_REG, ALS_FORCE_CMD) != 0) return -1;
    gpioDelay(10); // Wait for measurement

    // Trigger PS measurement
    if (write_register(i2c_handle, COMMAND_REG, PS_FORCE_CMD) != 0) return -1;
    gpioDelay(10); // Wait for measurement

    // Read PS1 data
    if (read_register(i2c_handle, PS1_DATA_REG, &ps1_low) != 0) return -1;
    if (read_register(i2c_handle, PS1_DATA_REG + 1, &ps1_high) != 0) return -1;
    *proximity = (ps1_high << 8) | ps1_low;

    // Read ALS_VIS data
    if (read_register(i2c_handle, ALS_VIS_DATA_REG, &als_vis_low) != 0) return -1;
    if (read_register(i2c_handle, ALS_VIS_DATA_REG + 1, &als_vis_high) != 0) return -1;
    *ambient_light = (als_vis_high << 8) | als_vis_low;

    return 0;
}

// Function to log data to a file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

