#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define WATERING_THRESHOLD 15.0 // cm
#define TIMEOUT_US 30000       // 30 ms

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold echo start and end times
typedef struct {
    uint32_t start_sec;
    uint32_t start_micros;
    uint32_t end_sec;
    uint32_t end_micros;
    int valid;
} echo_data_t;

echo_data_t echo_data = {0, 0, 0, 0, 0};

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start_sec, uint32_t start_micros, uint32_t end_sec, uint32_t end_micros);
void log_message(const char *message);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    uint32_t sec, micros;
    gpioTime(0, &sec, &micros);

    if (level == 1) {
        // Rising edge
        echo_data.start_sec = sec;
        echo_data.start_micros = micros;
        echo_data.valid = 0; // Reset valid flag on rising edge
    } else if (level == 0) {
        // Falling edge
        echo_data.end_sec = sec;
        echo_data.end_micros = micros;
        echo_data.valid = 1; // Set valid flag on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start_sec, uint32_t start_micros, uint32_t end_sec, uint32_t end_micros) {
    uint32_t diff_sec = end_sec - start_sec;
    uint32_t diff_micros = end_micros - start_micros;

    if (end_micros < start_micros) {
        diff_sec--;
        diff_micros += 1000000;
    }

    double pulse_seconds = (double)diff_sec + (double)diff_micros / 1000000.0;
    double distance = (pulse_seconds * SPEED_OF_SOUND) / 2.0;
    return distance;
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for echo data with timeout
        int timeout_counter = 0;
        while (!echo_data.valid && timeout_counter < TIMEOUT_US / 10 && running) {
            gpioDelay(10); // Check every 10 us
            timeout_counter++;
        }

        if (!running) break;

        if (!echo_data.valid) {
            log_message("Timeout waiting for echo.");
        } else {
            // Calculate distance
            double distance = calculate_distance(echo_data.start_sec, echo_data.start_micros, echo_data.end_sec, echo_data.end_micros);

            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                char message[100];
                snprintf(message, sizeof(message), "Distance: %.2f cm", distance);
                log_message(message);

                // Check if watering is needed
                if (distance < WATERING_THRESHOLD) {
                    log_message("Time to water the plant!");
                }
            } else {
                char message[100];
                snprintf(message, sizeof(message), "Invalid distance: %.2f cm", distance);
                log_message(message);
            }
        }

        // Reset echo data for next measurement
        echo_data.valid = 0;

        // Wait for 60 seconds
        gpioDelay(60000000); // 60 seconds
    }

    // Clean up
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    return 0;
}

