        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;

    // Read Part ID
    if (i2c_read_reg(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, MEAS_RATE0_REG, MEAS_RATE_VALUE) != 0) {
        fprintf(stderr, "Error writing MEAS_RATE0\n");
        return -1;
    }

    // Reset and start measurement
    if (i2c_write_reg(fd, COMMAND_REG, RESET_COMMAND) != 0) {
        fprintf(stderr, "Error writing COMMAND\n");
        return -1;
    }

    return 0;
}

// Read proximity data function
int read_proximity_data(int fd, uint16_t *proximity) {
    uint8_t data0, data1;

    if (i2c_read_reg(fd, PS_DATA0_REG, &data0) != 0) {
        fprintf(stderr, "Error reading PS_DATA0\n");
        return -1;
    }
    if (i2c_read_reg(fd, PS_DATA1_REG, &data1) != 0) {
        fprintf(stderr, "Error reading PS_DATA1\n");
        return -1;
    }

    *proximity = (uint16_t)((data1 << 8) | data0);
    return 0;
}

// Calculate BPM (Placeholder)
float calculate_bpm(uint16_t proximity) {
    // This is a placeholder.  A real BPM calculation would involve
    // analyzing the proximity signal over time.
    return (float)proximity / 10.0; // Example: Scale proximity to BPM
}

// Log data function
void log_data(FILE *fp, uint16_t proximity, float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    uint16_t proximity;
    float bpm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen("heartrate.csv", "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        if (read_proximity_data(i2c_fd, &proximity) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(proximity);

            // Log data
            log_data(csv_file, proximity, bpm);
        } else {
            fprintf(stderr, "Failed to read proximity data, skipping sample\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

