#define I2C_BUS 1
#define CH101_ADDR 0x45
#define TRIGGER_CMD 0x00
#define MEASUREMENT_DELAY_US 50000 // 50 ms
#define SAMPLE_DELAY_MS 200

int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0
    unsigned char buffer[2];
    int distance_mm;

    while (!terminate) {
        // Trigger measurement
        if (i2cWriteByte(i2c_handle, TRIGGER_CMD) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            gpioDelay(MEASUREMENT_DELAY_US);

            // Read distance
            if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
                distance_mm = (buffer[0] << 8) | buffer[1];

                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log to file
                fprintf(log_file, "%s, %d\n", timestamp, distance_mm);
                fflush(log_file); // Ensure data is written to disk

                // Print to stdout
                printf("%s, %d\n", timestamp, distance_mm);
            } else {
                fprintf(stderr, "Failed to read distance\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

