    // Example: Read two bytes from register 0x00 (adjust based on datasheet)
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Convert the raw data to a distance value (adjust based on datasheet)
    int raw_distance = (buffer[0] << 8) | buffer[1];
    *distance = (float)raw_distance * 0.1; // Example conversion

