#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, uint8_t reg, uint16_t *data);
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int handle, uint8_t reg, uint16_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *data = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retry %d: %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to file
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint16_t proximity, ambient;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data.\n");
        }
        if (read_sensor_data(i2c_handle, AMBIENT_REG, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient data.\n");
        }

        // Log data
        if (log_data(log_file, proximity, ambient) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

