#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_HIGH_REG 0x01
#define DISTANCE_LOW_REG 0x02
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
FILE *log_file;
int distance_threshold = DEFAULT_THRESHOLD;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance);
void control_led(int distance);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int led_gpio;
    int distance_threshold;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the sensor
int initialize_sensor() {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    printf("WHO_AM_I value: 0x%02X\n", who_am_i);

    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control the LED based on distance
void control_led(int distance) {
    if (distance < distance_threshold) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main(int argc, char *argv[]) {
    int distance;

    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Using distance threshold: %d mm\n", distance_threshold);
    } else {
        printf("Using default distance threshold: %d mm\n", DEFAULT_THRESHOLD);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

