    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(50); // 50 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
