#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY_MS 100
#define COMMAND_FRAME_SIZE 4
#define RESPONSE_FRAME_SIZE 15

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} SensorContext;

// Function prototypes
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int request_distance_measurement(int fd);
int parse_distance(unsigned char *data, int *distance);
float calculate_average_distance(int *distances, int count);
int log_intrusion(FILE *fp, float average_distance);
void signal_handler(int signal);
int setup_i2c(const char *bus);

// Global sensor context
SensorContext context = {0};

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to request a distance measurement
int request_distance_measurement(int fd) {
    unsigned char command_frame[COMMAND_FRAME_SIZE] = {0x50, 0x0A, 0x00, 0x01};
    if (i2c_write(fd, command_frame, COMMAND_FRAME_SIZE) != 0) {
        fprintf(stderr, "Failed to write command frame\n");
        return -1;
    }
    usleep(10000); // 10 ms delay
    return 0;
}

// Function to parse the distance from the response frame
int parse_distance(unsigned char *data, int *distance) {
    if (data[0] != 0x50) {
        fprintf(stderr, "Invalid header byte: 0x%02X\n", data[0]);
        return -1;
    }

    *distance = (data[11] << 8) | data[12];
    return 0;
}

// Function to calculate the average distance
float calculate_average_distance(int *distances, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += distances[i];
    }
    return sum / count;
}

// Function to log an intrusion event
int log_intrusion(FILE *fp, float average_distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Average Distance: %.2f mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, average_distance);
    fflush(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    context.running = 0;
}

// Function to setup I2C communication
int setup_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    context.i2c_fd = setup_i2c(I2C_BUS);
    if (context.i2c_fd < 0) {
        return 1;
    }

    // Open log file
    context.log_file = fopen("intrusion_log.txt", "a");
    if (context.log_file == NULL) {
        perror("Failed to open log file");
        close(context.i2c_fd);
        return 1;
    }

    context.running = 1;

    while (context.running) {
        int distances[SAMPLE_COUNT];
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            if (request_distance_measurement(context.i2c_fd) != 0) {
                fprintf(stderr, "Failed to request distance measurement\n");
                continue; // Skip to the next sample
            }

            unsigned char response_frame[RESPONSE_FRAME_SIZE];
            if (i2c_read(context.i2c_fd, response_frame, RESPONSE_FRAME_SIZE) != 0) {
                fprintf(stderr, "Failed to read response frame\n");
                continue; // Skip to the next sample
            }

            if (parse_distance(response_frame, &distances[i]) != 0) {
                fprintf(stderr, "Failed to parse distance\n");
                continue; // Skip to the next sample
            }
        }

        float average_distance = calculate_average_distance(distances, SAMPLE_COUNT);

        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(context.log_file, average_distance);
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
        }

        usleep(SAMPLE_DELAY_MS * 1000); // 100 ms delay
    }

    // Cleanup
    close(context.i2c_fd);
    fclose(context.log_file);

    return 0;
}

