#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, int reg)
{
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return data;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, int reg, int data)
{
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C register (little-endian)
int i2c_read_word(int handle, int reg)
{
    int data = i2cReadWordData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return data;
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int model_id = i2c_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Start a single measurement
        if (i2c_write_byte(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Error starting measurement.\n");
            continue; // Continue to the next iteration
        }

        // Poll for measurement completion with timeout
        int timeout = 100; // 100 ms timeout
        while (timeout > 0) {
            int interrupt_status = i2c_read_byte(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
            if (interrupt_status < 0) {
                fprintf(stderr, "Error reading interrupt status.\n");
                break; // Exit the inner loop
            }
            if (interrupt_status & 0x01) {
                break; // Measurement complete
            }
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            continue; // Continue to the next iteration
        }

        // Read the distance
        int distance = i2c_read_word(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance.\n");
            continue; // Continue to the next iteration
        }

        // Clear the interrupt
        if (i2c_write_byte(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Error clearing interrupt.\n");
        }

        // Get timestamp
        char timestamp[20];
        get_timestamp(timestamp);

        // Print the distance
        printf("%s Distance: %d mm\n", timestamp, distance);

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

