        char timestamp[20];
        get_timestamp(timestamp);

        // Print the distance
        printf("%s Distance: %d mm\n", timestamp, distance);

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

