#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define SCALE_FACTOR 0.125

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device is present
    unsigned char test_reg = DISTANCE_REG;
    if (write(i2c_fd, &test_reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device. Device might not be present.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    while (keep_running) {
        unsigned char reg = DISTANCE_REG;
        unsigned char buffer[2];
        int16_t raw_distance;
        float distance_mm;

        // Read distance register
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Error writing to I2C device");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Error reading from I2C device");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Convert to signed 16-bit integer (little-endian)
        raw_distance = (int16_t)((buffer[1] << 8) | buffer[0]);

        // Convert to millimeters
        distance_mm = raw_distance * SCALE_FACTOR;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

