        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg_addr);
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
