#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 200000      // 200 ms
#define MIN_PULSE_US 20        // 20 us
#define MAX_PULSE_US 15400     // 15.4 ms (38 cm)

// Global variables
static volatile int running = 1;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
float calculate_distance(uint32_t pulse_width);
void log_data(float distance);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance data with a timestamp
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Flag that rising edge was received
        } else if (level == 0) {
            if (echo_received) {
                echo_end_tick = tick;
                echo_received = 0; // Reset the flag
            }
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(1000); // Wait 1 second

        // Calculate pulse width
        uint32_t pulse_width = echo_end_tick - echo_start_tick;

        // Error handling
        if (pulse_width == 0) {
            fprintf(stderr, "Error: No echo received within timeout.\n");
        } else if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse width exceeded timeout.\n");
        } else if (pulse_width < MIN_PULSE_US || pulse_width > MAX_PULSE_US) {
            fprintf(stderr, "Error: Invalid pulse width: %u us\n", pulse_width);
        } else {
            // Calculate and log distance
            float distance = calculate_distance(pulse_width);
            log_data(distance);
        }
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

