                echo_received = 0; // Reset the flag
            }
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(1000); // Wait 1 second

        // Calculate pulse width
        uint32_t pulse_width = echo_end_tick - echo_start_tick;

        // Error handling
        if (pulse_width == 0) {
            fprintf(stderr, "Error: No echo received within timeout.\n");
        } else if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse width exceeded timeout.\n");
        } else if (pulse_width < MIN_PULSE_US || pulse_width > MAX_PULSE_US) {
            fprintf(stderr, "Error: Invalid pulse width: %u us\n", pulse_width);
        } else {
            // Calculate and log distance
            float distance = calculate_distance(pulse_width);
            log_data(distance);
        }
    }

