#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0 // meters
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define RANGE_BINS 64
#define FRAME_SIZE (8 + (RANGE_BINS * 2)) // Magic word (8 bytes) + range profile data (64 * 2 bytes)
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Function prototypes
int uart_init(uart_config_t *config);
int read_radar_data(int fd, short *range_profile);
float process_range_profile(const short *range_profile);
int detect_intrusion(float distance);
void activate_led(int gpio_pin);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int uart_init(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting termios attributes");
        close(config->fd);
        return -1;
    }

    config->tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 115200 baud, 8 data bits, no parity, 1 stop bit
    config->tty.c_iflag = IGNPAR;                           // Ignore parity errors
    config->tty.c_oflag = 0;
    config->tty.c_lflag = 0;                               // Non-canonical mode
    config->tty.c_cc[VMIN] = FRAME_SIZE;                      // Read at least FRAME_SIZE bytes
    config->tty.c_cc[VTIME] = 5;                             // Timeout of 0.5 seconds

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        perror("Error setting termios attributes");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Read radar data from UART
int read_radar_data(int fd, short *range_profile) {
    unsigned char buffer[FRAME_SIZE];
    ssize_t bytes_read = read(fd, buffer, FRAME_SIZE);

    if (bytes_read != FRAME_SIZE) {
        if (bytes_read < 0) {
            perror("Error reading from UART");
        } else {
            fprintf(stderr, "Incomplete frame received (%zd bytes)\n", bytes_read);
        }
        return -1;
    }

    // Validate magic word
    unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(buffer, magic_word, sizeof(magic_word)) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    // Convert range profile data to short integers
    for (int i = 0; i < RANGE_BINS; i++) {
        range_profile[i] = (short)((buffer[8 + (i * 2 + 1)] << 8) | buffer[8 + (i * 2)]);
    }

    return 0;
}

// Process range profile data to calculate distance
float process_range_profile(const short *range_profile) {
    // Find the index of the maximum value in the range profile
    int max_index = 0;
    for (int i = 1; i < RANGE_BINS; i++) {
        if (range_profile[i] > range_profile[max_index]) {
            max_index = i;
        }
    }

    // Calculate the distance in meters
    float distance = max_index * RANGE_RESOLUTION;
    return distance;
}

// Detect intrusion based on distance threshold
int detect_intrusion(float distance) {
    return (distance <= INTRUSION_THRESHOLD) ? 1 : 0;
}

// Activate LED for 2 seconds
void activate_led(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(2000);        // Wait for 2 seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Log intrusion event to file
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (uart_fd != -1) {
        close(uart_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    uart_config_t uart_config;
    short range_profile[RANGE_BINS];
    float distance;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Ensure LED is off initially

    // Initialize UART
    if (uart_init(&uart_config) != 0) {
        gpioTerminate();
        return 1;
    }
    uart_fd = uart_config.fd;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Radar intrusion detection system started.\n");

    while (program_running) {
        // Read radar data
        if (read_radar_data(uart_config.fd, range_profile) == 0) {
            // Process range profile
            distance = process_range_profile(range_profile);

            // Detect intrusion
            if (detect_intrusion(distance)) {
                printf("Intrusion detected! Distance: %.4f meters\n", distance);

                // Activate LED
                activate_led(GPIO_LED);

                // Log intrusion
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Error reading radar data. Retrying...\n");
        }

        gpioDelay(100); // Delay to avoid overwhelming the system
    }

    // Cleanup and exit
    cleanup();
    printf("Radar intrusion detection system stopped.\n");
    return 0;
}

