#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor_line;
struct gpiod_line *buzzer_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void control_buzzer(struct gpiod_line *line, int state);
void log_event(const char *timestamp, int sensor_value);
void signal_handler(int sig);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value;
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control the buzzer
void control_buzzer(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Function to log events to a file
void log_event(const char *timestamp, int sensor_value) {
    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s, %d\n", timestamp, sensor_value);
    fclose(fp);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    int sensor_value, previous_sensor_value = -1; // Initialize to an invalid value
    char *timestamp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request sensor line for input
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "obstacle_detector";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buzzer line for output
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "obstacle_detector";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &output_config, 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            // Handle read error, but continue to avoid program termination
            gpiod_line_release(sensor_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check for state change
        if (sensor_value != previous_sensor_value) {
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_event(timestamp, sensor_value);
                free(timestamp); // Free the allocated memory
            }
            control_buzzer(buzzer_line, sensor_value); // Buzzer on if obstacle detected (sensor_value == 0)
            previous_sensor_value = sensor_value;
        }

        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_request(sensor_line, &input_config, 0);
        gpiod_line_request(buzzer_line, &output_config, 0);

        struct timespec delay = {0, 100000000}; // 100 ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

