    if (gpiod_line_request(sensor_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buzzer line for output
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "obstacle_detector";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &output_config, 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            // Handle read error, but continue to avoid program termination
            gpiod_line_release(sensor_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check for state change
        if (sensor_value != previous_sensor_value) {
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_event(timestamp, sensor_value);
                free(timestamp); // Free the allocated memory
            }
            control_buzzer(buzzer_line, sensor_value); // Buzzer on if obstacle detected (sensor_value == 0)
            previous_sensor_value = sensor_value;
        }

        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_request(sensor_line, &input_config, 0);
        gpiod_line_request(buzzer_line, &output_config, 0);

        struct timespec delay = {0, 100000000}; // 100 ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

