#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance(uint16_t *distance);
float convert_to_cm(uint16_t distance);
int log_distance(float distance);
int set_alert_gpio(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int alert_gpio;
    float distance_threshold;
    int sample_interval_ms;
    char *log_file;
} Config;

Config config = {
    I2C_BUS,
    I2C_ADDRESS,
    ALERT_GPIO,
    DISTANCE_THRESHOLD,
    SAMPLE_INTERVAL_MS,
    LOG_FILE
};

int main() {
    uint16_t distance_raw;
    float distance_cm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance_raw) != 0) {
            fprintf(stderr, "Failed to read distance. Continuing.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay even on error
            continue;
        }

        // Convert to cm
        distance_cm = convert_to_cm(distance_raw);

        // Log distance
        if (log_distance(distance_cm) != 0) {
            fprintf(stderr, "Failed to log distance. Continuing.\n");
        }

        // Set alert GPIO
        if (set_alert_gpio(distance_cm) != 0) {
            fprintf(stderr, "Failed to set alert GPIO. Continuing.\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio, I2C, and GPIO
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(config.alert_gpio, PI_OUTPUT);

    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    // Read high byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %s\n", strerror(errno));
        return 1;
    }

    // Combine high and low bytes
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw distance to centimeters
float convert_to_cm(uint16_t distance) {
    // Assuming a linear relationship for simplicity.
    // Adjust the scaling factor based on the sensor's datasheet.
    return (float)distance * 0.1; // Example scaling factor
}

// Log distance to file with ISO 8601 timestamp
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s, %.2f cm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Set alert GPIO based on distance
int set_alert_gpio(float distance) {
    if (distance < config.distance_threshold) {
        gpioWrite(config.alert_gpio, 1); // Set GPIO HIGH
    } else {
        gpioWrite(config.alert_gpio, 0); // Set GPIO LOW
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

