#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x007
#define VL53L1X_REG_SYSRANGE__START 0x000
#define VL53L1X_REG_RESULT__INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT__RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM__INTERRUPT_CLEAR 0x014

// File path for logging
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void print_parking_guidance(uint16_t distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;
    uint8_t model_id;

    // Check if the sensor is present
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    // Poll SYSRANGE__START register until it self-clears
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE__START);
        if (status < 0) {
            fprintf(stderr, "Error reading SYSRANGE__START: %d\n", status);
            return -1;
        }
        if ((status & 0x01) == 0) {
            break; // Self-cleared
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for SYSRANGE__START to clear\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(uint16_t *distance) {
    int status;
    uint8_t data[2];

    // Poll RESULT__INTERRUPT_STATUS register until data-ready
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT__INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading RESULT__INTERRUPT_STATUS: %d\n", status);
            return -1;
        }
        if ((status & 0x01) != 0) {
            break; // Data ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data-ready\n");
        return -1;
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT__RANGE_STATUS + 10, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    // Clear interrupt
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM__INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error clearing interrupt: %d\n", status);
        return -1;
    }

    return 0;
}

// Log distance to file function
void log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file exists
    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (fp) {
        fclose(fp);
    }

    // Open the file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    // Write header if the file is new
    if (!file_exists) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    // Write the data
    fprintf(log_file, "%s,%u\n", timestamp, distance);

    // Close the file
    fclose(log_file);
}

// Print parking guidance message function
void print_parking_guidance(uint16_t distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance >= 300 && distance < 600) {
        printf("APPROACH\n");
    } else if (distance >= 600 && distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            log_distance(distance);
            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100); // Wait 100 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

