#define MIN_DISTANCE 50.0  // mm
#define MAX_DISTANCE 500.0 // mm
#define MIN_FREQUENCY 1.0  // Hz
#define MAX_FREQUENCY 10.0 // Hz
#define BLINK_DURATION 100 // ms
#define SAMPLE_INTERVAL 100 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(float *distance);
float map_distance_to_frequency(float distance);
void blink_led(int gpio, float frequency, int duration_ms);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            uint16_t raw_distance = (buf[0] << 8) | buf[1];
            *distance = (float)raw_distance / 10.0; // Convert to mm
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (error %d), retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to map distance to blink frequency
float map_distance_to_frequency(float distance) {
    if (distance <= MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance >= MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        return MAX_FREQUENCY - (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to blink the LED
void blink_led(int gpio, float frequency, int duration_ms) {
    int period_ms = (int)(1000.0 / frequency);
    int half_period_ms = period_ms / 2;

    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(half_period_ms * 1000); // Delay for half the period
    gpioWrite(gpio, 0); // Turn LED off
    gpioDelay(half_period_ms * 1000); // Delay for half the period
}

