    float frequency;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = map_distance_to_frequency(distance);
            blink_led(LED_GPIO, frequency, BLINK_DURATION);

