            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data
            printf("%s, Distance: %.2f mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for sample interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

