#define TRIGGER_COMMAND 0x00
#define MEASUREMENT_DELAY_US 10000 // 10ms
#define READ_DELAY_US 100000       // 100ms
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000       // 10ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_distance(unsigned short *distance);
void log_data(unsigned short distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, TRIGGER_COMMAND);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error triggering measurement (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read distance
int read_distance(unsigned short *distance) {
    char buffer[2];
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result == 2) {
            *distance = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading distance (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

