    time_t now = time(NULL);
    fprintf(log_file, "%ld,%u\n", now, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    unsigned short distance;
    while (!terminate) {
        if (trigger_measurement() == 0) {
            gpioDelay(MEASUREMENT_DELAY_US);
            if (read_distance(&distance) == 0) {
                log_data(distance);
            } else {
                fprintf(stderr, "Failed to read distance.\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement.\n");
        }
        gpioDelay(READ_DELAY_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

