#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50

// Global variables for sensor states and file pointer
int sensor1_state = 1; // Assume initially clear
int sensor2_state = 1; // Assume initially clear
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Function to read sensor value with debouncing
int read_sensor(int gpio) {
    int reading = gpioRead(gpio);
    gpioDelay(DEBOUNCE_MS * 1000); // Debounce
    return reading;
}

// Function to log events to file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_GPIO\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_GPIO\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == 0 && sensor1_state == 1) {
            log_event(1, "DETECTED");
            sensor1_state = 0;
        } else if (sensor1_value == 1 && sensor1_state == 0) {
            log_event(1, "CLEARED");
            sensor1_state = 1;
        }

        if (sensor2_value == 0 && sensor2_state == 1) {
            log_event(2, "DETECTED");
            sensor2_state = 0;
        } else if (sensor2_value == 1 && sensor2_state == 0) {
            log_event(2, "CLEARED");
            sensor2_state = 1;
        }

        gpioDelay(10 * 1000); // Poll every 10 ms
    }

    return 0; // This line will not be reached due to the infinite loop
}

