// Define sensor registers
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

// Define I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x49

// Define timeout for data ready status
#define DATA_READY_TIMEOUT_MS 50

// Define sampling interval
#define SAMPLING_INTERVAL_MS 500

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int distance_mm;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int i2c_read_word(int fd, unsigned char reg);
int trigger_measurement(int fd);
int is_data_ready(int fd);
int read_distance(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t size);
int log_data(FILE *fp, const char *timestamp, int distance_mm);
void signal_handler(int signum);

// I2C read register function
int i2c_read_register(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    int value = i2c_read_word(fd, reg);
    return value;
}

// I2C write register function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for word read");
        return -1;
    }
    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read word");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Trigger measurement function
int trigger_measurement(int fd) {
    return i2c_write_register(fd, MEAS_TRIGGER, 0x01);
}

// Check if data is ready function
int is_data_ready(int fd) {
    int status = i2c_read_register(fd, MEAS_STATUS);
    if (status < 0) {
        return -1; // Indicate error
    }
    return (status & 0x01) ? 1 : 0;
}

// Read distance function
int read_distance(int fd) {
    int distance = i2c_read_word(fd, DIST_HIGH);
    if (distance < 0) {
        return -1; // Indicate error
    }
    return distance;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp(char* timestamp_str, size_t size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

