    if (fprintf(fp, "%s,%d\n", timestamp, distance_mm) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            continue; // Skip to next iteration
        }

        // Wait for data ready with timeout
        int timeout_counter = 0;
        while (!is_data_ready(i2c_fd) && timeout_counter < DATA_READY_TIMEOUT_MS) {
            usleep(1000); // 1 ms delay
            timeout_counter++;
        }

        if (timeout_counter >= DATA_READY_TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue; // Skip to next iteration
        }

        // Read distance
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            continue; // Skip to next iteration
        }

        // Get timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, distance) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for next sample
        usleep(SAMPLING_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Clean up
    close(i2c_fd);
    fflush(log_file);
    fclose(log_file);

    return 0;
}

