#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Register addresses (Example - adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L5CX_REG_SYSTEM_START 0x0008
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L5CX_REG_RESULT_SPAD_NB_DETECTED 0x0083
#define VL53L5CX_REG_RESULT_PEAK_SIGNAL_RATE 0x0081
#define VL53L5CX_REG_RESULT_AMBIENT_RATE 0x0080
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM 0x0096
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L5CX_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD 0x001E
#define VL53L5CX_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE 0x001F
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L5CX_REG_SYSTEM_MODE_GPIO1 0x0010
#define VL53L5CX_REG_SYSTEM_MODE_GPIO0 0x000F
#define VL53L5CX_REG_SYSTEM_FIRMWARE_CHAR 0x0006
#define VL53L5CX_REG_SYSTEM_INTERRUPT_STATUS 0x0087
#define VL53L5CX_REG_RESULT_SPAD_MAP 0x0084
#define VL53L5CX_REG_RESULT_DISTANCE 0x0090

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    stop_flag = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, unsigned short reg, unsigned char value) {
    unsigned char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, unsigned short reg, unsigned char *value) {
    unsigned char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    if (write(fd, buf, 2) != 2) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C register
int i2c_read_word(int fd, unsigned short reg, unsigned short *value) {
    unsigned char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    if (write(fd, buf, 2) != 2) {
        perror("I2C write (address) failed");
        return -1;
    }

    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to initialize the VL53L5CX sensor
int vl53l5cx_init(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    if (i2c_write_byte(fd, VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L5CX_ADDR) != 0) return -1;
    if (i2c_write_byte(fd, VL53L5CX_REG_SYSTEM_START, 0x01) != 0) return -1; // Start the sensor
    usleep(10000); // Wait for startup

    // Configure ROI (Region of Interest) for 8x8 grid
    if (i2c_write_byte(fd, VL53L5CX_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD, 0x80) != 0) return -1; // Center SPAD
    if (i2c_write_byte(fd, VL53L5CX_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE, 0x08) != 0) return -1; // 8x8 grid

    return 0;
}

// Function to read distance data from the VL53L5CX sensor
int vl53l5cx_read_distances(int fd, unsigned short *distances) {
    // Read distance data for each of the 64 zones
    for (int i = 0; i < 64; i++) {
        unsigned char distance_msb, distance_lsb;
        unsigned short distance;

        // Calculate the register address for the current zone's distance data
        unsigned short distance_reg = VL53L5CX_REG_RESULT_DISTANCE + (i * 2); // Each zone's data is 2 bytes apart

        // Read the MSB and LSB of the distance
        if (i2c_read_byte(fd, distance_reg, &distance_msb) != 0) return -1;
        if (i2c_read_byte(fd, distance_reg + 1, &distance_lsb) != 0) return -1;

        // Combine the MSB and LSB to get the distance in millimeters
        distance = (distance_msb << 8) | distance_lsb;

        distances[i] = distance;
    }
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the VL53L5CX sensor
    if (vl53l5cx_init(i2c_fd) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("VL53L5CX sensor initialized successfully\n");

    // Main loop
    while (!stop_flag) {
        unsigned short distances[64];

        // Read distance data
        if (vl53l5cx_read_distances(i2c_fd, distances) == 0) {
            // Print distance data
            for (int i = 0; i < 64; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
        } else {
            fprintf(stderr, "Failed to read distance data\n");
        }

        // Wait for 500 ms
        usleep(500000); // 500 ms
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated\n");
    return 0;
}

