        // Read the MSB and LSB of the distance
        if (i2c_read_byte(fd, distance_reg, &distance_msb) != 0) return -1;
        if (i2c_read_byte(fd, distance_reg + 1, &distance_lsb) != 0) return -1;

        // Combine the MSB and LSB to get the distance in millimeters
        distance = (distance_msb << 8) | distance_lsb;

        distances[i] = distance;
    }
    return 0;
}

int main() {
