    if (vl53l5cx_init(i2c_fd) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("VL53L5CX sensor initialized successfully\n");

    // Main loop
    while (!stop_flag) {
        unsigned short distances[64];

        // Read distance data
        if (vl53l5cx_read_distances(i2c_fd, distances) == 0) {
