    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (result >= 0) {
            *distance = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

