    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        int distance;

        // Read distance data
        if (read_distance(&distance) == 0) {
            // Log the data
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance, skipping logging.\n");
        }

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

