int vl53l4cx_init(int i2c_handle);
int vl53l4cx_read_distance(int i2c_handle, uint16_t *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L4CX initialization function
int vl53l4cx_init(int i2c_handle) {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x7FFF, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (error code %d): %s\n", status, strerror(errno));
        return -1;
    }
    gpioDelay(10000); // 10 ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0009, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Start ranging failed (error code %d): %s\n", status, strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L4CX read distance function
int vl53l4cx_read_distance(int i2c_handle, uint16_t *distance) {
    int status;
    uint8_t range_status;

    // Read range status
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Read range status failed (error code %d): %s\n", status, strerror(errno));
        return -1;
    }
    range_status = (uint8_t)status;

    // Check if new data is available
    if (!(range_status & 0x01)) {
        return 0; // No new data
    }

    // Read distance
    status = i2cReadWordData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error: Read distance failed (error code %d): %s\n", status, strerror(errno));
        return -1;
    }
    *distance = (uint16_t)status;

    return 1; // New data available
}

int main() {
    int status;
    uint16_t distance;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d): %s\n", i2c_handle, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        if (vl53l4cx_read_distance(i2c_handle, &distance) == 1) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                // Print distance with timestamp
                printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error: Failed to get timestamp\n");
            }
        }

        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

