#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define READ_DELAY_MS 500

// VL53L1X register addresses
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, SOFT_RESET >> 8, SOFT_RESET & 0xFF) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set I2C slave device address (default 0x29)
    if (i2cWriteByteData(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS >> 8, I2C_SLAVE__DEVICE_ADDRESS & 0xFF) < 0) {
        fprintf(stderr, "Error: Setting I2C address failed\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, SYSTEM__MODE_START >> 8, SYSTEM__MODE_START & 0xFF) < 0) {
        fprintf(stderr, "Error: Starting continuous ranging failed\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    uint8_t data[2];

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM >> 8, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Reading distance failed\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control the buzzer based on distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance, re-initializing...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus after re-init\n");
                terminate = 1; // Exit loop if re-init fails
            } else if (vl53l1x_init() < 0) {
                fprintf(stderr, "Error: VL53L1X initialisation failed after re-init\n");
                terminate = 1; // Exit loop if re-init fails
            }
        }

        gpioDelay(READ_DELAY_MS * 1000); // Delay for 500ms
    }

    // Clean up resources before exiting
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

