#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 343.0 // m/s
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0   // cm
#define MAX_DISTANCE 400.0 // cm
#define MIN_ANGLE -90.0
#define MAX_ANGLE 90.0
#define ERROR_DISTANCE -1.0

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return ERROR_DISTANCE;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return ERROR_DISTANCE;
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    float time_taken = (float)diff_tick / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND * 100.0) / 2.0; // Distance in cm

    return distance;
}

// Function to map distance to servo angle
float distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
    }
}

// Function to set servo angle
void set_servo_angle(float angle) {
    int pulse_width = (int)(angle * (2000.0 / 180.0) + 1000.0); // Map angle to pulse width (1000-2000 us)
    gpioServo(SERVO_PIN, pulse_width);
}

