    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance != ERROR_DISTANCE) {
            float angle = distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(200); // Delay 200 ms
    }

    // Cleanup
    set_servo_angle(0.0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

