#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <mqueue.h>
#include <errno.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define POLLING_INTERVAL 50 // ms
#define MSG_QUEUE_NAME "/vl53l1x_queue"
#define MAX_MSG_SIZE 256

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
mqd_t mq;
volatile sig_atomic_t terminate = 0;

// Structure for distance message
typedef struct {
    int distance;
} distance_message_t;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void control_buzzer(int distance);
void send_distance_message(int distance);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// VL53L1X Initialization
int vl53l1x_init() {
    int status;
    uint8_t model_id;

    // Check sensor model ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }
    printf("VL53L1X model ID: 0x%02X\n", model_id);

    // Software reset
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00); // Reset
    if (status < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Enable
    if (status < 0) {
        fprintf(stderr, "Error enabling sensor: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Configure timing budget (50ms)
    status = i2cWriteByteData(i2c_handle, 0x001E, 0x00); // MSB
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget MSB: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x001F, 0x32); // LSB (50ms)
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget LSB: %d\n", status);
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int *distance) {
    int status;
    uint8_t range_status;
    uint8_t data[2];

    // Check data ready
    int retries = 0;
    while (retries < 5) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status >= 0) {
            range_status = (uint8_t)status;
            break;
        } else {
            fprintf(stderr, "Error reading range status (attempt %d): %d\n", retries + 1, status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries >= 5) {
        fprintf(stderr, "Failed to read range status after multiple retries.\n");
        return -1;
    }

    if (!(range_status & 0x01)) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read distance
    retries = 0;
    while (retries < 5) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading distance (attempt %d): %d\n", retries + 1, status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries >= 5) {
        fprintf(stderr, "Failed to read distance after multiple retries.\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control Buzzer
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

// Send Distance Message
void send_distance_message(int distance) {
    distance_message_t msg;
    msg.distance = distance;

    if (mq_send(mq, (const char *)&msg, sizeof(msg), 0) == -1) {
        perror("mq_send");
    }
}

int main() {
    int distance;
    struct mq_attr attr;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Configure message queue attributes
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = sizeof(distance_message_t);
    attr.mq_curmsgs = 0;

    // Open message queue
    mq = mq_open(MSG_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
            send_distance_message(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(POLLING_INTERVAL * 1000); // Delay for polling interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
    mq_close(mq);
    mq_unlink(MSG_QUEUE_NAME);

    return 0;
}

