    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
    mq_close(mq);
    mq_unlink(MSG_QUEUE_NAME);

    return 0;
}

