#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSEWIDTH 2000 // us
#define SERVO_CLOSED_PULSEWIDTH 1000 // us
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_STATUS_TOPIC "gate_status"
#define MQTT_CLIENT_ID "gate_controller"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_open();
void servo_close();
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);
int mqtt_publish_status(const char *status);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MMC_ENABLE 0x0024
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0027
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, char *value) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    int retries = 0;
    int result;

    // Software reset
    while (retries < MAX_RETRIES) {
        result = vl53l1x_write_byte(0x0000, 0x00); // Reset bit
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X initialization failed: Software reset failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for boot

    // Example configuration (adjust as needed for your sensor)
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = vl53l1x_write_byte(VL53L1X_REG_PRE_RANGE_CONFIG_MMC_ENABLE, 0x01);
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X initialization failed: Pre-range config failed after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = vl53l1x_write_byte(VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x0A);
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X initialization failed: Final range config failed after multiple retries.\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance() {
    int retries = 0;
    int result;
    char range_status;
    char distance_bytes[2];
    int distance;

    // Start ranging
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = vl53l1x_write_byte(VL53L1X_REG_SYSRANGE_START, 0x01);
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X read distance failed: Start ranging failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for measurement

    // Read range status
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = vl53l1x_read_byte(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status);
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X read distance failed: Read range status failed after multiple retries.\n");
        return -1;
    }

    // Read distance
    retries = 0;
    while (retries < MAX_RETRIES) {
        char reg = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
        result = i2cWriteDevice(i2c_handle, &reg, 1);
        if (result != 0) {
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }
        result = i2cReadDevice(i2c_handle, distance_bytes, 2);
        if (result == 0) break;
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "VL53L1X read distance failed: Read distance failed after multiple retries.\n");
        return -1;
    }

    distance = (distance_bytes[0] << 8) | distance_bytes[1];

    return distance;
}

// Servo control functions
void servo_open() {
    gpioPWM(SERVO_GPIO, SERVO_OPEN_PULSEWIDTH);
    log_event("Gate opened");
}

void servo_close() {
    gpioPWM(SERVO_GPIO, SERVO_CLOSED_PULSEWIDTH);
    log_event("Gate closed");
}

// Logging function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// MQTT callbacks
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("MQTT connected to %s:%d\n", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    printf("MQTT disconnected with code %d\n", rc);
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        printf("Received MQTT message on topic %s: %s\n", message->topic, payload);

        if (strcmp(payload, "force_open") == 0) {
            servo_open();
        } else if (strcmp(payload, "force_close") == 0) {
            servo_close();
        } else if (strcmp(payload, "status_request") == 0) {
            // Read distance and publish status
            int distance = vl53l1x_read_distance();
            if (distance >= 0) {
                char status[50];
                snprintf(status, sizeof(status), "Distance: %d mm", distance);
                mqtt_publish_status(status);
            } else {
                mqtt_publish_status("Error reading distance");
            }
        }
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// MQTT publish status function
int mqtt_publish_status(const char *status) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_STATUS_TOPIC, strlen(status), status, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing status: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz
    gpioSetPWMrange(SERVO_GPIO, 20000); // Range of 20000 for pulsewidth in us

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_open = 0; // 0 = closed, 1 = open
    while (!terminate) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD && !gate_open) {
                servo_open();
                gate_open = 1;
            } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
                servo_close();
                gate_open = 0;
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

