#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100   // us
#define MAX_PULSE_WIDTH 30000 // us
#define MEASUREMENT_INTERVAL 200 // ms
#define TIMEOUT_DURATION 60      // ms

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold echo timestamps
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
    int valid;
} echo_data_t;

echo_data_t echo_data = {0, 0, 0};

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void timeout_handler();
void signal_handler(int signal);
char* iso8601_timestamp();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_data.rising_tick = tick;
        echo_data.valid = 0; // Reset valid flag on rising edge
    } else if (level == 0) {
        echo_data.falling_tick = tick;
        echo_data.valid = 1; // Set valid flag on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to log distance to file and stdout
void log_distance(double distance) {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error generating timestamp.\n");
        return;
    }

    fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
    printf("%s Distance: %.2f cm\n", timestamp, distance);
    free(timestamp);
}

// Function to handle timeout
void timeout_handler() {
    fprintf(stderr, "Timeout: No echo received within %d ms\n", TIMEOUT_DURATION);
    char *timestamp = iso8601_timestamp();
    if (timestamp != NULL) {
        fprintf(log_file, "%s Timeout: No echo received within %d ms\n", timestamp, TIMEOUT_DURATION);
        fflush(log_file);
        free(timestamp);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register echo callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo
        gpioDelay(MEASUREMENT_INTERVAL);

        // Check for valid echo
        if (echo_data.valid) {
            uint32_t pulse_width = echo_data.falling_tick - echo_data.rising_tick;

            // Handle tick wraparound
            if (echo_data.falling_tick < echo_data.rising_tick) {
                pulse_width = (0xFFFFFFFF - echo_data.rising_tick) + echo_data.falling_tick;
            }

            // Validate pulse width
            if (pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
            } else {
                char *timestamp = iso8601_timestamp();
                if (timestamp != NULL) {
                    fprintf(stderr, "%s Warning: Invalid pulse width: %u us\n", timestamp, pulse_width);
                    fprintf(log_file, "%s Warning: Invalid pulse width: %u us\n", timestamp, pulse_width);
                    fflush(log_file);
                    free(timestamp);
                }
            }
        } else {
            timeout_handler();
        }

        // Reset echo data
        echo_data.rising_tick = 0;
        echo_data.falling_tick = 0;
        echo_data.valid = 0;
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

