#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define OPEN_ANGLE 2000  // Adjust as needed
#define CLOSE_ANGLE 1000 // Adjust as needed
#define OPEN_THRESHOLD 500 // 50cm in mm
#define CLOSE_THRESHOLD 600 // 60cm in mm
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile int gate_open = 0; // 0 = closed, 1 = open

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_open();
void servo_close();
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, char *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    char model_id;

    // Check sensor model ID
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Example initialization sequence (adjust based on datasheet)
    if (vl53l1x_write_byte(0x02D8, 0x01) != 0) return -1;
    if (vl53l1x_write_byte(0x02DD, 0x05) != 0) return -1;
    if (vl53l1x_write_byte(0x001E, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x001F, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0020, 0x01) != 0) return -1;
    if (vl53l1x_write_byte(0x0021, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0022, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0023, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0024, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0025, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0026, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0027, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0028, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(0x0029, 0x00) != 0) return -1;
