#define GATE_OPEN_GPIO 18
#define GATE_CLOSE_GPIO 19
#define DISTANCE_THRESHOLD 200 // mm
#define POLLING_INTERVAL 500 // ms

// VL53L1X Registers (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0015
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_VHV_CONFIG_PAD_SCL_SDA_EXTSUP_HV 0x0089

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void gate_open();
void gate_close();
void log_event(const char *event);
void signal_handler(int signal);

// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteI2CBlockData(i2c_handle, reg, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *data) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *data = result;
    return 0;
}

// VL53L1X Initialization
int vl53l1x_init() {
    // Soft reset
    if (vl53l1x_write_byte(0x0000, 0x00) < 0) return -1;
    gpioDelay(1000); // Wait for reset

    // Check device ID (example)
    int device_id;
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &device_id) < 0) return -1;
    if (device_id != 0xEA) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure timing budget (example)
    if (vl53l1x_write_byte(0x001E, 0x01) < 0) return -1; // Example: Set timing budget
    if (vl53l1x_write_byte(0x001F, 0x00) < 0) return -1; // Example: Set timing budget

    // Start ranging
    if (vl53l1x_write_byte(VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;

    return 0;
}

// VL53L1X Distance Reading
int vl53l1x_read_distance(int *distance) {
    char data[2];
    int result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Gate Control Functions
void gate_open() {
    gpioWrite(GATE_OPEN_GPIO, 1);
    gpioWrite(GATE_CLOSE_GPIO, 0);
    log_event("Gate opened");
}

void gate_close() {
    gpioWrite(GATE_OPEN_GPIO, 0);
    gpioWrite(GATE_CLOSE_GPIO, 1);
    log_event("Gate closed");
}

// Logging Function
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_GPIO, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                gate_open();
            } else {
                gate_close();
            }
        } else {
            log_event("Error reading distance");
        }

        gpioDelay(POLLING_INTERVAL * 1000); // Convert ms to us
    }

    // Cleanup
    gate_close(); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

