#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_GPIO 24
#define MOTOR_FORWARD_GPIO 17
#define MOTOR_BACKWARD_GPIO 18
#define DISTANCE_THRESHOLD_LOW 100 // mm
#define DISTANCE_THRESHOLD_HIGH 300 // mm
#define MAX_RETRIES 5

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void isr_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register with retry and backoff
int vl53l1x_write_register(int handle, uint16_t reg, uint8_t data) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay((1 << retries) * 1000); // Exponential backoff (1ms, 2ms, 4ms, 8ms, 16ms)
        retries++;
    }
    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read a byte from a VL53L1X register with retry and backoff
int vl53l1x_read_register(int handle, uint16_t reg, uint8_t *data) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *data = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay((1 << retries) * 1000); // Exponential backoff
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    uint8_t model_id;

    // Check sensor ID
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", model_id);
        return -1;
    }

    // Soft reset
    if (vl53l1x_write_register(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Failed to soft reset sensor\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Start measurement
    if (vl53l1x_write_register(i2c_handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t data_ready;
    uint8_t range_msb, range_lsb;

    // Poll data ready bit
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &data_ready) != 0) {
            fprintf(stderr, "Failed to read data ready bit\n");
            gpioDelay((1 << retries) * 1000);
            retries++;
            continue;
        }

        if (data_ready & 0x01) {
            break; // Data ready
        }

        gpioDelay(1000); // Wait 1ms
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range_msb) != 0) {
        fprintf(stderr, "Failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &range_lsb) != 0) {
        fprintf(stderr, "Failed to read distance LSB\n");
        return -1;
    }

    *distance = (uint16_t)((range_msb << 8) | range_lsb);

    return 0;
}

// Function to control the motor forward
void motor_forward() {
    gpioWrite(MOTOR_FORWARD_GPIO, 1);
    gpioWrite(MOTOR_BACKWARD_GPIO, 0);
    printf("Motor: FORWARD\n");
}

// Function to control the motor backward
void motor_backward() {
    gpioWrite(MOTOR_FORWARD_GPIO, 0);
    gpioWrite(MOTOR_BACKWARD_GPIO, 1);
    printf("Motor: BACKWARD\n");
}

// Function to stop the motor
void motor_stop() {
    gpioWrite(MOTOR_FORWARD_GPIO, 0);
    gpioWrite(MOTOR_BACKWARD_GPIO, 0);
    printf("Motor: STOP\n");
}

// Interrupt service routine (ISR) callback function
void isr_callback(int gpio, int level, uint32_t tick, void *user) {
    uint16_t distance;

    if (level == 1) { // Rising edge
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Failed to read distance in ISR\n");
            motor_stop(); // Stop motor on error
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_GPIO, PI_INPUT);
    gpioSetMode(MOTOR_FORWARD_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_GPIO, PI_OUTPUT);

    // Set up interrupt service routine (ISR)
    if (gpioSetISRFuncEx(TRIGGER_GPIO, RISING_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X sensor and motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Clean up resources
    i2cClose(i2c_handle);
    motor_stop();
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

