#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {17, 18, 27, 22}
#define NUM_ELECTRODES 12
#define POLLING_INTERVAL_MS 50

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_RESET 0x80

// Define LED patterns
const uint8_t LED_PATTERNS[NUM_ELECTRODES] = {
    0b0001, 0b0010, 0b0100, 0b1000,
    0b0011, 0b0110, 0b1100, 0b1001,
    0b0101, 0b1010, 0b1111, 0b1110
};

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_lines[4] = {NULL, NULL, NULL, NULL};

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mpr121_init(int fd);
int read_touch_status(int fd, uint16_t *touch_status);
void set_led_pattern(struct gpiod_line *lines[], uint8_t pattern);
void log_event(int electrode);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_reg(fd, MPR121_RESET, 0x63) < 0) return -1;
    usleep(10000); // Wait for reset

    // Verify sensor presence (read ELECONFIG0)
    uint8_t eleconfig0;
    if (i2c_read_reg(fd, MPR121_ELECONFIG0, &eleconfig0) < 0) return -1;
    if (eleconfig0 != 0x00) {
        fprintf(stderr, "Error: MPR121 not found or communication error.\n");
        return -1;
    }

    // Stop mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x00) < 0) return -1;

    // Baseline filtering
    if (i2c_write_reg(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLR, 0x00) < 0) return -1;

    // Auto-configuration thresholds
    if (i2c_write_reg(fd, 0x5A, 0x0B) < 0) return -1;
    if (i2c_write_reg(fd, 0x5D, 0xC8) < 0) return -1;
    if (i2c_write_reg(fd, 0x5E, 0x82) < 0) return -1;
    if (i2c_write_reg(fd, 0x5F, 0xB4) < 0) return -1;

    // Enable all electrodes in run mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

// Read touch status function
int read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t touch_status_l, touch_status_h;

    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0) return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) return -1;

    *touch_status = ((uint16_t)touch_status_h << 8) | touch_status_l;
    return 0;
}

// Set LED pattern function
void set_led_pattern(struct gpiod_line *lines[], uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        int value = (pattern >> i) & 1;
        if (gpiod_line_set_value(lines[i], value) < 0) {
            perror("Error setting GPIO value");
        }
    }
}

// Log event function
void log_event(int electrode) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Electrode %d touched\n", timestamp, electrode);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
        }
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO lines
    int gpio_pins[] = GPIO_PINS;
    for (int i = 0; i < 4; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, gpio_pins[i]);
        if (!gpio_lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        // Request GPIO line for output
        if (gpiod_line_request_output(gpio_lines[i], "proximity_art", 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }
    }

    // Main loop
    uint16_t touch_status;
    while (1) {
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, exiting.\n");
            break;
        }

        // Check for any electrode touch
        if (touch_status > 0) {
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if (touch_status & (1 << i)) {
                    set_led_pattern(gpio_lines, LED_PATTERNS[i]);
