                    break; // Only log the first touched electrode
                }
            }
        } else {
            // No electrode touched, turn off all LEDs
            set_led_pattern(gpio_lines, 0x00);
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Cleanup (in case of error in main loop)
    signal_handler(SIGTERM);

