// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FFI 0x2B
#define MPR121_SFI 0x2C
#define MPR121_ESI 0x2D
#define MPR121_DEBOUNCE 0x24
#define MPR121_AFECR 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NFDR 0x31
#define MPR121_FDLF 0x32
#define MPR121_E0FDL 0x43
#define MPR121_E0FDLR 0x44
#define MPR121_E0FDLF 0x45
#define MPR121_E1FDL 0x46
#define MPR121_E1FDLR 0x47
#define MPR121_E1FDLF 0x48
#define MPR121_E2FDL 0x49
#define MPR121_E2FDLR 0x4A
#define MPR121_E2FDLF 0x4B
#define MPR121_E3FDL 0x4C
#define MPR121_E3FDLR 0x4D
#define MPR121_E3FDLF 0x4E
#define MPR121_E4FDL 0x4F
#define MPR121_E4FDLR 0x50
#define MPR121_E4FDLF 0x51
#define MPR121_E5FDL 0x52
#define MPR121_E5FDLR 0x53
#define MPR121_E5FDLF 0x54
#define MPR121_E6FDL 0x55
#define MPR121_E6FDLR 0x56
#define MPR121_E6FDLF 0x57
#define MPR121_E7FDL 0x58
#define MPR121_E7FDLR 0x59
#define MPR121_E7FDLF 0x5A
#define MPR121_E8FDL 0x5B
#define MPR121_E8FDLR 0x5C
#define MPR121_E8FDLF 0x5D
#define MPR121_E9FDL 0x5E
#define MPR121_E9FDLR 0x5F
#define MPR121_E9FDLF 0x60
#define MPR121_E10FDL 0x61
#define MPR121_E10FDLR 0x62
#define MPR121_E10FDLF 0x63
#define MPR121_E11FDL 0x64
#define MPR121_E11FDLR 0x65
#define MPR121_E11FDLF 0x66

// GPIO pin for LED
#define LED_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void led_on();
void led_off();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the MPR121 sensor
int mpr121_init() {
    int status;
    uint8_t device_id;

    // Verify MPR121 is present
    status = i2cReadByteData(i2c_handle, 0x80); // Read Device ID register
    if (status < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", status);
        return -1;
    }
    device_id = (uint8_t)status;

    if (device_id != 0x5A) {
        fprintf(stderr, "MPR121 not found. Device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure MPR121 registers
    status = i2cWriteByteData(i2c_handle, MPR121_FFI, 0x01); // First Filter Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing FFI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_SFI, 0x01); // Second Filter Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing SFI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_ESI, 0x01); // Electrode Sample Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing ESI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x05); // Debounce
    if (status < 0) {
        fprintf(stderr, "Error writing DEBOUNCE: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_AFECR, 0x01); // AFE Control Register
    if (status < 0) {
        fprintf(stderr, "Error writing AFE Control Register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01); // MHD_R
    if (status < 0) {
        fprintf(stderr, "Error writing MHD_R: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01); // NHD_R
    if (status < 0) {
        fprintf(stderr, "Error writing NHD_R: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E); // NCLR
    if (status < 0) {
        fprintf(stderr, "Error writing NCLR: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00); // FDLR
    if (status < 0) {
        fprintf(stderr, "Error writing FDLR: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01); // MHDF
    if (status < 0) {
        fprintf(stderr, "Error writing MHDF: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01); // NHDF
    if (status < 0) {
        fprintf(stderr, "Error writing NHDF: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_NFDR, 0x0E); // NFDR
    if (status < 0) {
        fprintf(stderr, "Error writing NFDR: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00); // FDLF
    if (status < 0) {
        fprintf(stderr, "Error writing FDLF: %d\n", status);
        return -1;
    }

    // Set touch and release thresholds for electrode 0
    status = i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0, 0x0A); // Touch threshold
    if (status < 0) {
        fprintf(stderr, "Error writing touch threshold: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0, 0x05); // Release threshold
    if (status < 0) {
        fprintf(stderr, "Error writing release threshold: %d\n", status);
        return -1;
    }

    // Enable electrode 0
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x01); // Enable electrode 0
    if (status < 0) {
        fprintf(stderr, "Error enabling electrode 0: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int status;
    uint8_t touch_status;

    status = i2cReadByteData(i2c_handle, 0x00); // Read touch status register
    if (status < 0) {
        fprintf(stderr, "Error reading touch status: %d\n", status);
        return -1;
    }
    touch_status = (uint8_t)status;

    return touch_status;
}

// Function to turn the LED on
void led_on() {
    gpioWrite(LED_PIN, 1); // Set GPIO high
}

// Function to turn the LED off
void led_off() {
    gpioWrite(LED_PIN, 0); // Set GPIO low
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

