    status = i2cWriteByteData(i2c_handle, MPR121_FFI, 0x01); // First Filter Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing FFI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_SFI, 0x01); // Second Filter Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing SFI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_ESI, 0x01); // Electrode Sample Iteration
    if (status < 0) {
        fprintf(stderr, "Error writing ESI: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x05); // Debounce
    if (status < 0) {
        fprintf(stderr, "Error writing DEBOUNCE: %d\n", status);
