#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // microseconds

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int trigger_sensor(struct gpiod_line *trigger_line);
long measure_pulse_width(struct gpiod_line *echo_line);
double calculate_distance(long pulse_width);
int validate_distance(double distance);
int log_distance(double distance);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting gracefully.\n");
    }
}

// Trigger the ultrasonic sensor
int trigger_sensor(struct gpiod_line *trigger_line) {
    int ret;

    // Set trigger low for 5 microseconds
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(-ret));
        return -1;
    }
    usleep(5);

    // Set trigger high for 10 microseconds
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(-ret));
        return -1;
    }
    usleep(10);

    // Set trigger low again
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Measure the pulse width of the echo signal
long measure_pulse_width(struct gpiod_line *echo_line) {
    struct timespec start, end;
    int ret;
    long pulse_width;

    // Wait for rising edge
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(-value));
            return -1;
        }
        if (value == 1) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge.\n");
            return -1;
        }
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(-value));
            return -1;
        }
        if (value == 0) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge.\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Validate the distance
int validate_distance(double distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Log the distance to a file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file);

    return 0;
}

// Setup GPIO lines
int setup_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        goto err_chip;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        goto err_trigger;
    }

    ret = gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(-ret));
        goto err_echo;
    }

    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(-ret));
        goto err_trigger_release;
    }

    return 0;

err_trigger_release:
    gpiod_line_release(trigger_line);
err_echo:
    gpiod_line_release(echo_line);
err_trigger:
    gpiod_chip_close(chip);
err_chip:
    return -1;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    double distance;
    long pulse_width;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed.\n");
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor(trigger_line) != 0) {
            fprintf(stderr, "Sensor trigger failed.\n");
            continue; // Continue to the next iteration
        }

        // Measure the pulse width
        pulse_width = measure_pulse_width(echo_line);
        if (pulse_width < 0) {
            fprintf(stderr, "Pulse width measurement failed.\n");
            continue; // Continue to the next iteration
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Validate the distance
        if (validate_distance(distance)) {
            // Log the distance
            log_distance(distance);
        } else {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    fclose(log_file);

    return 0;
}

