    fflush(log_file);

    return 0;
}

// Setup GPIO lines
int setup_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        goto err_chip;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        goto err_trigger;
    }

    ret = gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(-ret));
        goto err_echo;
    }

    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(-ret));
        goto err_trigger_release;
    }

    return 0;

err_trigger_release:
    gpiod_line_release(trigger_line);
err_echo:
    gpiod_line_release(echo_line);
err_trigger:
    gpiod_chip_close(chip);
err_chip:
    return -1;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    double distance;
    long pulse_width;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed.\n");
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor(trigger_line) != 0) {
            fprintf(stderr, "Sensor trigger failed.\n");
            continue; // Continue to the next iteration
        }

        // Measure the pulse width
        pulse_width = measure_pulse_width(echo_line);
        if (pulse_width < 0) {
            fprintf(stderr, "Pulse width measurement failed.\n");
            continue; // Continue to the next iteration
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Validate the distance
        if (validate_distance(distance)) {
            // Log the distance
            log_distance(distance);
        } else {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    fclose(log_file);

    return 0;
}

