// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // Speed of sound in m/s
#define MIN_PULSE_WIDTH 58   // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 25000 // Maximum pulse width in microseconds (25 ms)
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge was received
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(1000000); // Wait 1 second

        if (echo_received) {
            uint32_t pulse_width = end_tick - start_tick;

            // Handle tick wraparound
            if (end_tick < start_tick) {
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
            }

            // Validate pulse width
            if (pulse_width > 0 && pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
                printf("Distance: %.2f m\n", distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u\n", pulse_width);
            }
            echo_received = 0; // Reset flag for next measurement
        } else {
            fprintf(stderr, "No echo received!\n");
        }
    }

    return 0;
}

