#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
int read_status(uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Set XSHUT pin high to enable the sensor
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(1000); // Wait 1ms

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure the sensor for continuous ranging mode
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to MODE_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to TIMEOUT_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to START_RANGING_REG");
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialized successfully");
    return 0;
}

// Read the distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to read distance: %d", result);
        return -1;
    }

    *distance = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

// Read the status from the sensor
int read_status(uint8_t *status) {
    int result = i2cReadByteData(i2c_handle, STATUS_REG);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read status: %d", result);
        return -1;
    }

    *status = (uint8_t)result;
    return 0;
}

// Log the data to the systemd journal
void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    syslog(LOG_INFO, "%s - Distance: %d mm, Status: 0x%02X", buf, distance, status);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 0); // Initially low

    // Open syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (init_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    uint16_t distance;
    uint8_t status;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100000); // Wait 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

