#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define OPEN 1
#define CLOSE 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance();
void control_gate(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int vl53l1x_address;
    int gate_gpio;
    float distance_threshold;
} sensor_config_t;

// Function to initialize the VL53L1X sensor
int init_sensor() {
    int status;
    unsigned char model_id;

    // Read model ID
    status = i2cReadByteData(i2c_handle, 0x010F);
    if (status < 0) {
        log_message("Error reading model ID");
        return -1;
    }
    model_id = (unsigned char)status;

    if (model_id != 0xEA) {
        char message[100];
        sprintf(message, "Incorrect model ID: 0x%02X", model_id);
        log_message(message);
        return -1;
    }

    // Set ranging mode to short
    status = i2cWriteByteData(i2c_handle, 0x0021, 0x00);
    if (status < 0) {
        log_message("Error setting ranging mode");
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0015, 0x01);
    if (status < 0) {
        log_message("Error starting ranging");
        return -1;
    }

    log_message("Sensor initialized successfully");
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int status;
    unsigned char msb, lsb;
    int distance_mm;

    // Read MSB
    status = i2cReadByteData(i2c_handle, 0x0089);
    if (status < 0) {
        log_message("Error reading distance MSB");
        return -1;
    }
    msb = (unsigned char)status;

    // Read LSB
    status = i2cReadByteData(i2c_handle, 0x008A);
    if (status < 0) {
        log_message("Error reading distance LSB");
        return -1;
    }
    lsb = (unsigned char)status;

    distance_mm = (msb << 8) | lsb;
    return distance_mm;
}

// Function to control the gate actuator
void control_gate(int state) {
    gpioWrite(GATE_GPIO, state);
    char message[50];
    sprintf(message, "Gate %s", state == OPEN ? "opened" : "closed");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error opening I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        log_message("Sensor initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for gate control
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is initially closed

