#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define TIMEOUT_MS 30
#define TRIGGER_PULSE_DURATION 10 // us
#define TRIGGER_DELAY_MS 100
#define MOVING_AVERAGE_SIZE 5
#define SERVO_DEFAULT_ANGLE 90

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
double distance_history[MOVING_AVERAGE_SIZE];
int history_index = 0;
double distance_sum = 0.0;
int data_ready = 0;
double pulse_width = 0.0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_distance(double pulse_width);
double apply_moving_average(double new_distance);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
int log_data(double distance, double angle);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static uint32_t last_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;

        // Calculate pulse width in microseconds
        if (end_tick > start_tick) {
            pulse_width = (double)(end_tick - start_tick) / 1000.0; // Convert to us
        } else {
            // Handle wrap-around
            pulse_width = (double)(UINT32_MAX - start_tick + end_tick) / 1000.0;
        }

        data_ready = 1; // Set the flag to indicate data is ready
    } else if (level == PI_TIMEOUT) {
        // Timeout occurred
        pulse_width = -1.0; // Indicate timeout
        data_ready = 1;
    }
}

// Function to calculate distance from pulse width
double calculate_distance(double pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to apply a moving average filter
double apply_moving_average(double new_distance) {
    distance_sum -= distance_history[history_index];
    distance_history[history_index] = new_distance;
    distance_sum += new_distance;
    history_index = (history_index + 1) % MOVING_AVERAGE_SIZE;
    return distance_sum / MOVING_AVERAGE_SIZE;
}

// Function to map distance to servo angle (logarithmic mapping)
double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return 0.0;
    } else if (distance > MAX_DISTANCE) {
        return 180.0;
    } else {
        // Logarithmic mapping
        double normalized_distance = (log10(distance) - log10(MIN_DISTANCE)) / (log10(MAX_DISTANCE) - log10(MIN_DISTANCE));
        return normalized_distance * 180.0;
    }
}

// Function to set the servo angle
int set_servo_angle(double angle) {
    int pulse_width = MIN_PULSE_WIDTH + (int)((angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    return gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to a CSV file
int log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer after each write
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(cm),Angle(degrees)\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin with timeout
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize distance history
    for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for echo data with timeout
        data_ready = 0; // Reset the flag
        gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL); // Re-register the callback
        gpioDelay(TRIGGER_DELAY_MS); // Wait for the trigger delay

        if (!data_ready) {
            // Timeout occurred
            fprintf(stderr, "Timeout waiting for echo!\n");
            pulse_width = -1.0; // Indicate timeout
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Apply moving average filter
        double filtered_distance = apply_moving_average(distance);

        // Map distance to servo angle
        double angle = map_distance_to_angle(filtered_distance);

        // Set servo angle
        int servo_result = set_servo_angle(angle);
        if (servo_result != 0) {
            fprintf(stderr, "Error setting servo angle: %d\n", servo_result);
        }

        // Log data
        if (distance < 0 || distance > MAX_DISTANCE) {
            log_data(-1.0, SERVO_DEFAULT_ANGLE);
            set_servo_angle(SERVO_DEFAULT_ANGLE);
        } else {
            log_data(filtered_distance, angle);
        }

        gpioDelay(50); // Delay between measurements
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

