#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 200 // mm
#define BUFFER_SIZE 10
#define READ_DELAY_MS 50

// VL53L1X Register Addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0029
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool running = true;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void buffer_add(int distance);
int buffer_get_average();
void gpio_control(int level);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = result;
    return 0;
}

// VL53L1X Initialization Sequence
int vl53l1x_init() {
    int model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) return -1;
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) return -1;

    if (model_id != 0xEACC || revision_id != 0x10) {
        fprintf(stderr, "Error: Invalid sensor ID (Model: 0x%02X, Revision: 0x%02X)\n", model_id, revision_id);
        return -1;
    }

    // Recommended initialization sequence (example - adjust based on datasheet)
    if (vl53l1x_write_byte(VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x27) != 0) return -1;
    if (vl53l1x_write_byte(VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x09) != 0) return -1;
    if (vl53l1x_write_byte(VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) != 0) return -1; // Example value
    if (vl53l1x_write_byte(VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x0A) != 0) return -1; // Example value

    return 0;
}

// Function to read distance from VL53L1X
int vl53l1x_read_distance() {
    int distance = -1; // Default to error value
    int range_status;

    // Start a single measurement (example - adjust based on datasheet)
    if (vl53l1x_write_byte(VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1; // Start single measurement
    gpioDelay(10); // Wait for measurement to complete

    // Read range status
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) return -1;

    // Read distance (example - adjust based on datasheet)
    int distance_msb, distance_lsb;
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) return -1;
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) return -1;

    distance = (distance_msb << 8) | distance_lsb;

    return distance;
}

