#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define GPIO_PIN 27
#define MSG_QUEUE_KEY 1234
#define MAX_MSG_SIZE 256

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDRESS;
int msg_queue_id;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Message structure for inter-process communication
struct msgbuf {
    long mtype;
    char mtext[MAX_MSG_SIZE];
};

// Function prototypes
int init_i2c(int address);
int read_proximity(int handle);
int set_threshold(int new_threshold);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // I2C bus 1
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read proximity value from the sensor
int read_proximity(int handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, PROXIMITY_REG_HIGH, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to set the proximity threshold
int set_threshold(int new_threshold) {
    threshold = new_threshold;
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity = read_proximity(i2c_handle);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity in interrupt handler.\n");
        return;
    }

    struct msgbuf message;
    message.mtype = 1; // Message type
    snprintf(message.mtext, MAX_MSG_SIZE, "%d", proximity);

    if (msgsnd(msg_queue_id, &message, strlen(message.mtext), 0) == -1) {
        perror("msgsnd");
        fprintf(stderr, "Error sending message to queue.\n");
    }
}

// Function to log data to a file
void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue_id >= 0) {
        msgctl(msg_queue_id, IPC_RMID, NULL);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize message queue
    msg_queue_id = msgget(MSG_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        perror("msgget");
        fprintf(stderr, "Error creating message queue.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler.\n");
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        struct msgbuf message;
        if (msgrcv(msg_queue_id, &message, MAX_MSG_SIZE, 1, IPC_NOWAIT) != -1) {
            int proximity = atoi(message.mtext);
            const char *status = (proximity > threshold) ? "ALERT" : "SAFE";
            log_data(proximity, status);
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

