#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 200.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 200000   // 200 ms

// Global variables
static volatile int running = 1;
static float previous_frequency = 0.0;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float distance_to_frequency(float distance);
void set_tone_frequency(float frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioTrigger(TRIGGER_PIN, 10, 1); // Send 10 us trigger pulse

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff_tick / 1000000.0 * 34300.0 / 2.0;

    return distance;
}

// Function to map distance to frequency
float distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return previous_frequency; // Keep previous frequency
    }

    float frequency = 200.0 * exp(distance / 50.0);

    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to set the tone frequency using PWM
void set_tone_frequency(float frequency) {
    if (frequency <= 0.0) {
        gpioPWM(SPEAKER_PIN, 0); // Turn off PWM if frequency is invalid
        return;
    }

    int range = 1000; // PWM range
    int duty_cycle = range / 2; // 50% duty cycle

    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioSetPWMrange(SPEAKER_PIN, range);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(SPEAKER_PIN, 1000); // Set PWM range to 1000
    gpioSetPWMfrequency(SPEAKER_PIN, 1000); // Initial frequency (will be updated later)

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

