#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT 100000      // us (100 ms)

// Global variables
volatile sig_atomic_t program_running = 1;
float last_valid_distance = 0.0;

// Function prototypes
void triggerSensor();
float getDistance();
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping buzzer and terminating pigpio.\n");
        program_running = 0;
        gpioPWM(BUZZER_PIN, 0); // Stop PWM output
        gpioTerminate();        // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    triggerSensor();

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout (high). Using last valid distance: %.2f cm\n", last_valid_distance);
        return last_valid_distance;
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout (low). Using last valid distance: %.2f cm\n", last_valid_distance);
        return last_valid_distance;
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff_tick * 343.0 / 20000.0; // cm

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Error: Distance out of range (%.2f cm). Using last valid distance: %.2f cm\n", distance, last_valid_distance);
        return last_valid_distance;
    }

    last_valid_distance = distance;
    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to set the buzzer frequency using hardware PWM
void setBuzzerFrequency(float frequency) {
    int range = 1000000; // Adjust range for finer resolution
    int dutycycle = (int)(range * frequency / 1000.0); // Calculate duty cycle

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency); // Set PWM frequency
    gpioPWM(BUZZER_PIN, dutycycle / (range / 100)); // Set PWM duty cycle (0-100)
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = getDistance();
        float frequency = mapDistanceToFrequency(distance);
        setBuzzerFrequency(frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

