#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// Define sensor registers
#define REG_CONTROL 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Define error codes
#define ERROR_SPI_INIT -1
#define ERROR_SENSOR_INIT -2
#define ERROR_SPI_TRANSFER -3
#define ERROR_FILE_OPEN -4
#define ERROR_FILE_WRITE -5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int spi_read_register(int handle, uint8_t reg, uint8_t *value);
int read_distance(int handle);
int log_distance(FILE *fp, int distance);
void signal_handler(int signal);

// SPI write function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for write
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed (reg 0x%02X, value 0x%02X)\n", reg, value);
        return ERROR_SPI_TRANSFER;
    }

    return 0;
}

// SPI read function
int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed (reg 0x%02X)\n", reg);
        return ERROR_SPI_TRANSFER;
    }

    *value = rx_buf[1];
    return 0;
}

// Read distance from the sensor
int read_distance(int handle) {
    uint8_t low_byte, high_byte;
    int distance;

    if (spi_read_register(handle, REG_DISTANCE_LOW, &low_byte) != 0) {
        fprintf(stderr, "Error: Failed to read low byte\n");
        return -1;
    }

    if (spi_read_register(handle, REG_DISTANCE_HIGH, &high_byte) != 0) {
        fprintf(stderr, "Error: Failed to read high byte\n");
        return -1;
    }

    distance = (high_byte << 8) | low_byte;
    return distance;
}

// Log distance to file
int log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return ERROR_FILE_WRITE;
    }

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    int distance;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (spi_write_register(spi_handle, REG_CONTROL, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set continuous measurement mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (spi_write_register(spi_handle, REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set range to 5m\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (spi_write_register(spi_handle, REG_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance(spi_handle);
        if (distance >= 200 && distance <= 5000) {
            result = log_distance(log_file, distance);
            if (result != 0) {
                fprintf(stderr, "Error: Failed to log distance\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid distance reading: %d\n", distance);
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

