#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_LSB_REG 0x22
#define ALS_VISIBLE_MSB_REG 0x23
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// Read ALS visible light value
uint16_t read_als_visible(int fd) {
    int lsb = i2c_read_reg(fd, ALS_VISIBLE_LSB_REG);
    int msb = i2c_read_reg(fd, ALS_VISIBLE_MSB_REG);

    if (lsb == -1 || msb == -1) {
        return 0; // Return 0 on error
    }

    return (uint16_t)((msb << 8) | lsb);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to CSV file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Setup function
int setup() {
    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read ALS visible light value
        uint16_t als_visible = read_als_visible(i2c_fd);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log.\n");
            sleep(5);
            continue;
        }

        // Log data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 5 seconds
        sleep(5);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

