#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_PART_ID_REG 0x00
#define SI1120_ALS_DATA_LOW 0x22
#define SI1120_ALS_DATA_HIGH 0x23
#define SI1120_PS_DATA_LOW 0x18
#define SI1120_PS_DATA_HIGH 0x19
#define SI1120_PART_ID 0x41
#define LOG_FILE "si1120_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *als, uint16_t *ps);
int log_data(uint16_t als, uint16_t ps);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    uint16_t als;
    uint16_t ps;
} sensor_data_t;

// Function to handle signals (Ctrl+C, etc.)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1120 sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, SI1120_RESET_REG, 0x01);
        if (status == 0) break; // Success
        fprintf(stderr, "Error resetting sensor (attempt %d): %d\n", retries + 1, status);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset sensor after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Verify part ID
    retries = 0;
    int part_id;
    while (retries < MAX_RETRIES) {
        part_id = i2cReadByteData(i2c_handle, SI1120_PART_ID_REG);
        if (part_id >= 0) break; // Success
        fprintf(stderr, "Error reading part ID (attempt %d): %d\n", retries + 1, part_id);
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 sensor initialized successfully.\n");
    return 0;
}

// Function to read ALS and proximity data from the sensor
int read_sensor_data(uint16_t *als, uint16_t *ps) {
    int retries = 0;
    int status;
    int als_low, als_high, ps_low, ps_high;

    // Read ALS data
    while (retries < MAX_RETRIES) {
        als_low = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_LOW);
        als_high = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_HIGH);
        if (als_low >= 0 && als_high >= 0) break; // Success
        fprintf(stderr, "Error reading ALS data (attempt %d): low=%d, high=%d\n", retries + 1, als_low, als_high);
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS data after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    *als = (uint16_t)((als_high << 8) | als_low);

    // Read Proximity data
    retries = 0;
    while (retries < MAX_RETRIES) {
        ps_low = i2cReadByteData(i2c_handle, SI1120_PS_DATA_LOW);
        ps_high = i2cReadByteData(i2c_handle, SI1120_PS_DATA_HIGH);
        if (ps_low >= 0 && ps_high >= 0) break; // Success
        fprintf(stderr, "Error reading PS data (attempt %d): low=%d, high=%d\n", retries + 1, ps_low, ps_high);
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS data after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    *ps = (uint16_t)((ps_high << 8) | ps_low);

    return 0;
}

// Function to log data to a file
int log_data(uint16_t als, uint16_t ps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, PS: %u\n", timestamp, als, ps);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    uint16_t als_value, ps_value;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&als_value, &ps_value) == 0) {
            log_data(als_value, ps_value);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Clean up and exit
    cleanup();
    return 0;
}

