#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_proximity();
int log_data(int proximity);
void signal_handler(int signal);
int i2c_write_with_retry(int handle, int reg, int val);
int i2c_read_with_retry(int handle, int reg);

// Structure for sensor configuration
typedef struct {
    int meas_rate;
    int no_interrupt;
    int als_vis_ir_adc_counter;
    int als_vis_adc_gain;
    int ps_adc_counter;
    int ps_led21;
    int ps_led3;
    int ps_adc_misc;
    int ps_adc_gain;
    int command;
} sensor_config_t;

// Function to write a byte to an I2C register with retry
int i2c_write_with_retry(int handle, int reg, int val) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, val);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d. Retry %d/%d\n", reg, val, result, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, val 0x%02X). Exiting.\n", MAX_RETRIES, reg, val);
    return -1; // Failure
}

// Function to read a byte from an I2C register with retry
int i2c_read_with_retry(int handle, int reg) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retry %d/%d\n", reg, result, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X). Exiting.\n", MAX_RETRIES, reg);
    return -1; // Failure
}

// Function to initialize the Si1145 sensor
int init_sensor() {
    sensor_config_t config = {
        .meas_rate = 0x02,
        .no_interrupt = 0x00,
        .als_vis_ir_adc_counter = 0x0B,
        .als_vis_adc_gain = 0x00,
        .ps_adc_counter = 0x49,
        .ps_led21 = 0x03,
        .ps_led3 = 0x0F,
        .ps_adc_misc = 0x03,
        .ps_adc_gain = 0x07,
        .command = 0x03
    };

    if (i2c_write_with_retry(i2c_handle, 0x07, 0x03) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x06, config.meas_rate) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x1A, config.no_interrupt) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x21, config.als_vis_ir_adc_counter) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x24, config.als_vis_adc_gain) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x22, config.ps_adc_counter) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x0C, config.ps_led21) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x0F, config.ps_led3) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x11, config.ps_adc_misc) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x0D, config.ps_adc_gain) != 0) return -1;
    if (i2c_write_with_retry(i2c_handle, 0x80, config.command) != 0) return -1;

    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity() {
    int low_byte = i2c_read_with_retry(i2c_handle, 0x16);
    int high_byte = i2c_read_with_retry(i2c_handle, 0x17);

    if (low_byte < 0 || high_byte < 0) {
        return -1; // Indicate error
    }

    return (high_byte << 8) | low_byte;
}

// Function to log the data to a file
int log_data(int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            if (log_data(proximity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading proximity data\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

