#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile static uint32_t start_tick = 0;
volatile static uint32_t end_tick = 0;
volatile static int echo_received = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
double calculateDistance(uint32_t pulse_width);
void controlBuzzer(double distance);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        // Falling edge
        end_tick = tick;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance from pulse width
double calculateDistance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer based on distance
void controlBuzzer(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        triggerSensor(); // Trigger the sensor
        gpioDelay(50); // Wait for echo

        uint32_t pulse_width = end_tick - start_tick; // Calculate pulse width
        double distance = calculateDistance(pulse_width); // Calculate distance

        printf("Distance: %.2f cm\n", distance); // Print distance
        controlBuzzer(distance); // Control buzzer

        sleep(1); // Wait for 1 second
    }

    return 0; // This line will never be reached due to the infinite loop
}

