#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants for distance mapping
#define MAX_DISTANCE 200.0  // cm
#define MIN_DISTANCE 20.0   // cm
#define SERVO_MAX_PULSEWIDTH 2500 // us
#define SERVO_MIN_PULSEWIDTH 500  // us

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04 sensor
float getDistance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) return -1.0; // Timeout
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) return -1.0; // Timeout
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = time_taken * 34300.0 / 2.0; // Distance in cm

    return distance;
}

// Function to set servo angle
void setServoAngle(float distance) {
    float pulsewidth;

    if (distance <= MIN_DISTANCE) {
        pulsewidth = SERVO_MAX_PULSEWIDTH;
    } else if (distance >= MAX_DISTANCE) {
        pulsewidth = SERVO_MIN_PULSEWIDTH;
    } else {
        // Linear mapping
        pulsewidth = SERVO_MAX_PULSEWIDTH - (distance - MIN_DISTANCE) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    gpioServo(SERVO_PIN, (int)pulsewidth);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = getDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            setServoAngle(distance);
        } else {
            fprintf(stderr, "Error: Sensor timeout or error\n");
        }

        gpioDelay(100); // Update every 100 ms
    }

    // Cleanup before exiting
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

