#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 18
#define OPEN_PULSE_WIDTH 2000
#define CLOSED_PULSE_WIDTH 1000
#define OPEN_THRESHOLD 200
#define CLOSED_THRESHOLD 250
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    int status;
    unsigned char model_id;

    // Check model ID
    status = i2cReadByteData(i2c_handle, 0x010F);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (unsigned char)status;
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget (e.g., 50ms)
    status = i2cWriteByteData(i2c_handle, 0x001E, 0x32); // Example value, adjust as needed
    if (status < 0) {
        fprintf(stderr, "Error setting timing budget: %d\n", status);
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Start ranging
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from the sensor
int read_distance() {
    int status;
    unsigned char msb, lsb;
    int distance;

    status = i2cReadByteData(i2c_handle, 0x0089); // Read MSB
    if (status < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", status);
        return -1;
    }
    msb = (unsigned char)status;

    status = i2cReadByteData(i2c_handle, 0x008A); // Read LSB
    if (status < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", status);
        return -1;
    }
    lsb = (unsigned char)status;

    distance = (msb << 8) | lsb;
    return distance;
}

// Open the gate
void open_gate() {
    gpioPWM(GATE_GPIO, OPEN_PULSE_WIDTH);
    log_event("Gate opened");
}

// Close the gate
void close_gate() {
    gpioPWM(GATE_GPIO, CLOSED_PULSE_WIDTH);
    log_event("Gate closed");
}

// Log an event to the log file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    int distance;
    int gate_state = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

