int read_distance() {
    int status;
    unsigned char msb, lsb;
    int distance;

    status = i2cReadByteData(i2c_handle, 0x0089); // Read MSB
    if (status < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", status);
        return -1;
    }
    msb = (unsigned char)status;

    status = i2cReadByteData(i2c_handle, 0x008A); // Read LSB
    if (status < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", status);
        return -1;
