#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int configure_sensor();
int read_sensor_data(float *temperature, float *humidity);
void convert_data(unsigned short raw_temp, unsigned short raw_humidity, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buffer[4];
    int result;

    // Read temperature
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    unsigned short raw_temp = (buffer[0] << 8) | buffer[1];

    // Read humidity
    result = i2cReadI2CBlockData(i2c_handle, HUMID_REG, (char *)buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    unsigned short raw_humidity = (buffer[0] << 8) | buffer[1];

    convert_data(raw_temp, raw_humidity, temperature, humidity);
    return 0;
}

// Convert raw data to temperature and humidity
void convert_data(unsigned short raw_temp, unsigned short raw_humidity, float *temperature, float *humidity) {
    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;
}

// Log the data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            if (open_i2c_bus() != 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }
        gpioDelay(2000000); // 2 seconds delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

