#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High repeatability measurement command
#define SHT40_MEASURE_HIGH_REPEATABILITY 0xFD

// I2C bus
#define I2C_BUS 1

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for graceful shutdown
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd = SHT40_MEASURE_HIGH_REPEATABILITY;
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Open I2C bus
        i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        float temperature, humidity;

        // Read temperature and humidity
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 sensor.\n");
        }

        // Close I2C bus
        i2cClose(i2c_handle);
        i2c_handle = -1; // Reset handle

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Close I2C bus if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

