#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function prototypes
int init_i2c();
TemperatureData read_temperatures();
float convert_to_celsius(unsigned int raw_temp);
int log_temperature(TemperatureData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperatures from the sensor
TemperatureData read_temperatures() {
    TemperatureData data;
    unsigned char buffer[4];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        data.ambient_temp = -273.15; // Indicate error with absolute zero
    } else {
        unsigned int raw_ambient = (buffer[1] << 8) | buffer[0];
        data.ambient_temp = convert_to_celsius(raw_ambient);
    }

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        data.object_temp = -273.15; // Indicate error with absolute zero
    } else {
        unsigned int raw_object = (buffer[1] << 8) | buffer[0];
        data.object_temp = convert_to_celsius(raw_object);
    }

    return data;
}

// Convert raw temperature to Celsius
float convert_to_celsius(unsigned int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Log temperature data to file
int log_temperature(TemperatureData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fclose(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        TemperatureData data = read_temperatures();

        if (data.ambient_temp > -273.0 && data.object_temp > -273.0) {
            if (log_temperature(data) != 0) {
                fprintf(stderr, "Error logging temperature data.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data. Skipping logging.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

