#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x08
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int config_sensor();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    uint8_t crc_received = data[len - 1];
    return (crc_calculated == crc_received);
}

// Data conversion function
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor_pressure = (data[6] << 8) | data[7];
    uint16_t scale_factor_temperature = (data[8] << 8) | data[9];

    sensor_data.pressure = (float)raw_pressure / scale_factor_pressure;
    sensor_data.temperature = (float)raw_temperature / scale_factor_temperature;

    return sensor_data;
}

// Timestamp generation function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Data logging function
int log_data(const char *timestamp, float pressure, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor configuration function
int config_sensor() {
    char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait at least 1 ms
    return 0;
}

// Sensor data reading function
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Could not read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (config_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t converted_data;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC for pressure data
            if (validate_crc(sensor_data, 3)) {
                // Validate CRC for temperature data
                if (validate_crc(sensor_data + 3, 3)) {
                    // Validate CRC for scale factors
                    if (validate_crc(sensor_data + 6, 3)) {
                        // Convert data
                        converted_data = convert_data(sensor_data);

                        // Get timestamp
                        timestamp = get_iso8601_timestamp();

                        // Log data
                        if (log_data(timestamp, converted_data.pressure, converted_data.temperature) != 0) {
                            fprintf(stderr, "Error: Could not log data\n");
                        }

                        free(timestamp); // Free the allocated memory
                    } else {
                        fprintf(stderr, "Error: Scale factors CRC check failed\n");
                    }
                } else {
                    fprintf(stderr, "Error: Temperature CRC check failed\n");
                }
            } else {
                fprintf(stderr, "Error: Pressure CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read sensor data\n");
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

