#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define RETRY_COUNT 3
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C bus");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C bus");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data conversion function
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Logging function
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    uint8_t write_data[1] = {MEASURE_HIGH_REPEATABILITY};
    uint8_t read_data[6];
    sensor_data_t sensor_values;
    int retry;

    while (!stop_flag) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            // Send measurement command
            if (i2c_write(i2c_fd, SHT40_ADDR, write_data, 1) < 0) {
                fprintf(stderr, "I2C write failed, retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                usleep(100000); // 100ms delay
                continue;
            }

            // Wait for measurement (at least 10ms)
            usleep(10000);

            // Read data
            if (i2c_read(i2c_fd, SHT40_ADDR, read_data, 6) < 0) {
                fprintf(stderr, "I2C read failed, retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                usleep(100000); // 100ms delay
                continue;
            }

            // CRC validation
            if (crc8(read_data, 2) != read_data[2] || crc8(read_data + 3, 2) != read_data[5]) {
                fprintf(stderr, "CRC validation failed, retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                usleep(100000); // 100ms delay
                continue;
            }

            // Convert data
            uint16_t raw_temperature = (read_data[0] << 8) | read_data[1];
            uint16_t raw_humidity = (read_data[3] << 8) | read_data[4];
            sensor_values = convert_data(raw_temperature, raw_humidity);

            // Log data
            if (log_data(sensor_values.temperature, sensor_values.humidity) < 0) {
                fprintf(stderr, "Logging failed.\n");
            }

            break; // Exit retry loop on success
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

