#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_CMD 0x2196
#define TRIGGER_CMD_HIGH (TRIGGER_CMD >> 8)
#define TRIGGER_CMD_LOW (TRIGGER_CMD & 0xFF)
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate_flag = 0;

// Function prototypes
int initialize();
int trigger_measurement();
int read_sensor_data(int16_t *pressure, int16_t *temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure_pa, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_pressure, raw_temperature;
    sensor_data_t sensor_data;

    while (!terminate_flag) {
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(1); // Wait at least 1 ms

        if (read_sensor_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        sensor_data.pressure_pa = convert_pressure(raw_pressure);
        sensor_data.temperature_c = convert_temperature(raw_temperature);

        if (log_data(sensor_data.pressure_pa, sensor_data.temperature_c) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int trigger_measurement() {
    char cmd[2] = {TRIGGER_CMD_HIGH, TRIGGER_CMD_LOW};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return 1;
    }
    return 0;
}

int read_sensor_data(int16_t *pressure, int16_t *temperature) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }

    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 60.0;
}

float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

int log_data(float pressure_pa, float temperature_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate_flag = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

