#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define TEMP_CONVERSION 175.72
#define TEMP_OFFSET -46.85
#define HUMID_CONVERSION 125.0
#define HUMID_OFFSET -6.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, unsigned char command, unsigned short *data);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humid);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int handle, unsigned char command, unsigned short *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, command, 0); // Write command
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %s (pigpio error: %s)\n", strerror(errno), pigpio_error(result));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(20000); // Wait 20ms for measurement

        result = i2cReadWordData(handle, command); // Read data
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C: %s (pigpio error: %s)\n", strerror(errno), pigpio_error(result));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        *data = (unsigned short)result;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned short raw_temp) {
    return (TEMP_CONVERSION * raw_temp / 65536.0) + TEMP_OFFSET;
}

// Function to convert raw humidity to percentage relative humidity
float convert_humidity(unsigned short raw_humid) {
    float humidity = (HUMID_CONVERSION * raw_humid / 65536.0) + HUMID_OFFSET;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
