#define MEASURE_CMD 0x2C06
#define CONVERSION_DELAY_MS 15
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
float convert_to_celsius(unsigned short raw_value);
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    int sample_interval;
} config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 2) {
        log_error("Failed to send measurement command");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read sensor data");
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw value to Celsius
float convert_to_celsius(unsigned short raw_value) {
    return -45.0 + 175.0 * (raw_value / 65535.0);
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

