    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            log_error("Failed to send measurement command, retrying I2C init");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
