int send_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SHT40 sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
    return (calculated_crc == checksum);
}

