                // Validate CRC for temperature
                if (!validate_crc(data, 2, data[2])) {
                    fprintf(stderr, "Temperature CRC validation failed\n");
                } else {
                    // Validate CRC for humidity
                    if (!validate_crc(data, 2, data[5])) {
                        fprintf(stderr, "Humidity CRC validation failed\n");
                    } else {
                        // Convert data
                        uint16_t raw_temperature = (data[0] << 8) | data[1];
                        uint16_t raw_humidity = (data[3] << 8) | data[4];
                        sensor_data = convert_data(raw_temperature, raw_humidity);

                        // Log data
                        log_data(sensor_data);
                    }
                }
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

