#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define PRESSURE_SCALE_FACTOR 240.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define TEMPERATURE_OFFSET -45.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send the measurement command to the sensor
int send_measurement_command() {
    uint8_t command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC Check
    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[3], data[4]};

    if (calculate_crc(pressure_data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / PRESSURE_SCALE_FACTOR;
    }

    if (calculate_crc(temperature_data, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;
    }

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(1); // Wait for measurement (at least 1ms)

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (converted_data.pressure != -999.0 && converted_data.temperature != -999.0) {
            log_data(converted_data);
        } else {
            fprintf(stderr, "Error: Invalid sensor data, not logging.\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

