#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entry
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int handle, float *temperature, float *humidity);
void control_fan(float temperature);
void add_reading(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature and humidity from the sensor
int read_sensor(int handle, float *temperature, float *humidity) {
    int retries = 3;
    int result;
    uint16_t raw_temperature, raw_humidity;

    // Read temperature
    while (retries > 0) {
        result = i2cWriteByteData(handle, 0, 0xE3); // Trigger temperature measurement
        if (result == 0) break;
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to trigger temperature measurement after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    retries = 3;
    while (retries > 0) {
        raw_temperature = i2cReadWordData(handle, 0);
        if (raw_temperature >= 0) break;
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read temperature after multiple retries.\n");
        return -1;
    }

    // Read humidity
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, 0, 0xE5); // Trigger humidity measurement
        if (result == 0) break;
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to trigger humidity measurement after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    retries = 3;
    while (retries > 0) {
        raw_humidity = i2cReadWordData(handle, 0);
        if (raw_humidity >= 0) break;
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read humidity after multiple retries.\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, float humidity) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, buffer[index].temperature, buffer[index].humidity);
    }
    printf("------------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor(i2c_handle, &temperature, &humidity) == 0) {
            add_reading(temperature, humidity);
            control_fan(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

