#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_DATA_READY 0xE4B8

// Log file name
#define LOG_FILE "air_quality.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int check_data_ready(int handle);
sensor_data_t read_sensor_data(int handle);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Check if data is ready
int check_data_ready(int handle) {
    uint8_t data[3];
    if (send_command(handle, CMD_DATA_READY) != 0) {
        return -1;
    }
    gpioDelay(1); // Small delay after sending the command
    if (read_data(handle, data, 3) != 0) {
        return -1;
    }
    return (data[0] == 0x00 && data[1] == 0x00);
}

// Read sensor data
sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data;
    uint8_t raw_data[9];

    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) {
        data.co2 = 0; // Indicate error
        data.temperature = 0.0;
        data.humidity = 0.0;
        return data;
    }
    gpioDelay(1); // Small delay after sending the command
    if (read_data(handle, raw_data, 9) != 0) {
        data.co2 = 0; // Indicate error
        data.temperature = 0.0;
        data.humidity = 0.0;
        return data;
    }

    // CRC check
    if (crc8(raw_data, 2) != raw_data[2] ||
        crc8(raw_data + 3, 2) != raw_data[5] ||
        crc8(raw_data + 6, 2) != raw_data[8]) {
        fprintf(stderr, "CRC check failed\n");
        data.co2 = 0; // Indicate error
        data.temperature = 0.0;
        data.humidity = 0.0;
        return data;
    }

    data.co2 = (raw_data[0] << 8) | raw_data[1];
    uint16_t temp_raw = (raw_data[3] << 8) | raw_data[4];
    uint16_t humidity_raw = (raw_data[6] << 8) | raw_data[7];

    data.temperature = -45 + 175 * (float)temp_raw / 65535.0;
    data.humidity = 100 * (float)humidity_raw / 65535.0;

    return data;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, (float)data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }
    gpioDelay(1); // Small delay after sending the command

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (check_data_ready(i2c_handle) == 1) {
            // Read sensor data
            sensor_data_t data = read_sensor_data(i2c_handle);

            // Log data
            log_data(data);
        } else {
            fprintf(stderr, "Data not ready yet\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

