    uint8_t temperature_data[2] = {read_buf[3], read_buf[4]};
    if (!validate_crc(temperature_data, 2, read_buf[5])) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for Humidity
    uint8_t humidity_data[2] = {read_buf[6], read_buf[7]};
    if (!validate_crc(humidity_data, 2, read_buf[8])) {
