}

// Print circular buffer
void print_circular_buffer() {
    printf("\n--- Circular Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("Index: %d, CO2: %u, Temperature: %.2f, Humidity: %.2f, Timestamp: %ld\n",
               index, circular_buffer[index].data.co2, circular_buffer[index].data.temperature,
               circular_buffer[index].data.humidity, circular_buffer[index].timestamp);
    }
    printf("--- End of Buffer ---\n\n");
}

// Control LED based on CO2 level
void control_led(int co2_level) {
    if (co2_level > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    uint16_t co2;
    float temperature, humidity;

    while (!terminate) {
        // Check data ready status
        int data_ready = get_data_ready_status();
        if (data_ready < 0) {
            fprintf(stderr, "Error getting data ready status, retrying...\n");
            sleep(1);
            continue;
        }

        if (data_ready) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                sensor_data.co2 = co2;
                sensor_data.temperature = temperature;
                sensor_data.humidity = humidity;

                // Add data to circular buffer
                add_to_circular_buffer(sensor_data);

                // Print data to stdout
                printf("CO2: %u ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);

                // Control LED
                control_led(co2);
            } else {
                fprintf(stderr, "Error reading measurement data, retrying...\n");
            }
        } else {
            // Wait for data to be ready
            gpioDelay(100); // Check every 100ms
        }

        sleep(5); // Measure every 5 seconds
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Error stopping periodic measurement\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    // Print circular buffer
    print_circular_buffer();

    return 0;
}

