#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50ms timeout
#define SAMPLE_INTERVAL_S 5
#define MAX_CONSECUTIVE_FAILURES 3

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int consecutive_failures = 0;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int level;

    // Wait for the GPIO to change state
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == (level = gpioRead(GPIO_PIN))) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for GPIO to change state.\n");
            return -1.0; // Indicate timeout error
        }
    }

    // Measure high time
    high_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == level) {
        if (gpioTick() - high_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for GPIO to return to previous state (high).\n");
            return -1.0; // Indicate timeout error
        }
    }
    high_tick = gpioTick() - high_tick;

    // Measure low time
    low_tick = gpioTick();
    while (gpioRead(GPIO_PIN) != level) {
        if (gpioTick() - low_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for GPIO to change state (low).\n");
            return -1.0; // Indicate timeout error
        }
    }
    low_tick = gpioTick() - low_tick;

    uint32_t total_tick = high_tick + low_tick;

    // Calculate temperature
    float temperature = 4215.0 - (2143.0 * (float)high_tick / (float)total_tick);

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging.\n");
        return;
    }

    if (log_file != NULL) {
        if (temperature >= -40.0 && temperature <= 150.0) {
            fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
            fflush(log_file); // Ensure data is written to disk immediately
            consecutive_failures = 0; // Reset failure count on success
        } else {
            fprintf(log_file, "%s, ERROR: Temperature out of range: %.2f\n", timestamp, temperature);
            fflush(log_file);
            consecutive_failures++;
            if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                consecutive_failures = 0; // Reset after logging malfunction
            }
        }
    } else {
