    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open temperature_log.txt");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay for 5 seconds
    }

