#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define SIMULATION_DURATION 3600 // seconds (1 hour)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
sensor_data_t convert_data(uint8_t data[]);
sensor_data_t add_sinusoidal_offset(sensor_data_t data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();
uint8_t crc8(const uint8_t *data, int len);

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(uint8_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result;

    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
            continue;
        }

        gpioDelay(15000); // Wait 15 ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
        }
    }
    return -1; // All retries failed
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    return (crc8(data, nbrOfBytes) == checksum);
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint8_t data[]) {
    sensor_data_t sensor_data;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Add sinusoidal offset to simulate environmental changes
sensor_data_t add_sinusoidal_offset(sensor_data_t data) {
    time_t now = time(NULL);
    double time_elapsed = (double)now;

    data.temperature += 2.0 * sin(time_elapsed * M_PI / 180.0); // ±2 °C
    data.humidity += 5.0 * sin(time_elapsed * M_PI / 180.0);    // ±5 %RH

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data_raw[6];
    sensor_data_t sensor_data;
    time_t start_time = time(NULL);

    // Main loop
    while (!terminate && (time(NULL) - start_time) < SIMULATION_DURATION) {
        // Read sensor data
        if (read_sensor_data(sensor_data_raw) == 0) {
            // Validate CRC for temperature
            if (!validate_crc(sensor_data_raw, 2, sensor_data_raw[2])) {
                fprintf(stderr, "Temperature CRC validation failed\n");
                sensor_data.temperature = NAN;
            } else {
                // Validate CRC for humidity
                if (!validate_crc(sensor_data_raw + 3, 2, sensor_data_raw[5])) {
                    fprintf(stderr, "Humidity CRC validation failed\n");
                    sensor_data.humidity = NAN;
                } else {
                    // Convert data
                    sensor_data = convert_data(sensor_data_raw);

                    // Add sinusoidal offset
                    sensor_data = add_sinusoidal_offset(sensor_data);

                    // Log data
                    log_data(sensor_data);
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            sensor_data.temperature = NAN;
            sensor_data.humidity = NAN;
            log_data(sensor_data); // Log NaN values
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

