#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define MEASURE_DELAY_MS 15
#define DATA_LENGTH 6
#define CSV_FILE "environment.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_data(int handle, char *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = crc8(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Temperature conversion function
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Humidity conversion function
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to SHT35
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT35
int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    // Get current timestamp in ISO 8601 format
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASURE_DELAY_MS * 1000); // Convert ms to us

        // Read data
        char data[DATA_LENGTH];
        if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc((uint8_t *)data, 3) || !validate_crc((uint8_t *)data + 3, 3)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];
        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait before next measurement
        gpioDelay(5000000); // 5 seconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

