#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor with timeout
int read_sensor_data(int handle, unsigned char command, unsigned char *data, int len) {
    int retries = 0;
    int bytes_read;

    while (retries < 10) {
        if (i2cWriteByte(handle, command) != 0) {
            fprintf(stderr, "Error writing command to sensor.\n");
            return -1;
        }
        gpioDelay(10); // Small delay after writing the command

        bytes_read = i2cReadDevice(handle, (char *)data, len);
        if (bytes_read == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading data from sensor (attempt %d): %d bytes read\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(10); // Wait before retrying
        }
    }
    fprintf(stderr, "Failed to read data from sensor after multiple retries.\n");
    return -1; // Failure after multiple retries
}

// Function to read temperature and humidity from the sensor
int read_temperature_humidity(int handle, float *temperature, float *humidity) {
    unsigned char data[3];

    // Read humidity
    if (read_sensor_data(handle, HUMID_CMD, data, 3) != 0) {
        fprintf(stderr, "Error reading humidity data.\n");
        return -1;
    }

    // CRC check for humidity
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Humidity CRC check failed.\n");
        return -1;
    }

    unsigned int raw_humidity = (data[0] << 8) | data[1];

    // Read temperature
    if (read_sensor_data(handle, TEMP_CMD, data, 3) != 0) {
        fprintf(stderr, "Error reading temperature data.\n");
        return -1;
    }

    // CRC check for temperature
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed.\n");
        return -1;
    }

    unsigned int raw_temperature = (data[0] << 8) | data[1];

