// Constants
#define I2C_BUS 1
#define SDP810_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_MS 50
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int write_data_to_file(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc8(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Data conversion
sensor_data_t convert_data(const uint8_t *data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int32_t scale_factor = (data[6] << 16) | (data[7] << 8) | data[8];

    float pressure = (float)raw_pressure / scale_factor - 1000.0f;
    float temperature = (float)raw_temperature / 200.0f - 45.0f;

    sensor_data_t sensor_data;
    sensor_data.pressure = pressure;
    sensor_data.temperature = temperature;

    return sensor_data;
}

// File writing
int write_data_to_file(const sensor_data_t *data) {
    if (fwrite(data, sizeof(sensor_data_t), 1, fp) != 1) {
        perror("Error writing to file");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command.\n");
            break;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data.\n");
            break;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 3)) {
            fprintf(stderr, "Pressure CRC validation failed.\n");
            continue; // Skip to the next iteration
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 3)) {
            fprintf(stderr, "Temperature CRC validation failed.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Write data to file
        if (write_data_to_file(&sensor_data) != 0) {
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

