    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    uint8_t command[2] = {(CONTINUOUS_MEASUREMENT_COMMAND >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

