volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes);
float convert_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
