#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 10.0
#define FLOW_RATE_MIN_COUNTS 1638
#define FLOW_RATE_MAX_COUNTS 14745
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor();
float convert_to_flow_rate(int raw_value);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to read the sensor data
int read_sensor() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int raw_value = (buf[0] << 8) | buf[1];

    // Mask off the status bits (2 most significant bits)
    raw_value &= 0x3FFF; // 0011 1111 1111 1111

    return raw_value;
}

// Function to convert raw sensor value to flow rate (SLPM)
float convert_to_flow_rate(int raw_value) {
    float flow_rate = ((float)(raw_value - FLOW_RATE_MIN_COUNTS) / (FLOW_RATE_MAX_COUNTS - FLOW_RATE_MIN_COUNTS)) * (FLOW_RATE_MAX - FLOW_RATE_MIN);
    return flow_rate;
}

// Function to set the fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    // Map flow rate (0-10 SLPM) to PWM duty cycle (0-100%)
    int duty_cycle = (int)((flow_rate / FLOW_RATE_MAX) * 1000000); // pigpio uses 0-1000000 for duty cycle

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value = read_sensor();
        if (raw_value >= 0) {
            float flow_rate = convert_to_flow_rate(raw_value);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor, skipping this iteration.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

