#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor-specific constants
#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1_REG 0x10
#define PRESS_OUT_XL_REG 0x28
#define PRESS_OUT_L_REG 0x29
#define PRESS_OUT_H_REG 0x2A
#define TEMP_OUT_L_REG 0x2B
#define TEMP_OUT_H_REG 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(float *pressure, float *temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[20];

    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

// Initialize the LPS33HW sensor
int init_sensor() {
    int status;
    uint8_t who_am_i;

    // Check WHO_AM_I register
    status = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (status < 0) {
        log_error("Failed to read WHO_AM_I register");
        return -1;
    }
    who_am_i = (uint8_t)status;

    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xB1\n", who_am_i);
        log_error("Incorrect WHO_AM_I value");
        return -1;
    }

    // Configure CTRL_REG1 for 10 Hz output rate and active mode
    status = i2cWriteByteData(i2c_handle, CTRL_REG1_REG, 0xB0);
    if (status < 0) {
        log_error("Failed to write CTRL_REG1 register");
        return -1;
    }

    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(float *pressure, float *temperature) {
    int status;
    uint8_t press_xl, press_l, press_h;
    uint8_t temp_l, temp_h;
    int32_t raw_pressure;
    int16_t raw_temperature;

    // Read pressure data
    status = i2cReadByteData(i2c_handle, PRESS_OUT_XL_REG);
    if (status < 0) {
        log_error("Failed to read PRESS_OUT_XL register");
        return -1;
    }
    press_xl = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, PRESS_OUT_L_REG);
    if (status < 0) {
        log_error("Failed to read PRESS_OUT_L register");
        return -1;
    }
    press_l = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, PRESS_OUT_H_REG);
    if (status < 0) {
        log_error("Failed to read PRESS_OUT_H register");
        return -1;
    }
    press_h = (uint8_t)status;

    // Combine pressure data into a 24-bit value
    raw_pressure = (int32_t)((press_h << 16) | (press_l << 8) | press_xl);

    // Read temperature data
    status = i2cReadByteData(i2c_handle, TEMP_OUT_L_REG);
    if (status < 0) {
        log_error("Failed to read TEMP_OUT_L register");
        return -1;
    }
    temp_l = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, TEMP_OUT_H_REG);
    if (status < 0) {
        log_error("Failed to read TEMP_OUT_H register");
        return -1;
    }
    temp_h = (uint8_t)status;

    // Combine temperature data into a 16-bit value
    raw_temperature = (int16_t)((temp_h << 8) | temp_l);

    // Convert raw data to hPa and Celsius
    *pressure = (float)raw_pressure / 4096.0;
    *temperature = 42.5 + (float)raw_temperature / 480.0;

    return 0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[20];

    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main() {
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

