#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stlm75_address;
    int led_pin;
    float temperature_threshold;
} Config;

Config config = {I2C_BUS, STLM75_ADDR, LED_GPIO, TEMP_THRESHOLD};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -1000.0) { // Check for error value
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping.\n");
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(config.i2c_bus, config.stlm75_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(config.led_pin, PI_OUTPUT);
    gpioWrite(config.led_pin, 0); // Initially turn off the LED

    // Initialize the buffer with a default value (e.g., 0.0)
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    return 0;
}

float read_temperature() {
    int raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", raw_data);
        return -1000.0; // Return a special error value
    }

    // Convert raw data to temperature (Celsius)
    int16_t swapped_data = ((raw_data & 0xFF) << 8) | ((raw_data & 0xFF00) >> 8);
    float temperature = (float)(swapped_data >> 7) / 2.0;
    return temperature;
}

void update_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

void control_led(float average_temperature) {
    if (average_temperature > config.temperature_threshold) {
        gpioWrite(config.led_pin, 1); // Turn on LED
    } else {
        gpioWrite(config.led_pin, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    gpioWrite(config.led_pin, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

