#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 2

// Log file path
#define LOG_FILE "air_quality.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int set_measurement_interval(int interval);
int read_measurement(float *co2, float *temperature, float *humidity);
int is_data_ready();
unsigned char crc8(const unsigned char *data, int len);
int log_data(float co2, float temperature, float humidity, const char *ventilation_status);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    unsigned char cmd[2] = {(SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        return -1;
    }
    return 0;
}

// Set measurement interval
int set_measurement_interval(int interval) {
    unsigned char cmd[2] = {(SCD30_CMD_SET_MEASUREMENT_INTERVAL >> 8) & 0xFF, SCD30_CMD_SET_MEASUREMENT_INTERVAL & 0xFF};
    unsigned char data[2] = {(interval >> 8) & 0xFF, interval & 0xFF};
    unsigned char buf[4];
    memcpy(buf, cmd, 2);
    memcpy(buf + 2, data, 2);

    if (i2cWriteDevice(i2c_handle, buf, 4) != 4) {
        fprintf(stderr, "Failed to set measurement interval\n");
        return -1;
    }
    return 0;
}

// Check if data is ready
int is_data_ready() {
    unsigned char cmd[2] = {(SCD30_CMD_GET_DATA_READY >> 8) & 0xFF, SCD30_CMD_GET_DATA_READY & 0xFF};
    unsigned char buf[3];
    unsigned char data[1];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write data ready command\n");
        return -1;
    }

    gpioDelay(10); // Small delay after writing the command

    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Failed to read data ready status\n");
        return -1;
    }

    return data[0];
}

// Read measurement data
int read_measurement(float *co2, float *temperature, float *humidity) {
    unsigned char cmd[2] = {(SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_READ_MEASUREMENT & 0xFF};
    unsigned char data[18];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write read measurement command\n");
        return -1;
    }

    gpioDelay(10); // Small delay after writing the command

    if (i2cReadDevice(i2c_handle, data, 18) != 18) {
        fprintf(stderr, "Failed to read measurement data\n");
        return -1;
    }

    // CRC check
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8] ||
        crc8(data + 9, 2) != data[11]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    *co2 = (float)((((unsigned int)data[0]) << 8) | data[1]);
    *temperature = (float)((((unsigned int)data[3]) << 8) | data[4]);
    *humidity = (float)((((unsigned int)data[6]) << 8) | data[7]);

    return 0;
}

// Log data to file
int log_data(float co2, float temperature, float humidity, const char *ventilation_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%s\n", timestamp, co2, temperature, humidity, ventilation_status);
    fflush(log_file);

    return 0;
}

// Ventilation control logic
void ventilation_control(float co2) {
    if (co2 < 800.0) {
        log_data(co2, 0.0, 0.0, "OFF");
    } else if (co2 >= 800.0 && co2 < 1200.0) {
        log_data(co2, 0.0, 0.0, "LOW");
    } else {
        log_data(co2, 0.0, 0.0, "HIGH");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop periodic measurement
    unsigned char stop_cmd[2] = {(SCD30_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    i2cWriteDevice(i2c_handle, stop_cmd, 2);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set measurement interval
    if (set_measurement_interval(MEASUREMENT_INTERVAL) != 0) {
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    float co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (is_data_ready()) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity, "UNKNOWN");

                // Ventilation control
                ventilation_control(co2);
            } else {
                fprintf(stderr, "Failed to read measurement, retrying...\n");
            }
        } else {
            fprintf(stderr, "Data not ready, retrying...\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Wait for the measurement interval
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

