#define SDP32_MEASURE_CMD_1 0x36
#define SDP32_MEASURE_CMD_2 0x2F

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
int sampling_interval_ms = 1000; // Default sampling interval

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

