    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // I2C bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement mode
int start_measurement() {
    char cmd[2] = {SDP32_MEASURE_CMD_1, SDP32_MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

