// Define the read command (consult datasheet)
#define READ_COMMAND 0x00 // Example command, adjust as needed

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the MLX90833 sensor
int read_pressure(int i2c_handle, float *pressure) {
    char buf[2];
    int result;

    // Send the read command
    result = i2cWriteByte(i2c_handle, READ_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the raw data to pressure (adjust scaling as needed)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure * 0.1; // Example scaling, adjust based on datasheet

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float pressure;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Read pressure
        if (read_pressure(i2c_handle, &pressure) == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the pressure reading with timestamp
            printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
        } else {
            fprintf(stderr, "Error reading pressure\n");
        }

        // Wait 500 milliseconds
        gpioDelay(500000); // pigpio uses microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

