// Define sensor-specific constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x63
#define CMD_READ_CALIB 0x50
#define CMD_TRIGGER_MEAS 0x40
#define CMD_READ_DATA 0x30
#define MEASUREMENT_DELAY_MS 7

// Calibration data structure
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
    uint16_t c01;
    uint16_t c11;
    uint16_t c20;
    uint16_t c21;
} calibration_data_t;

// Global variables
int i2c_handle;
calibration_data_t calib_data;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, calibration_data_t *calib_data);
int trigger_measurement(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
double convert_temperature(uint16_t raw_temp, calibration_data_t calib_data);
double convert_pressure(uint32_t raw_pressure, uint16_t raw_temp, calibration_data_t calib_data);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read calibration data from the sensor
int read_calibration_data(int i2c_handle, calibration_data_t *calib_data) {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CMD_READ_CALIB, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calib_data->c0 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    calib_data->c1 = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    calib_data->c00 = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    calib_data->c10 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    calib_data->c01 = 0; // Not used in this implementation
    calib_data->c11 = 0; // Not used in this implementation
    calib_data->c20 = 0; // Not used in this implementation
    calib_data->c21 = 0; // Not used in this implementation

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, CMD_TRIGGER_MEAS, 0x03); // High precision mode
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, CMD_READ_DATA, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw temperature to Celsius
double convert_temperature(uint16_t raw_temp, calibration_data_t calib_data) {
    // Placeholder conversion formula - replace with actual formula from datasheet
    return (double)raw_temp / 100.0; // Example: 0.01 degree C resolution
}

// Function to convert raw pressure to Pascals
double convert_pressure(uint32_t raw_pressure, uint16_t raw_temp, calibration_data_t calib_data) {
    // Placeholder conversion formula - replace with actual formula from datasheet
    return (double)raw_pressure * 10.0; // Example: 0.1 Pa resolution
}

// Function to log data with ISO 8601 timestamp
void log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", buf, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib_data) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

