#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define PRESSURE_REG_MSB 0xAA
#define PRESSURE_REG_LSB 0xAB

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read pressure from the MLX90819 sensor
int read_pressure(int fd) {
    uint8_t msb, lsb;
    int16_t raw_pressure;

    // Trigger measurement (no specific command needed for MLX90819, just read)

    // Read MSB
    if (write(fd, &PRESSURE_REG_MSB, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read LSB
    if (write(fd, &PRESSURE_REG_LSB, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB into a 16-bit value
    raw_pressure = (msb << 8) | lsb;

    return raw_pressure;
}

// Function to convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return raw_pressure * 0.1;
}

// Function to log the pressure reading with a timestamp
void log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int raw_pressure = read_pressure(i2c_fd);
        if (raw_pressure != -1) {
            float pressure_kPa = convert_to_kPa(raw_pressure);
            log_pressure(pressure_kPa);
        } else {
            fprintf(stderr, "Error reading pressure, retrying...\n");
        }
        sleep(1);
    }

    // The program should never reach here due to the signal handler
    close(i2c_fd);
    return 0;
}

