#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND_1 0x36
#define MEASUREMENT_COMMAND_2 0x2F
#define MEASUREMENT_DELAY_MS 8
#define CSV_FILENAME "airflow_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *pressure_raw);
uint8_t calculate_crc(uint8_t data1, uint8_t data2);
float convert_to_pressure(int16_t raw_pressure);
char* get_timestamp();
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int16_t raw_pressure;
    float pressure_pa;
    char timestamp[20];
} sensor_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.raw_pressure) == 0) {
            // Convert to pressure
            sensor_data.pressure_pa = convert_to_pressure(sensor_data.raw_pressure);

            // Get timestamp
            strcpy(sensor_data.timestamp, get_timestamp());

            // Log data
            if (log_data(sensor_data.pressure_pa) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *pressure_raw) {
    char cmd[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    char buffer[3];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return 1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

    // Read data
    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 1;
    }

    // CRC check
    uint8_t crc_calculated = calculate_crc(buffer[0], buffer[1]);
    if (crc_calculated != buffer[2]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc_calculated, buffer[2]);
        return 1;
    }

    // Combine data bytes
    *pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);

    return 0;
}

