uint8_t calculate_crc(uint8_t data1, uint8_t data2) {
    uint8_t crc = 0xFF;
    uint8_t data[2] = {data1, data2};

    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

