    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to preserve value between calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

