int log_data(float pressure) {
    FILE *fp;
    char *timestamp = get_timestamp();

    // Check if file exists
    if (access(CSV_FILENAME, F_OK) == -1) {
        // File doesn't exist, create it and write header
        fp = fopen(CSV_FILENAME, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open CSV file for writing\n");
            return 1;
        }
        fprintf(fp, "Timestamp,Pressure(Pa)\n");
    } else {
        // File exists, open in append mode
        fp = fopen(CSV_FILENAME, "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open CSV file for appending\n");
            return 1;
        }
    }

    // Write data
    fprintf(fp, "%s,%.2f\n", timestamp, pressure);

    // Close file
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

