#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_pressure(int *pressure_raw);
float convert_to_kPa(int pressure_raw);
int log_pressure(float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    float min_pressure;
    float max_pressure;
    char *log_file_name;
} config_t;

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(int *pressure_raw) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    *pressure_raw = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure to kPa
float convert_to_kPa(int pressure_raw) {
    return (float)pressure_raw * SCALE_FACTOR;
}

// Log pressure to file
int log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int pressure_raw;
    float pressure_kPa;

    while (!terminate) {
        // Read pressure
        if (read_pressure(&pressure_raw) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(pressure_raw);

            // Log pressure
            log_pressure(pressure_kPa);

            // Check for warning
            if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
                fprintf(stderr, "WARNING: Pressure out of range: %.2f kPa\n", pressure_kPa);
            }
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle
            if (open_i2c_bus() != 0) {
                fprintf(stderr, "Failed to reopen I2C bus, exiting...\n");
                break; // Exit loop if reopen fails
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

