#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for SENT sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define SENT timing parameters
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define NIBBLE_MIN_TICKS 36
#define NIBBLE_MAX_TICKS 813

// Define pressure conversion parameters
#define SCALE 0.1
#define OFFSET 0.0

// Define timeout duration (in seconds)
#define TIMEOUT_SECONDS 1

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int gpio;
    int raw_value;
    float pressure;
    int last_tick;
    int nibble_count;
    int nibble_data[5];
    int checksum;
    int timeout_count;
} sensor_data_t;

// Function prototypes
int read_sent_data(sensor_data_t *sensor);
int validate_checksum(sensor_data_t *sensor);
float convert_to_pressure(int raw_value);
void log_pressure_data(int sensor_id, float pressure);
void signal_handler(int signal);
void timeout_callback(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Timeout callback function
void timeout_callback(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *sensor = (sensor_data_t *)user_data;
    sensor->timeout_count++;
    fprintf(stderr, "Timeout on sensor %d (GPIO %d), timeout count: %d\n", sensor->gpio, sensor->gpio, sensor->timeout_count);
    sensor->raw_value = -1; // Indicate timeout
    sensor->pressure = -1.0;
}

// Function to read SENT data from a sensor
int read_sent_data(sensor_data_t *sensor) {
    int i;
    int pulse_width;
    int nibble_value;

    sensor->nibble_count = 0;
    sensor->checksum = 0;
    sensor->timeout_count = 0;

    // Wait for synchronization pulse
    while (gpioRead(sensor->gpio) == 1 && program_running) {
        gpioDelay(TICK_TIME_US);
    }

    if (!program_running) return -1;

    // Read nibbles
    for (i = 0; i < 5; i++) {
        nibble_value = 0;
        pulse_width = 0;

        // Measure pulse width
        while (gpioRead(sensor->gpio) == 0 && program_running) {
            pulse_width++;
            gpioDelay(TICK_TIME_US);
        }

        if (!program_running) return -1;

        while (gpioRead(sensor->gpio) == 1 && program_running) {
            pulse_width++;
            gpioDelay(TICK_TIME_US);
        }

        if (!program_running) return -1;

        // Validate pulse width
        if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "Error: Invalid pulse width on sensor %d (GPIO %d), pulse width: %d\n", sensor->gpio, sensor->gpio, pulse_width);
            return -1; // Bus error
        }

        // Convert pulse width to nibble value (example mapping, adjust as needed)
        nibble_value = (pulse_width - NIBBLE_MIN_TICKS) / 24; // Scale to 0-15

        sensor->nibble_data[i] = nibble_value;
        sensor->checksum += nibble_value;

        // Accumulate nibble value for raw data
        if (i > 0) {
            sensor->raw_value = (sensor->raw_value << 4) | nibble_value;
        }
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(sensor_data_t *sensor) {
    int calculated_checksum = sensor->checksum % 16;
    int received_checksum = sensor->nibble_data[4];

    if (calculated_checksum != received_checksum) {
        fprintf(stderr, "Error: Checksum mismatch on sensor %d (GPIO %d), calculated: %d, received: %d\n", sensor->gpio, sensor->gpio, calculated_checksum, received_checksum);
        return -1; // Checksum error
    }

    return 0;
}

// Function to convert raw value to pressure
float convert_to_pressure(int raw_value) {
    return (float)raw_value * SCALE + OFFSET;
}

// Function to log pressure data to a file
void log_pressure_data(int sensor_id, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Sensor %d: Pressure: %.2f Pa\n", timestamp, sensor_id, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Initialize sensor data structures
    sensor_data_t sensor1 = {SENSOR1_GPIO, 0, 0.0, 0, 0, {0}, 0, 0};
    sensor_data_t sensor2 = {SENSOR2_GPIO, 0, 0.0, 0, 0, {0}, 0, 0};
    sensor_data_t sensor3 = {SENSOR3_GPIO, 0, 0.0, 0, 0, {0}, 0, 0};

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timeout callbacks
    gpioSetAlertFuncEx(SENSOR1_GPIO, timeout_callback, &sensor1);
    gpioSetAlertFuncEx(SENSOR2_GPIO, timeout_callback, &sensor2);
    gpioSetAlertFuncEx(SENSOR3_GPIO, timeout_callback, &sensor3);

    // Main loop
    while (program_running) {
        // Read data from sensor 1
        if (read_sent_data(&sensor1) == 0) {
            if (validate_checksum(&sensor1) == 0) {
                sensor1.pressure = convert_to_pressure(sensor1.raw_value);
                log_pressure_data(1, sensor1.pressure);
            }
        }

        // Read data from sensor 2
        if (read_sent_data(&sensor2) == 0) {
            if (validate_checksum(&sensor2) == 0) {
                sensor2.pressure = convert_to_pressure(sensor2.raw_value);
                log_pressure_data(2, sensor2.pressure);
            }
        }

        // Read data from sensor 3
        if (read_sent_data(&sensor3) == 0) {
            if (validate_checksum(&sensor3) == 0) {
                sensor3.pressure = convert_to_pressure(sensor3.raw_value);
                log_pressure_data(3, sensor3.pressure);
            }
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

