#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x0F
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define DATA_FILE "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int verify_device_id(int i2c_handle);
float read_temperature(int i2c_handle);
int write_temperature_to_file(float temperature, FILE *fp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to verify the device ID
int verify_device_id(int i2c_handle) {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x0117) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x0117)\n", device_id);
        return -1;
    }
    printf("Device ID verified: 0x%04X\n", device_id);
    return 0;
}

// Function to read the temperature from the sensor
float read_temperature(int i2c_handle) {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error
    }
    return (float)raw_temp * TEMP_SCALE;
}

// Function to write the temperature to the file
int write_temperature_to_file(float temperature, FILE *fp) {
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file in append binary mode
    fp = fopen(DATA_FILE, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
