#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CONVERSION_DELAY_MS 8500
#define TEMP_MIN -45.0
#define TEMP_MAX 175.0
#define HUM_MIN -6.0
#define HUM_MAX 125.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_sensor_data(unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_hum);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Opens the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads sensor data from the SHT40
int read_sensor_data(unsigned char *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_MS);

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    return 0;
}

// Calculates the CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validates the CRC-8 checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char calculated_crc = calculate_crc(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Converts raw temperature data to Celsius
float convert_temperature(unsigned short raw_temp) {
    return TEMP_MIN + (TEMP_MAX - TEMP_MIN) * (raw_temp / 65535.0);
}

// Converts raw humidity data to relative humidity percentage
float convert_humidity(unsigned short raw_hum) {
    return HUM_MIN + (HUM_MAX - HUM_MIN) * (raw_hum / 65535.0);
}

// Logs the temperature and humidity data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char sensor_data[6];
    unsigned short raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC for temperature data
            if (validate_crc(sensor_data, 3)) {
                raw_temperature = (sensor_data[0] << 8) | sensor_data[1];
                temperature = convert_temperature(raw_temperature);

                // Validate CRC for humidity data
                if (validate_crc(sensor_data + 3, 3)) {
                    raw_humidity = (sensor_data[3] << 8) | sensor_data[4];
                    humidity = convert_humidity(raw_humidity);

                    // Log the data
                    log_data(temperature, humidity);
                } else {
                    fprintf(stderr, "Humidity CRC validation failed\n");
                }
            } else {
                fprintf(stderr, "Temperature CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

