#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_value);
float convert_to_gauss(int raw_value);
float convert_to_celsius(int raw_value);
int log_data(float field_gauss, float temp_celsius);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float field_gauss;
    float temp_celsius;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }
    rewind(log_file);

    int raw_value;
    float field_gauss, temp_celsius;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_value) == 0) {
            // Convert raw value to Gauss and Celsius
            field_gauss = convert_to_gauss(raw_value);
            temp_celsius = convert_to_celsius(raw_value);

            // Log the data
            if (log_data(field_gauss, temp_celsius) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log NaN values if sensor read fails
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data from the Si7202
int read_sensor_data(int *raw_value) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return 1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw value to Gauss
float convert_to_gauss(int raw_value) {
    return raw_value * 0.1;
}

// Convert raw value to Celsius
float convert_to_celsius(int raw_value) {
    return raw_value * 0.01 - 25.0;
}

// Log data to file
int log_data(float field_gauss, float temp_celsius) {
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, field_gauss, temp_celsius);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

