#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RESOLUTION 0.0078125
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int tmp117_address;
    char *log_file_name;
} config_t;

config_t config = {I2C_BUS, TMP117_ADDR, "temperature_log.txt"};

int main() {
    float temperature;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
        if (i2c_handle >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C open failed (attempt %d): %d\n", attempts + 1, i2c_handle);
            attempts++;
            gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Wait 0.1 seconds before retrying
        }
    }
    return -1; // Failure after multiple attempts
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int16_t raw_temp;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * TEMP_RESOLUTION;

    return 0;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s, Temperature: %.4f C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

