    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
        if (i2c_handle >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C open failed (attempt %d): %d\n", attempts + 1, i2c_handle);
            attempts++;
            gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Wait 0.1 seconds before retrying
        }
    }
    return -1; // Failure after multiple attempts
