#include <string.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100ms timeout
#define SAMPLE_INTERVAL_S 2

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
} DHT11Data;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
int read_dht11(DHT11Data *data);
int validate_checksum(const DHT11Data *data);
void log_data(const DHT11Data *data);
void log_error(const char *message, int status_code);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to get ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read DHT11 data
int read_dht11(DHT11Data *data) {
    int i, j;
    int data_bits[40];
    unsigned int start_time, end_time, pulse_length;

    // 1. Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20us

    // 2. Switch to input mode and wait for response
    gpioSetMode(DHT11_GPIO, PI_INPUT);
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP);

    // Wait for the initial low pulse (response signal)
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("DHT11 timeout waiting for initial low pulse", 101);
            return -1;
        }
    }

    // Wait for the initial high pulse
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("DHT11 timeout waiting for initial high pulse", 102);
            return -1;
        }
    }

    // 3. Read 40 data bits
    for (i = 0; i < 40; i++) {
        // Wait for the low pulse of the data bit
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("DHT11 timeout waiting for data bit low pulse", 103);
                return -1;
            }
        }

        // Measure the high pulse duration
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("DHT11 timeout waiting for data bit high pulse", 104);
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_length = end_time - start_time;

        // Determine the bit value based on pulse length
        data_bits[i] = (pulse_length > 40) ? 1 : 0; // Adjust threshold as needed
    }

    // 4. Convert data bits to bytes
    data->humidity = 0;
    data->temperature = 0;
    data->checksum = 0;

    for (i = 0; i < 8; i++) {
        data->humidity = (data->humidity << 1) | data_bits[i];
    }

    for (i = 8; i < 16; i++) {
        data->temperature = (data->temperature << 1) | data_bits[i];
    }

    for (i = 16; i < 24; i++) {
        data->checksum = (data->checksum << 1) | data_bits[i];
    }

    for (i = 24; i < 32; i++) {
        // Ignore the last 8 bits
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const DHT11Data *data) {
    int sum = (data->humidity & 0xFF) + ((data->temperature >> 8) & 0xFF) + (data->temperature & 0xFF);
    return (sum == data->checksum);
}

// Function to log data to file
void log_data(const DHT11Data *data) {
    char* timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s, Humidity: %d, Temperature: %d, Checksum: %d\n",
            timestamp, data->humidity, data->temperature, data->checksum);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Function to log errors to file
void log_error(const char *message, int status_code) {
    char* timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s, ERROR: %s, Status Code: %d\n", timestamp, message, status_code);
    fflush(log_file);
    free(timestamp);
}

int main() {
    DHT11Data dht11_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_dht11(&dht11_data);
        if (result == 0) {
            if (validate_checksum(&dht11_data)) {
                log_data(&dht11_data);
            } else {
                log_error("Checksum validation failed", 200);
            }
        } else {
            // Log error already done in read_dht11
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sleep for 2 seconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

