#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Define register addresses
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68

// Define expected device ID
#define EXPECTED_DEVICE_ID 0x2A

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "cct_log.csv"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
double calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
double average_cct(double cct1, double cct2);
int log_cct(double average_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    int device_id;

    // Read device ID
    device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    // Verify device ID
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[6];
    int result;

    // Read red, green, and blue data
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Convert little-endian to big-endian
    *red = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    *green = (uint16_t)buffer[2] | ((uint16_t)buffer[3] << 8);
    *blue = (uint16_t)buffer[4] | ((uint16_t)buffer[5] << 8);

    return 0;
}

// Function to calculate CCT using McCamy's formula
double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double X, Y, Z, x, y, z, n, cct;

    // Normalize RGB values
    X = (double)red;
    Y = (double)green;
    Z = (double)blue;

    double sum = X + Y + Z;
    if (sum == 0) return 0; // Avoid division by zero

    x = X / sum;
    y = Y / sum;
    z = Z / sum;

    // Use McCamy's formula
    n = (x - 0.3320) / (0.1858 - y);
    cct = -449.0 * (x * x * x) + 3525.0 * (x * x) - 6823.3 * x + 5520.33;
    cct = cct / (100.0 * x * x * x) - 20.0 * x * x + 100.0 * x;
    cct = cct + 244.0;

    return cct;
}

// Function to calculate the average CCT
double average_cct(double cct1, double cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log the average CCT to a CSV file
int log_cct(double average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Write timestamp and average CCT to the log file
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    // Close the log file
    fclose(log_file);
    log_file = NULL; // Reset log_file pointer

    return 0;
}

int main() {
    uint16_t red1, green1, blue1, red2, green2, blue2;
    double cct1, cct2, avg_cct;
    int init_result1, init_result2, read_result1, read_result2, log_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    init_result1 = initialize_sensor(i2c_handle1);
    if (init_result1 != 0) {
        fprintf(stderr, "Sensor 1 initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    init_result2 = initialize_sensor(i2c_handle2);
    if (init_result2 != 0) {
        fprintf(stderr, "Sensor 2 initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        read_result1 = read_sensor_data(i2c_handle1, &red1, &green1, &blue1);
        if (read_result1 != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        }

        read_result2 = read_sensor_data(i2c_handle2, &red2, &green2, &blue2);
        if (read_result2 != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        }

        // Calculate CCT values
        cct1 = calculate_cct(red1, green1, blue1);
        cct2 = calculate_cct(red2, green2, blue2);

        // Calculate average CCT
        avg_cct = average_cct(cct1, cct2);

        // Log average CCT
        log_result = log_cct(avg_cct);
        if (log_result != 0) {
            fprintf(stderr, "Error logging average CCT\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    return 0;
}

