#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 800.0
#define OUTPUT_MIN 0.0
#define OUTPUT_MAX 32768.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize();
sensor_data_t read_sensor_data();
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int16_t raw_pressure, raw_temperature;
    int result;

    // Read raw pressure
    result = i2cReadWordData(i2c_handle, PRESSURE_REG);
    if (result < 0) {
        fprintf(log_file, "%s I2C read error (pressure): %d\n", __TIME__, result);
        fflush(log_file);
        data.pressure_kPa = -1.0; // Indicate error
    } else {
        raw_pressure = (int16_t)result;
        data.pressure_kPa = convert_pressure(raw_pressure);
    }

    // Read raw temperature
    result = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (result < 0) {
        fprintf(log_file, "%s I2C read error (temperature): %d\n", __TIME__, result);
        fflush(log_file);
        data.temperature_C = -100.0; // Indicate error
    } else {
        raw_temperature = (int16_t)result;
        data.temperature_C = convert_temperature(raw_temperature);
    }

    return data;
}

// Function to convert raw pressure to kPa
float convert_pressure(int16_t raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return raw_temperature * 0.01 - 40.0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (data.pressure_kPa >= 0 && data.temperature_C > -99.0) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_kPa, data.temperature_C);
        fflush(log_file);
    } else {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
        fflush(log_file);
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(2000); // 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

