#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define MAX_I2C_RETRIES 3

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_celsius(int16_t raw_temp);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read function with retry mechanism
int i2c_read_word(int fd, uint8_t reg) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_I2C_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register address) failed");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        uint8_t buffer[2];
        if (read(fd, buffer, 2) != 2) {
            perror("I2C read failed");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = (buffer[0] << 8) | buffer[1];
        return result;
    }

    fprintf(stderr, "I2C read failed after %d retries. errno: %d\n", MAX_I2C_RETRIES, errno);
    return -1; // Indicate failure
}

// Temperature conversion function
float convert_to_celsius(int16_t raw_temp) {
    return (float)(raw_temp >> 4) * 0.0625;
}

// GPIO control function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "GPIO set_value failed: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "temperature_monitor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    int led_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        // Read temperature
        int16_t raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature, exiting...\n");
            break;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(raw_temp);

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Control LED with hysteresis
        if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
            if (gpio_set_value(gpio_line, 1) == 0) {
                led_state = 1;
            }
        } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
            if (gpio_set_value(gpio_line, 0) == 0) {
                led_state = 0;
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

