#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define MEASUREMENT_REG 0x00
#define TEMP_RESOLUTION 14
#define HUMIDITY_RESOLUTION 14
#define CONVERSION_FACTOR 65536.0
#define TEMP_OFFSET -40.0
#define HUMIDITY_SCALE 100.0
#define LOG_FILE "enviro_log.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int configure_hdc1080();
int read_hdc1080(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure HDC1080
    if (configure_hdc1080() != 0) {
        fprintf(stderr, "Failed to configure HDC1080. Exiting.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1080(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log the data
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure HDC1080
int configure_hdc1080() {
    // Set temperature and humidity resolution to 14 bits
    uint16_t config_value = (TEMP_RESOLUTION << 8) | HUMIDITY_RESOLUTION;
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(float *temperature, float *humidity) {
    char buf[1];
    char read_buf[4];
    uint16_t raw_temp, raw_humidity;

    // Trigger measurement
    buf[0] = MEASUREMENT_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return 1;
    }

    // Wait for conversion (at least 20ms)
    gpioSleep(PI_TIME_RELATIVE, 0, 20000);

    // Read 4 bytes of data
    if (i2cReadDevice(i2c_handle, read_buf, 4) != 4) {
        fprintf(stderr, "Failed to read data\n");
        return 1;
    }

    // Extract raw temperature and humidity values
    raw_temp = (read_buf[0] << 8) | read_buf[1];
    raw_humidity = (read_buf[2] << 8) | read_buf[3];

    // Convert raw values to temperature and humidity
    *temperature = ((float)raw_temp / CONVERSION_FACTOR) * 165.0 + TEMP_OFFSET;
    *humidity = ((float)raw_humidity / CONVERSION_FACTOR) * HUMIDITY_SCALE;

    return 0;
}

// Log data to file
void log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

