#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_1 0x2C
#define MEASURE_CMD_2 0xE0
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
float read_sts40_temperature() {
    unsigned char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    unsigned char data[3];
    int ret;

    // Send measurement command
    ret = write(i2c_fd, cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Wait for conversion (at least 10 ms)
    usleep(10000);

    // Read 3 bytes of data
    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // CRC validation
    unsigned char crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC mismatch! Calculated: 0x%02X, Received: 0x%02X\n", crc, data[2]);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_ticks = (data[0] << 8) | data[1];
    float temperature = -45.0 + 175.0 * (float)raw_ticks / 65535.0;

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_sts40_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }
        sleep(5);
    }

    return 0;
}

