} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measure_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    uint8_t crc_received = data[len - 1];
    return (crc_calculated == crc_received);
}

// Function to send the measurement command
int send_measure_command() {
    char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    sensor_data.pressure_Pa = (float)raw_pressure * (float)scale_factor / 1000.0;
    sensor_data.temperature_C = -45.0 + 175.0 * (float)raw_temperature / 65535.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, data.pressure_Pa, data.temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Main function
int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint8_t data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measure_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for 45 ms
        gpioDelay(45);

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 2)) {
            fprintf(stderr, "CRC validation failed for pressure\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 2)) {
            fprintf(stderr, "CRC validation failed for temperature\n");
            continue;
        }

        // Validate CRC for scale factor
        if (!validate_crc(data + 6, 2)) {
            fprintf(stderr, "CRC validation failed for scale factor\n");
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

