#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define ICP_10125_ADDR 0x63
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define HIGH_ACCURACY_CMD 0x4011
#define MEASUREMENT_DELAY_MS 20
#define PRESSURE_THRESHOLD 95000.0

// Calibration data structure
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
} calibration_data_t;

// Global variables
int i2c_fd = -1;
struct gpiod_line *led_line = NULL;
struct gpiod_chip *gpio_chip = NULL;
calibration_data_t calibration;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int read_calibration_data(int fd, calibration_data_t *cal);
int trigger_measurement(int fd);
int read_raw_data(int fd, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len, uint8_t crc);
double convert_pressure(uint8_t *data, calibration_data_t cal);
double convert_temperature(uint8_t *data, calibration_data_t cal);
int control_led(struct gpiod_line *line, int on);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Read calibration data from OTP memory
int read_calibration_data(int fd, calibration_data_t *cal) {
    uint8_t data[8];
    if (i2c_read_bytes(fd, 0x66, data, 8) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    cal->c0 = (data[0] << 8) | data[1];
    cal->c1 = (data[2] << 8) | data[3];
    cal->c00 = (data[4] << 8) | data[5];
    cal->c10 = (data[6] << 8) | data[7];

    return 0;
}

// Trigger measurement
int trigger_measurement(int fd) {
    uint8_t cmd[2];
    cmd[0] = (HIGH_ACCURACY_CMD >> 8) & 0xFF;
    cmd[1] = HIGH_ACCURACY_CMD & 0xFF;

    if (i2c_write_bytes(fd, 0x00, cmd, 2) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    return 0;
}

// Read raw data
int read_raw_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial: x^8 + x^5 + x^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC
int verify_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Convert pressure
double convert_pressure(uint8_t *data, calibration_data_t cal) {
    int32_t raw_pressure = (data[0] << 8) | data[1];
    double p = cal.c00 + raw_pressure * cal.c10;
    return p;
}

// Convert temperature
double convert_temperature(uint8_t *data, calibration_data_t cal) {
    int32_t raw_temperature = (data[2] << 8) | data[3];
    double t = cal.c0 + raw_temperature * cal.c1;
    return t;
}

// Control LED
int control_led(struct gpiod_line *line, int on) {
    int ret = gpiod_line_set_value(line, on);
    if (ret < 0) {
        perror("Failed to set LED value");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calibration) != 0) {
        close(i2c_fd);
        return 1;
