#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(int reg, float *temperature);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &sensor_data.ambient_temp) != 0) {
            fprintf(stderr, "Failed to read ambient temperature.\n");
        }
        if (read_temperature(OBJECT_TEMP_REG, &sensor_data.object_temp) != 0) {
            fprintf(stderr, "Failed to read object temperature.\n");
        }

        // Log temperatures
        log_temperature(sensor_data.ambient_temp, sensor_data.object_temp);

        // Control fan
        control_fan(sensor_data.object_temp);

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from MLX90614
int read_temperature(int reg, float *temperature) {
    int raw_temp;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            // Success
            *temperature = (float)raw_temp * 0.02 - 273.15;
            return 0;
        } else {
            // Failure, retry
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying (%d/%d): %d\n", reg, retries + 1, RETRY_COUNT, raw_temp);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    // All retries failed
    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n", reg, RETRY_COUNT);
    return 1;
}

// Log temperature to file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check for invalid temperatures
    if (ambient_temp < -50.0 || ambient_temp > 150.0 || object_temp < -50.0 || object_temp > 150.0) {
        fprintf(stderr, "Invalid temperature reading: Ambient=%.2f, Object=%.2f. Skipping log entry.\n", ambient_temp, object_temp);
        return;
    }

    fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Control fan based on object temperature
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

