#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define TEMP_MSB_REG 0x00
#define TEMP_LSB_REG 0x01
#define HUMID_MSB_REG 0x02
#define HUMID_LSB_REG 0x03
#define MAX_RETRIES 3
#define TIMEOUT_US 500000 // 500ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_hdc2010();
int read_hdc2010(float *temperature, float *humidity);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize HDC2010 sensor
int init_hdc2010() {
    // Configure the HDC2010 for one-shot measurement, heater off, 14-bit resolution
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC2010
int read_hdc2010(float *temperature, float *humidity) {
    int retries = 0;
    int status;
    uint16_t raw_temperature, raw_humidity;

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", i2c_handle);
        return -1;
    }

    // Wait for measurement to complete (poll MEASUREMENT_CONFIG bit 0)
    while (1) {
        status = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG);
        if (status < 0) {
            fprintf(stderr, "Error reading measurement config: %d\n", i2c_handle);
            return -1;
        }
        if (!(status & 0x01)) {
            break; // Measurement complete
        }
        gpioDelay(1000); // Wait 1ms
    }

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMP_MSB_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", i2c_handle);
        return -1;
    }

    // Read humidity data
    raw_humidity = i2cReadWordData(i2c_handle, HUMID_MSB_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", i2c_handle);
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HDC2010 sensor
    if (init_hdc2010() < 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_hdc2010(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

