#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define MEASUREMENT_DELAY_US 45000 // 45 ms
#define DATA_LENGTH 6

// Global variables for signal handling
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    uint8_t command[2] = {(CONTINUOUS_MEASUREMENT_COMMAND >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_COMMAND & 0xFF};
    int write_result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (write_result != 2) {
        fprintf(stderr, "Failed to write command to I2C: %d\n", write_result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from sensor
        char buffer[DATA_LENGTH];
        int read_result = i2cReadDevice(i2c_handle, buffer, DATA_LENGTH);
        if (read_result != DATA_LENGTH) {
            fprintf(stderr, "Failed to read data from I2C: %d\n", read_result);
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip to next iteration
            }
            gpioDelay(100000); // Wait 100ms before retrying
            continue;           // Retry reading
        }

        // Extract raw pressure and temperature values
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        // CRC check for pressure
        uint8_t pressure_data[2] = {buffer[0], buffer[1]};
        uint8_t pressure_crc = buffer[2];
        uint8_t calculated_pressure_crc = crc8(pressure_data, 2);
        if (pressure_crc != calculated_pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed! Expected 0x%02X, got 0x%02X\n", pressure_crc, calculated_pressure_crc);
        }

        // CRC check for temperature
        uint8_t temperature_data[2] = {buffer[3], buffer[4]};
        uint8_t temperature_crc = buffer[5];
        uint8_t calculated_temperature_crc = crc8(temperature_data, 2);
        if (temperature_crc != calculated_temperature_crc) {
            fprintf(stderr, "Temperature CRC check failed! Expected 0x%02X, got 0x%02X\n", temperature_crc, calculated_temperature_crc);
        }

        // Log raw values to console
        printf("Raw Pressure: 0x%04X, Raw Temperature: 0x%04X\n", raw_pressure, raw_temperature);

        // Wait 500ms
        gpioDelay(500000);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

