#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000000  // 1 MHz / 1 kHz = 1000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_SIZE 100

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
double target_profile[MAX_PROFILE_SIZE][2]; // [time, temperature]
int profile_size = 0;
int current_profile_index = 0;
double integral = 0.0;
double previous_error = 0.0;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_thermocouple();
double calculate_pid(double setpoint, double actual_temperature);
void set_relay_duty_cycle(double duty_cycle);
int load_profile(const char *filename);
double get_target_temperature(double current_time);
void log_data(double current_time, double actual_temperature, double target_temperature, double pid_output);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_thermocouple() {
    char buffer[2];
    int count;

    count = spiRead(spi_handle, buffer, 2);
    if (count != 2) {
        fprintf(stderr, "Error reading SPI data: %d\n", count);
        return -1; // Indicate error
    }

    int raw = (buffer[0] << 8) | buffer[1];

    // Check for fault bit (bit 2)
    if (raw & 0x0004) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -2; // Indicate fault
    }

    // Extract temperature (bits 3-14)
    int temp_raw = (raw >> 3) & 0x07FF;
    double temperature = temp_raw * 0.25;

    return (int)temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;

    // Clamp output to 0.0 - 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set relay duty cycle using PWM
void set_relay_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(RELAY_GPIO, pwm_value);
}

// Function to load target temperature profile from file
int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL && profile_size < MAX_PROFILE_SIZE) {
        double time, temperature;
        if (sscanf(line, "%lf,%lf", &time, &temperature) == 2) {
            target_profile[profile_size][0] = time;
            target_profile[profile_size][1] = temperature;
            profile_size++;
        } else {
            fprintf(stderr, "Error parsing line in profile file: %s", line);
        }
    }

    fclose(fp);
    if (profile_size == 0) {
        fprintf(stderr, "No profiles found in %s\n", filename);
        return -1;
    }

    return 0;
}

// Function to get target temperature based on current time
double get_target_temperature(double current_time) {
    if (current_profile_index >= profile_size) {
        return target_profile[profile_size - 1][1]; // Return last temperature if profile is complete
    }

    if (current_time >= target_profile[current_profile_index][0]) {
        current_profile_index++;
        if (current_profile_index < profile_size) {
            return target_profile[current_profile_index][1];
        } else {
            return target_profile[profile_size - 1][1]; // Return last temperature if profile is complete
        }
    } else {
        return target_profile[current_profile_index][1];
    }
}

// Function to log data to CSV file
void log_data(double current_time, double actual_temperature, double target_temperature, double pid_output) {
    fprintf(log_file, "%.2f,%.2f,%.2f,%.4f\n", current_time, actual_temperature, target_temperature, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RELAY_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY_GPIO, PWM_RANGE);

    // Load target temperature profile
    if (load_profile(PROFILE_FILE) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Time,Actual Temperature,Target Temperature,PID Output\n");

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    time_t start_time = time(NULL);
    while (!terminate) {
        // Read temperature
        int temperature = read_thermocouple();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting\n");
            // Handle error appropriately (e.g., use a default value or exit)
            // For now, just continue to the next iteration
            time_sleep(1.0);
            continue;
        }

        // Get current time
        time_t current_time = time(NULL) - start_time;

        // Get target temperature
        double target_temperature = get_target_temperature((double)current_time);

        // Calculate PID output
        double pid_output = calculate_pid(target_temperature, (double)temperature);

        // Set relay duty cycle
        set_relay_duty_cycle(pid_output);

        // Log data
        log_data((double)current_time, (double)temperature, target_temperature, pid_output);

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioPWM(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
    fclose(log_file);

    return 0;
}

