static float Ki = 0.0;
static float Kd = 0.0;
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
float read_temperature();
float calculate_pid(float current_temperature);
void set_heater_output(float pid_output);
void log_data(float average_temperature, float pid_output, float duty_cycle);
void signal_handler(int sig);
unsigned char crc8(const unsigned char *data, int len);

// CRC-8 calculation (DS18B20)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
            unsigned char mix = (crc ^ byte) & 0x01;
            crc >>= 1;
            if (mix)
                crc ^= 0x8C;
            byte >>= 1;
        }
    }
    return crc;
}

// Read temperature from DS18B20 sensor
float read_temperature() {
    DIR *d;
    struct dirent *dir;
    char sensor_path[256];
    char w1_slave_path[256];
    float temperature = -1000.0; // Initialize to an invalid value
    int sensor_count = 0;

    d = opendir("/sys/bus/w1/devices/");
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strncmp(dir->d_name, "28-", 3) == 0) {
                sensor_count++;
                snprintf(sensor_path, sizeof(sensor_path), "/sys/bus/w1/devices/%s", dir->d_name);
                snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/w1_slave", sensor_path);

                FILE *fp = fopen(w1_slave_path, "r");
                if (fp) {
                    char line1[256], line2[256];
                    if (fgets(line1, sizeof(line1), fp) != NULL && fgets(line2, sizeof(line2), fp) != NULL) {
                        if (strstr(line1, "YES") != NULL) {
                            char *temp_str = strstr(line2, "t=");
                            if (temp_str) {
                                long temp_raw = strtol(temp_str + 2, NULL, 10);
                                temperature += (float)temp_raw / 1000.0;
                            }
                        }
                    }
                    fclose(fp);
                } else {
                    fprintf(stderr, "Error opening %s: %s\n", w1_slave_path, strerror(errno));
                }
            }
        }
        closedir(d);

        if (sensor_count > 0) {
            temperature /= sensor_count; // Calculate average temperature
        } else {
            fprintf(stderr, "No DS18B20 sensors found.\n");
        }
    } else {
        fprintf(stderr, "Error opening /sys/bus/w1/devices/: %s\n", strerror(errno));
    }

    return temperature;
}

// Calculate PID output
float calculate_pid(float current_temperature) {
    float error = setpoint - current_temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Set heater output (relay and PWM)
void set_heater_output(float pid_output) {
    // Relay control
    if (pid_output > 0.0) {
        if (gpiod_line_set_value(heater_relay_line, 1) < 0) {
            fprintf(stderr, "Error setting heater relay high: %s\n", strerror(errno));
        }
    } else {
        if (gpiod_line_set_value(heater_relay_line, 0) < 0) {
            fprintf(stderr, "Error setting heater relay low: %s\n", strerror(errno));
        }
    }

    // PWM control
    if (pid_output > 100.0) pid_output = 100.0;
    if (pid_output < 0.0) pid_output = 0.0;

    int duty_cycle_ns = (int)((pid_output / 100.0) * PWM_PERIOD_NS);
