    nanosleep(&on_time, NULL);

    if (gpiod_line_set_value(heater_pwm_line, 0) < 0) {
        fprintf(stderr, "Error setting PWM low: %s\n", strerror(errno));
    }
    nanosleep(&off_time, NULL);

    gpiod_line_release(heater_pwm_line);
}

// Log data to file
void log_data(float average_temperature, float pid_output, float duty_cycle) {
    time_t now = time(NULL);
