    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);

    // Turn off heater relay
    if (heater_relay_line) {
        gpiod_line_set_value(heater_relay_line, 0);
    }

    // Set PWM duty cycle to 0
    if (heater_pwm_line) {
        gpiod_line_set_value(heater_pwm_line, 0);
    }

    // Close GPIO lines
    if (heater_relay_line) {
        gpiod_line_release(heater_relay_line);
    }
    if (heater_pwm_line) {
        gpiod_line_release(heater_pwm_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main(int argc, char *argv[]) {
