        gpiod_chip_close(chip);
        gpiod_line_release(heater_relay_line);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "greenhouse";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(heater_relay_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting heater relay line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(heater_relay_line);
        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(heater_pwm_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting heater PWM line: %s\n", strerror(errno));
        gpiod_line_release(heater_relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
