#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_HIGH_THRESHOLD 60.0
#define HUMIDITY_LOW_THRESHOLD 55.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_trigger_measurement(int i2c_handle);
int aht20_read_data(int i2c_handle, uint8_t *data);
float aht20_convert_humidity(uint32_t raw_humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// AHT20 Initialization
int aht20_init(int i2c_handle) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed (error code %d)\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for initialization to complete
    return 0;
}

// AHT20 Trigger Measurement
int aht20_trigger_measurement(int i2c_handle) {
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)measure_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 measurement trigger failed (error code %d)\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);
    return 0;
}

// AHT20 Read Data
int aht20_read_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error: AHT20 data read failed (error code %d)\n", result);
        return -1;
    }
    return 0;
}

// AHT20 Convert Humidity
float aht20_convert_humidity(uint32_t raw_humidity) {
    return ((float)raw_humidity / 0x100000) * 100;
}

// Control Dehumidifier
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH_THRESHOLD) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_LOW_THRESHOLD) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF\n");
    }
}

// Log Data
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for dehumidifier control
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        uint8_t data[6];
        int retry = 0;
        int result;

        // Trigger measurement with retries
        while (retry < RETRY_COUNT) {
            result = aht20_trigger_measurement(i2c_handle);
            if (result == 0) break;
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }
        if (result != 0) {
            fprintf(stderr, "Error: AHT20 measurement trigger failed after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Read data with retries
        retry = 0;
        while (retry < RETRY_COUNT) {
            result = aht20_read_data(i2c_handle, data);
            if (result == 0) break;
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }
        if (result != 0) {
            fprintf(stderr, "Error: AHT20 data read failed after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Check status byte
        if ((data[0] & 0x80) != 0) {
            fprintf(stderr, "Error: AHT20 not calibrated or busy\n");
            continue; // Skip to the next iteration
        }

