#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "api.example.com"
#define API_PORT 80
#define RETRY_COUNT 3
#define RETRY_DELAY 5 // seconds

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, exiting...");
}

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read humidity from HTU21D sensor
float read_humidity() {
    unsigned char buf[3];
    int ret;

    // Trigger humidity measurement
    buf[0] = TRIGGER_HUMID_MEASURE;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %s", strerror(errno));
        return -1.0;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    // Read 3 bytes of humidity data
    ret = read(i2c_fd, buf, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %s", strerror(errno));
        return -1.0;
    }

    // CRC check
    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC check failed for humidity data");
        return -1.0;
    }

    // Convert to relative humidity
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC; // Clear status bits
    float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    return humidity;
}

// Function to create HTTP POST request
char *create_http_request(float humidity) {
    char *request = malloc(256);
    if (request == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for HTTP request");
        return NULL;
    }

    snprintf(request, 256, 
             "POST /humidity HTTP/1.1\r\n" \
             "Host: %s\r\n" \
             "Content-Type: application/json\r\n" \
             "Content-Length: %zu\r\n" \
             "Connection: close\r\n" \
             "\r\n" \
             "{\"humidity\": %.2f}", API_ENDPOINT, strlen("{\"humidity\": ")+snprintf(NULL, 0, "%.2f", humidity)+1, humidity);

    return request;
}

// Function to send HTTP POST request
int send_http_request(const char *request) {
    int sockfd;
    struct sockaddr_in serv_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(API_PORT);

    if (inet_pton(AF_INET, API_ENDPOINT, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", API_ENDPOINT);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char buffer[1024] = {0};
    ssize_t bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    buffer[bytes_received] = '\0';
    syslog(LOG_INFO, "Received response: %s", buffer);

    close(sockfd);
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    while (program_running) {
        float humidity = -1.0;
        int retry = 0;

        while (humidity < 0.0 && retry < RETRY_COUNT) {
            humidity = read_humidity();
            if (humidity < 0.0) {
                syslog(LOG_WARNING, "Failed to read humidity, retrying (%d/%d)", retry + 1, RETRY_COUNT);
                retry++;
                sleep(RETRY_DELAY);
            }
        }

        if (humidity >= 0.0) {
            char *request = create_http_request(humidity);
            if (request != NULL) {
                if (send_http_request(request) != 0) {
                    syslog(LOG_ERR, "Failed to send HTTP request");
                }
                free(request);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after multiple retries");
        }

        sleep(60);
    }

    // Cleanup
    close(i2c_fd);
    closelog();

    return 0;
}

