#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bmp280();
int read_calibration_data(bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Open I2C bus
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            retries--;
            sleep(1);
            continue;
        }

        // Verify chip ID
        char chip_id;
        status = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading chip ID: %d\n", status);
            i2cClose(i2c_handle);
            retries--;
            sleep(1);
            continue;
        }

        if (chip_id != 0x58) {
            fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
            i2cClose(i2c_handle);
            retries--;
            sleep(1);
            continue;
        }

        // Read calibration data
        if (read_calibration_data(&calib) != 0) {
            fprintf(stderr, "Error reading calibration data\n");
            i2cClose(i2c_handle);
            retries--;
            sleep(1);
            continue;
        }

        // Configure sensor (forced mode, 1x oversampling)
        char config_data[2];
        config_data[0] = BMP280_REG_CTRL_MEAS;
        config_data[1] = 0x27; // Forced mode, 1x oversampling
        status = i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1);
        if (status < 0) {
            fprintf(stderr, "Error writing config data: %d\n", status);
            i2cClose(i2c_handle);
            retries--;
            sleep(1);
            continue;
        }

        printf("BMP280 initialized successfully\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize BMP280 after multiple retries\n");
    return -1; // Failure
}

// Read calibration data from BMP280
int read_calibration_data(bmp280_calib_data *calib) {
    char data[24];
    int status = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 24);
    if (status < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", status);
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
