#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO_CHIP "gpiochip4"
#define PIR_GPIO_LINE 17
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_chip *pir_chip = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int init_gpio(const char *chip, int line);
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir(void);
void log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int sig);
void close_resources(void);
char* get_iso8601_timestamp(char* buf, size_t buf_size);

// Helper function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* buf, size_t buf_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return buf;
}

// I2C initialization function
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// GPIO initialization function
int init_gpio(const char *chip, int line) {
    pir_chip = gpiod_chip_open_by_name(chip);
    if (!pir_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(pir_chip, line);
    if (!pir_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(pir_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(pir_chip);
        return -1;
    }

    return 0;
}

// TMP117 reading function
int read_tmp117(float *temperature) {
    unsigned char buf[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading TMP117 data");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        int16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = raw_temp * 0.0078125;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// AHT20 reading function
int read_aht20(float *humidity) {
    unsigned char init_cmd[] = {0xBE, 0x08, 0x00};
    unsigned char measure_cmd[] = {0xAC, 0x33, 0x00};
    unsigned char data[7];
    int retries = 0;

    // Initialization
    while (retries < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (write(i2c_fd, init_cmd, sizeof(init_cmd)) != sizeof(init_cmd)) {
            perror("Error writing AHT20 init command");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(20000); // Wait for initialization
        break;
    }
    if (retries == I2C_RETRY_COUNT) {
        fprintf(stderr, "Failed to initialize AHT20 after %d retries\n", I2C_RETRY_COUNT);
        return -1;
    }

    // Measurement
    retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (write(i2c_fd, measure_cmd, sizeof(measure_cmd)) != sizeof(measure_cmd)) {
            perror("Error writing AHT20 measure command");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(80000); // Wait for measurement

        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Error reading AHT20 data");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }

        if (!(data[0] & 0x80)) {
            uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
            uint32_t temperature_raw = ((uint32_t)(data[3] & 0x0F) << 16) | ((uint32_t)data[4] << 8) | data[5];

            *humidity = ((float)humidity_raw / 0x100000) * 100;
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 busy\n");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// PIR sensor reading function
int read_pir(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        perror("Error reading PIR sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Data logging function
void log_data(float temperature, float humidity, int motion_detected) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Resource cleanup function
void close_resources(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (pir_chip) {
        gpiod_chip_close(pir_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

