        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active low, so 0 means rain
}

// Function to close the window
void close_window(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line) {
    log_event("Closing window...");

    // Set IN1 high, IN2 low to move forward
    if (gpiod_line_set_value(in1_line, 1) < 0) {
        fprintf(stderr, "Error setting IN1 high\n");
        return;
    }
    if (gpiod_line_set_value(in2_line, 0) < 0) {
        fprintf(stderr, "Error setting IN2 low\n");
        return;
    }

    // Enable the motor
    if (gpiod_line_set_value(enable_line, 1) < 0) {
