    if (!rain_sensor_line) {
        fprintf(stderr, "Error getting rain sensor line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    motor_enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    if (!motor_enable_line) {
        fprintf(stderr, "Error getting motor enable line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        return 1;
    }

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1_line) {
        fprintf(stderr, "Error getting motor IN1 line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        return 1;
    }

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2_line) {
        fprintf(stderr, "Error getting motor IN2 line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_in1_line);
        return 1;
    }

    // Request GPIO lines for input/output
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        fprintf(stderr, "Error requesting rain sensor line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_in2_line);
        return 1;
    }

    if (gpiod_line_request_output(motor_enable_line, "motor_enable", 0) < 0) {
        fprintf(stderr, "Error requesting motor enable line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_in2_line);
        return 1;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN1 line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_in2_line);
        return 1;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN2 line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_in2_line);
        return 1;
    }

    log_event("GPIO lines requested.");

    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor(rain_sensor_line);
        if (rain_detected == 1) {
            log_event("Rain detected!");
            close_window(motor_enable_line, motor_in1_line, motor_in2_line);
        } else if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor, exiting.\n");
            break;
        }
        sleep(2);
    }

    // Cleanup (in case the loop breaks)
    gpiod_line_release(rain_sensor_line);
    gpiod_line_release(motor_enable_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_in2_line);
    gpiod_chip_close(chip);

    return 0;
}

