#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Structure to hold CPU usage data
typedef struct {
    unsigned long long user;
    unsigned long long nice;
    unsigned long long system;
    unsigned long long idle;
    unsigned long long iowait;
    unsigned long long irq;
    unsigned long long softirq;
} cpu_stats_t;

// Global variables
static volatile int running = 1;
static cpu_stats_t prev_cpu_stats = {0};
static cpu_stats_t current_cpu_stats = {0};

// Function prototypes
int read_cpu_stats(cpu_stats_t *stats);
double calculate_cpu_load(cpu_stats_t prev, cpu_stats_t current);
void map_load_to_color(double load, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(cpu_stats_t *stats) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               &stats->user, &stats->nice, &stats->system, &stats->idle,
               &stats->iowait, &stats->irq, &stats->softirq) != 7) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
double calculate_cpu_load(cpu_stats_t prev, cpu_stats_t current) {
    unsigned long long prev_idle = prev.idle + prev.iowait;
    unsigned long long current_idle = current.idle + current.iowait;

    unsigned long long prev_non_idle = prev.user + prev.nice + prev.system + prev.irq + prev.softirq;
    unsigned long long current_non_idle = current.user + current.nice + current.system + current.irq + current.softirq;

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long current_total = current_idle + current_non_idle;

    unsigned long long totald = current_total - prev_total;
    unsigned long long idled = current_idle - prev_idle;

    double cpu_usage = (double)(totald - idled) / totald;
    return cpu_usage * 100.0;
}

// Function to map CPU load to RGB color values
void map_load_to_color(double load, int *red, int *green, int *blue) {
    if (load <= 50.0) {
        // Green to Yellow
        *red = 0;
        *green = (int)(255.0 * (load / 50.0));
        *blue = 0;
    } else {
        // Yellow to Red
        *red = (int)(255.0 * ((load - 50.0) / 50.0));
        *green = 255 - (int)(255.0 * ((load - 50.0) / 50.0));
        *blue = 0;
    }
}

// Function to set the RGB LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    // Clamp values to 0-255 range
    if (red < 0) red = 0;
    if (red > 255) red = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0) blue = 0;
    if (blue > 255) blue = 255;

    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU statistics
        if (read_cpu_stats(&current_cpu_stats) != 0) {
            fprintf(stderr, "Error reading CPU stats, exiting...\n");
            break;
        }

        // Calculate CPU load
        double cpu_load = calculate_cpu_load(prev_cpu_stats, current_cpu_stats);

        // Map CPU load to RGB color
        int red, green, blue;
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU stats
        prev_cpu_stats = current_cpu_stats;

        // Sleep for 500 milliseconds
        usleep(500000); // 500 ms = 500000 microseconds
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

