#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_START 0x88
#define BMP280_REG_CALIB_END 0xA1
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA_START 0xF7

// UDP server address and port
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000

// Global variables for I2C handle and UDP socket
int i2c_handle = -1;
int udp_socket = -1;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int send_udp_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data() {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_START, data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    // Set forced mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_DATA_START, data, 6) != 6) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)data[0]) << 12) | (((uint32_t)data[1]) << 4) | ((uint32_t)data[2] >> 4));
    *temperature = (int32_t)((((uint32_t)data[3]) << 12) | (((uint32_t)data[4]) << 4) | ((uint32_t)data[5] >> 4));

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Send temperature and pressure data over UDP
int send_udp_data(double temperature, double pressure) {
    char json_string[100];
    snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            double temperature = compensate_temperature(raw_temperature);
            double pressure = compensate_pressure(raw_pressure, temperature);

            if (send_udp_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to send UDP data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle);
    close(udp_socket);
    gpioTerminate();

    return 0;
}

