#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Data structure for temperature readings
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void add_reading(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char tx_buf[4] = {0}; // Transmit buffer (dummy data)
    char rx_buf[4];       // Receive buffer
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;
    *temperature = thermocouple_data * 0.25;

    // Extract fault bits (bits 15:13)
    int fault = (rx_buf[2] >> 1) & 0x7;

    if (fault != 0) {
        fprintf(stderr, "Error: MAX31855 fault detected (0x%X)\n", fault);
        if (fault & 0x1) fprintf(stderr, "  Open Circuit\n");
        if (fault & 0x2) fprintf(stderr, "  Short to GND\n");
        if (fault & 0x4) fprintf(stderr, "  Short to VCC\n");
        return -1;
    }

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
    } else if (temperature < 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) / (60.0 - 40.0) * 150.0);
        if (duty_cycle > 200) duty_cycle = 200;
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update fan speed using PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, int duty_cycle) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Reading Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[i].timestamp));
        printf("[%d] %s - Temperature: %.2f°C, Duty Cycle: %d\n", i, timestamp_str, buffer[i].temperature, buffer[i].duty_cycle);
    }
    printf("----------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan_speed(duty_cycle);

            // Add reading to buffer
            add_reading(temperature, duty_cycle);

            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep(1.0)
    }

    // Stop PWM
    update_fan_speed(0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print buffer contents
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

