#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile int logging_enabled = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_bmp180();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_data(double temperature, double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Initialize I2C
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP180
    if (init_bmp180() != 0) {
        fprintf(stderr, "BMP180 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;
            double temperature, pressure;

            if (read_raw_temperature(&raw_temperature) != 0) {
                fprintf(stderr, "Error reading raw temperature\n");
                continue;
            }

            if (read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw pressure\n");
                continue;
            }

            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, raw_temperature);

            log_data(temperature, pressure);
        }
        sleep(1);
    }

    return 0;
}

int init_bmp180()
{
    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return 1;
    }

    return 0;
}

int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_uint16(BMP180_REG_CAL_AC4);
    ac5 = read_uint16(BMP180_REG_CAL_AC5);
    ac6 = read_uint16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        return 1;
    }

    return 0;
}

int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return 1;
    }
    gpioDelay(5000); // Wait 4.5ms

    *raw_temperature = read_int16(BMP180_REG_MSB);
