#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// Fault Status Flags
#define FAULT_HIGH_THRESHOLD 0x01
#define FAULT_LOW_THRESHOLD 0x02
#define FAULT_REFIN_LOW 0x04
#define FAULT_REFIN_HIGH 0x08
#define FAULT_RTDIN_LOW 0x10
#define FAULT_RTDIN_HIGH 0x20
#define FAULT_OVERUNDER_VOLTAGE 0x40
#define FAULT_OPEN_CIRCUIT 0x80

// Global Variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int read_max31865(uint8_t reg, uint8_t *data, int len);
int write_max31865(uint8_t reg, uint8_t data);
int check_fault_status(uint8_t fault_status);
double calculate_temperature(uint16_t rtd_value);
int log_data(double temperature, const char *error_message);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_program", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read from MAX31865
int read_max31865(uint8_t reg, uint8_t *data, int len) {
    uint8_t tx_buf[len + 1];
    uint8_t rx_buf[len + 1];
    struct spi_ioc_transfer tr;

    tx_buf[0] = reg | 0x80; // Set MSB for read
    memset(tx_buf + 1, 0, len);
    memset(rx_buf, 0, len + 1);

    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = len + 1;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.cs_change = 0;

    gpiod_line_set_value(cs_line, 0); // Assert CS
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }
    gpiod_line_set_value(cs_line, 1); // Deassert CS

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Write to MAX31865
int write_max31865(uint8_t reg, uint8_t data) {
    uint8_t tx_buf[2];
    struct spi_ioc_transfer tr;

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = 0; // Dummy receive buffer
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.cs_change = 0;

    gpiod_line_set_value(cs_line, 0); // Assert CS
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }
    gpiod_line_set_value(cs_line, 1); // Deassert CS

    return 0;
}

// Check Fault Status
int check_fault_status(uint8_t fault_status) {
    if (fault_status & FAULT_HIGH_THRESHOLD) {
        fprintf(stderr, "Fault: RTD High Threshold\n");
        return -1;
    }
    if (fault_status & FAULT_LOW_THRESHOLD) {
        fprintf(stderr, "Fault: RTD Low Threshold\n");
        return -1;
    }
    if (fault_status & FAULT_REFIN_LOW) {
        fprintf(stderr, "Fault: Refin- Low\n");
        return -1;
    }
    if (fault_status & FAULT_REFIN_HIGH) {
        fprintf(stderr, "Fault: Refin- High\n");
        return -1;
    }
    if (fault_status & FAULT_RTDIN_LOW) {
        fprintf(stderr, "Fault: RTDIN- Low\n");
        return -1;
    }
    if (fault_status & FAULT_RTDIN_HIGH) {
        fprintf(stderr, "Fault: RTDIN- High\n");
        return -1;
    }
    if (fault_status & FAULT_OVERUNDER_VOLTAGE) {
        fprintf(stderr, "Fault: Over/Under Voltage\n");
        return -1;
    }
    if (fault_status & FAULT_OPEN_CIRCUIT) {
        fprintf(stderr, "Fault: Open Circuit\n");
        return -1;
    }
    return 0;
}

// Calculate Temperature (Callendar-Van Dusen)
double calculate_temperature(uint16_t rtd_value) {
    // These are example values.  Calibration is crucial.
    double A = 3.9083e-3;
    double B = -5.775e-7;
    double C = -4.183e-12;
    double R0 = 100.0; // Resistance at 0°C
    double Rt = (double)rtd_value;

    double rtd_resistance = Rt / 32768.0; // Assuming 16-bit ADC

    double temperature = -242.06 + 2.2228 * rtd_resistance;
    temperature += 2.5859e-2 * pow(rtd_resistance, 2.0);
    temperature -= 4.8260e-5 * pow(rtd_resistance, 3.0);
    temperature -= 2.8183e-7 * pow(rtd_resistance, 4.0);
    temperature -= 1.5443e-9 * pow(rtd_resistance, 5.0);

    return temperature;
}

// Log Data
int log_data(double temperature, const char *error_message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (error_message != NULL) {
        fprintf(log_file, "%s,ERROR,%s\n", timestamp, error_message);
        fprintf(stderr, "%s,ERROR,%s\n", timestamp, error_message);
    } else {
        fprintf(log_file, "%s,%.2f,\n", timestamp, temperature);
    }

    fflush(log_file);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Configure MAX31865 for 3-wire RTD mode with bias
    if (write_max31865(MAX31865_CONFIG_REG, 0xC2) != 0) {
        fprintf(stderr, "Failed to configure MAX31865. Exiting.\n");
        log_data(0.0, "Failed to configure MAX31865");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t rtd_msb, rtd_lsb, fault_status;
        uint16_t rtd_value;
        double temperature;

        // Read RTD value
        if (read_max31865(MAX31865_RTD_MSB_REG, &rtd_msb, 1) != 0) {
            log_data(0.0, "Failed to read RTD MSB");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        if (read_max31865(MAX31865_RTD_LSB_REG, &rtd_lsb, 1) != 0) {
            log_data(0.0, "Failed to read RTD LSB");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        rtd_value = ((uint16_t)rtd_msb << 8) | rtd_lsb;
        rtd_value &= 0x0FFF; // Clear fault bit

        // Read Fault Status
        if (read_max31865(MAX31865_FAULT_REG, &fault_status, 1) != 0) {
            log_data(0.0, "Failed to read Fault Status");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Check for faults
        if (check_fault_status(fault_status) != 0) {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "Fault detected: 0x%02X", fault_status);
            log_data(0.0, error_message);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Calculate temperature
        temperature = calculate_temperature(rtd_value);

        // Log data
        log_data(temperature, NULL);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

