// Function to initialize the BME280 sensor
int bme280_init() {
    uint8_t chip_id;

    // Read the chip ID
    if (i2c_smbus_read_byte_data(i2c_fd, BME280_REG_CHIPID) < 0) {
        perror("Error reading chip ID");
        return -1;
    }
    chip_id = i2c_smbus_read_byte_data(i2c_fd, BME280_REG_CHIPID);

    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Reset the sensor
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_RESET, 0xB6) < 0) {
        perror("Error resetting sensor");
        return -1;
    }
    usleep(10000); // Wait for the reset to complete

    // Set humidity oversampling to 1x
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        perror("Error setting humidity oversampling");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        perror("Error setting temperature and pressure oversampling");
        return -1;
    }

    // Set the standby time to 0.5ms
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CONFIG, 0x00) < 0) {
        perror("Error setting standby time");
        return -1;
    }

    return 0;
}

