    calib.dig_H6 = (int8_t)i2c_smbus_read_byte_data(i2c_fd, BME280_REG_CALIB_26 + 7);

    return 0;
}

// Function to read raw data from the sensor
int bme280_read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int32_t raw_pressure, raw_temperature, raw_humidity;

    raw_pressure = (i2c_smbus_read_byte_data(i2c_fd, BME280_REG_PRESS_MSB) << 12) | (i2c_smbus_read_byte_data(i2c_fd, BME280_REG_PRESS_LSB) << 4) | (i2c_smbus_read_byte_data(i2c_fd, BME280_REG_PRESS_XLSB) >> 4);
