    if (var_H < 0)
        var_H = 0;
    if (var_H > 100)
        var_H = 100;
    return (float)var_H;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log data to a CSV file
int log_data(float temperature, float humidity, float pressure) {
    char timestamp[20];
    get_timestamp(timestamp);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int32_t raw_temperature, raw_pressure, raw_humidity;
    float temperature, humidity, pressure;
    double t_fine;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BME280 sensor
    if (bme280_init() < 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bme280_read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    rewind(log_file);

    // Main loop
    while (!stop_flag) {
        // Read raw data
        if (bme280_read_raw_data(&raw_temperature, &raw_pressure, &raw_humidity) < 0) {
            fprintf(stderr, "Error reading raw data.\n");
            break;
        }

        // Compensate data
        temperature = bme280_compensate_temperature(raw_temperature);
        t_fine = temperature * 5120.0; // Store t_fine for pressure and humidity compensation
        pressure = bme280_compensate_pressure(raw_pressure, t_fine);
        humidity = bme280_compensate_humidity(raw_humidity, t_fine);

        // Log data
        if (log_data(temperature, humidity, pressure) < 0) {
            fprintf(stderr, "Error logging data.\n");
            break;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the log file and I2C bus
    fclose(log_file);
    close(i2c_fd);

    printf("Program finished.\n");
    return 0;
}

