#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS = 0)
#define BMP180_OSS 0

// Alert GPIO pin
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 samples/second)
#define BUFFER_SIZE 1200

// Alert threshold (hPa)
#define ALERT_THRESHOLD 5.0

// Global variables
int i2c_handle;
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;
double pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temperature, int raw_pressure);
double calculate_rolling_average();
void trigger_alert();
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C unsigned word from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }

    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);

    return 0;
}

// Function to calculate the pressure in hPa
double calculate_pressure(int raw_temperature, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = (ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return p / 100.0; // Return pressure in hPa
}

// Function to calculate the rolling average of the pressure readings
double calculate_rolling_average()
{
    if (buffer_count == 0) {
        return 0.0; // Avoid division by zero
    }

    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i];
    }
    return sum / buffer_count;
}

// Function to trigger an alert by setting GPIO24 HIGH for 1 second
void trigger_alert()
{
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000000);       // Wait for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

// Timer callback function
void timer_callback()
{
    int raw_temperature, raw_pressure;
    double pressure;

    if (read_raw_temperature(&raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature in timer callback\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure in timer callback\n");
        return;
    }

    pressure = calculate_pressure(raw_temperature, raw_pressure);

    // Add pressure reading to the circular buffer
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    // Calculate rolling average
    double rolling_average = calculate_rolling_average();

    // Check for alert condition
    if (fabs(pressure - rolling_average) > ALERT_THRESHOLD) {
        trigger_alert();
    }

    // Print pressure reading to stdout
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", timestamp, pressure, rolling_average);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback function (every 50ms)
    gpioSetTimerFuncEx(0, 50, timer_callback, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 50, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Reset GPIO
    gpioTerminate();

    return 0;
}

