    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    printf("BMP180 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("BMP180 data logging stopped.\n");

    return 0;
}

