    }

    X1 = (pressure >> 8) * (pressure >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * pressure) >> 16;
    float calculated_pressure = pressure + ((X1 + X2 + 3791) >> 4);

    return calculated_pressure;
}

