#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000 // 25 kHz

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate fan duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 255.0);
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting or using a default temperature here
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Stopping fan and cleaning up...\n");
    set_fan_speed(0); // Stop the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

