#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_REG_CHIPID  0xD0
#define BMP280_REG_RESET   0xE0
#define BMP280_REG_STATUS  0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
};

// Global variables
static int i2c_fd = -1;
static int bmp280_address = 0x76;
static volatile sig_atomic_t terminate = 0;
static struct bmp280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int bmp280_init(int fd, int address);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib);
double bmp280_compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib);
int log_data(double temperature, double pressure);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd, int address) {
    uint8_t chip_id;

    // Check chip ID
    if (i2c_read_bytes(fd, BMP280_REG_CHIPID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_bytes(fd, BMP280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (calib_data[1] << 8) | calib_data[0];
    calib.dig_T2 = (calib_data[3] << 8) | (int8_t)calib_data[2];
    calib.dig_T3 = (calib_data[5] << 8) | (int8_t)calib_data[4];
    calib.dig_P1 = (calib_data[7] << 8) | calib_data[6];
    calib.dig_P2 = (calib_data[9] << 8) | (int8_t)calib_data[8];
    calib.dig_P3 = (calib_data[11] << 8) | (int8_t)calib_data[10];
    calib.dig_P4 = (calib_data[13] << 8) | (int8_t)calib_data[12];
    calib.dig_P5 = (calib_data[15] << 8) | (int8_t)calib_data[14];
    calib.dig_P6 = (calib_data[17] << 8) | (int8_t)calib_data[16];
    calib.dig_P7 = (calib_data[19] << 8) | (int8_t)calib_data[18];
    calib.dig_P8 = (calib_data[21] << 8) | (int8_t)calib_data[20];
    calib.dig_P9 = (calib_data[23] << 8) | (int8_t)calib_data[22];

    // Set oversampling and mode
    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Forced mode
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    // Read pressure and temperature data
    if (i2c_read_bytes(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    int32_t t_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (int32_t)(var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Log data to file function
int log_data(double temperature, double pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("weather_data.txt", "a");
    if (fp == NULL) {
        perror("Failed to open weather_data.txt");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, exiting gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int address = 0x76;
    int i2c_bus = 1;
    char i2c_device[20];

    // Parse command-line arguments
    if (argc > 1) {
        address = strtol(argv[1], NULL, 0);
    }

    // Open I2C device
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", i2c_bus);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd, address) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature, calib);
            pressure = bmp280_compensate_pressure(raw_pressure, 0, calib); // t_fine is not used in the current implementation

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            if (bmp280_init(i2c_fd, address) != 0) {
                fprintf(stderr, "BMP280 re-initialization failed\n");
            }
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

