        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Log data to file function
int log_data(double temperature, double pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("weather_data.txt", "a");
    if (fp == NULL) {
        perror("Failed to open weather_data.txt");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, exiting gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int address = 0x76;
    int i2c_bus = 1;
    char i2c_device[20];

    // Parse command-line arguments
    if (argc > 1) {
        address = strtol(argv[1], NULL, 0);
    }

    // Open I2C device
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", i2c_bus);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd, address) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature, calib);
            pressure = bmp280_compensate_pressure(raw_pressure, 0, calib); // t_fine is not used in the current implementation

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            if (bmp280_init(i2c_fd, address) != 0) {
                fprintf(stderr, "BMP280 re-initialization failed\n");
            }
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

