#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_MS 1000000 // 1 second in microseconds

// Global variables
static volatile int running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
void cleanup_gpio(void);
int init_i2c(void);
void cleanup_i2c(void);
int read_temperature(float *temperature);
void update_buffer(float temperature);
float calculate_average(void);
void control_led(float average_temperature);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Initialize GPIO
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Initialize I2C
int init_i2c(void) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Cleanup I2C
void cleanup_i2c(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Read temperature from LM75
int read_temperature(float *temperature) {
    uint8_t buffer[2];
    int16_t raw_temp;

    // Write the temperature register address
    if (write(i2c_fd, &TEMP_REG, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read two bytes from the temperature register
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    raw_temp = (buffer[0] << 8) | buffer[1];

    // Convert to signed 16-bit integer
    if (raw_temp & 0x8000) {
        raw_temp = -((~raw_temp & 0xFFFF) + 1);
    }

    // Extract the temperature value (11 bits) and shift left by 5 bits
    raw_temp = (raw_temp >> 5) & 0x7FF; // Mask out the status bits

    // Convert to Celsius
    *temperature = (float)raw_temp / 256.0;

    return 0;
}

// Update circular buffer
void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Calculate running average
float calculate_average(void) {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / buffer_count;
}

// Control LED based on temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpiod_line_set_value(gpio_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(gpio_line, 0); // Turn LED off
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        cleanup_gpio();
        return 1;
    }

    float temperature;
    float average_temperature;

    // Main loop
    while (running) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            // Update buffer
            update_buffer(temperature);

            // Calculate average
            average_temperature = calculate_average();
            printf("Average Temperature: %.2f °C\n", average_temperature);

            // Control LED
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, attempting re-initialization.\n");
            cleanup_i2c();
            if (init_i2c() < 0) {
                fprintf(stderr, "I2C re-initialization failed, exiting.\n");
                running = 0; // Exit loop if re-initialization fails
            }
        }

        // Sleep for 1 second
        usleep(SLEEP_MS);
    }

    // Cleanup
    cleanup_i2c();
    cleanup_gpio();
    pthread_mutex_destroy(&buffer_mutex);

    return 0;
}

