        log_error("pigpio initialisation failed");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        log_error("SPI initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for PWM
