#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <stdbool.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd);
int bmp180_read_raw_pressure(int fd, uint8_t oss);
float bmp180_calculate_temperature(int raw_temp);
float bmp180_calculate_pressure(int raw_pressure, int raw_temp, uint8_t oss);
void log_breach(float temperature, float pressure);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, &reg, 1);
        if (result != 1) {
            perror("I2C write (register address) failed");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 3;
    uint8_t buf[2];
    int result;

    buf[0] = reg;
    buf[1] = data;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries\n");
    return -1; // Failure
}

// Function to read calibration data from BMP180
int bmp180_read_calibration_data(int fd) {
    uint8_t data[22];

    if (i2c_read_reg(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature value from BMP180
int bmp180_read_raw_temperature(int fd) {
    uint8_t data[2];

    if (i2c_write_reg(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms

    if (i2c_read_reg(fd, BMP180_REG_MSB, data, 2) != 0) {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to read raw pressure value from BMP180
int bmp180_read_raw_pressure(int fd, uint8_t oss) {
    uint8_t data[3];
    uint8_t cmd;

    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE0; break;
        case 1: cmd = BMP180_CMD_PRESSURE1; break;
        case 2: cmd = BMP180_CMD_PRESSURE2; break;
        case 3: cmd = BMP180_CMD_PRESSURE3; break;
        default: cmd = BMP180_CMD_PRESSURE0; break; // Default to oss=0
    }

    if (i2c_write_reg(fd, BMP180_REG_CONTROL, cmd) != 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return -1;
    }

    usleep((2 + (3 << oss)) * 1000); // Wait for conversion

    if (i2c_read_reg(fd, BMP180_REG_MSB, data, 3) != 0) {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
}

// Function to calculate temperature in degrees Celsius
float bmp180_calculate_temperature(int raw_temp) {
    long x1, x2;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in hPa
float bmp180_calculate_pressure(int raw_pressure, int raw_temp, uint8_t oss) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Reuse calculations from temperature
    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p / 100.0f; // Return pressure in hPa
}

// Function to log temperature and pressure breaches
void log_breach(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bmp180_read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor...\n");

    while (running) {
        // Read raw temperature and pressure
        int raw_temp = bmp180_read_raw_temperature(i2c_fd);
        int raw_pressure = bmp180_read_raw_pressure(i2c_fd, 3); // Use oss=3 for highest accuracy

        if (raw_temp != -1 && raw_pressure != -1) {
            // Calculate temperature and pressure
            float temperature = bmp180_calculate_temperature(raw_temp);
            float pressure = bmp180_calculate_pressure(raw_pressure, raw_temp, 3);

            // Check for breaches
            if (temperature > 30.0f || pressure < 950.0f) {
                log_breach(temperature, pressure);
                printf("Breach detected: Temperature=%.2f°C, Pressure=%.2f hPa\n", temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

