// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, &reg, 1);
        if (result != 1) {
            perror("I2C write (register address) failed");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 3;
    uint8_t buf[2];
    int result;

    buf[0] = reg;
    buf[1] = data;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries\n");
    return -1; // Failure
}

