    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest reading from the buffer
sensor_data_t get_latest_reading() {
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Ensure positive index
    return circular_buffer[index];
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t data[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
