    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    uint8_t data[3];
