    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    unsigned long x5 = ((long)ac3 * b6) / pow(2, 13);
    unsigned long x6 = ((long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    unsigned long b4 = ((unsigned long)ac4 * (x5 + x6 + 32768)) / pow(2, 15);

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    float temperature, pressure;
    time_t timestamp;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);
        timestamp = time(NULL);

        add_to_buffer(timestamp, temperature, pressure);

        printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data. Skipping sample.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up...\n", signal);
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Keep the program running
    while (1) {
        sleep(1);
    }

    return 0;
}

