#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define PWM_FREQUENCY 1000
#define MAX_DUTY_CYCLE 800000 // 80% of 1000000
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static float target_temperature = DEFAULT_TARGET_TEMP;
static float Kp = 1.0;
static float Ki = 0.1;
static float integral = 0.0;

// Function prototypes
float read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
int pi_control(float temperature);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char buffer[4];
    int i;

    if (spiRead(spi_handle, buffer, 4) != 4) {
        fprintf(stderr, "Error reading SPI data\n");
        return -273.15; // Return absolute zero on error
    }

    // Check for fault conditions
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -273.15;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -273.15;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -273.15;
    }

    // Extract temperature data (bits 3-18 of the first two bytes)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to implement PI controller
int pi_control(float temperature) {
