#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (in m°C)
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    char buffer[10];
    int temp = -1; // Default to -1 to indicate error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        char *endptr;
        temp = strtol(buffer, &endptr, 10);
        if (*endptr != '\0' && *endptr != '\n') {
            fprintf(stderr, "Error: Invalid temperature format.\n");
            temp = -1; // Set to error value
        }
    } else {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        temp = -1; // Set to error value
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close temperature file.\n");
    }

    return temp;
}

// Function to set RGB LED color based on temperature
void set_led_color(int temperature)
{
    int red = 255, green = 255, blue = 255;

    if (temperature < TEMP_BLUE) {
        red = 255;
        green = 255;
        blue = 0;
    } else if (temperature < TEMP_GREEN) {
        red = 255;
        green = 0;
        blue = 255;
    } else {
        red = 0;
        green = 255;
        blue = 255;
    }

    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temperature = read_cpu_temp();

        if (temperature != -1) {
            set_led_color(temperature);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, 255 - gpioGetPWMdutycycle(RED_PIN), 255 - gpioGetPWMdutycycle(GREEN_PIN), 255 - gpioGetPWMdutycycle(BLUE_PIN));
        } else {
            fprintf(stderr, "Error: Could not read temperature. Skipping LED update.\n");
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Cleanup before exiting
    printf("Cleaning up and exiting...\n");
    gpioPWM(RED_PIN, 255);   // Turn off red
    gpioPWM(GREEN_PIN, 255); // Turn off green
    gpioPWM(BLUE_PIN, 255);  // Turn off blue
    gpioTerminate();         // Terminate pigpio

    return 0;
}

