        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            return -1; // Timeout
        }
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal\n");
            return -1; // Timeout
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data bit start\n");
                return -1; // Timeout
            }
        }

        // Measure the length of the high pulse
        struct timeval start, end;
        gettimeofday(&start, NULL);
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data bit end\n");
                return -1; // Timeout
            }
        }
        gettimeofday(&end, NULL);

        long pulse_length = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_usec - start.tv_usec);

        // Determine if it's a 0 or a 1 based on the pulse length
        if (pulse_length > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Copy the raw data to the output buffer
    for (i = 0; i < 5; i++) {
        data[i] = (unsigned char)(raw_data[i] & 0xFF);
    }

    return 0;
}

// Function to calculate the checksum
unsigned char calculate_checksum(const unsigned char *data) {
    return data[0] + data[1] + data[2] + data[3];
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    unsigned char checksum = calculate_checksum(data);
    return (checksum == data[4]);
}

// Function to parse the DHT22 data
int parse_dht22_data(const unsigned char *data, SensorData *sensor_data) {
    // Combine the first two bytes for humidity and the next two for temperature
    int humidity = (data[0] << 8) | data[1];
    int temperature = (data[2] << 8) | data[3];

    // Convert to float values
    sensor_data->humidity = (float)humidity / 10.0;
    sensor_data->temperature = (float)temperature / 10.0;

    return 0;
}

// Function to create a JSON payload
char *create_json_payload(const SensorData *sensor_data) {
    json_t *root = json_object();
    json_object_set_new(root, "temperature", json_real(sensor_data->temperature));
    json_object_set_new(root, "humidity", json_real(sensor_data->humidity));

    char *json_string = json_dumps(root, JSON_REAL_PRECISION(3));
    json_decref(root);
    return json_string;
}

// Function to send data to the server using libcurl
int send_data_to_server(const char *json_payload) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data sent successfully. Response code: %ld\n", response_code);
            } else {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    int i;
    unsigned char dht22_data[5];
    SensorData sensor_data;
    char *json_payload;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            // Read DHT22 data
            if (read_dht22(DHT22_GPIO, dht22_data) == 0) {
                // Validate checksum
                if (validate_checksum(dht22_data)) {
                    // Parse data
                    if (parse_dht22_data(dht22_data, &sensor_data) == 0) {
                        // Create JSON payload
                        json_payload = create_json_payload(&sensor_data);

                        // Send data to server
                        if (send_data_to_server(json_payload) == 0) {
                            success = 1; // Mark as successful
                        } else {
                            fprintf(stderr, "Failed to send data to server. Retry %d/%d\n", retries + 1, MAX_RETRIES);
                        }

                        free(json_payload);
                    } else {
                        fprintf(stderr, "Failed to parse DHT22 data. Retry %d/%d\n", retries + 1, MAX_RETRIES);
                    }
                } else {
                    fprintf(stderr, "Checksum validation failed. Retry %d/%d\n", retries + 1, MAX_RETRIES);
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data. Retry %d/%d\n", retries + 1, MAX_RETRIES);
            }

            if (!success) {
                retries++;
                gpioDelay(2000); // Wait 2 seconds before retrying
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    // Clean up pigpio
    gpioTerminate();

    return 0;
}

