#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// Conversion delay (ms)
#define BMP180_CONVERSION_DELAY (2 + (3 << BMP180_OSS))

// GPIO pin for push-button interrupt
#define GPIO_BUTTON 4

// Debounce time (us)
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_time = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_pressure(int32_t raw_temperature, int32_t raw_pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_uint16(BMP180_REG_CAL_AC4);
    ac5 = read_uint16(BMP180_REG_CAL_AC5);
    ac6 = read_uint16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }
    gpioDelay(BMP180_CONVERSION_DELAY * 1000); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the compensated pressure in hPa
double calculate_pressure(int32_t raw_temperature, int32_t raw_pressure)
{
    int32_t X1, X2, X3, B3, B5, B6, B7, p;
    uint32_t B4;

    X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    B5 = X1 + X2;
    B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    X2 = ac2 * B6 / pow(2, 11);
    X3 = X1 + X2;
    B3 = (((ac1 * 4 + X3) << BMP180_OSS) + 2) / 4;
    X1 = ac3 * B6 / pow(2, 13);
    X2 = (b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    X3 = ((X1 + X2) + 2) / pow(2, 2);
    B4 = ac4 * (uint32_t)(X3 + 32768) / pow(2, 15);
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    p = p + (X1 + X2 + 3791) / pow(2, 4);

    return p / 100.0; // Return pressure in hPa
}

// Interrupt handler for the push-button
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    if (tick - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = tick;
        if (logging_enabled) {
            printf("Logging enabled\n");
        } else {
            printf("Logging disabled\n");
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);

    // Set interrupt handler for falling edge
    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;
            double pressure;
            time_t now;
            struct tm *timeinfo;
            char timestamp[20];
            FILE *fp;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading sensor data\n");
                continue; // Skip to the next iteration
            }

            // Calculate compensated pressure
            pressure = calculate_pressure(raw_temperature, raw_pressure);

            // Get current timestamp
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Open log file in append mode
            fp = fopen("pressure_log.txt", "a");
            if (fp == NULL) {
                fprintf(stderr, "Error opening log file\n");
                continue; // Skip to the next iteration
            }

            // Write timestamp and pressure to log file
            fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);

            // Close log file
            fclose(fp);

            printf("%s, %.2f hPa\n", timestamp, pressure);
        } else {
            printf("Logging disabled\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

