    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;
            double pressure;
            time_t now;
            struct tm *timeinfo;
            char timestamp[20];
            FILE *fp;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading sensor data\n");
                continue; // Skip to the next iteration
            }

            // Calculate compensated pressure
            pressure = calculate_pressure(raw_temperature, raw_pressure);

            // Get current timestamp
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Open log file in append mode
            fp = fopen("pressure_log.txt", "a");
            if (fp == NULL) {
                fprintf(stderr, "Error opening log file\n");
                continue; // Skip to the next iteration
            }

            // Write timestamp and pressure to log file
            fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);

            // Close log file
            fclose(fp);

            printf("%s, %.2f hPa\n", timestamp, pressure);
        } else {
            printf("Logging disabled\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

