#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DEFAULT_URL "http://your-server.com/api/humidity"
#define TIMEOUT_US 100000 // 100ms timeout for DHT22 read

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
    int checksum;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = DEFAULT_URL;

// Function prototypes
int read_dht22(DHT22Data *data);
int validate_checksum(const DHT22Data *data);
int post_humidity(const DHT22Data *data);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // We don't need to process the response body, just return the size
    return real_size;
}

// Function to read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    unsigned int pulse_lengths[80];
    int pulse_count = 0;
    int start_seconds, start_micros;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Measure pulse lengths
    gpioTime(PI_TIME_RELATIVE, &start_seconds, &start_micros);
    while (pulse_count < 80) {
        int level = gpioRead(DHT22_GPIO);
        int current_seconds, current_micros;
        gpioTime(PI_TIME_RELATIVE, &current_seconds, &current_micros);
        unsigned int pulse_length = (current_seconds - start_seconds) * 1000000 + (current_micros - start_micros);

        if (pulse_length > TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 read timeout");
            return -1; // Timeout
        }

        if (level != (pulse_count % 2 == 0 ? 0 : 1)) {
            pulse_lengths[pulse_count] = pulse_length;
            pulse_count++;
            gpioTime(PI_TIME_RELATIVE, &start_seconds, &start_micros);
        }
    }

    // Decode data bits
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        data_bits[i] = (pulse_lengths[index] > pulse_lengths[index + 1]);
    }

    // Convert data bits to humidity and temperature
    data->humidity = 0;
    data->temperature = 0;
    data->checksum = 0;

    for (i = 0; i < 16; i++) {
        data->humidity <<= 1;
        data->humidity |= data_bits[i];
    }

    for (i = 16; i < 32; i++) {
        data->temperature <<= 1;
        data->temperature |= data_bits[i];
    }

    for (i = 32; i < 40; i++) {
        data->checksum <<= 1;
        data->checksum |= data_bits[i];
    }

    data->humidity /= 10.0;
    data->temperature /= 10.0;

    return 0;
}

// Function to validate the checksum
int validate_checksum(const DHT22Data *data) {
    int checksum = 0;
    int i;
    int temp_humidity = (int)(data->humidity * 10);
    int temp_temperature = (int)(data->temperature * 10);

    for (i = 0; i < 16; i++) {
        checksum += (temp_humidity >> i) & 1;
    }
    for (i = 0; i < 16; i++) {
        checksum += (temp_temperature >> i) & 1;
    }

    return (checksum == data->checksum);
}

// Function to post humidity data to the server
int post_humidity(const DHT22Data *data) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f}", data->humidity);

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, server_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL); // Remove Content-Type header
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

            res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                retries++;
                sleep(2);
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Humidity posted successfully: %.1f", data->humidity);
                    curl_easy_cleanup(curl);
                    return 0; // Success
                } else {
                    syslog(LOG_ERR, "HTTP request failed with code: %ld", response_code);
                    curl_easy_cleanup(curl);
                    retries++;
                    sleep(2);
                }
            }
        } else {
            syslog(LOG_ERR, "curl_easy_init() failed");
            return -1; // Initialization failed
        }
    }

    syslog(LOG_ERR, "Failed to post humidity after %d retries", MAX_RETRIES);
    return -1; // All retries failed
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data dht22_data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize libcurl
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        syslog(LOG_ERR, "libcurl initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_dht22(&dht22_data) == 0) {
            if (validate_checksum(&dht22_data)) {
                if (post_humidity(&dht22_data) != 0) {
                    syslog(LOG_ERR, "Failed to post humidity");
                }
            } else {
                syslog(LOG_ERR, "Checksum validation failed");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor");
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

