#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variable to track the current fan state
static int current_fan_state = 0;

// Function prototypes
int read_cpu_temp();
int set_fan_state(int state);
int get_max_fan_state();
void log_fan_state(int state);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        set_fan_state(0); // Stop the fan
        log_fan_state(0); // Log the shutdown
        exit(0);
    }
}

// Function to read CPU temperature from sysfs
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(CPU_TEMP_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening CPU temperature file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            temp = atoi(buffer);
            fclose(fp);
            return temp;
        } else {
            fprintf(stderr, "Error reading CPU temperature: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read CPU temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to set the fan state
int set_fan_state(int state) {
    FILE *fp;
    int max_state;
    int retries = 0;

    max_state = get_max_fan_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to get max fan state.\n");
        return -1;
    }

    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state: %d. Must be between 0 and %d.\n", state, max_state);
        return -1;
    }

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening fan state file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        if (fprintf(fp, "%d", state) > 0) {
            fclose(fp);
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing fan state: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to set fan state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to get the maximum fan state
int get_max_fan_state() {
    FILE *fp;
    char buffer[10];
    int max_state = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening fan state file for reading max state: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Read the current state to determine the max state
        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            int current_state = atoi(buffer);
            fclose(fp);

            // Attempt to increment the state to find the max
            int test_state = current_state + 1;
            FILE *test_fp = fopen(FAN_STATE_FILE, "w");
            if (test_fp != NULL) {
                if (fprintf(test_fp, "%d", test_state) > 0) {
                    max_state = test_state;
                } else {
                    fprintf(stderr, "Error writing to test fan state: %s\n", strerror(errno));
                }
                fclose(test_fp);
            } else {
                fprintf(stderr, "Error opening fan state file for test: %s\n", strerror(errno));
            }

            // Restore the original state
            set_fan_state(current_state);

            return max_state;
        } else {
            fprintf(stderr, "Error reading fan state for max state: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to get max fan state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to log fan state changes
void log_fan_state(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d Fan state: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state);

    fclose(fp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature, skipping this cycle.\n");
            sleep(5);
            continue;
        }

        int fan_state;
        if (cpu_temp < 45000) {
            fan_state = 0;
        } else if (cpu_temp < 55000) {
            fan_state = 1;
        } else if (cpu_temp < 65000) {
            fan_state = 2;
        } else {
            fan_state = 3;
        }

        if (fan_state != current_fan_state) {
            if (set_fan_state(fan_state) == 0) {
                log_fan_state(fan_state);
                current_fan_state = fan_state;
            } else {
                fprintf(stderr, "Failed to set fan state.\n");
            }
        }

        sleep(5);
    }

    return 0;
}

