#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define LOG_FILE "heater_log.txt"
#define DEFAULT_TARGET_TEMP 50.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double target_temperature = DEFAULT_TARGET_TEMP;
static double Kp = DEFAULT_KP;
static double Ki = DEFAULT_KI;
static double Kd = DEFAULT_KD;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double current_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void handle_fault(uint32_t raw_data);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Function to read temperature from MAX31855
double read_temperature() {
    char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(log_file, "%s SPI read error: %d\n", __func__, result);
        fflush(log_file);
        return -273.15; // Return absolute zero on error
    }

    uint32_t raw_data = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];

    // Check for fault bits
    if (raw_data & 0x00000007) {
        handle_fault(raw_data);
        return -273.15; // Return absolute zero on fault
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out the fault bits
    double temperature = thermocouple_data * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to 0-100
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 100.0) {
        output = 100.0;
    }

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 10000.0); // pigpio uses 0-1000000 for 0-100%
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %.2f %%, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Function to handle MAX31855 faults
void handle_fault(uint32_t raw_data) {
    fprintf(log_file, "%s Fault detected!\n", __func__);
    fflush(log_file);

    if (raw_data & 0x00000001) {
        fprintf(log_file, "%s Thermocouple open circuit.\n", __func__);
        fflush(log_file);
    } else if (raw_data & 0x00000002) {
        fprintf(log_file, "%s Thermocouple shorted to GND.\n", __func__);
        fflush(log_file);
    } else if (raw_data & 0x00000004) {
        fprintf(log_file, "%s Thermocouple shorted to VCC.\n", __func__);
        fflush(log_file);
    }

    // Disable heater and reset PID state
    set_pwm_duty_cycle(0.0);
    integral = 0.0;
    previous_error = 0.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:k:p:d:")) != -1) {
        switch (opt) {
            case 't':
                target_temperature = atof(optarg);
                break;
            case 'k':
                Kp = atof(optarg);
                break;
            case 'p':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_temperature] [-k Kp] [-p Ki] [-d Kd]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(log_file, "SPI open failed: %d\n", spi_handle);
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM output mode
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, 1000000); // Set range to 0-1000000 for finer control

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > -273.0) {
            // Failsafe check
            if (temperature > 100.0 || temperature < 0.0) {
                fprintf(log_file, "Temperature out of range: %.2f C. Disabling heater.\n", temperature);
                fflush(log_file);
                set_pwm_duty_cycle(0.0);
                running = 0; // Exit loop
            } else {
                double pid_output = calculate_pid(temperature);
                set_pwm_duty_cycle(pid_output);
                log_data(temperature, pid_output, pid_output);
            }
        } else {
            fprintf(log_file, "Error reading temperature. Skipping PID calculation.\n");
            fflush(log_file);
        }

        gpioDelay(1000); // 1 second delay
    }

    // Clean up
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

