#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_cpu_temp() {
    FILE *fp;
    int temp_milli;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli / 1000; // Convert to degrees Celsius
}

int calculate_duty_cycle(int temperature) {
    if (temperature <= 40) {
        return 0;
    } else if (temperature >= 70) {
        return 100;
    } else {
        return (int)(((float)(temperature - 40) / (70 - 40)) * 100);
    }
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle * 2.55) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Write CSV header
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error creating log file");
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    fclose(fp);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading CPU temperature, using previous value.\n");
            // Consider handling the error more gracefully, e.g., using a default temperature
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed.\n");
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Temperature: %d°C, Duty Cycle: %d%%\n", temperature, duty_cycle);

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio

    return 0;
}

