int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle);
float convert_to_flow_rate(int raw_value);
int validate_crc(unsigned char data[], int len);
void log_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 checksum calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle) {
    unsigned char data[3];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (bytes_read == 3) {
            return (data[0] << 8) | data[1];
        } else {
            fprintf(stderr, "I2C read error (handle %d): %d retries remaining\n", i2c_handle, retries);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor after multiple retries (handle %d)\n", i2c_handle);
    return -1; // Indicate failure
}

// Function to convert raw value to flow rate
float convert_to_flow_rate(int raw_value) {
    return raw_value * 0.01;
}

