        if (raw_value1 != -1) {
            unsigned char data1[3];
            data1[0] = (raw_value1 >> 8) & 0xFF;
            data1[1] = raw_value1 & 0xFF;
            data1[2] = 0; // Dummy CRC value for validation

            if (validate_crc(data1, 3)) {
                flow1 = convert_to_flow_rate(raw_value1);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 1\n");
            }
        }

        if (raw_value2 != -1) {
            unsigned char data2[3];
            data2[0] = (raw_value2 >> 8) & 0xFF;
            data2[1] = raw_value2 & 0xFF;
            data2[2] = 0; // Dummy CRC value for validation

            if (validate_crc(data2, 3)) {
                flow2 = convert_to_flow_rate(raw_value2);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 2\n");
            }
        }

        // Log data
        if (flow1 != -1.0 && flow2 != -1.0) {
            log_data(flow1, flow2);
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    return 0;
}

