#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder();
float calculate_angle(int state);
int log_data(float angle);
void signal_handler(int signal);

// Quadrature state machine states
enum {
    STATE_00 = 0,
    STATE_01,
    STATE_11,
    STATE_10
};

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);

    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder
int read_encoder() {
    int a = gpioRead(ENCODER_A_PIN);
    int b = gpioRead(ENCODER_B_PIN);

    if (a == 0 && b == 0) return STATE_00;
    if (a == 0 && b == 1) return STATE_01;
    if (a == 1 && b == 1) return STATE_11;
    if (a == 1 && b == 0) return STATE_10;

    return -1; // Error: Invalid state
}

// Function to calculate the normalized angular position
float calculate_angle(int state) {
    switch (state) {
        case STATE_00: return 0.00;
        case STATE_01: return 90.00;
        case STATE_11: return 180.00;
        case STATE_10: return 270.00;
        default: return -1.00; // Error
    }
}

// Function to log the data to a file
int log_data(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    int current_state = STATE_00;
    int previous_state = STATE_00;
    int pulse_count = 0;

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int new_state = read_encoder();

        if (new_state == -1) {
            fprintf(stderr, "Error reading encoder state.\n");
            continue; // Skip to the next iteration
        }

        // Quadrature decoding logic
        if (new_state != current_state) {
            if (new_state == STATE_00 && previous_state == STATE_01) {
                pulse_count++;
            } else if (new_state == STATE_00 && previous_state == STATE_11) {
                pulse_count--;
            } else if (new_state == STATE_01 && previous_state == STATE_00) {
                pulse_count++;
            } else if (new_state == STATE_01 && previous_state == STATE_10) {
                pulse_count--;
            } else if (new_state == STATE_11 && previous_state == STATE_01) {
                pulse_count--;
            } else if (new_state == STATE_11 && previous_state == STATE_10) {
                pulse_count++;
            } else if (new_state == STATE_10 && previous_state == STATE_11) {
                pulse_count++;
            } else if (new_state == STATE_10 && previous_state == STATE_00) {
                pulse_count--;
            }

            previous_state = current_state;
            current_state = new_state;

            // Calculate the normalized angular position
            float angle = calculate_angle(current_state);

            // Log the data
            if (log_data(angle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Pulse Count: %d, Angle: %.2f\n", pulse_count, angle);
        }

        gpioDelay(1000); // Delay for 1 millisecond
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Rotary encoder monitoring stopped.\n");

    return 0;
}

