#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable ISR
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register ISR
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate RPM
        double rpm = calculate_rpm(current_pulse_count);

        // Log RPM
        log_rpm(rpm);

        // Sleep for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    return 0;
}

