#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <wiringPiI2C.h>

// Define constants
#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_RED_LSB 0x08
#define FIFO_DATA_RED_MSB 0x09
#define FIFO_DATA_IR_LSB 0x0A
#define FIFO_DATA_IR_MSB 0x0B
#define IR_THRESHOLD 2000
#define LED_GPIO 17
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_register(int reg);
int write_register(int reg, int value);
int read_ir_data();
int read_red_data();
int check_ir_threshold(int ir_value);
void log_data(int red_value, int ir_value);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO initialization function
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adpd144ri";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read a register
int read_register(int reg) {
    int value = wiringPiI2CReadReg8(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register
int write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read IR data
int read_ir_data() {
    int lsb = read_register(FIFO_DATA_IR_LSB);
    int msb = read_register(FIFO_DATA_IR_MSB);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to read Red data
int read_red_data() {
    int lsb = read_register(FIFO_DATA_RED_LSB);
    int msb = read_register(FIFO_DATA_RED_MSB);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to check IR threshold
int check_ir_threshold(int ir_value) {
    return ir_value > IR_THRESHOLD;
}

// Function to log data
void log_data(int red_value, int ir_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red_value, ir_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Verify sensor presence
    int part_id = read_register(PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("PART_ID: 0x%02X\n", part_id);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int red_value = read_red_data();
        int ir_value = read_ir_data();

        if (red_value >= 0 && ir_value >= 0) {
            log_data(red_value, ir_value);

            if (check_ir_threshold(ir_value)) {
                gpiod_line_set_value(gpio_line, 1); // Turn on LED
            } else {
                gpiod_line_set_value(gpio_line, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

