        return -1;
    }
    return 0;
}

// Function to read IR data
int read_ir_data() {
    int lsb = read_register(FIFO_DATA_IR_LSB);
    int msb = read_register(FIFO_DATA_IR_MSB);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to read Red data
int read_red_data() {
    int lsb = read_register(FIFO_DATA_RED_LSB);
    int msb = read_register(FIFO_DATA_RED_MSB);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to check IR threshold
int check_ir_threshold(int ir_value) {
    return ir_value > IR_THRESHOLD;
}

// Function to log data
void log_data(int red_value, int ir_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red_value, ir_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Verify sensor presence
    int part_id = read_register(PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("PART_ID: 0x%02X\n", part_id);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int red_value = read_red_data();
        int ir_value = read_ir_data();

        if (red_value >= 0 && ir_value >= 0) {
            log_data(red_value, ir_value);

            if (check_ir_threshold(ir_value)) {
                gpiod_line_set_value(gpio_line, 1); // Turn on LED
            } else {
                gpiod_line_set_value(gpio_line, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

