#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[7];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->tvoc = (buf[1] << 8) | buf[0];
    data->eco2 = (buf[6] << 8) | buf[5];

    return 0;
}

// Calculate IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
    if (iaq < 0.0) {
        iaq = 0.0;
    } else if (iaq > 100.0) {
        iaq = 100.0;
    }
    return iaq;
}

// Log data to file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file);
    return 0;
}

// Cleanup resources
