#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define CONSUMER "ttp223_tamper"
#define POLL_TIMEOUT_MS 100
#define INTRUSION_THRESHOLD_S 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec start_time, current_time;
    int intrusion_detected = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (value == 1) {
            // Sensor is touched
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                                  (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed_time >= INTRUSION_THRESHOLD_S && !intrusion_detected) {
                printf("INTRUSION DETECTED\n");
                intrusion_detected = 1;
            }
        } else {
            // Sensor is released
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            intrusion_detected = 0;
        }

        usleep(POLL_TIMEOUT_MS * 1000); // Convert ms to microseconds
    }

    cleanup_gpio();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

