#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 24 // Bits
#define PERIOD_SIZE 1024 // Frames
#define GPIO_PIN 17
#define FILENAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle;
FILE *output_file;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, stopping...\n", sig);
    stop_flag = 1;
}

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format to 32-bit signed integer (left-justified 24-bit)
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S32_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", rate);
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set period size
    snd_pcm_uframes_t period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(*pcm_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }
    if (period_size != PERIOD_SIZE) {
        fprintf(stderr, "Warning: Period size changed to %d\n", period_size);
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 1); // Select left channel

    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file) {
    int err;
    snd_pcm_uframes_t frames;
    int16_t *buffer = (int16_t *) malloc(PERIOD_SIZE * sizeof(int16_t)); // Allocate buffer for 16-bit samples
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return -1;
    }

    while (!stop_flag) {
        frames = PERIOD_SIZE;
        err = snd_pcm_readi(pcm_handle, buffer, frames);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        } else if (err != frames) {
            fprintf(stderr, "Short read, read %d frames, expected %d\n", err, frames);
        } else {
            // Write the 16-bit data to the file
            if (fwrite(buffer, sizeof(int16_t), frames, output_file) != frames) {
                fprintf(stderr, "Error writing to file\n");
                break;
            }
        }
    }

    free(buffer);
    return 0;
}

// Function to cleanup resources
void cleanup(snd_pcm_t *pcm_handle, FILE *output_file) {
    fprintf(stderr, "Cleaning up resources...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (output_file) {
        fclose(output_file);
    }
    gpioWrite(GPIO_PIN, 0); // Deselect channel
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Initialize ALSA
    if (init_alsa(&pcm_handle) < 0) {
        gpioTerminate();
        return 1;
    }

    // Open output file
    output_file = fopen(FILENAME, "wb");
    if (!output_file) {
        fprintf(stderr, "Error opening output file\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Capture audio
    if (capture_audio(pcm_handle, output_file) < 0) {
        cleanup(pcm_handle, output_file);
        return 1;
    }

    // Cleanup resources
    cleanup(pcm_handle, output_file);

    return 0;
}

