#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define flame detection timeout (seconds)
#define FLAME_TIMEOUT 5

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected, int flame_duration);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t flame_start_time;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioPWM(FAN_PIN, 0); // Initially turn off the fan

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int readings[5];
    int sum = 0;

    for (i = 0; i < 5; i++) {
        readings[i] = gpioRead(FLAME_SENSOR_PIN);
        gpioDelay(10); // 10 ms delay
        sum += readings[i];
    }

    // Return 0 if at least 3 readings are LOW, otherwise return 1
    return (sum < 3) ? 0 : 1;
}

// Function to control the fan using PWM
void control_fan(int flame_detected, int flame_duration) {
    if (flame_detected) {
        // Calculate duty cycle based on flame duration (exponential curve)
        float duty_cycle = 0.0;
        if (flame_duration <= 10) {
            duty_cycle = 0.2 * flame_duration;
        } else {
            duty_cycle = 0.2 * (10 + (flame_duration - 10) * 0.8); // Scale up to 80% after 10 seconds
            if (duty_cycle > 0.8) duty_cycle = 0.8;
        }

        int pwm_value = (int)(duty_cycle * 255.0); // pigpio PWM range is 0-255
        gpioPWM(FAN_PIN, pwm_value);
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off the fan
    }
}

