void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(FAN_PIN, 0); // Turn off the fan
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    time_t last_flame_detection = 0;
    int flame_detected = 0;

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected
            if (!flame_detected) {
                flame_detected = 1;
                state.flame_detected = 1;
                state.flame_start_time = time(NULL);
                log_event("Flame detected");
            } else {
                // Flame still detected, update duration
                int flame_duration = time(NULL) - state.flame_start_time;
                control_fan(1, flame_duration);
            }
            last_flame_detection = time(NULL);
        } else {
            // No flame detected
            if (flame_detected) {
                flame_detected = 0;
                state.flame_detected = 0;
                log_event("Flame ended");
            }
        }

        // Check for timeout
        if (flame_detected && (time(NULL) - last_flame_detection > FLAME_TIMEOUT)) {
            log_event("Flame detection timeout");
            flame_detected = 0;
            state.flame_detected = 0;
        }

        control_fan(flame_detected, time(NULL) - state.flame_start_time);

        gpioDelay(50); // Poll every 50 ms
    }

    cleanup();

    return 0;
}

