#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.log"
#define MAGIC_NUMBER 0x52444144

// Configuration structure
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    float frame_period;
} config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int write_log_header();
int request_frame();
int read_data(uint8_t *data);
int log_data(uint8_t *data, int frame_number);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write the log header
int write_log_header() {
    uint32_t magic = MAGIC_NUMBER;
    uint64_t timestamp = time(NULL);
    config_t config = {77.0, 79.0, 64, 256, 0.1};

    if (fwrite(&magic, sizeof(magic), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number\n");
        return -1;
    }
    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write config\n");
        return -1;
    }

    return 0;
}

// Request a frame
int request_frame() {
    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_GPIO, 0);
    return 0;
}

// Read data from SPI
int read_data(uint8_t *data) {
    char tx_buffer[FRAME_SIZE];
    memset(tx_buffer, 0, FRAME_SIZE); // Dummy data for full-duplex

    if (spiXfer(spi_handle, tx_buffer, data, FRAME_SIZE) != FRAME_SIZE) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return 0;
}

// Log the data
int log_data(uint8_t *data, int frame_number) {
    uint64_t timestamp = time(NULL);

    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame number\n");
        return -1;
    }
    if (fwrite(data, FRAME_SIZE, 1, log_file) != 1) {
        fprintf(stderr, "Failed to write data\n");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    if (write_log_header() != 0) {
        cleanup();
        return 1;
    }

    int frame_number = 0;
    uint8_t *data = (uint8_t *)malloc(FRAME_SIZE);
    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for data\n");
        cleanup();
        return 1;
    }

    while (!terminate) {
        request_frame();

        // Wait for data ready
        while (gpioRead(DATA_READY_GPIO) == 0 && !terminate) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (terminate) break;

        if (read_data(data) == 0) {
            if (log_data(data, frame_number) == 0) {
                frame_number++;
            } else {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read data\n");
        }
    }

    free(data);
    cleanup();
    return 0;
}

