#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810 // Continuous mode, 100ms conversion, auto full scale
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
float calculate_lux(uint16_t raw_data);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float lux;
    char timestamp[32];
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF; // MSB
    buf[2] = CONFIG_VALUE & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *raw_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to calculate lux value
float calculate_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return LUX_SCALE * (1 << exponent) * mantissa;
}

// Function to log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float lux;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_data) == 0) {
            lux = calculate_lux(raw_data);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

