#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 18
#define RIGHT_SENSOR 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (!terminate) {
        // Read sensor values
        int left_value = gpioRead(LEFT_SENSOR);
        int center_value = gpioRead(CENTER_SENSOR);
        int right_value = gpioRead(RIGHT_SENSOR);

        // Print sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

