#include <errno.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
const int gpio_lines[] = {2, 3, 4, 5, 6, 7, 8, 9};
#define NUM_LINES (sizeof(gpio_lines) / sizeof(gpio_lines[0]))

// Global variables for signal handling and GPIO resources
static volatile sig_atomic_t terminate = 0;
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_LINES] = {NULL};

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the state of a single GPIO line
int read_gpio_line(struct gpiod_line *line)
{
    int value;
    if (line == NULL) {
        fprintf(stderr, "Error: Null line pointer passed to read_gpio_line.\n");
        return -1; // Indicate an error
    }
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the state of all GPIO lines to the console
void log_gpio_states(struct gpiod_line **lines, int num_lines)
{
    for (int i = 0; i < num_lines; i++) {
        int value = read_gpio_line(lines[i]);
