#define CH3_GPIO 4
#define CH4_GPIO 5
#define CH5_GPIO 6
#define CH6_GPIO 7
#define CH7_GPIO 8
#define CH8_GPIO 9

// Global variable to control the main loop
volatile sig_atomic_t running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-down resistors
    int gpios[] = {CH1_GPIO, CH2_GPIO, CH3_GPIO, CH4_GPIO, CH5_GPIO, CH6_GPIO, CH7_GPIO, CH8_GPIO};
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(gpios[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(gpios[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read sensor data
    while (running) {
        // Get current timestamp in milliseconds
        long long start_time = time_time();
        int milliseconds = (int)(start_time % 1000);

        // Read sensor data
        int ch1 = gpioRead(CH1_GPIO);
        int ch2 = gpioRead(CH2_GPIO);
        int ch3 = gpioRead(CH3_GPIO);
        int ch4 = gpioRead(CH4_GPIO);
        int ch5 = gpioRead(CH5_GPIO);
        int ch6 = gpioRead(CH6_GPIO);
        int ch7 = gpioRead(CH7_GPIO);
        int ch8 = gpioRead(CH8_GPIO);

        // Print sensor data in the specified format
        printf("[+%d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               milliseconds, ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

