// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the state of a single GPIO pin
int read_gpio(int gpio) {
    return gpioRead(gpio);
}

// Function to format the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the sensor data to the console in CSV format
void log_data(const char* timestamp, const int* sensor_values) {
    printf("%s", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf(",%d", sensor_values[i]);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor_values[num_channels];
        for (int i = 0; i < num_channels; i++) {
            sensor_values[i] = read_gpio(gpio_pins[i]);
        }

        // Get the current timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            gpioDelay(50); // Wait 50ms
            continue;
        }

        // Log the data
        log_data(timestamp, sensor_values);

        // Free the allocated timestamp memory
        free(timestamp);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

