#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_tilt_state;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the current state of the tilt sensor
        current_tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the sensor reading
        if (current_tilt_state != 0 && current_tilt_state != 1) {
            fprintf(stderr, "Error: Invalid sensor reading: %d\n", current_tilt_state);
            gpioTerminate();
            return 1;
        }

        // Check if the tilt state has changed
        if (current_tilt_state != tilt_state) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the timestamped message
            if (current_tilt_state == 0) {
                printf("%s Tilted\n", timestamp);
            } else {
                printf("%s Not Tilted\n", timestamp);
            }

            // Update the tilt state
            tilt_state = current_tilt_state;

            // Flush stdout to ensure immediate output
            fflush(stdout);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

