#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x17
#define HW_KEY_VAL 0x00
#define CHLIST_REG 0x01
#define CHLIST_VAL 0x01 // Enable UV and ALS_VIS
#define ALS_FORCE_REG 0x18
#define UV_INDEX_REG 0x2C
#define ALS_VIS_DATA0 0x22
#define ALS_VIS_DATA1 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *uv_index, uint16_t *als_visible);
int log_data(float uv_index, uint16_t als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int initialize_sensor() {
    int status;
    uint8_t part_id;

    // Verify PART ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", status);
        return -1;
    }
