#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses and GPIO pin
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_PIN 17
#define I2C_BUS "/dev/i2c-1"

// Define measurement command
#define MEASURE_CMD 0x3608

// Define scale factor for flow rate conversion
#define FLOW_SCALE_FACTOR 0.036

// Define alarm threshold
#define ALARM_THRESHOLD 0.5

// Global variables for I2C file descriptors and GPIO line
int i2c_fd1 = -1, i2c_fd2 = -1;
struct gpiod_line *gpio_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int read_sensor(int fd, int address, float *flow_rate);
uint8_t crc8(const uint8_t *data, int len);
float convert_flow(int16_t raw_flow);
float calculate_average(float flow1, float flow2);
void set_alarm(int alarm_state);
void log_flow(float avg_flow);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Set GPIO low
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    exit(0);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Initialize GPIO pin
int init_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flow_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor(int fd, int address, float *flow_rate) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[9];
    int16_t raw_flow;
    uint8_t crc;

    // Send measurement command
    if (write(fd, cmd, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (100ms)
    usleep(100000);

    // Read 9 bytes from register 0x00
    if (read(fd, buffer, 9) != 9) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Extract flow data and CRC
    raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    crc = buffer[2];

    // Validate CRC
    if (crc8(buffer, 2) != crc) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02x\n", address);
        return -1;
    }

    // Convert raw flow to ml/min
    *flow_rate = convert_flow(raw_flow);

    return 0;
}

// CRC8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw flow to ml/min
float convert_flow(int16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Calculate average flow rate
float calculate_average(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Set alarm state
void set_alarm(int alarm_state) {
    if (gpiod_line_set_value(gpio_line, alarm_state) < 0) {
        perror("Error setting GPIO value");
    }
}

// Log flow rate to file
void log_flow(float avg_flow) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Average Flow: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);

    fclose(fp);
}

int main() {
    float flow1, flow2, avg_flow;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd1 = init_i2c(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        return 1;
    }
    i2c_fd2 = init_i2c(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        close(i2c_fd1);
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    // Main loop
    while (1) {
        flow1 = 0.0; // Initialize to 0.0 to handle errors
        flow2 = 0.0;

        // Read sensor 1
        if (read_sensor(i2c_fd1, SENSOR1_ADDR, &flow1) < 0) {
            fprintf(stderr, "Error reading sensor 1, skipping...\n");
            flow1 = 0.0; // Set to 0 to avoid affecting the average
        }

        // Read sensor 2
        if (read_sensor(i2c_fd2, SENSOR2_ADDR, &flow2) < 0) {
            fprintf(stderr, "Error reading sensor 2, skipping...\n");
            flow2 = 0.0; // Set to 0 to avoid affecting the average
        }

        // Calculate average flow rate
        avg_flow = calculate_average(flow1, flow2);

        // Set alarm state
        set_alarm(avg_flow < ALARM_THRESHOLD);

        // Log flow rate
        log_flow(avg_flow);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

