#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int reading);
void print_buffer();
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        print_buffer();
        gpioTerminate();
        exit(0);
    }
}

// Initializes the pigpio library and configures the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    return 0;
}

// Reads the sensor value from the GPIO pin
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a timestamp and sensor reading to the circular buffer
void add_to_buffer(time_t timestamp, int reading) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Prints the contents of the circular buffer in chronological order
void print_buffer() {
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        char timestamp_str[30];
        struct tm *tm_info = localtime(&buffer[index].timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("Timestamp: %s, Reading: %d\n", timestamp_str, buffer[index].reading);
    }
    printf("--- End of Sensor Data ---\n");
}

