    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int reading = read_sensor();
        time_t now = time(NULL);

        if (reading == 0) {
            add_to_buffer(now, reading);
            char timestamp_str[30];
            struct tm *tm_info = localtime(&now);
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("Obstacle detected at %s\n", timestamp_str);
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

