#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB 0x2A
#define ACCEL_X_MSB 0x2B
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Y_MSB 0x2D
#define ACCEL_Z_LSB 0x2E
#define ACCEL_Z_MSB 0x2F
#define SAMPLE_INTERVAL_MS 500
#define SCALING_FACTOR 0.0009765625
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_register(uint8_t reg, uint8_t *value);
int write_register(uint8_t reg, uint8_t value);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("fan_health.csv", "a+");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }
    rewind(csv_file);

    // Main loop
    sensor_data_t data;
    while (!terminate) {
        // Read acceleration data
        int16_t raw_x, raw_y, raw_z;
        if (read_acceleration(&raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Retry on next iteration
        }

        // Convert to g
        data.x = convert_to_g(raw_x);
        data.y = convert_to_g(raw_y);
        data.z = convert_to_g(raw_z);

        // Log data
        if (log_data(data.x, data.y, data.z) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", filename);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize sensor
int init_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        // Write to MODE_CONTROL register
        if (write_register(MODE_CONTROL_REG, 0x10) != 0) {
            fprintf(stderr, "Failed to write to MODE_CONTROL register (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Check operating status
        uint8_t status;
        if (read_register(OPERATING_STATUS_REG, &status) != 0) {
            fprintf(stderr, "Failed to read operating status (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (!(status & 0x01)) {
            fprintf(stderr, "Sensor not active (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

// Read a register
int read_register(uint8_t reg, uint8_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "Failed to write register address (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (read(i2c_fd, value, 1) != 1) {
            fprintf(stderr, "Failed to read register value (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read register after %d retries\n", MAX_RETRIES);
    return -1;
}

// Write a register
int write_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to write to register (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to write to register after %d retries\n", MAX_RETRIES);
    return -1;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        // Read all 6 bytes at once
        if (write(i2c_fd, (uint8_t[]){ACCEL_X_LSB}, 1) != 1) {
            fprintf(stderr, "Failed to write register address for acceleration read (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (read(i2c_fd, buffer, 6) != 6) {
            fprintf(stderr, "Failed to read acceleration data (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Combine LSB and MSB for each axis
        *x = (int16_t)((buffer[1] << 8) | buffer[0]);
        *y = (int16_t)((buffer[3] << 8) | buffer[2]);
        *z = (int16_t)((buffer[5] << 8) | buffer[4]);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read acceleration after %d retries\n", MAX_RETRIES);
    return -1;
}

// Convert to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value * SCALING_FACTOR;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to CSV file\n");
        return -1;
    }

    fflush(csv_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

