        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

