        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        // Check if obstacle is detected by either sensor
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn LED ON
            if (control_led(1) != 0) {
                break; // Exit loop if LED control fails
            }
        } else {
            // Turn LED OFF
            if (control_led(0) != 0) {
                break; // Exit loop if LED control fails
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

