#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Define the stall duration threshold (in seconds)
#define STALL_DURATION 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
int is_stalled(int sensor1_value, int sensor2_value);
int log_stall_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading from GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check if a stall has occurred
int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to the log file
int log_stall_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the log file exists and is not empty
    if (access(LOG_FILE, F_OK) == 0) {
        FILE *temp_file = fopen(LOG_FILE, "r");
        if (temp_file != NULL) {
            char first_char;
            if (fread(&first_char, 1, 1, temp_file) > 0) {
                fclose(temp_file);
                // Log file is not empty, check for duplicate entry
                FILE *log_file_temp = fopen(LOG_FILE, "a");
                if (log_file_temp == NULL) {
                    perror("Error opening log file for appending");
                    return -1;
                }
                fprintf(log_file_temp, "%s - Stall detected\n", timestamp);
                fclose(log_file_temp);
                return 0;
            } else {
                fclose(temp_file);
            }
        } else {
            perror("Error opening log file for reading");
            return -1;
        }
    } else {
        // Log file doesn't exist, create it and add the entry
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Error opening log file for writing");
            return -1;
        }
        fprintf(log_file, "%s - Stall detected\n", timestamp);
        fclose(log_file);
        return 0;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    time_t stall_start_time = 0;
    int stalled = 0;

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (is_stalled(sensor1_value, sensor2_value)) {
            if (!stalled) {
                // Stall detected for the first time
                stalled = 1;
                stall_start_time = time(NULL);
                printf("Stall detected!\n");
            } else {
                // Check if the stall duration has exceeded the threshold
                if (time(NULL) - stall_start_time >= STALL_DURATION) {
                    // Log the stall event
                    if (log_stall_event() == 0) {
                        printf("Stall event logged.\n");
                    } else {
                        fprintf(stderr, "Error logging stall event.\n");
                    }
                    stalled = 0; // Reset stalled flag
                }
            }
        } else {
            // Reset the stall detection
            stalled = 0;
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

