#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x8D
#define CONFIG_REG 0x01
#define X_AXIS_REG 0x02
#define Y_AXIS_REG 0x04
#define Z_AXIS_REG 0x06
#define LSB_SCALE_FACTOR 0.0078125 // 50 mT range
#define LOG_FILE "magnetic_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mT(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    int status;
    uint8_t device_id;

    // Verify device ID
    status = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", status);
        return -1;
    }
    device_id = (uint8_t)status;

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    // Configure for continuous conversion mode, all axes enabled
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x03); // Continuous mode, all axes enabled
    if (status < 0) {
        fprintf(stderr, "Error writing configuration: %d\n", status);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int status;

    status = i2cReadWordData(i2c_handle, X_AXIS_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading X axis data: %d\n", status);
        return -1;
    }
    *x = (int16_t)status;

    status = i2cReadWordData(i2c_handle, Y_AXIS_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading Y axis data: %d\n", status);
        return -1;
    }
    *y = (int16_t)status;

    status = i2cReadWordData(i2c_handle, Z_AXIS_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading Z axis data: %d\n", status);
        return -1;
    }
    *z = (int16_t)status;

    return 0;
}

// Convert raw value to mT
float convert_to_mT(int16_t raw_value) {
    return (float)raw_value * LSB_SCALE_FACTOR;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    float x_mT, y_mT, z_mT;
    int file_exists = 0;

    // Check if the log file exists
    if (access(LOG_FILE, F_OK) == 0) {
        file_exists = 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,X (mT),Y (mT),Z (mT)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to mT
            x_mT = convert_to_mT(raw_x);
            y_mT = convert_to_mT(raw_y);
            z_mT = convert_to_mT(raw_z);

            // Log data
            log_data(x_mT, y_mT, z_mT);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

