    return 0;
}

// Convert raw value to mT
float convert_to_mT(int16_t raw_value) {
    return (float)raw_value * LSB_SCALE_FACTOR;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    float x_mT, y_mT, z_mT;
    int file_exists = 0;

    // Check if the log file exists
    if (access(LOG_FILE, F_OK) == 0) {
        file_exists = 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,X (mT),Y (mT),Z (mT)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to mT
            x_mT = convert_to_mT(raw_x);
            y_mT = convert_to_mT(raw_y);
            z_mT = convert_to_mT(raw_z);

            // Log data
            log_data(x_mT, y_mT, z_mT);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

