#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define RETRY_DELAY 60 // seconds

static volatile int running = 1;
static int sockfd = -1; // Socket file descriptor

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to the console and file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s %s\n", timestamp, message);
    printf("%s %s\n", timestamp, message);
    fclose(fp);
}

// Function to send data to the server
int send_data(const char *data) {
    struct sockaddr_in serv_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        log_message("Error creating socket");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        log_message("Invalid address/ Address not supported");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection Failed");
        log_message("Connection Failed");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (send(sockfd, data, strlen(data), 0) < 0) {
        perror("Send failed");
        log_message("Send failed");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    close(sockfd);
    sockfd = -1;
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signum);
    log_message("Caught signal, exiting...");

    if (sockfd != -1) {
        close(sockfd);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Daemon started");

    while (running) {
        // Read sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            log_message("Error reading GPIO, re-initializing...");
            gpioTerminate();
            sleep(RETRY_DELAY);
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                log_message("pigpio re-initialisation failed");
                running = 0; // Exit if re-initialization fails
                break;
            }
            gpioSetMode(GPIO_PIN, PI_INPUT);
            gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
            continue; // Skip to the next iteration
        }

        // Check for water detection
        if (sensor_value == 1) {
            char *timestamp = get_timestamp();
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "ALERT: Water detected");
            log_message(log_message_buffer);

            char data[200];
            snprintf(data, sizeof(data), "%s ALERT: Water detected", timestamp);

            if (send_data(data) != 0) {
                log_message("Failed to send data to server");
            }
        }

        sleep(2);
    }

    // Clean up resources before exiting
    gpioTerminate();
    log_message("Daemon stopped");

    return 0;
}

