void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable alert callback
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    close(socket_desc);
    exit(0);
}

