void send_rpm_to_server(double rpm) {
    char *timestamp = get_timestamp();
    char message[100];
    snprintf(message, sizeof(message), "%s %.2f", timestamp, rpm);

    if (send(socket_desc, message, strlen(message), 0) < 0) {
        perror("Send failed");
    }
}

