    server.sin_port = htons(SERVER_PORT);

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connect failed");
        fclose(log_file);
        gpioTerminate();
        close(socket_desc);
        return 1;
    }

    puts("Connected to server\n");

    // Main loop
    while (1) {
        pulse_count = 0; // Reset pulse count
        gpioSetTimerFuncEx(0, 1000, NULL, NULL); // Start 1-second timer
        gpioDelay(1000); // Wait for 1 second
        gpioSetTimerFuncEx(0, 0, NULL, NULL); // Stop timer

        int pulses_per_second = pulse_count;
        double rpm = calculate_rpm(pulses_per_second);

        log_rpm(rpm);
        send_rpm_to_server(rpm);

        printf("%s %.2f\n", get_timestamp(), rpm);
    }

    return 0;
}

