#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define quadrature states
#define QUADRATURE_STATE_00 0
#define QUADRATURE_STATE_01 1
#define QUADRATURE_STATE_11 2
#define QUADRATURE_STATE_10 3

// Define rotation directions
#define CLOCKWISE 1
#define COUNTER_CLOCKWISE -1

// Global variables
static volatile int quadrature_state = QUADRATURE_STATE_00;
static volatile int running = 1; // Flag to control the main loop
static pthread_mutex_t mutex;
static pthread_cond_t cond;
static FILE *log_file = NULL;

// Function prototypes
void sensor_a_callback(int gpio, int level, uint32_t tick, void *user);
void sensor_b_callback(int gpio, int level, uint32_t tick, void *user);
int determine_rotation_direction(int current_state, int previous_state);
char* get_timestamp();
void log_rotation_event(int direction);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to pass data to the callback functions
typedef struct {
    int gpio;
} callback_data_t;

// Callback function for Sensor A
void sensor_a_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)tick; // unused
    (void)user; // unused
    int sensor_a_value = gpioRead(SENSOR_A_GPIO);
    int sensor_b_value = gpioRead(SENSOR_B_GPIO);

    pthread_mutex_lock(&mutex);
    int previous_state = quadrature_state;

    if (sensor_a_value == 1 && sensor_b_value == 0) {
        quadrature_state = QUADRATURE_STATE_01;
    } else if (sensor_a_value == 1 && sensor_b_value == 1) {
        quadrature_state = QUADRATURE_STATE_11;
    } else if (sensor_a_value == 0 && sensor_b_value == 1) {
        quadrature_state = QUADRATURE_STATE_10;
    } else {
        quadrature_state = QUADRATURE_STATE_00;
    }

    int direction = determine_rotation_direction(quadrature_state, previous_state);
    if (direction != 0) {
        log_rotation_event(direction);
    }

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Callback function for Sensor B
void sensor_b_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)tick; // unused
    (void)user; // unused
    int sensor_a_value = gpioRead(SENSOR_A_GPIO);
    int sensor_b_value = gpioRead(SENSOR_B_GPIO);

    pthread_mutex_lock(&mutex);
    int previous_state = quadrature_state;

    if (sensor_a_value == 1 && sensor_b_value == 0) {
        quadrature_state = QUADRATURE_STATE_01;
    } else if (sensor_a_value == 1 && sensor_b_value == 1) {
        quadrature_state = QUADRATURE_STATE_11;
    } else if (sensor_a_value == 0 && sensor_b_value == 1) {
        quadrature_state = QUADRATURE_STATE_10;
    } else {
        quadrature_state = QUADRATURE_STATE_00;
    }

    int direction = determine_rotation_direction(quadrature_state, previous_state);
    if (direction != 0) {
        log_rotation_event(direction);
    }

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Function to determine rotation direction
int determine_rotation_direction(int current_state, int previous_state) {
    if (current_state == previous_state) {
        return 0; // No change
    }

    if (previous_state == QUADRATURE_STATE_00) {
        if (current_state == QUADRATURE_STATE_01) return CLOCKWISE;
        if (current_state == QUADRATURE_STATE_10) return COUNTER_CLOCKWISE;
    } else if (previous_state == QUADRATURE_STATE_01) {
        if (current_state == QUADRATURE_STATE_11) return CLOCKWISE;
