#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, message);
}

int main() {
    // Open syslog for logging
    openlog("touch_led_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            control_led(1); // Turn LED on
            log_event("Touch detected, LED on");
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup before exiting
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    log_event("Program terminated");

    // Close syslog
    closelog();

    return 0;
}

