#define DEBOUNCE_TIME 50

// Global variables for signal handling
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void toggle_led();
void signal_handler(int signal);

