    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            toggle_led();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
        }
        gpioDelay(1000); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

