#define BUFFER_SIZE 100

// Structure for log entry
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();
    print_log_buffer();
    exit(0);
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %d\n", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED on pin %d: %d\n", pin, result);
    }
}

// Function to log events
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

