    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n",
               log_buffer[i].sensor_pin, log_buffer[i].timestamp, log_buffer[i].state);
    }
