#include <string.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE_PATH "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a rain event to the log file
int log_rain_event(const char *message) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging event.\n");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file is not open, not logging event.\n");
        free(timestamp);
        return -1;
    }
    free(timestamp);
    return 0;
}

// Function to read the rain sensor state
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading rain sensor: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = 1; // Initialize to a default state (dry)
    int current_state;

    // Main loop
    while (running) {
        current_state = read_rain_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting loop.\n");
            break;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_rain_event("Rain Detected");
            } else {
                log_rain_event("No Rain");
            }
            previous_state = current_state;
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

