#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile unsigned long last_sensor1_change = 0;
volatile unsigned long last_sensor2_change = 0;
volatile unsigned long last_rpm_calculation = 0;
double rpm = 0.0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, unsigned int tick, void *user);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user);
double calculate_rpm(unsigned long current_time, unsigned long last_time);
void log_data(unsigned long timestamp, int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio;
    volatile int *state;
    volatile unsigned long *last_change;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_sensor1_change > DEBOUNCE_TIME * 1000) {
        sensor1_state = level;
        last_sensor1_change = current_time;
        log_data(current_time, sensor1_state, sensor2_state);
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_sensor2_change > DEBOUNCE_TIME * 1000) {
        sensor2_state = level;
        last_sensor2_change = current_time;
        log_data(current_time, sensor1_state, sensor2_state);
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned long current_time, unsigned long last_time) {
    double time_diff = (double)(current_time - last_time) / 1000000.0; // Convert to seconds
    if (time_diff > 0) {
        return 60.0 / time_diff; // RPM = 60 / time_per_revolution
    } else {
        return 0.0;
    }
}

// Function to log data to a CSV file
void log_data(unsigned long timestamp, int sensor1_state, int sensor2_state) {
    if (log_file != NULL) {
        fprintf(log_file, "%lu,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up callbacks for sensor changes
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        unsigned long current_time = gpioTick();
        if (current_time - last_rpm_calculation > 1000000) { // Calculate RPM every 1 second
            rpm = calculate_rpm(current_time, last_rpm_calculation);
            printf("RPM: %.2f\n", rpm);
            last_rpm_calculation = current_time;
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

