#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t led_drive_strength;
    uint8_t sample_rate;
} sensor_config_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Verify sensor presence
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (status >= 0) {
            if (status == 0x82) {
                printf("Si1182 sensor found.\n");
                break;
            } else {
                fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X\n", status);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading PART_ID: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Could not read PART_ID after multiple retries.\n");
        return -1;
    }

    // Configure sensor for continuous measurement
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01); // Example configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", status);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *heart_rate, int *spo2) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, HEART_RATE_REG);
        if (status >= 0) {
            *heart_rate = status;
            break;
        } else {
            fprintf(stderr, "Error reading heart rate: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Could not read heart rate after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SPO2_REG);
        if (status >= 0) {
            *spo2 = status;
            break;
        } else {
            fprintf(stderr, "Error reading SpO2: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Could not read SpO2 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int heart_rate, spo2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
