#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Define tilt threshold (2 seconds)
#define TILT_THRESHOLD 2000 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor state
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long tilt_start_time;
} SensorState;

SensorState current_state = {0, 0, 0};

int main() {
    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Update sensor states
        current_state.sensor1_state = sensor1_value;
        current_state.sensor2_state = sensor2_value;

        // Check for tilt start
        if ((current_state.sensor1_state == 1 || current_state.sensor2_state == 1) &&
            (current_state.sensor1_state != current_state.sensor2_state)) {
            if (current_state.tilt_start_time == 0) {
                current_state.tilt_start_time = gpioTick();
                log_event("tilt-start");
            }
        }

        // Check for tilt threshold exceeded
        if (current_state.tilt_start_time != 0) {
            unsigned long current_time = gpioTick();
            if (current_time - current_state.tilt_start_time >= TILT_THRESHOLD) {
                activate_alarm();
                log_event("threshold-exceeded");
                current_state.tilt_start_time = 0; // Reset tilt start time after activation
            }
        }

        // Check for tilt end
        if (current_state.sensor1_state == 0 && current_state.sensor2_state == 0) {
            if (current_state.tilt_start_time != 0) {
                deactivate_alarm();
                log_event("tilt-end");
                current_state.tilt_start_time = 0; // Reset tilt start time
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Read sensor value with error handling
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate an error
    }
    return value;
}

// Activate the alarm (set GPIO HIGH)
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
}

// Deactivate the alarm (set GPIO LOW)
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Log an event to the log file with ISO-8601 timestamp
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to deactivate alarm and close log file
void cleanup() {
    deactivate_alarm(); // Ensure alarm is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

