#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_L 0x28
#define ACCEL_X_H 0x29
#define ACCEL_Y_L 0x2A
#define ACCEL_Y_H 0x2B
#define ACCEL_Z_L 0x2C
#define ACCEL_Z_H 0x2D
#define LED_GPIO 17
#define THRESHOLD 500.0
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000 // 1 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_magnitude(sensor_data_t data);
void control_led(int on);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initializes the pigpio library and I2C connection
int initialize_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify sensor presence by reading CTRL1 register
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, CTRL1_REG, buf, 1) != 1) {
        fprintf(stderr, "Failed to read CTRL1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Clear power-down bit in CTRL1 register
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads acceleration data from the sensor with retries
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_L, buf, 6) == 6) {
            // Convert little-endian data to signed 16-bit integers
            data.x = (int16_t)((buf[1] << 8) | buf[0]);
            data.y = (int16_t)((buf[3] << 8) | buf[2]);
            data.z = (int16_t)((buf[5] << 8) | buf[4]);
            return data;
        } else {
            fprintf(stderr, "I2C read failed, retry %d\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    data.x = 0; data.y = 0; data.z = 0; // Return default values on failure
    return data;
}

// Calculates the Euclidean magnitude of the acceleration vector
double calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Controls the LED (on or off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs the event to the log file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    if (initialize_sensor() != 0) {
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_magnitude(data);

        if (magnitude > THRESHOLD) {
            printf("Threshold exceeded: %.2f\n", magnitude);
            control_led(1); // Turn on LED
            log_event(magnitude);
            gpioDelay(1000000); // 1 second
            control_led(0); // Turn off LED
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
    fclose(log_file);

    printf("Seismic monitor stopped.\n");
    return 0;
}

