        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_L, buf, 6) == 6) {
            // Convert little-endian data to signed 16-bit integers
            data.x = (int16_t)((buf[1] << 8) | buf[0]);
            data.y = (int16_t)((buf[3] << 8) | buf[2]);
            data.z = (int16_t)((buf[5] << 8) | buf[4]);
            return data;
        } else {
            fprintf(stderr, "I2C read failed, retry %d\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    data.x = 0; data.y = 0; data.z = 0; // Return default values on failure
    return data;
}

// Calculates the Euclidean magnitude of the acceleration vector
double calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Controls the LED (on or off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs the event to the log file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    if (initialize_sensor() != 0) {
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_magnitude(data);

        if (magnitude > THRESHOLD) {
            printf("Threshold exceeded: %.2f\n", magnitude);
            control_led(1); // Turn on LED
            log_event(magnitude);
            gpioDelay(1000000); // 1 second
            control_led(0); // Turn off LED
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
    fclose(log_file);

    printf("Seismic monitor stopped.\n");
    return 0;
}

