        gpiod_line_request(sensor2_line, &input_config, 0) < 0 ||
        gpiod_line_request(sensor3_line, &input_config, 0) < 0 ||
        gpiod_line_request(sensor4_line, &input_config, 0) < 0 ||
        gpiod_line_request(led_line, &output_config, 0) < 0) {
