#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Structure to hold sensor information
typedef struct {
    int gpio;
    int id;
    struct gpiod_line *line;
} sensor_t;

// Array of sensors
sensor_t sensors[] = {
    {GPIO_2, 1, NULL},
    {GPIO_3, 2, NULL},
    {GPIO_4, 3, NULL},
    {GPIO_17, 4, NULL},
    {GPIO_27, 5, NULL}
};

const int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce(struct gpiod_line *line);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int sig);
int setup_gpio(sensor_t *sensor, struct gpiod_chip *chip);
void cleanup_gpio(sensor_t *sensor, struct gpiod_chip *chip);

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading sensor value: %s", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor
int debounce(struct gpiod_line *line) {
    int value = read_sensor(line);
    if (value < 0) return -1; // Propagate error

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIME_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    int debounced_value = read_sensor(line);
    if (debounced_value < 0) return -1; // Propagate error

    return (value == debounced_value) ? value : -1; // Return -1 if not stable
}

// Function to log an event to the log file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %s", strerror(errno));
        return -1; // Indicate an error
    }

    // Acquire exclusive lock on the file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Error acquiring file lock: %s", strerror(errno));
        fclose(fp);
        return -1; // Indicate an error
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);

    // Release the file lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Error releasing file lock: %s", strerror(errno));
    }

    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating program...");
    terminate = 1;
}

// Function to setup GPIO line
int setup_gpio(sensor_t *sensor, struct gpiod_chip *chip) {
    sensor->line = gpiod_chip_get_line(chip, sensor->gpio);
    if (!sensor->line) {
        syslog(LOG_ERR, "Error getting line for GPIO %d: %s", sensor->gpio, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(sensor->line, &config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Error requesting line for GPIO %d: %s", sensor->gpio, strerror(errno));
        gpiod_line_release(sensor->line);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO line
void cleanup_gpio(sensor_t *sensor, struct gpiod_chip *chip) {
    if (sensor->line) {
        gpiod_line_release(sensor->line);
    }
}

int main() {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Starting flame monitor...");

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Setup GPIO lines
    for (int i = 0; i < num_sensors; i++) {
        if (setup_gpio(&sensors[i], chip) != 0) {
            syslog(LOG_ERR, "Failed to setup GPIO %d, exiting.", sensors[i].gpio);
            // Cleanup already initialized lines
            for (int j = 0; j < i; j++) {
                cleanup_gpio(&sensors[j], chip);
            }
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int value = debounce(sensors[i].line);
            if (value < 0) {
                syslog(LOG_ERR, "Error during debounce for sensor %d (GPIO %d), continuing...", sensors[i].id, sensors[i].gpio);
                continue; // Continue to the next sensor
            }

            if (value == 0) { // Flame detected (LOW signal)
                if (log_event(sensors[i].id, sensors[i].gpio) != 0) {
                    syslog(LOG_ERR, "Error logging event for sensor %d (GPIO %d), continuing...", sensors[i].id, sensors[i].gpio);
                }
            }
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup GPIO lines
    for (int i = 0; i < num_sensors; i++) {
        cleanup_gpio(&sensors[i], chip);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Exiting flame monitor.");
    closelog();

    return 0;
}

