#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
const int gpio_lines[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_lines = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL};

// Previous state of the touch sensor outputs
int previous_states[8] = {0};

// Function prototypes
int read_gpio_line(int line_num);
void log_state_change(int sensor_index, int pin_num, int state);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to read the state of a single GPIO line
int read_gpio_line(int line_num) {
    int value;
    value = gpiod_line_get_value(lines[line_num]);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", line_num, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log state changes with ISO 8601 timestamp
void log_state_change(int sensor_index, int pin_num, int state) {
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", info);

    printf("%s Sensor %d (Pin %d): %s\n", buffer, sensor_index, pin_num, state ? "TOUCHED" : "RELEASED");
}

// Function to set up GPIO lines for input
int setup_gpio(void) {
    int i;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get GPIO lines
    for (i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_lines[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        // Request GPIO line for input
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", gpio_lines[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to release GPIO lines and close the chip
void cleanup_gpio(void) {
    int i;

    // Release GPIO lines
    for (i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i, current_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (i = 0; i < num_lines; i++) {
            current_state = read_gpio_line(i);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, exiting.\n", i);
                cleanup_gpio();
                return 1;
            }

            if (current_state != previous_states[i]) {
                log_state_change(i, gpio_lines[i], current_state);
                previous_states[i] = current_state;
            }
        }

        // Delay for 50 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

