#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_sensor();
int read_als(uint16_t *raw_lux);
float convert_to_lux(uint16_t raw_lux);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the VEML7700 sensor
int config_sensor() {
    // Configuration value: ALS gain 1/8, ALS integration time 100ms
    uint16_t config_value = 0x0000; //0x0000 for gain 1/8 and 100ms integration time
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config_value & 0xFF;       // Low byte
    buf[2] = (config_value >> 8) & 0xFF;  // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light data from the VEML7700 sensor
int read_als(uint16_t *raw_lux) {
    char buf[1];
    char read_buf[2];
    buf[0] = ALS_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *raw_lux = (read_buf[1] << 8) | read_buf[0]; // Combine high and low bytes
    return 0;
}

// Convert raw lux value to lux
float convert_to_lux(uint16_t raw_lux) {
    return (float)raw_lux * 0.0576;
}

// Set the LED brightness using hardware PWM
int set_led_brightness(float lux) {
    int brightness = 0;

    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (config_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    uint16_t raw_lux;
    float lux;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        error_code = 0;
        if (read_als(&raw_lux) == 0) {
            lux = convert_to_lux(raw_lux);
            set_led_brightness(lux);
            log_data(lux, (int)((lux < 100) ? 100 : (lux < 500) ? 75 : (lux < 1000) ? 50 : 25), error_code);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
            log_data(0.0, 0, -1); // Log error
            error_code = -1;
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 1 second
    }

    // Cleanup
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

