#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_START_PIN 2
#define TOUCH_SENSOR_END_PIN 9
#define LED_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *touch_states);
int debounce_touch_sensors(int *touch_states, int *last_touch_states);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);

int main() {
    int touch_states[8] = {0}; // Array to store the current touch states
    int last_touch_states[8] = {0}; // Array to store the last touch states
    int any_touched = 0; // Flag to indicate if any touch sensor is currently touched

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read touch sensor states
        if (read_touch_sensors(touch_states) != 0) {
            fprintf(stderr, "Error reading touch sensors.\n");
        }

        // Debounce touch sensor states
        if (debounce_touch_sensors(touch_states, last_touch_states) != 0) {
            fprintf(stderr, "Error debouncing touch sensors.\n");
        }

        // Check for new touch events
        any_touched = 0;
        for (int i = 0; i < 8; i++) {
            if (touch_states[i] && !last_touch_states[i]) {
                // New touch detected on channel i+1
                log_touch_event(i + 1);
                control_led(1); // Turn on the LED
                any_touched = 1;
            }
            last_touch_states[i] = touch_states[i];
        }

        // Turn off the LED if no touch sensors are touched
        if (!any_touched) {
            control_led(0);
        }

        // Delay for 50ms
        gpioDelay(50000); // Delay in microseconds
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure touch sensor pins as inputs with pull-down resistors
    for (int i = TOUCH_SENSOR_START_PIN; i <= TOUCH_SENSOR_END_PIN; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn the LED off

    return 0;
}

// Read the state of each touch sensor
int read_touch_sensors(int *touch_states) {
    for (int i = 0; i < 8; i++) {
        touch_states[i] = gpioRead(TOUCH_SENSOR_START_PIN + i);
    }
    return 0;
}

// Debounce touch sensor readings
int debounce_touch_sensors(int *touch_states, int *last_touch_states) {
    int stable_states[8];
    for (int i = 0; i < 8; i++) {
        stable_states[i] = touch_states[i];
