#define TOUCH_SENSOR_END_PIN 9
#define LED_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *touch_states);
int debounce_touch_sensors(int *touch_states, int *last_touch_states);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);

int main() {
    int touch_states[8] = {0}; // Array to store the current touch states
    int last_touch_states[8] = {0}; // Array to store the last touch states
    int any_touched = 0; // Flag to indicate if any touch sensor is currently touched

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

