        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read touch sensor states
        if (read_touch_sensors(touch_states) != 0) {
            fprintf(stderr, "Error reading touch sensors.\n");
        }

        // Debounce touch sensor states
        if (debounce_touch_sensors(touch_states, last_touch_states) != 0) {
            fprintf(stderr, "Error debouncing touch sensors.\n");
        }

        // Check for new touch events
        any_touched = 0;
        for (int i = 0; i < 8; i++) {
