                log_touch_event(i + 1);
                control_led(1); // Turn on the LED
                any_touched = 1;
            }
            last_touch_states[i] = touch_states[i];
        }

        // Turn off the LED if no touch sensors are touched
        if (!any_touched) {
            control_led(0);
        }

