#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
double calculate_lux(uint16_t raw_data);
int log_data(double lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_data = CONFIG_VALUE;
    uint16_t swapped_config_data = ((config_data & 0xFF00) >> 8) | ((config_data & 0x00FF) << 8);

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, swapped_config_data);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_data) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }
    *raw_data = (uint16_t)result;
    return 0;
}

// Calculate lux value
double calculate_lux(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t mantissa = raw_data & 0x0FFF;
    return mantissa * LUX_SCALE * (1 << exponent);
}

// Log data to file
int log_data(double lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);
    printf("%s, %.2f\n", timestamp, lux);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (read_sensor_data(&raw_data) == 0) {
            double lux = calculate_lux(raw_data);
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

