#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x08
#define MEASUREMENT_COMMAND 0x3608
#define FLOW_SCALE_FACTOR 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_data(int16_t *raw_flow, uint8_t *crc);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_to_ml_min(int16_t raw_flow);
int log_data(float flow_rate, uint8_t sensor_flags, const char *status);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;
    uint8_t sensor_flags;
    char status[10];
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int16_t raw_flow;
        uint8_t crc;
        float flow_rate;
        char status[10] = "OK";

        // Read flow data
        if (read_flow_data(&raw_flow, &crc) != 0) {
            flow_rate = -1.0; // Indicate error
            strcpy(status, "ERROR");
        } else {
            // Convert to ml/min
            flow_rate = convert_to_ml_min(raw_flow);

            // Validate flow rate
            if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
                strcpy(status, "INVALID");
            }
        }

        // Log data
        if (log_data(flow_rate, 0, status) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Send measurement command
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    // Wait 2 ms
    gpioDelay(2000); // microseconds

    return 0;
}

// Read flow data
int read_flow_data(int16_t *raw_flow, uint8_t *crc) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow data: %d\n", result);
        return 1;
    }

    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    *crc = buffer[2];

    // CRC validation
    uint8_t data[2] = {buffer[0], buffer[1]};
    uint8_t calculated_crc = calculate_crc(data, 2);
    if (calculated_crc != *crc) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, *crc);
        return 1;
    }

    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_SCALE_FACTOR;
}

// Log data
int log_data(float flow_rate, uint8_t sensor_flags, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (flow_rate == -1.0) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    }

    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

