        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, const char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO lines for the sensors
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        if (left_line) gpiod_line_release(left_line);
        if (middle_line) gpiod_line_release(middle_line);
        if (right_line) gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as inputs
    if (gpiod_line_request_input(left_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(middle_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(right_line, "obstacle_avoidance") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break; // Exit the loop if there's an error reading sensors
        }

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (!timestamp) {
            fprintf(stderr, "Error getting timestamp, exiting...\n");
            break; // Exit the loop if there's an error getting the timestamp
        }

        // Log the data to the file
        if (log_data(log_file, timestamp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            free(timestamp);
            break; // Exit the loop if there's an error logging data
        }

        free(timestamp); // Free the allocated memory for the timestamp

        // Wait for 50 milliseconds
        struct timespec delay = {0, 50000000}; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup (in case of error during the loop)
    signal_handler(SIGINT);

    return 0;
}

