#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIOCHIP "/dev/gpiochip4"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *touch_line = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(void);
int toggle_led(void);
int log_event(int led_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        perror("Error getting touch sensor line");
        goto err_chip;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        goto err_touch_line;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor");
    if (ret < 0) {
        perror("Error requesting touch sensor line as input");
        goto err_led_line;
    }

    ret = gpiod_line_request_output(led_line, "led", 0); // Initial state: off
    if (ret < 0) {
        perror("Error requesting LED line as output");
        goto err_touch_line_input;
    }

    return 0;

err_touch_line_input:
    gpiod_line_release(touch_line);
err_led_line:
    gpiod_line_release(led_line);
err_touch_line:
    gpiod_chip_close(chip);
err_chip:
    return -1;
}

// Read touch sensor value
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        perror("Error reading touch sensor value");
        return -1;
    }
    return value;
}

// Toggle LED state
int toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        perror("Error getting current LED value");
        return -1;
    }
    int new_value = !current_value;
    int ret = gpiod_line_set_value(led_line, new_value);
    if (ret < 0) {
        perror("Error setting LED value");
        return -1;
    }
    return new_value;
}

// Log event to file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s LED: %s\n", timestamp, led_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup GPIO resources
void cleanup(void) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int led_state;
    int touch_value;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            break;
        }

        if (touch_value == 1) {
            led_state = toggle_led();
            if (led_state < 0) {
                fprintf(stderr, "Error toggling LED, exiting.\n");
                break;
            }
            if (log_event(led_state) != 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
            // Debounce: Wait for a short period to avoid multiple triggers
            struct timespec delay = {0, 100000000}; // 100ms
            nanosleep(&delay, NULL);
        }

        // Small delay to avoid busy-waiting
        struct timespec sleep_time = {0, 10000000}; // 10ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Program finished.\n");
    return 0;
}

