#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200 // milliseconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a touch event to the file
void log_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging event.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open, not logging event.\n");
    }
    free(timestamp);
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    int result = gpioWrite(LED_PIN, !current_level);
    if (result != 0) {
        fprintf(stderr, "Error toggling LED: %d\n", result);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    int result = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting TOUCH_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting LED_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 1; // Initialize to released state
    unsigned long last_debounce_time = 0;

    // Main loop
    while (running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 0 && last_touch_state == 1) {
            // Rising edge detected
            unsigned long current_time = gpioTick();
            if (current_time - last_debounce_time > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
                toggle_led();
                log_touch_event();
                last_debounce_time = current_time;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

