// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", SENSOR1_GPIO);
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", SENSOR2_GPIO);
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR3_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", SENSOR3_GPIO);
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", gpio);
        return -1; // Indicate an error
    }
    return level;
}

// Function to log the state of a sensor
int log_state(int sensor_id, int state) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor%d: %s\n", timestamp, sensor_id, state == 0 ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
        free(timestamp);
        return 1;
    }
    free(timestamp);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    sensor_states_t current_states = {1, 1, 1}; // Initialize to magnet removed (high)
    sensor_states_t previous_states = {1, 1, 1};

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor, skipping this iteration\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Log state changes
        if (sensor1_state != previous_states.sensor1_state) {
            log_state(1, sensor1_state);
            current_states.sensor1_state = sensor1_state;
        }
        if (sensor2_state != previous_states.sensor2_state) {
            log_state(2, sensor2_state);
            current_states.sensor2_state = sensor2_state;
        }
        if (sensor3_state != previous_states.sensor3_state) {
            log_state(3, sensor3_state);
            current_states.sensor3_state = sensor3_state;
        }

        previous_states = current_states;

        gpioDelay(100); // Wait 100ms
    }

    // Close the log file and terminate pigpio (should not reach here if signal handler works)
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

