#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x03
#define AVG_REG 0x04
#define ENABLE_REG 0x05
#define HR_REG 0x2A
#define CSV_FILE "heart_rate.csv"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t led_current;
    uint8_t averaging;
    uint8_t enable;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int read_heart_rate(uint16_t *raw_hr);
float convert_to_bpm(uint16_t raw_hr);
float apply_moving_average(float bpm, float *history, int history_size, int *index);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

// Initialize the sensor
int initialize_sensor() {
    int retries = 0;
    int result;

    // Verify PART_ID
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (result >= 0) {
            if (result != 0x02) {
                fprintf(stderr, "Error: Invalid PART_ID: 0x%02X\n", result);
                return -1;
            }
            break;
        } else {
            fprintf(stderr, "Error reading PART_ID (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to read PART_ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Verify HW_REV
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, HW_REV_REG);
        if (result >= 0) {
            if (result != 0x01) {
                fprintf(stderr, "Error: Invalid HW_REV: 0x%02X\n", result);
                return -1;
            }
            break;
        } else {
            fprintf(stderr, "Error reading HW_REV (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to read HW_REV after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Configure sensor
    sensor_config_t config = {0x3F, 0x04, 0x01};
    uint8_t buf[3];

    buf[0] = LED_CURRENT_REG;
    buf[1] = config.led_current;
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, config.led_current);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing LED_CURRENT (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to write LED_CURRENT after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    buf[0] = AVG_REG;
    buf[1] = config.averaging;
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, AVG_REG, config.averaging);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing AVG (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to write AVG after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    buf[0] = ENABLE_REG;
    buf[1] = config.enable;
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, ENABLE_REG, config.enable);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing ENABLE (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to write ENABLE after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Read heart rate data
int read_heart_rate(uint16_t *raw_hr) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, HR_REG);
        if (result >= 0) {
            *raw_hr = (uint16_t)result;
            return 0;
        } else {
            fprintf(stderr, "Error reading HR (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Error: Failed to read HR after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Convert raw heart rate to BPM
float convert_to_bpm(uint16_t raw_hr) {
    return (float)raw_hr * 0.5;
}

// Apply moving average filter
float apply_moving_average(float bpm, float *history, int history_size, int *index) {
    float sum = 0.0;
    history[*index] = bpm;
    *index = (*index + 1) % history_size;

    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }

    return sum / history_size;
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= 30.0 && bpm <= 220.0);
}

// Log data to CSV file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Moving average filter variables
    float bpm_history[5] = {0.0}; // History of BPM values
    int history_index = 0;        // Current index in the history

    // Main loop
    uint16_t raw_hr;
    float bpm, filtered_bpm;

    while (!terminate) {
        // Read heart rate
        if (read_heart_rate(&raw_hr) == 0) {
            // Convert to BPM
            bpm = convert_to_bpm(raw_hr);

            // Apply moving average filter
            filtered_bpm = apply_moving_average(bpm, bpm_history, 5, &history_index);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                log_data(filtered_bpm);
                printf("BPM: %.2f\n", filtered_bpm);
            } else {
                fprintf(stderr, "Error: Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Error: Failed to read heart rate\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

