#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pins
#define NUM_CHANNELS 8
const int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
const int display_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[NUM_CHANNELS];
struct gpiod_line *display_lines[NUM_CHANNELS];
int counter = 0;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_channel(int channel);
void update_display(int value);
void log_touch_event(int channel, int counter);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a sensor channel
int read_sensor_channel(int channel) {
    int value;
    value = gpiod_line_get_value(sensor_lines[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor channel %d: %s\n", channel + 1, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to update the display
void update_display(int value) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int bit = (value >> i) & 1;
        int ret = gpiod_line_set_value(display_lines[i], bit);
        if (ret < 0) {
            fprintf(stderr, "Error setting display pin %d to %d: %s\n", display_pins[i], bit, strerror(errno));
        }
    }
}

// Function to log a touch event
void log_touch_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Warning: Log file not open. Using stdout for logging.\n");
    }

    printf("Touch on channel %d | Counter: %d\n", channel + 1, counter);
}

// Function to setup GPIO lines
int setup_gpio(void) {
    int i;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    // Get display lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        display_lines[i] = gpiod_chip_get_line(chip, display_pins[i]);
        if (!display_lines[i]) {
            fprintf(stderr, "Error getting display line %d: %s\n", display_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    // Request sensor lines as inputs
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    for (i = 0; i < NUM_CHANNELS; i++) {
        int ret = gpiod_line_request(sensor_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    // Request display lines as outputs
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    for (i = 0; i < NUM_CHANNELS; i++) {
        int ret = gpiod_line_request(display_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting display line %d: %s\n", display_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release display lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (display_lines[i]) {
            gpiod_line_release(display_lines[i]);
        }
    }

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i, prev_state[NUM_CHANNELS] = {0};
    struct timespec delay = {0, 10000000}; // 10 ms
    struct timespec stabilization_delay = {0, 200000000}; // 200 ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Could not open log file: %s\n", strerror(errno));
    }

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        if (log_file) fclose(log_file);
        return 1;
    }

    // Stabilization delay
    nanosleep(&stabilization_delay, NULL);

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int current_state = read_sensor_channel(i);
            if (current_state < 0) continue; // Skip on error

            if (current_state == 1 && prev_state[i] == 0) {
                // Rising edge detected
                counter = (counter + 1) % 256;
                update_display(counter);
                log_touch_event(i, counter);
            }
            prev_state[i] = current_state;
        }
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    if (log_file) fclose(log_file);
    return 0;
}

