#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for libgpiod resources
struct gpiod_chip *chip = NULL;
struct gpiod_line *line17 = NULL;
struct gpiod_line *line18 = NULL;
struct gpiod_line *line27 = NULL;
struct gpiod_line *line22 = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read the value of a sensor
int read_sensor(int pin) {
    struct gpiod_line *line = NULL;
    int value = -1; // Initialize to an invalid value

    if (pin == SENSOR1_PIN) {
        line = line17;
    } else if (pin == SENSOR2_PIN) {
        line = line18;
    } else if (pin == SENSOR3_PIN) {
        line = line27;
    } else if (pin == SENSOR4_PIN) {
        line = line22;
    } else {
        fprintf(stderr, "Error: Invalid sensor pin: %d\n", pin);
        return -1; // Indicate an error
    }

    if (line == NULL) {
        fprintf(stderr, "Error: GPIO line not initialized for pin %d\n", pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", pin, strerror(errno));
        return -1; // Indicate an error
    }

    return value;
}

// Function to log data to the CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Function to set up GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
