    line18 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line27 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    line22 = gpiod_chip_get_line(chip, SENSOR4_PIN);

    if (!line17 || !line18 || !line27 || !line22) {
        fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", SENSOR1_PIN, strerror(errno));
        fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", SENSOR2_PIN, strerror(errno));
        fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", SENSOR3_PIN, strerror(errno));
        fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", SENSOR4_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }

