    memset(&config, 0, sizeof(config));
    config.consumer = "tracking_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line17, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request(line18, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request(line27, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", SENSOR3_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request(line22, &config, 0) < 0) {
