#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for signal handling
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int control_led(struct gpiod_line *line, int state);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value;
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
int control_led(struct gpiod_line *line, int state) {
    int ret;
    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

int main() {
    int sensor1_value, sensor2_value, led_state;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get lines for sensors and LED
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting line for sensor 1 (GPIO%d): %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup_chip;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting line for sensor 2 (GPIO%d): %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup_sensor1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting line for LED (GPIO%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup_sensor2;
    }

    // Request lines for input and output
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor 1 line as input: %s\n", strerror(errno));
        goto cleanup_led;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor 2 line as input: %s\n", strerror(errno));
        goto cleanup_sensor1_input;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup_sensor2_input;
    }

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup_led_output;
    }

    // Main loop
    while (keep_running) {
        // Read sensor values
        sensor1_value = read_sensor(sensor1_line);
        sensor2_value = read_sensor(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break;
        }

        // Determine LED state
        led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        // Control LED
        if (control_led(led_line, led_state) < 0) {
            fprintf(stderr, "Error controlling LED, exiting.\n");
            break;
        }

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        // Wait 100ms
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&req, NULL);
    }

    // Cleanup
    fclose(log_file);

cleanup_led_output:
    gpiod_line_release(led_line);

cleanup_sensor2_input:
    gpiod_line_release(sensor2_line);

cleanup_sensor1_input:
    gpiod_line_release(sensor1_line);

cleanup_led:
    gpiod_chip_close(chip);

cleanup_sensor2:
    gpiod_chip_close(chip);

cleanup_sensor1:
    gpiod_chip_close(chip);

