#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling period (in microseconds)
#define SAMPLING_PERIOD 125

// Define LED on time (in milliseconds)
#define LED_ON_TIME 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read microphone input
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0)
        {
            fprintf(stderr, "Failed to read GPIO%d\n", MIC_PIN);
            break; // Exit loop on error
        }

        // Check for peak detection
        if (mic_value == 1)
        {
            // Get current timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);
            long long timestamp_ms = (long long)(tv.tv_sec) * 1000 + (long long)(tv.tv_usec) / 1000;

            // Print timestamp to stdout
            printf("%lld\n", timestamp_ms);

            // Turn LED on
            if (gpioWrite(LED_PIN, 1) != 0)
            {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }

            // Delay for LED on time
            gpioDelay(LED_ON_TIME * 1000); // Convert milliseconds to microseconds

            // Turn LED off
            if (gpioWrite(LED_PIN, 0) != 0)
            {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD);
    }

    // Clean up and terminate
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

