    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a register from the Si1175
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return value;
}

// Function to combine LSB and MSB into a 16-bit value
uint16_t combine_als_data(uint8_t lsb, uint8_t msb) {
    return (uint16_t)((msb << 8) | lsb);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus. Exiting.\n");
        return 1;
    }

    printf("I2C bus initialized successfully.\n");

    // Main loop to read and log data
    while (1) {
        // Read the LSB and MSB registers
        int lsb = read_register(i2c_fd, ALS_VIS_LSB);
        int msb = read_register(i2c_fd, ALS_VIS_MSB);

        if (lsb < 0 || msb < 0) {
            fprintf(stderr, "Error reading ALS data. Retrying in 100ms.\n");
            usleep(100000); // 100ms
            continue;
        }

        // Combine the data into a 16-bit value
        uint16_t als_value = combine_als_data((uint8_t)lsb, (uint8_t)msb);

        // Log the raw sensor value to the console
        printf("ALS Visible: %u\n", als_value);

        // Wait for 100ms
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(i2c_fd);
    return 0;
}

