#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins for each channel
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for libgpiod resources
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL};

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines as inputs
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        struct gpiod_line_request_config config;
        config.consumer = "ttp226_reader";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1000000000.0;

        // Read sensor values and log to console
        printf("[%.3fs] ", timestamp);
        for (int i = 0; i < num_channels; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Error reading GPIO line value");
                // Release resources before exiting
                for (int j = 0; j < num_channels; j++) {
                    if (lines[j] != NULL) {
                        gpiod_line_release(lines[j]);
                    }
                }
                gpiod_chip_close(chip);
                return 1;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Wait 200ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

