#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Number of steps in the fade
#define FADE_STEPS 50

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
}

// Function to convert HSV to RGB
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    if (s == 0.0) {
        *r = *g = *b = (int)(v * 255);
        return;
    }

    h = fmod(h, 360.0);
    h /= 60.0;
    int i = (int)h;
    float f = h - i;
    float p = v * (1 - s);
    float q = v * (1 - s * f);
    float t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        default: // case 5:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int r, int g, int b)
{
    // Invert the color values for common anode LED
    int red   = 255 - r;
    int green = 255 - g;
    int blue  = 255 - b;

    // Clamp the values to the range [0, 255]
    if (red   < 0) red   = 0;
    if (red   > 255) red   = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue  < 0) blue  = 0;
    if (blue  > 255) blue  = 255;

    // Set the PWM duty cycle for each color channel
    if (gpioPWM(RED_PIN, red) < 0) {
        syslog(LOG_ERR, "Failed to set PWM for red pin");
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        syslog(LOG_ERR, "Failed to set PWM for green pin");
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        syslog(LOG_ERR, "Failed to set PWM for blue pin");
    }
}

int main()
{
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(urandom);
        closelog();
        return 1;
    }
    fclose(urandom);
    srand(seed);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set mode for red pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set mode for green pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set mode for blue pin");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for red pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for green pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for blue pin");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM range (0-255)
    if (gpioSetPWMrange(RED_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for red pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for green pin");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for blue pin");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate random hue
        float hue = (float)(rand() % 360);

        // Convert HSV to RGB
        int r, g, b;
        hsv_to_rgb(hue, 1.0, 1.0, &r, &g, &b);

        // Fade to the new color
        for (int i = 0; i <= FADE_STEPS; i++) {
            // Calculate the intermediate hue
            float intermediate_hue = hue + (float)i * (360.0 / FADE_STEPS);
            if (intermediate_hue >= 360.0) {
                intermediate_hue -= 360.0;
            }

            // Convert intermediate HSV to RGB
            int intermediate_r, intermediate_g, intermediate_b;
            hsv_to_rgb(intermediate_hue, 1.0, 1.0, &intermediate_r, &intermediate_g, &intermediate_b);

            // Set the LED color
            set_led_color(intermediate_r, intermediate_g, intermediate_b);

            // Wait for a short time
            usleep(50000); // 50ms
        }
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

