#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_ID              (0x12)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// TCS34725 Commands
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_AIEN     (0x10)  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      (0x08)  // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN_WEN  (TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN | TCS34725_ENABLE_WEN)

// GPIO Pin for LED
#define LED_GPIO_PIN             (17)

// Sensor Initialization Values
#define TCS34725_ID_VALUE        (0x44)
#define TCS34725_ATIME_VALUE     (0xEB) // 154ms integration time
#define TCS34725_CONTROL_VALUE   (0x00) // 1x gain

// Calibration Parameters
#define RED_GAIN   1.0
#define RED_OFFSET 0.0
#define GREEN_GAIN 1.0
#define GREEN_OFFSET 0.0
#define BLUE_GAIN  1.0
#define BLUE_OFFSET 0.0
#define CLEAR_GAIN 1.0
#define CLEAR_OFFSET 0.0

// Red Threshold
#define RED_THRESHOLD 200

// Global Variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
int control_led(int gpio_pin, int state);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    uint8_t id;
    uint8_t enable;
    uint8_t atime;
    uint8_t control;

    // Verify Sensor ID
    if (read(fd, &id, 1) != 1) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    // Enable Power and RGBC
    enable = TCS34725_ENABLE_AEN_WEN;
    if (write(fd, &enable, 1) != 1) {
        fprintf(stderr, "Error writing to enable register: %s\n", strerror(errno));
        return -1;
    }

    // Set Integration Time
    atime = TCS34725_ATIME_VALUE;
    if (write(fd, &atime, 1) != 1) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set Gain
    control = TCS34725_CONTROL_VALUE;
    if (write(fd, &control, 1) != 1) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 Data Reading Function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    // Read all 8 bytes at once
    if (read(fd, data, 8) != 8) {
        fprintf(stderr, "Error reading data registers: %s\n", strerror(errno));
        return -1;
    }

    *clear = data[1] << 8 | data[0];
    *red   = data[3] << 8 | data[2];
    *green = data[5] << 8 | data[4];
    *blue  = data[7] << 8 | data[6];

    return 0;
}

// Data Calibration Function
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    *calibrated_clear = (float)clear * CLEAR_GAIN + CLEAR_OFFSET;
    *calibrated_red   = (float)red   * RED_GAIN   + RED_OFFSET;
    *calibrated_green = (float)green * GREEN_GAIN + GREEN_OFFSET;
    *calibrated_blue  = (float)blue  * BLUE_GAIN  + BLUE_OFFSET;
}

// LED Control Function
int control_led(int gpio_pin, int state) {
    int ret;

    ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    uint16_t clear, red, green, blue;
    float calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;
    int led_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed. Attempting re-initialization...\n");
        close(i2c_fd);
        sleep(1);
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
            fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }
        if (tcs34725_init(i2c_fd) < 0) {
            fprintf(stderr, "TCS34725 re-initialization failed.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "tcs34725", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading sensor data. Attempting re-initialization...\n");
            close(i2c_fd);
            sleep(1);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed.\n");
                terminate = 1;
                continue;
            }
            continue; // Skip to next iteration after re-initialization
        }

        // Calibrate data
        calibrate_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

        // Print calibrated values
        printf("C: %.2f, R: %.2f, G: %.2f, B: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

        // Control LED based on red value
        if (calibrated_red > RED_THRESHOLD) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        if (control_led(LED_GPIO_PIN, led_state) < 0) {
            terminate = 1; // Exit loop if LED control fails
        }

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    printf("Cleaning up resources...\n");

    // Turn off LED
    control_led(LED_GPIO_PIN, 0);

    // Release GPIO line
    gpiod_line_release(led_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    // Power down sensor (optional, but good practice)
    uint8_t enable = 0x00; // Disable all features
    if (write(i2c_fd, &enable, 1) != 1) {
        fprintf(stderr, "Error powering down sensor: %s\n", strerror(errno));
    }

    // Close I2C device
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

