            fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
            fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }
        if (tcs34725_init(i2c_fd) < 0) {
            fprintf(stderr, "TCS34725 re-initialization failed.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "tcs34725", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading sensor data. Attempting re-initialization...\n");
            close(i2c_fd);
            sleep(1);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed.\n");
                terminate = 1;
                continue;
            }
            continue; // Skip to next iteration after re-initialization
        }

        // Calibrate data
        calibrate_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

        // Print calibrated values
        printf("C: %.2f, R: %.2f, G: %.2f, B: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

        // Control LED based on red value
        if (calibrated_red > RED_THRESHOLD) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        if (control_led(LED_GPIO_PIN, led_state) < 0) {
            terminate = 1; // Exit loop if LED control fails
        }

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    printf("Cleaning up resources...\n");

    // Turn off LED
    control_led(LED_GPIO_PIN, 0);

    // Release GPIO line
    gpiod_line_release(led_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    // Power down sensor (optional, but good practice)
    uint8_t enable = 0x00; // Disable all features
    if (write(i2c_fd, &enable, 1) != 1) {
        fprintf(stderr, "Error powering down sensor: %s\n", strerror(errno));
    }

    // Close I2C device
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

