// Configuration
#define BH1750_ADDR 0x23
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void set_led_brightness(int brightness);
int map_lux_to_brightness(float lux);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error configuring BH1750\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(180000); // Wait 180ms

    return 0;
}

// Read light level from BH1750
int read_bh1750(float *lux) {
    char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            gpioDelay(10000); // Wait 10ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries\n");
    return -1; // Failure
}

// Set LED brightness using pigpio's wave functionality
void set_led_brightness(int brightness) {
    // WS2812B timing constants (in microseconds)
    const int T0H = 350;  // 0 bit: 350us high, 800us low
    const int T0L = 800;
    const int T1H = 700;  // 1 bit: 700us high, 600us low
    const int T1L = 600;
    const int RESET = 50000; // Reset pulse: 50us low, 50ms high

    // Calculate the number of bits needed to represent the brightness
    int bits_needed = (int)log2(brightness + 1) + 1; // log2(brightness) + 1
    if (bits_needed > 8) bits_needed = 8; // Limit to 8 bits

    // Create a bit pattern based on the brightness
    uint8_t bit_pattern = 0;
    for (int i = 0; i < bits_needed; i++) {
        bit_pattern |= (1 << i);
    }

    // Generate the WS2812B data stream
    gpioWaveClear();
    gpioPulse_t pulse[24]; // 24 pulses for 8 bits (24 LEDs)
    int pulse_index = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        uint8_t data = (i == 0) ? bit_pattern : 0; // Only the first LED is lit
        for (int j = 7; j >= 0; j--) {
            if ((data >> j) & 1) {
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T1H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T1L;
                pulse_index++;
            } else {
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T0H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T0L;
                pulse_index++;
            }
        }
    }

    // Add reset pulse
    pulse[pulse_index].gpioOn = 0;
    pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
    pulse[pulse_index].usDelay = RESET;
    pulse_index++;

    gpioWaveAddGeneric(pulse_index, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send the wave once
        while (gpioWaveTxBusy()) gpioDelay(100); // Wait for the wave to finish
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Map lux value to brightness (non-linear mapping)
int map_lux_to_brightness(float lux) {
    // Clamp lux value to a maximum of 1000
    if (lux > 1000) {
        lux = 1000;
    }

    // Use a logarithmic mapping
    float brightness_float = log10(lux + 1) / log10(1001) * 255; // Map 0-1000 lux to 0-255 brightness
    int brightness = (int)brightness_float;

    return brightness;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read light level
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);
        } else {
            fprintf(stderr, "Failed to read light level\n");
        }

        gpioDelay(100000); // Wait 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

