#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define NUM_LEDS 1
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int init_spi(const char *device);
int read_bh1750(int fd, float *lux);
int map_lux_to_brightness(float lux);
int send_apa102_frame(int fd, int brightness);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI
int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read BH1750 sensor
int read_bh1750(int fd, float *lux) {
    uint8_t cmd = 0x20; // One-Time High-Resolution Mode
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    usleep(120000); // Wait for conversion (120 ms)

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    *lux = (float)raw / 1.2;

    return 0;
}

// Map lux value to brightness (0-31)
int map_lux_to_brightness(float lux) {
    if (lux < 10) {
        return 0;
    } else if (lux > 300) {
        return 31;
    } else {
        return (int)((lux - 10) / 290 * 31);
    }
}

// Send APA102 frame
int send_apa102_frame(int fd, int brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led_frame[4];

    led_frame[0] = 0xE0 | brightness; // Global brightness
    led_frame[1] = 0x00; // Blue
    led_frame[2] = 0x00; // Green
    led_frame[3] = 0xFF; // Red

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)start_frame,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending start frame: %s\n", strerror(errno));
        return -1;
    }

    tr.tx_buf = (unsigned long)led_frame;
    tr.len = 4;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending LED frame: %s\n", strerror(errno));
        return -1;
    }

    tr.tx_buf = (unsigned long)end_frame;
    tr.len = 4;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending end frame: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    float lux;
    int brightness;

    while (!terminate) {
        // Read lux value
        if (read_bh1750(i2c_fd, &lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Send APA102 frame
            if (send_apa102_frame(spi_fd, brightness) != 0) {
                fprintf(stderr, "Error sending APA102 frame\n");
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Turn off LEDs (send zero brightness frame)
    send_apa102_frame(spi_fd, 0);

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

