#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 10
#define FADE_STEPS 500
#define FADE_DELAY_MS 2 // Adjust for smoother/faster fading

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c_sensors();
float read_bh1750(int handle);
float average_lux(float lux1, float lux2);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int brightness);
void fade_brightness(int target_brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize I2C sensors
int init_i2c_sensors() {
    i2c_handle_low = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_LOW, i2c_handle_low);
        i2c_handle_low = -1; // Ensure handle is invalid
    } else {
        if (i2cWriteByteData(i2c_handle_low, 0x00, BH1750_ONE_TIME_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error setting BH1750 mode for address 0x%02X: %d\n", BH1750_ADDR_LOW, i2c_handle_low);
            i2cClose(i2c_handle_low);
            i2c_handle_low = -1;
        }
    }

    i2c_handle_high = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_HIGH, i2c_handle_high);
        i2c_handle_high = -1; // Ensure handle is invalid
    } else {
        if (i2cWriteByteData(i2c_handle_high, 0x00, BH1750_ONE_TIME_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error setting BH1750 mode for address 0x%02X: %d\n", BH1750_ADDR_HIGH, i2c_handle_high);
            i2cClose(i2c_handle_high);
            i2c_handle_high = -1;
        }
    }

    return (i2c_handle_low >= 0 || i2c_handle_high >= 0) ? 0 : -1; // Return 0 if at least one sensor is initialized
}

// Read lux value from BH1750 sensor
float read_bh1750(int handle) {
    if (handle < 0) return -1.0; // Invalid handle

    int data = i2cReadWordData(handle, 0x00);
    if (data < 0) {
        fprintf(stderr, "Error reading BH1750 data: %d\n", data);
        return -1.0;
    }

    // BH1750 returns big-endian, pigpio returns little-endian
    data = ((data & 0xFF00) >> 8) | ((data & 0x00FF) << 8);

    return (float)data / 1.2; // Convert to lux
}

// Average lux readings from sensors
float average_lux(float lux1, float lux2) {
    int valid_count = 0;
    float sum = 0.0;

    if (lux1 >= 0.0) {
        sum += lux1;
        valid_count++;
    }
    if (lux2 >= 0.0) {
        sum += lux2;
        valid_count++;
    }

    if (valid_count == 0) {
        return 0.0; // No valid readings
    }

    return sum / valid_count;
}

// Map lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Inverse mapping: lower lux -> higher brightness
    // Adjust the max_lux value based on your environment
    float max_lux = 100.0; // Example maximum lux value
    int brightness = (int)(31.0 - (average_lux / max_lux) * 31.0);

    // Clamp the brightness value to the range 0-31
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;

    return brightness;
}

// Set APA102 strip brightness using hardware SPI
void set_apa102_brightness(int brightness) {
    // Start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, 4);

    // LED data (4 bytes per LED: 0xE0 | brightness, 0x00, 0x00, 0x00)
    char led_data[4];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[0] = 0xE0 | (brightness & 0x1F); // Global brightness
        led_data[1] = 0x00;
        led_data[2] = 0x00;
        led_data[3] = 0x00;
        spiWrite(spi_handle, led_data, 4);
    }

    // End frame (at least (NUM_LEDS + 1) / 2 bytes of 0xFF)
    int end_frame_size = (NUM_LEDS + 1) / 2;
    char end_frame[end_frame_size];
    for (int i = 0; i < end_frame_size; i++) {
        end_frame[i] = 0xFF;
    }
    spiWrite(spi_handle, end_frame, end_frame_size);
}

// Fade brightness smoothly
void fade_brightness(int target_brightness) {
    // Get the current brightness (assuming it's stored somewhere, e.g., a global variable)
    // For this example, let's assume we have a global variable 'current_brightness'
    // In a real application, you'd need to read the current brightness from the LED strip
    // or maintain it in a variable.
    int current_brightness = 0; // Initial brightness (example)

    int brightness_diff = target_brightness - current_brightness;
    int step_size = brightness_diff / FADE_STEPS;

    if (step_size == 0) {
        // No change needed, set brightness directly
        set_apa102_brightness(target_brightness);
        return;
    }

    for (int i = 0; i < FADE_STEPS; i++) {
        current_brightness += step_size;
        // Clamp the brightness value to the range 0-31
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;

        set_apa102_brightness(current_brightness);
        gpioDelay(FADE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Ensure the final brightness is exactly the target brightness
    set_apa102_brightness(target_brightness);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C sensors
    if (init_i2c_sensors() != 0) {
        fprintf(stderr, "Failed to initialize I2C sensors. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
        if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux values from sensors
        float lux1 = read_bh1750(i2c_handle_low);
        float lux2 = read_bh1750(i2c_handle_high);

        // Average lux readings
        float average_lux_value = average_lux(lux1, lux2);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux_value);

        // Fade brightness
        fade_brightness(target_brightness);

        // Delay
        gpioDelay(100 * 1000); // 100 ms
    }

    // Clean up resources before exiting
    set_apa102_brightness(0); // Turn off LEDs

    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

