#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define NUM_LEDS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables (to be cleaned up by signal handler)
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(const char *chip, int pin);
int veml7700_init(int fd);
int read_veml7700(int fd, uint16_t *als);
float calculate_lux(uint16_t raw_als);
uint8_t map_lux_to_brightness(float lux);
void set_led_brightness(struct gpiod_line *line, uint8_t brightness);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int init_gpio(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ws2812b";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// VEML7700 initialization function
int veml7700_init(int fd) {
    uint8_t config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Integration time 100ms, Gain 1/8
    config_data[2] = 0x00;

    if (write(fd, config_data, 3) != 3) {
        perror("Error writing to VEML7700 config register");
        return -1;
    }

    return 0;
}

// VEML7700 reading function
int read_veml7700(int fd, uint16_t *als) {
    uint8_t als_reg = ALS_REG;
    uint8_t data[2];

    if (write(fd, &als_reg, 1) != 1) {
        perror("Error writing to VEML7700 ALS register");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from VEML7700 ALS register");
        return -1;
    }

    *als = (data[1] << 8) | data[0];
    return 0;
}

// Lux calculation function
float calculate_lux(uint16_t raw_als) {
    return raw_als * 0.0288;
}

// Brightness mapping function
uint8_t map_lux_to_brightness(float lux) {
    float brightness_float = 255.0 * pow(lux / 120000.0, 1.0 / 2.2);
    if (brightness_float < 0.0) brightness_float = 0.0;
    if (brightness_float > 255.0) brightness_float = 255.0;
    return (uint8_t)brightness_float;
}

