    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        log_event("Program terminated by SIGINT");

        // Release GPIO lines
        if (flame_sensor_line) {
            gpiod_line_release(flame_sensor_line);
