    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, event);
}

// Self-test function
int self_test() {
    int i, flame_detected = 1;
    int value;

    log_event("Starting self-test...");

    // Blink LED twice (500ms on, 500ms off) with buzzer off
    for (i = 0; i < 2; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000); // 500ms
        gpiod_line_set_value(led_line, 0);
        usleep(500000); // 500ms
    }

