            gpiod_line_set_value(buzzer_line, 1);
            usleep(600000); // 600ms
            gpiod_line_set_value(buzzer_line, 0);
            usleep(200000); // 200ms
        }

        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    // Main loop
    while (1) {
        value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
