        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Send the continuous high-resolution mode command
    unsigned char command = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO pin
int init_gpio() {
    char buffer[64];
    int fd;

