#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for signal handling
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set a GPIO line value
int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to shift out data to the 74HC595
int shift_out(unsigned char data)
{
    for (int i = 7; i >= 0; i--) {
        if (set_gpio_value(data_line, (data >> i) & 1) < 0) {
            return -1;
        }
        if (set_gpio_value(clock_line, 1) < 0) {
            return -1;
        }
        if (set_gpio_value(clock_line, 0) < 0) {
            return -1;
        }
    }
    return 0;
}

// Function to display the digit '5'
int display_five()
{
    // Define the segment pattern for '5' (common cathode)
    unsigned char five_pattern = 0b00111000; // a,b,c,f,g

    if (shift_out(five_pattern) < 0) {
        return -1;
    }

    if (set_gpio_value(latch_line, 1) < 0) {
        return -1;
    }
    if (set_gpio_value(latch_line, 0) < 0) {
        return -1;
    }

    return 0;
}

// Function to clear the display
int clear_display()
{
    // Send all zeros to clear the display
    unsigned char clear_pattern = 0b00000000;

    if (shift_out(clear_pattern) < 0) {
        return -1;
    }

    if (set_gpio_value(latch_line, 1) < 0) {
        return -1;
    }
    if (set_gpio_value(latch_line, 0) < 0) {
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return 1;
    }

    // Get the GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        if (data_line) gpiod_line_release(data_line);
        if (clock_line) gpiod_line_release(clock_line);
        if (latch_line) gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(data_line, "five_display", 0) < 0) {
        fprintf(stderr, "Error requesting data line for output\n");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(clock_line, "five_display", 0) < 0) {
        fprintf(stderr, "Error requesting clock line for output\n");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "five_display", 0) < 0) {
        fprintf(stderr, "Error requesting latch line for output\n");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Display '5'
        if (display_five() < 0) {
            fprintf(stderr, "Error displaying '5'\n");
            break;
        }

        // Wait for 500ms
        struct timespec sleep_time = {0, 500000000}; // 500ms
        nanosleep(&sleep_time, NULL);

        // Clear the display
        if (clear_display() < 0) {
            fprintf(stderr, "Error clearing display\n");
            break;
        }

        // Wait for 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

