#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main()
{
    int ret;
    struct timespec sleep_time;
    char timestamp[20];

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (Button)");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return 1;
    }

    // Request LED line as output
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return 1;
    }

    // Request button line as input with pull-up and falling edge event detection
    ret = gpiod_line_request_rising_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (on)");
            break;
        }

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Check for button press
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(button_line, &sleep_time);
        if (ret > 0) {
            // Button pressed, get timestamp
            get_timestamp(timestamp);

            // Print timestamp message
            printf("%s: Button pressed, stopping blink.\n", timestamp);

            // Turn LED off
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value (off)");
                break;
            }

            break; // Exit the loop
        } else if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (off)");
            break;
        }

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

