#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("SIGINT received, exiting gracefully.\n");
    }
}

int main() {
    int result;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO5 as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    /* Register signal handler for SIGINT */
    signal(SIGINT, signal_handler);

    printf("LED blinking started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        /* Turn LED on */
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750000); // 750 ms

        /* Turn LED off */
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000); // 750 ms
    }

    /* Clean up and exit */
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

