            fprintf(stderr, "Error setting line value to HIGH: %s\n", strerror(errno));
            return -1;
        }
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = PWM_STEP * 1000000000; // Convert seconds to nanoseconds
        clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL);
    }

    // Set the line value to LOW for the remaining duration
    for (int i = 0; i < low_steps; i++) {
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting line value to LOW: %s\n", strerror(errno));
            return -1;
        }
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = PWM_STEP * 1000000000; // Convert seconds to nanoseconds
        clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL);
    }

    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        if (red_line) gpiod_line_release(red_line);
        if (green_line) gpiod_line_release(green_line);
        if (blue_line) gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random RGB values
        int red_value = rand() % 101;
        int green_value = rand() % 101;
        int blue_value = rand() % 101;

        // Set duty cycles
        if (set_duty_cycle(red_line, red_value) < 0 ||
            set_duty_cycle(green_line, green_value) < 0 ||
            set_duty_cycle(blue_line, blue_value) < 0) {
            fprintf(stderr, "Error setting duty cycle, exiting...\n");
            break;
        }

        // Wait 100 ms
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = 100000000; // 100 ms
        clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    return 1;
