#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void handle_impact(int16_t x, int16_t y, int16_t z, double magnitude);
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x, y, z;
    double magnitude;
} sensor_data_t;

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&sensor_data.x, &sensor_data.y, &sensor_data.z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        sensor_data.magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

        // Check for impact
        if (sensor_data.magnitude > threshold) {
            handle_impact(sensor_data.x, sensor_data.y, sensor_data.z, sensor_data.magnitude);
        }

        // Log data
        log_data(sensor_data.x, sensor_data.y, sensor_data.z, sensor_data.magnitude);

        // Delay for 10 Hz sampling rate
        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    return 0;
}

// Initialize sensor
int init_sensor() {
    // Enable all axes, 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return 1;
    }

    // 2G full-scale, sensitivity 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return 1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Handle impact
void handle_impact(int16_t x, int16_t y, int16_t z, double magnitude) {
    gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    gpioDelay(50000);       // Wait 50 ms
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
}

// Log data
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

