#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define RED_MSB_REG 0x67
#define GREEN_LSB_REG 0x68
#define GREEN_MSB_REG 0x69
#define BLUE_LSB_REG 0x6A
#define BLUE_MSB_REG 0x6B
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
int set_led_brightness(uint16_t als);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, MODE_REG, 0x01) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing sensor: %s\n", strerror(errno));
            gpioDelay(100); // Wait 100ms
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buffer, 8) == 8) {
            *als = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
            *red = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
            *green = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];
            *blue = (uint16_t)buffer[7] << 8 | (uint16_t)buffer[6];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            gpioDelay(100); // Wait 100ms
            retries--;
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Function to set LED brightness using PWM
int set_led_brightness(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als / 65535.0) * 255.0);
    gpioPWM(LED_GPIO, duty_cycle);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    fflush(log_file);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue);
            set_led_brightness(sensor_data.als);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

