#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FXOS8700CQ_ADDRESS 0x1F
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define SENSITIVITY 4096.0f // Counts per g for +/- 2g range
#define GRAVITY 9.81f       // m/s^2
#define IMPACT_THRESHOLD 19.62f // m/s^2
#define SAMPLE_RATE 50 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the FXOS8700CQ sensor
int initialize_sensor() {
    int status;
    char buf[2];

    // Verify WHO_AM_I register
    buf[0] = WHO_AM_I_REG;
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register: %d\n", status);
        return -1;
    }

    char who_am_i;
    status = i2cReadDevice(i2c_handle, &who_am_i, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    buf[0] = CTRL_REG1;
    buf[1] = 0x00; // Clear active mode bit
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error setting standby mode: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Configure accelerometer range to +/- 2g
    buf[0] = XYZ_DATA_CFG;
    buf[1] = 0x00; // +/- 2g range
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error configuring accelerometer range: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Activate the sensor (active mode, 200 Hz ODR)
    buf[0] = CTRL_REG1;
    buf[1] = 0x01; // Active mode, 200 Hz ODR
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error activating sensor: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Reads acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buf[1];
    char data[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    // Read 6 bytes of acceleration data
    buf[0] = OUT_X_MSB;
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to OUT_X_MSB register: %d\n", status);
        return -1;
    }

    status = i2cReadDevice(i2c_handle, data, 6);
    if (status != 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2, and convert to g
    raw_x = (int16_t)((data[0] << 8) | data[1]) >> 2;
    raw_y = (int16_t)((data[2] << 8) | data[3]) >> 2;
    raw_z = (int16_t)((data[4] << 8) | data[5]) >> 2;

    *x = (float)raw_x / SENSITIVITY * GRAVITY;
    *y = (float)raw_y / SENSITIVITY * GRAVITY;
    *z = (float)raw_z / SENSITIVITY * GRAVITY;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Logs impact data to a file
void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main() {
    float x, y, z, magnitude;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing...\n");
        }

        gpioDelay(SAMPLE_RATE * 1000); // Delay for 50ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

