#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/time.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDRESS 0x69

// Define register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Define sensitivity
#define SENSITIVITY 0.00875

// Define calibration samples
#define CALIBRATION_SAMPLES 100

// Define maximum angular velocity
#define MAX_ANGULAR_VELOCITY 50.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int gyro_init(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_gyro(int fd);
void log_data(float x, float y, float z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Gyroscope not found (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled, 100 Hz ODR)
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read 6 bytes of data starting from OUT_X_L
    if (write(fd, (uint8_t[]){OUT_X_L}, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine low and high bytes to form 16-bit signed values
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate the gyroscope
void calibrate_gyro(int fd) {
    int16_t x, y, z;
    long x_sum = 0, y_sum = 0, z_sum = 0;

    printf("Calibrating gyroscope...\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading gyroscope data during calibration\n");
            return;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(10000); // 10 ms delay
    }

    x_offset = (float)x_sum / CALIBRATION_SAMPLES * SENSITIVITY;
    y_offset = (float)y_sum / CALIBRATION_SAMPLES * SENSITIVITY;
    z_offset = (float)z_sum / CALIBRATION_SAMPLES * SENSITIVITY;

    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n", x_offset, y_offset, z_offset);
}

// Function to log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timeval tv;

    gettimeofday(&tv, NULL);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", tv.tv_usec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);

    if (fabs(x) > MAX_ANGULAR_VELOCITY || fabs(y) > MAX_ANGULAR_VELOCITY || fabs(z) > MAX_ANGULAR_VELOCITY) {
        fprintf(stderr, "WARNING: Angular velocity exceeds threshold!\n");
        fprintf(log_file, "%s,ALERT,Angular velocity exceeds threshold: X=%.3f, Y=%.3f, Z=%.3f\n", timestamp, x, y, z);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

int main() {
    int16_t x, y, z;
    float x_dps, y_dps, z_dps;
    struct timespec sleep_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    calibrate_gyro(i2c_fd);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 50 ms

    while (!stop_flag) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Convert to degrees per second
            x_dps = (float)x * SENSITIVITY - x_offset;
            y_dps = (float)y * SENSITIVITY - y_offset;
            z_dps = (float)z * SENSITIVITY - z_offset;

            // Log data
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Sleep for 50 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

