#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_DATAX0 0x32
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31

// LED GPIO pin
#define LED_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Verify DEVID
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format: full resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error setting data format\n");
        return -1;
    }

    // Set power control: measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error setting power control\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int result = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to g units
    *x = ((int16_t)((raw_data[1] << 8) | raw_data[0])) * 0.0039; // 3.9 mg/LSB
    *y = ((int16_t)((raw_data[3] << 8) | raw_data[2])) * 0.0039;
    *z = ((int16_t)((raw_data[5] << 8) | raw_data[4])) * 0.0039;

    return 0;
}

// Function to log data to file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", now, x, y, z);
    fflush(log_file); // Ensure data is written immediately
}

// Function to control the LED
void control_led(float x, float y, float z) {
    if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }
        gpioDelay(100); // 10 Hz sampling rate
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

