// Sensor I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// Accelerometer registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28

// Magnetometer registers
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03

// Scaling factors
#define ACCEL_SCALE 0.001 // 1 mg = 0.001 g
#define MAG_SCALE 0.001   // 1 mGauss = 0.001 Gauss

// Global variables for I2C handles and log file
int accel_handle = -1;
int mag_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_accelerometer(int handle);
int init_magnetometer(int handle);
int read_accelerometer_data(int handle, float *x, float *y, float *z);
int read_magnetometer_data(int handle, float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y);
void log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer I2C device: %d\n", accel_handle);
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer I2C device: %d\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer(accel_handle) != 0) {
        fprintf(stderr, "Accelerometer initialization failed\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

