    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_accelerometer_data(accel_handle, &sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        if (read_magnetometer_data(mag_handle, &sensor_data.mag_x, &sensor_data.mag_y, &sensor_data.mag_z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Calculate heading
        sensor_data.heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y);

        // Log data
        log_data(log_file, sensor_data.heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

// Initialize accelerometer
int init_accelerometer(int handle) {
    int status = i2cWriteByteData(handle, CTRL_REG1_A, 0x27); // 50 Hz, all axes enabled
    if (status < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A: %d\n", status);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer(int handle) {
    int status = i2cWriteByteData(handle, MR_REG_M, 0x00); // Continuous-conversion mode
    if (status < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M: %d\n", status);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buffer, 6); // Read 6 bytes with auto-increment
    if (status < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) * ACCEL_SCALE;
    *y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) * ACCEL_SCALE;
    *z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) * ACCEL_SCALE;

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(handle, OUT_X_H_M, buffer, 6); // Read 6 bytes
    if (status < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to Gauss
    *x = (float)((int16_t)((buffer[0] << 8) | buffer[1])) * MAG_SCALE;
    *y = (float)((int16_t)((buffer[2] << 8) | buffer[3])) * MAG_SCALE;
    *z = (float)((int16_t)((buffer[4] << 8) | buffer[5])) * MAG_SCALE;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float cosRoll = cos(roll);
    float sinRoll = sin(roll);
    float cosPitch = cos(pitch);
    float sinPitch = sin(pitch);

    float x_h = mag_x * cosPitch + mag_z * sinPitch;
    float y_h = mag_x * sinRoll * sinPitch + mag_y * cosRoll - mag_z * sinRoll * cosPitch;

    float heading = atan2(y_h, x_h) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

