}

// VL6180X initialization function
int vl6180x_init() {
    int status;

    // Required by datasheet
    status = i2cWriteByteData(i2c_handle, 0x0207, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0207: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0208, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0208: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0096, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0096: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0097, 0xfd);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0097: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00e3, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00e3: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00e4, 0x04);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00e4: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00e5, 0x02);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00e5: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00e6, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00e6: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00e7, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00e7: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00f5, 0x02);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00f5: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00d9, 0x05);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00d9: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00db, 0xce);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00db: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00dc, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00dc: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00dd, 0xf8);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00dd: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x009f, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x009f: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00a3, 0x3c);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00a3: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00b7, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00b7: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00bb, 0x3c);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00bb: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00b2, 0x09);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00b2: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00ca, 0x09);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00ca: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0198, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0198: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x01b0, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x01b0: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x01ad, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x01ad: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x00ff, 0x05);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x00ff: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0100, 0x05);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0100: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0199, 0x05);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0199: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x01a6, 0x1b);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x01a6: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x01ac, 0x3e);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x01ac: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x01a7, 0x1f);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x01a7: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0030, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0030: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance from VL6180X
int read_distance() {
    int distance = -1;
    int status;

    // Start a range measurement
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting range measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10000); // 10ms

    // Read the range value
    distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading range value: %d\n", distance);
        return -1;
    }

    // Clear interrupt
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CLEAR, 0x07);
    if (status < 0) {
        fprintf(stderr, "Error clearing interrupt: %d\n", status);
        return -1;
    }

    return distance;
}

// Function to log data to file
void log_data(int distance, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm, Status: %s\n", timestamp, distance, status);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int distance;
    const char *status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (vl6180x_init() != 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();

        if (distance >= 0) {
            if (distance < 100) {
                status = "DOOR_OPEN";
            } else {
                status = "DOOR_CLOSED";
            }
            log_data(distance, status);
        } else {
            fprintf(stderr, "Error reading distance, attempting re-initialization...\n");
            log_data(-1, "ERROR");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initialization
            i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit if re-initialization fails
            } else {
                if (vl6180x_init() != 0) {
                    fprintf(stderr, "VL6180X re-initialization failed\n");
                    terminate = 1; // Exit if re-initialization fails
                }
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

