#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define register addresses
#define CONTROL_REG 0x00
#define DATA_REG 0x01

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 10

// Define I2C bus
#define I2C_BUS 1

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int16_t read_sensor_data(int i2c_handle);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, int16_t tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    int result;

    // Write 0x80 to the control register to enable continuous measurement
    result = i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80);
    if (result != 0) {
        fprintf(stderr, "Error writing to control register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read data from a sensor
int16_t read_sensor_data(int i2c_handle) {
    int result;
    int16_t data;

    // Read 16-bit data from the data register
    result = i2cReadWordData(i2c_handle, DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return 0; // Return 0 on error
    }

    data = (int16_t)result; // Cast to signed 16-bit integer

    return data;
}

// Function to log data to a file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, int16_t tdoa) {
    int result;

    // Write data to the log file in CSV format
    result = fprintf(fp, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    struct timespec ts;
    int16_t sensor1_data, sensor2_data, tdoa;
    int retry_count;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize both sensors
    if (initialize_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue; // Skip to the next iteration
        }

        // Read data from sensor 1 with retry
        retry_count = 0;
        do {
            sensor1_data = read_sensor_data(i2c_handle1);
            if (sensor1_data == 0 && retry_count < 3) {
                fprintf(stderr, "Error reading sensor 1 data, retrying...\n");
                gpioDelay(1000); // Wait 1 ms before retrying
                retry_count++;
            } else {
                break; // Exit retry loop if data is valid or max retries reached
            }
        } while (retry_count < 3);

        // Read data from sensor 2 with retry
        retry_count = 0;
        do {
            sensor2_data = read_sensor_data(i2c_handle2);
            if (sensor2_data == 0 && retry_count < 3) {
                fprintf(stderr, "Error reading sensor 2 data, retrying...\n");
                gpioDelay(1000); // Wait 1 ms before retrying
                retry_count++;
            } else {
                break; // Exit retry loop if data is valid or max retries reached
            }
        } while (retry_count < 3);

        // Calculate TDOA
        tdoa = sensor1_data - sensor2_data;

        // Log data to file
        if (log_data(log_file, ts, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000); // Convert ms to us
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

