#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scale Factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_3

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int read_register(uint8_t reg_addr, uint16_t *data);
int write_register(uint8_t reg_addr, uint16_t data);
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accl_x, float *accl_y, float *accl_z);
void log_data(float gyro_x, float gyro_y, float gyro_z, float accl_x, float accl_y, float accl_z);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP_SELECT);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adis16448_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read Register
int read_register(uint8_t reg_addr, uint16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer tr;

    // Set CS low
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    // Prepare transmit buffer (register address with MSB set)
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    // Prepare transmit buffer for reading data
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    // Set CS high
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buf[1] << 8) | rx_buf[0];

    return 0;
}

// Write Register
int write_register(uint8_t reg_addr, uint16_t data) {
    uint8_t tx_buf[2];
    struct spi_ioc_transfer tr;

    // Set CS low
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    // Prepare transmit buffer (register address with MSB clear)
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = data & 0xFF; //LSB

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = 0; // Dummy receive
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    tx_buf[1] = (data >> 8) & 0xFF; //MSB

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = 0; // Dummy receive
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    // Set CS high
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return 0;
}

// Read IMU Data
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accl_x, float *accl_y, float *accl_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accl_x, raw_accl_y, raw_accl_z;

    if (read_register(XGYRO_OUT, &raw_gyro_x) != 0) {
        fprintf(stderr, "Error reading XGYRO_OUT\n");
        *gyro_x = 0.0;
    } else {
        *gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SCALE;
    }

    if (read_register(YGYRO_OUT, &raw_gyro_y) != 0) {
        fprintf(stderr, "Error reading YGYRO_OUT\n");
        *gyro_y = 0.0;
    } else {
        *gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SCALE;
    }

    if (read_register(ZGYRO_OUT, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading ZGYRO_OUT\n");
        *gyro_z = 0.0;
    } else {
        *gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SCALE;
    }

    if (read_register(XACCL_OUT, &raw_accl_x) != 0) {
        fprintf(stderr, "Error reading XACCL_OUT\n");
        *accl_x = 0.0;
    } else {
        *accl_x = (float)((int16_t)raw_accl_x) * ACCL_SCALE;
    }

    if (read_register(YACCL_OUT, &raw_accl_y) != 0) {
        fprintf(stderr, "Error reading YACCL_OUT\n");
        *accl_y = 0.0;
    } else {
        *accl_y = (float)((int16_t)raw_accl_y) * ACCL_SCALE;
    }

    if (read_register(ZACCL_OUT, &raw_accl_z) != 0) {
        fprintf(stderr, "Error reading ZACCL_OUT\n");
        *accl_z = 0.0;
    } else {
        *accl_z = (float)((int16_t)raw_accl_z) * ACCL_SCALE;
    }
}

// Log Data
void log_data(float gyro_x, float gyro_y, float gyro_z, float accl_x, float accl_y, float accl_z) {
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
           gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    float gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    // Main loop
    while (!terminate) {
        read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accl_x, &accl_y, &accl_z);
        log_data(gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

