#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    uint8_t who_am_i;
    int retries = 3;

    // Verify sensor presence
    while (retries > 0) {
        if (i2c_read_byte(fd, WHO_AM_I, &who_am_i) == 0) {
            if (who_am_i == 0x86) {
                printf("MPU-6886 found!\n");
                break;
            } else {
                fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x86\n", who_am_i);
                return -1;
            }
        } else {
            fprintf(stderr, "WHO_AM_I read failed, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "WHO_AM_I read failed after multiple retries\n");
        return -1;
    }

    // Wake up the MPU-6886
    retries = 3;
    while (retries > 0) {
        if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) == 0) {
            break;
        } else {
            fprintf(stderr, "PWR_MGMT_1 write failed, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "PWR_MGMT_1 write failed after multiple retries\n");
        return -1;
    }

    // Configure accelerometer range to +-2g
    retries = 3;
    while (retries > 0) {
        if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) == 0) {
            break;
        } else {
            fprintf(stderr, "ACCEL_CONFIG write failed, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "ACCEL_CONFIG write failed after multiple retries\n");
        return -1;
    }

    // Configure gyroscope range to +-250 dps
    retries = 3;
    while (retries > 0) {
        if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) == 0) {
            break;
        } else {
            fprintf(stderr, "GYRO_CONFIG write failed, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "GYRO_CONFIG write failed after multiple retries\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6886_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[12];
    int retries = 3;

    while (retries > 0) {
        if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 12) == 0) {
            // Combine high and low bytes for accelerometer data
            *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
            *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
            *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

            // Combine high and low bytes for gyroscope data
            *gyro_x = (int16_t)((buf[6] << 8) | buf[7]);
            *gyro_y = (int16_t)((buf[8] << 8) | buf[9]);
            *gyro_z = (int16_t)((buf[10] << 8) | buf[11]);

            return 0; // Success
        } else {
            fprintf(stderr, "MPU6886 data read failed, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "MPU6886 data read failed after multiple retries\n");
    return -1; // Failure
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (1) {
        // Read MPU-6886 data
        if (read_mpu6886_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print raw data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU-6886 data\n");
        }

        // Delay for 50ms
        usleep(50000);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

