#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

// GPIO pin for the red LED
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Scale factor for full resolution mode (+/- 2g range)
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// ADXL345 initialization function
int adxl345_init() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format register for full resolution and +-2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B); // Full resolution, +-2g
    if (status < 0) {
        fprintf(stderr, "Error writing to data format register: %d\n", status);
        return -1;
    }

    // Set bandwidth rate register
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0F); // 3200 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to bandwidth rate register: %d\n", status);
        return -1;
    }

    // Set power control register to start measurement
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08); // Measurement mode
    if (status < 0) {
        fprintf(stderr, "Error writing to power control register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SCALE_FACTOR;
    float y_g = (float)y / SCALE_FACTOR;
    float z_g = (float)z / SCALE_FACTOR;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log impact data to a file
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n", timestamp, magnitude, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                gpioWrite(LED_PIN, 1);
                gpioDelay(500); // 500 ms
                gpioWrite(LED_PIN, 0);

                // Log impact data
                log_impact(magnitude, x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

