#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

// Accelerometer and gyroscope data registers
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Sensitivity scales
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE 131.0f    // +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU (PWR_MGMT_1 = 0x00)\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 dps)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[14];

    // Read accelerometer and gyroscope data in a single burst
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope data
    data->gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    data->gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    data->gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    // Convert raw values to g and dps
    float accel_x_g = (float)data.accel_x / ACCEL_SCALE;
    float accel_y_g = (float)data.accel_y / ACCEL_SCALE;
    float accel_z_g = (float)data.accel_z / ACCEL_SCALE;
    float gyro_x_dps = (float)data.gyro_x / GYRO_SCALE;
