#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

// Accelerometer and gyroscope data registers
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Sensitivity scales
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE 131.0f    // +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU (PWR_MGMT_1 = 0x00)\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

