#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Configuration
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO 17
#define ACCEL_RANGE 2.0f // +/- 2g
#define ACCEL_SENSITIVITY 1024.0f // Counts per g
#define IMPACT_THRESHOLD 2.0f // g
#define IMPACT_DURATION 500 // ms
#define LOG_FILE "impact_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mma8451q(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
bool detect_impact(float x, float y, float z);
int control_led(struct gpiod_line *line, int on);
int log_impact(const char *filename);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// MMA8451Q initialization function
int init_mma8451q(int fd) {
    // Verify sensor ID
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    printf("MMA8451Q WHO_AM_I: 0x%02X\n", who_am_i);

    // Set to active mode, 100 Hz data rate
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = i2c_read_reg(fd, OUT_X_MSB);
    x_lsb = i2c_read_reg(fd, OUT_X_LSB);
    y_msb = i2c_read_reg(fd, OUT_Y_MSB);
    y_lsb = i2c_read_reg(fd, OUT_Y_LSB);
    z_msb = i2c_read_reg(fd, OUT_Z_MSB);
    z_lsb = i2c_read_reg(fd, OUT_Z_LSB);

    if (x_msb == -1 || x_lsb == -1 || y_msb == -1 || y_lsb == -1 || z_msb == -1 || z_lsb == -1) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((x_msb << 8) | x_lsb) >> 4;
    raw_y = (int16_t)((y_msb << 8) | y_lsb) >> 4;
    raw_z = (int16_t)((z_msb << 8) | z_lsb) >> 4;

    *x = (float)raw_x / ACCEL_SENSITIVITY * ACCEL_RANGE;
    *y = (float)raw_y / ACCEL_SENSITIVITY * ACCEL_RANGE;
    *z = (float)raw_z / ACCEL_SENSITIVITY * ACCEL_RANGE;

    return 0;
}

// Impact detection function
bool detect_impact(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    return (magnitude > IMPACT_THRESHOLD);
}

// LED control function
int control_led(struct gpiod_line *line, int on) {
    int ret;
    if (on) {
        ret = gpiod_line_set_value(line, 1);
    } else {
        ret = gpiod_line_set_value(line, 0);
    }
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// Log impact function
int log_impact(const char *filename) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "%s: Impact detected\n", timestamp);
    fclose(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q(i2c_fd) != 0) {
        fprintf(stderr, "MMA8451Q initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "impact_detector", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    float x, y, z;

    printf("Starting impact detection...\n");

    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (detect_impact(x, y, z)) {
                printf("Impact detected!\n");
                if (control_led(gpio_line, 1) == 0) {
                    usleep(IMPACT_DURATION * 1000); // 500ms
                    control_led(gpio_line, 0);
                }
                log_impact(LOG_FILE);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }
        usleep(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    printf("Exiting.\n");
    return 0;
}

