#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define FREEFALL_THRESHOLD 0.3 // 300 mg
#define FREEFALL_DURATION 0.1  // 100 ms
#define LOG_FILE "freefall_log.csv"

// ADXL345 Registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int gpio_request_line(struct gpiod_chip *chip, int pin);
int gpio_set_edge(struct gpiod_line *line, const char *edge);
int gpio_get_value(struct gpiod_line *line);
int adxl345_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// I2C helper functions
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C block read failed");
        return -1;
    }
    return 0;
}

// GPIO helper functions
int gpio_request_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }
    if (gpiod_line_request(line, "freefall", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        return -1;
    }
    return 0;
}

int gpio_set_edge(struct gpiod_line *line, const char *edge) {
    if (gpiod_line_set_edge(line, edge) < 0) {
        perror("Failed to set GPIO edge");
        return -1;
    }
    return 0;
}

int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to get GPIO value");
        return -1;
    }
    return value;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    uint8_t devid;

    // Verify device ID
    if (i2c_read_byte(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set freefall threshold
    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, (uint8_t)(FREEFALL_THRESHOLD * 100)) < 0) {
        fprintf(stderr, "Failed to set freefall threshold\n");
        return -1;
    }

    // Set freefall duration
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, (uint8_t)(FREEFALL_DURATION * 10)) < 0) {
        fprintf(stderr, "Failed to set freefall duration\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x04) < 0) {
        fprintf(stderr, "Failed to enable freefall interrupt\n");
        return -1;
    }

    // Map interrupt to INT1
    if (i2c_write_byte(fd, ADXL345_REG_INT_MAP, 0x00) < 0) {
        fprintf(stderr, "Failed to map interrupt to INT1\n");
        return -1;
    }

    // Enter measurement mode
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to enter measurement mode\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2c_read_block(fd, ADXL345_REG_DATAX0, data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g-force units (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d.%03ld,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, milliseconds,
            x, y, z);
    fflush(fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int gpio_fd;
    struct gpiod_line_event event;
    float x, y, z;
    uint8_t int_source;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request(gpio_line, "freefall", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO edge to falling
    if (gpiod_line_set_edge(gpio_line, "falling") < 0) {
        perror("Failed to set GPIO edge");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (!terminate) {
        // Read GPIO value (not strictly necessary with gpiod_line_event, but good practice)
        int gpio_value = gpiod_line_get_value(gpio_line);
        if (gpio_value < 0) {
            perror("Failed to get GPIO value");
            break;
        }

        // Wait for falling edge
        if (gpiod_line_event_wait(gpio_line, NULL) < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        // Read INT_SOURCE register
        if (i2c_read_byte(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) < 0) {
            fprintf(stderr, "Failed to read INT_SOURCE\n");
            break;
        }

        // Check if freefall bit is set
        if (int_source & 0x04) {
            // Read acceleration data
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                // Log data
                log_data(log_file, x, y, z);
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

