#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // +/- 2g
#define GYRO_RANGE 250.0f // +/- 250 dps

// ODR and data rate
#define ODR 104 // Hz

// Freefall and impact thresholds
#define FREEFALL_THRESHOLD 0.2f  // g
#define IMPACT_THRESHOLD 2.5f    // g
#define TIME_WINDOW 1.0f         // seconds

// Scaling factors
#define ACCEL_SCALE (ACCEL_RANGE / 32768.0f)
#define GYRO_SCALE (GYRO_RANGE / 32768.0f)

// State machine states
enum State {
    IDLE,
    FREEFALL,
    IMPACT
};

// Global variables
int i2c_handle;
FILE *log_file;
enum State current_state = IDLE;
time_t freefall_start_time = 0;
time_t impact_start_time = 0;

// Function prototypes
int init_lsm6dsr();
int read_accel_data(float *x, float *y, float *z);
int read_gyro_data(float *x, float *y, float *z);
float calculate_acceleration_magnitude(float x, float y, float z);
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void update_state_machine(float acceleration_magnitude);
void signal_handler(int signal);

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x50) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x50) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_acceleration_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Function to log data to a file
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file);
}

// Function to update the state machine
void update_state_machine(float acceleration_magnitude) {
    time_t now = time(NULL);

    switch (current_state) {
        case IDLE:
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                current_state = FREEFALL;
                freefall_start_time = now;
                printf("State: FREEFALL\n");
            }
            break;
        case FREEFALL:
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                current_state = IMPACT;
                impact_start_time = now;
                printf("State: IMPACT\n");
            } else if (difftime(now, freefall_start_time) > TIME_WINDOW) {
                current_state = IDLE;
                printf("State: IDLE\n");
            }
            break;
        case IMPACT:
            if (difftime(now, impact_start_time) > TIME_WINDOW) {
                current_state = IDLE;
                printf("State: IDLE\n");
            }
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "LSM6DSR not found (WHO_AM_I = 0x%X)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float acceleration_magnitude;

    while (1) {
        // Read sensor data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Calculate acceleration magnitude
        acceleration_magnitude = calculate_acceleration_magnitude(accel_x, accel_y, accel_z);

        // Update state machine
        update_state_machine(acceleration_magnitude);

        // Log data
        log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 10ms (100Hz)
        gpioDelay(10000); // 10ms = 10000 us
    }

    return 0;
}

