        fprintf(log_file, "Timestamp,AngularRate(deg/s)\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_gyro_data;
        float angular_rate;

        // Read gyroscope data
        if (spi_read_register(spi_handle, X_GYRO_OUT, &raw_gyro_data) == 0) {
            // Scale the data
            angular_rate = scale_gyro_data((int16_t)raw_gyro_data);

