#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C address of the GY-50 gyroscope
#define GYRO_ADDRESS 0x69

// Define the register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Define the sensitivity of the gyroscope (8.75 mdps/LSB)
#define SENSITIVITY 8.75f

// Define the sampling rate (10 ms)
#define SAMPLE_RATE 10000 // in microseconds

// Global variables for I2C handle and file pointer
int i2c_handle;
FILE *log_file;

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the gyroscope
int initialize_gyro() {
    int retries = 3;
    int status;

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // Wait 1 ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (+-250 dps full-scale range)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // Wait 1 ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / SENSITIVITY;
    *y_dps = (float)y / SENSITIVITY;
    *z_dps = (float)z / SENSITIVITY;
}

// Function to log data to a file
int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    long timestamp_ns = (long)ts.tv_sec * 1000000000L + (long)ts.tv_nsec;

    if (fprintf(fp, "%ld,%f,%f,%f\n", timestamp_ns, x, y, z) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register returned 0x%X, expected 0xD3\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("WHO_AM_I register verified.\n");

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    float x_dps, y_dps, z_dps;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            convert_to_dps(x_raw, y_raw, z_raw, &x_dps, &y_dps, &z_dps);

            // Log the data
            if (log_data(log_file, x_dps, y_dps, z_dps) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_RATE);
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

