#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x53
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelerationData;

// Function prototypes
int init_i2c(const char *bus, int addr);
AccelerationData read_acceleration(int fd);
char* get_iso8601_timestamp();
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signum);
void cleanup();

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read acceleration data from the sensor
AccelerationData read_acceleration(int fd) {
    AccelerationData data;
    uint8_t buffer[6];
    int ret;

    // Read X axis
    ret = read(fd, buffer, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        data.x = 0; // Set to 0 to indicate error
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to the CSV file
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Cleanup function to close files and I2C device
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    while (program_running) {
        // Read acceleration data
        AccelerationData data = read_acceleration(i2c_fd);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data to CSV file
        if (data.x != 0 || data.y != 0 || data.z != 0) {
            if (log_data(csv_file, timestamp, data.x, data.y, data.z) != 0) {
                fprintf(stderr, "Error logging data. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        free(timestamp);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program finished.\n");
    return 0;
}

