#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
void log_data(int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to read sensor value
int read_sensor(int pin) {
    int value;
    if (pin == SENSOR1_PIN) {
        value = gpiod_line_get_value(sensor1_line);
    } else if (pin == SENSOR2_PIN) {
        value = gpiod_line_get_value(sensor2_line);
    } else {
        fprintf(stderr, "Error: Invalid sensor pin: %d\n", pin);
        return -1; // Indicate error
    }

    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to file
void log_data(int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to halt the conveyor
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

// Function to set up GPIO lines
int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting line for sensor 1 (pin %d): %s\n", SENSOR1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting line for sensor 2 (pin %d): %s\n", SENSOR2_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(sensor1_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line for sensor 1: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    if (gpiod_line_request(sensor2_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line for sensor 2: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying.\n");
            // Optionally add a delay here before retrying
            continue; // Skip logging and halt check this iteration
        }

        log_data(sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

