double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_fall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// MMA8452Q initialization function
int init_mma8452q(int fd) {
    uint8_t who_am_i;

    // Verify sensor identity
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x2A) {
