        close(fd);
        return 1;
    }

    // Initialize MMA8452Q
    if (init_mma8452q(fd) != 0) {
        fprintf(stderr, "Error initializing MMA8452Q\n");
        close(fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(fd, &x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check for fall event
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_fall_event(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, skipping iteration\n");
        }

        // Delay for 10 ms
        usleep(10000);
    }

    return 0;
}

