#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>
#include <errno.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Calibration constants (example values, replace with your calibration data)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detection threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int lis3mdl_init(int fd);
magnetometer_data_t read_magnetometer_data(int fd);
magnetometer_data_t calibrate_magnetometer_data(magnetometer_data_t raw_data);
void log_magnetometer_data(magnetometer_data_t data);
void metal_detection_alert(magnetometer_data_t data);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Configure CTRL_REG1 (ODR = 80 Hz, Continuous conversion mode)
        if (i2c_write_reg(fd, CTRL_REG1, 0x70) != 0) {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        // Configure CTRL_REG3 (Enable I2C)
        if (i2c_write_reg(fd, CTRL_REG3, 0x00) != 0) {
            fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        // Configure CTRL_REG4 (High-performance mode, +-4 gauss)
        if (i2c_write_reg(fd, CTRL_REG4, 0x0C) != 0) {
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        // Verify WHO_AM_I register
        uint8_t who_am_i;
        if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
            fprintf(stderr, "Error reading WHO_AM_I, retrying...\n");
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        if (who_am_i != 0x3D) {
            fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D, retrying...\n", who_am_i);
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        printf("LIS3MDL initialized successfully.\n");
        return 0; // Initialization successful
    }

    fprintf(stderr, "LIS3MDL initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    uint8_t buffer[6];

    // Read X, Y, and Z axis data (6 bytes)
    if (write(fd, (uint8_t[]){OUT_X_L}, 1) != 1) {
        perror("I2C write (register address) failed");
        data.x = 0.0; data.y = 0.0; data.z = 0.0;
        return data;
    }
    if (read(fd, buffer, 6) != 6) {
        perror("I2C read failed");
        data.x = 0.0; data.y = 0.0; data.z = 0.0;
        return data;
    }

    // Combine low and high bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to milliGauss (0.146 mG/LSB)
    data.x = (float)x * 0.146;
    data.y = (float)y * 0.146;
    data.z = (float)z * 0.146;

    return data;
}

// Function to calibrate magnetometer data
magnetometer_data_t calibrate_magnetometer_data(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = (raw_data.x - X_OFFSET) * X_SCALE;
    calibrated_data.y = (raw_data.y - Y_OFFSET) * Y_SCALE;
    calibrated_data.z = (raw_data.z - Z_OFFSET) * Z_SCALE;

    return calibrated_data;
}

// Function to log magnetometer data to a file
void log_magnetometer_data(magnetometer_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to detect metal
void metal_detection_alert(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.3f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize LIS3MDL
    if (lis3mdl_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms (10 Hz)

    while (!stop_flag) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data(i2c_fd);

        // Calibrate magnetometer data
        magnetometer_data_t calibrated_data = calibrate_magnetometer_data(raw_data);

        // Log magnetometer data
        log_magnetometer_data(calibrated_data);

        // Metal detection alert
        metal_detection_alert(calibrated_data);

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

