#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_M 0x09
#define ADXL354B_XDATA_H 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_M 0x0C
#define ADXL354B_YDATA_H 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_M 0x0F
#define ADXL354B_ZDATA_H 0x10
#define ADXL354B_STATUS   0x04
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_RESET    0x1F
#define ADXL354B_PARTID   0x01

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354b_read_register(int handle, uint8_t reg);
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z);
int adxl354b_reset(int handle);
int adxl354b_check_presence(int handle);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a single register from the ADXL354B
int adxl354b_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = 0x80 | reg; // Set read bit (bit 7)
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// Function to write a single register to the ADXL354B
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg;       // Register address
    tx[1] = value;     // Value to write

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z) {
    char tx[4], rx[4];
    uint32_t raw_x, raw_y, raw_z;

    // Read X data
    tx[0] = 0x80 | ADXL354B_XDATA_L; // Set read bit (bit 7)
    tx[1] = 0x00;       // Dummy byte for reading
    tx[2] = 0x00;       // Dummy byte for reading
    tx[3] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 4) != 0) {
        fprintf(stderr, "SPI read error for X data\n");
        return -1;
    }

    raw_x = ((uint32_t)rx[1] << 12) | ((uint32_t)rx[2] << 4) | ((uint32_t)rx[3] >> 4);
    if (raw_x & 0x800000) {
        raw_x |= 0xFFF00000; // Sign extend
    }

    // Read Y data
    tx[0] = 0x80 | ADXL354B_YDATA_L; // Set read bit (bit 7)
    tx[1] = 0x00;       // Dummy byte for reading
    tx[2] = 0x00;       // Dummy byte for reading
    tx[3] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 4) != 0) {
        fprintf(stderr, "SPI read error for Y data\n");
        return -1;
    }

    raw_y = ((uint32_t)rx[1] << 12) | ((uint32_t)rx[2] << 4) | ((uint32_t)rx[3] >> 4);
    if (raw_y & 0x800000) {
        raw_y |= 0xFFF00000; // Sign extend
    }

    // Read Z data
    tx[0] = 0x80 | ADXL354B_ZDATA_L; // Set read bit (bit 7)
    tx[1] = 0x00;       // Dummy byte for reading
    tx[2] = 0x00;       // Dummy byte for reading
    tx[3] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 4) != 0) {
        fprintf(stderr, "SPI read error for Z data\n");
        return -1;
    }

    raw_z = ((uint32_t)rx[1] << 12) | ((uint32_t)rx[2] << 4) | ((uint32_t)rx[3] >> 4);
    if (raw_z & 0x800000) {
        raw_z |= 0xFFF00000; // Sign extend
    }

    // Convert to g-force units (3.9 microg/LSB)
    *x = (float)raw_x * 0.0000039;
    *y = (float)raw_y * 0.0000039;
    *z = (float)raw_z * 0.0000039;

    return 0;
}

// Function to reset the ADXL354B
int adxl354b_reset(int handle) {
    if (adxl354b_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to check the ADXL354B part ID
int adxl354b_check_presence(int handle) {
    int partid = adxl354b_read_register(handle, ADXL354B_PARTID);
    if (partid < 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X (expected 0x1D)\n", partid);
        return -1;
    }
    printf("ADXL354B detected with PARTID: 0x%02X\n", partid);
    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.6f,%.6f,%.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Check ADXL354B presence
    if (adxl354b_check_presence(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset ADXL354B
    if (adxl354b_reset(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

