#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle SIGINT signal
void sigint_handler(int sig)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor()
{
    int value;
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to log a message with a timestamp
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate self-parking
void self_park()
{
    log_message("Self-parking sequence started");
    sleep(2);
    log_message("Self-parking sequence completed");
}

int main()
{
    int ret;

    // Register signal handler for SIGINT
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(-errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(-errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input
    ret = gpiod_line_request_input(line, "obstacle_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            self_park();
        } else if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

