#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL;
struct gpiod_line *line2 = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void log_status(int sensor1_value, int sensor2_value);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO lines
        if (line1) {
            gpiod_line_release(line1);
        }
        if (line2) {
            gpiod_line_release(line2);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value;
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log the sensor status with a timestamp
void log_status(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines for the sensors
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Error getting line for sensor 1: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Error getting line for sensor 2: %s\n", strerror(errno));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ir_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret1 = gpiod_line_request(line1, &config, 0);
    if (ret1 < 0) {
        fprintf(stderr, "Error requesting line for sensor 1: %s\n", strerror(errno));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    int ret2 = gpiod_line_request(line2, &config, 0);
    if (ret2 < 0) {
        fprintf(stderr, "Error requesting line for sensor 2: %s\n", strerror(errno));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(line1);
        int sensor2_value = read_sensor(line2);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break; // Exit loop on error
        }

        log_status(sensor1_value, sensor2_value);

        // Delay for 100 milliseconds
        struct timespec delay = {0, 100000000}; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 1;
}

