#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_MSC_CTRL 0x24
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, int16_t *data);
int spi_write_register(uint8_t address, uint16_t data);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(uint8_t address, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];
    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t address, uint16_t data) {
    char tx_buf[3];
    tx_buf[0] = address & 0x7F; // Clear MSB for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB
    tx_buf[2] = data & 0xFF;      // LSB

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiWrite(spi_handle, tx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deassert CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266 (Enable Data Ready Mode)
    if (spi_write_register(ADIS16266_REG_MSC_CTRL, 0x0004) != 0) {
        fprintf(stderr, "Failed to initialize ADIS16266\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x_rate, y_rate, z_rate;
        float x_rate_deg, y_rate_deg, z_rate_deg;

        // Read gyroscope data
        if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &x_rate) != 0) {
            fprintf(stderr, "Failed to read X gyro data\n");
            continue; // Continue to the next iteration
        }
        if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &y_rate) != 0) {
            fprintf(stderr, "Failed to read Y gyro data\n");
            continue;
        }
        if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &z_rate) != 0) {
            fprintf(stderr, "Failed to read Z gyro data\n");
            continue;
        }

        // Convert to degrees per second
        x_rate_deg = (float)x_rate * 0.02;
        y_rate_deg = (float)y_rate * 0.02;
        z_rate_deg = (float)z_rate * 0.02;

        // Log the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate_deg, y_rate_deg, z_rate_deg);

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

