#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    int retries = 3;
    int status;

    // Verify sensor presence
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
        if (status >= 0) {
            if (status == 0xC7) {
                printf("FXOS8700 sensor found.\n");
                break;
            } else {
                fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", status);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure accelerometer: Active mode, 100 Hz ODR
    status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01 | (0x01 << 3)); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure magnetometer: Hybrid mode, ODR = 10 Hz
    status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x1F); // Hybrid mode, ODR = 10 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure magnetometer: High resolution
    status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x20); // High resolution
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

