// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    int retries = 3;
    int status;

    // Verify sensor presence
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
        if (status >= 0) {
            if (status == 0xC7) {
                printf("FXOS8700 sensor found.\n");
