#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y);
void log_tilt_event(float tilt_x, float tilt_y);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = DATAX0;

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate tilt angles
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y) {
    *tilt_x = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    *tilt_y = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;
}

// Function to log tilt events
void log_tilt_event(float tilt_x, float tilt_y) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Tilt X: %.2f, Tilt Y: %.2f\n", timestamp, tilt_x, tilt_y);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int16_t x, y, z;
    float tilt_x, tilt_y;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (i2c_write_reg(i2c_fd, POWER_CTL, 0x08) < 0) { // Enable measurement mode
        fprintf(stderr, "Failed to initialize ADXL345 (POWER_CTL)\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, DATA_FORMAT, 0x08) < 0) { // Set full resolution
        fprintf(stderr, "Failed to initialize ADXL345 (DATA_FORMAT)\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt angles
            calculate_tilt_angles(x, y, z, &tilt_x, &tilt_y);

            // Log tilt event if threshold is exceeded
            if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD) {
                log_tilt_event(tilt_x, tilt_y);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay
        usleep(100000); // 100 ms
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

