#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 17
#define WINDOW_SIZE_MS 5000
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define ALERT_PREFIX "ALERT"

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the GPIO pin
int read_gpio() {
    return gpioRead(GPIO_PIN);
}

// Function to process the sensor data and determine if an alert is triggered
int process_data(int high_count, int threshold) {
    return high_count > threshold;
}

// Function to print the alert message with timestamp
void print_alert() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("%s %s\n", buf, ALERT_PREFIX);
}

// Function to print the status message with timestamp
void print_status(int high_count) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("%s High readings: %d\n", buf, high_count);
}

// Function to cleanup and terminate the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold;
    char *endptr;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Validate command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value.  Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int high_count = 0;
        int i;

        // Sample GPIO pin for WINDOW_SIZE_MS
        for (i = 0; i < WINDOW_SIZE_MS / (SAMPLE_INTERVAL_US / 1000); ++i) {
            if (read_gpio() == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Process data and print alert or status
        if (process_data(high_count, threshold)) {
            print_alert();
        } else {
            print_status(high_count);
        }

        // Pause for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

