// Read DHT22 sensor (using sysfs for simplicity)
int read_dht22_sensor(float *temperature) {
    FILE *fp;
    char buffer[256];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen("/sys/bus/w1/devices/28-000000000000/w1_slave", "r");
        if (fp == NULL) {
            perror("Error opening DHT22 sensor file");
            log_error("Error opening DHT22 sensor file");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            perror("Error reading DHT22 sensor file");
            log_error("Error reading DHT22 sensor file");
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);

        if (strstr(buffer, "YES") != NULL) {
            char *temp_str = strstr(buffer, "t=");
            if (temp_str != NULL) {
                long temp_value = strtol(temp_str + 2, NULL, 10);
                *temperature = (float)temp_value / 1000.0;
                return 0;
            } else {
                fprintf(stderr, "Error: Could not find temperature in DHT22 data.\n");
                log_error("Error: Could not find temperature in DHT22 data.");
                return -1;
            }
        } else {
            fprintf(stderr, "Error: DHT22 sensor data invalid.\n");
            log_error("Error: DHT22 sensor data invalid.");
            return -1;
        }
    }

    fprintf(stderr, "Error: Failed to read DHT22 sensor after %d retries.\n", MAX_RETRIES);
