        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Error: Could not open log file.\n");
        log_error("Error: Could not open log file.");
        return -1;
    }
}

int main(void) {
    int input_code;
    sensor_data_t sensor_data;
    int pir_value;
    int unlock_door_a = 0;

    // Seed the random number generator
    srand(time(NULL));

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        log_error("Error opening log file");
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("Error opening error log file");
        fprintf(stderr, "Error: Could not open error log file. Continuing without error logging.\n");
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        fclose(log_file);
        if (error_log_file) fclose(error_log_file);
        return 1;
    }

    // Generate initial security code
    security_code = generate_security_code();
    printf("Initial security code: %d\n", security_code);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read PIR sensor
        pir_value = read_pir_sensor();
        if (pir_value > 0) {
            printf("Motion detected!\n");

            // Read sensor data
            if (read_dht22_sensor(&sensor_data.temperature) != 0) {
                sensor_data.temperature = -999.0; // Indicate error
            }
            if (read_bmp180_sensor(&sensor_data.pressure) != 0) {
                sensor_data.pressure = -999.0; // Indicate error
            }
            if (read_mq2_sensor(&sensor_data.gas_level) != 0) {
                sensor_data.gas_level = -999.0; // Indicate error
            }
            sensor_data.motion = pir_value;

            // Log sensor data
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Motion: %d, Temperature: %.2f, Pressure: %.2f, Gas: %.2f\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec,
                    sensor_data.motion, sensor_data.temperature, sensor_data.pressure, sensor_data.gas_level);
            fflush(log_file);

            // Unlock door A
            if (!unlock_door_a) {
                if (unlock_door(DOOR_A_PIN) == 0) {
                    printf("Door A unlocked!\n");
                    unlock_door_a = 1;
                    gpiod_line_set_value(led_line, 1); // Turn on LED
                    sleep(5);
                    lock_door(DOOR_A_PIN);
                    printf("Door A locked!\n");
                    unlock_door_a = 0;
                    gpiod_line_set_value(led_line, 0); // Turn off LED
                } else {
                    fprintf(stderr, "Error unlocking door A.\n");
                    log_error("Error unlocking door A");
                }
            }
        }

        // Prompt for security code
        printf("Enter security code: ");
        if (scanf("%d", &input_code) != 1) {
            // Clear the input buffer
            while (getchar() != '\n');
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            log_error("Invalid input for security code");
            continue;
        }

        // Validate security code
        if (input_code == security_code) {
            printf("Access granted!\n");
            log_access(input_code);

            // Generate new security code
            security_code = generate_security_code();
            printf("New security code: %d\n", security_code);
        } else {
            printf("Access denied!\n");
            log_error("Access denied");
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    fclose(log_file);
    if (error_log_file) fclose(error_log_file);

    return 0;
}

