#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MEASUREMENT_MODE 0x21
#define CONVERSION_DELAY_MS 180

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to configure the BH1750 sensor
int config_sensor() {
    unsigned char mode = MEASUREMENT_MODE;
    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read raw data from the sensor
int read_raw_data(unsigned short *raw_value) {
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to calculate illuminance in lux
float calculate_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log the data to a file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(log_file);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Configure the sensor
    if (config_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short raw_value;

        // Read raw data
        if (read_raw_data(&raw_value) != 0) {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate lux value
        float lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(lux_value) != 0) {
            fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

