// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PORT 12345
#define SHARED_SECRET "MySecretKey"
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_data);
float map_touch_to_frequency(int touch_data);
void play_tone(float frequency);
void stop_tone();
int handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        stop_tone();
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (server_fd >= 0) {
            close(server_fd);
        }
        if (new_socket >= 0) {
            close(new_socket);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure Electrode Filtering (Example values, adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // MHD_R
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x01) < 0) return -1; // NHD_R
    if (i2cWriteByteData(i2c_handle, 0x60, 0x01) < 0) return -1; // NCL_R
    if (i2cWriteByteData(i2c_handle, 0x61, 0x00) < 0) return -1; // FDL_R
    if (i2cWriteByteData(i2c_handle, 0x62, 0x01) < 0) return -1; // MHDR
    if (i2cWriteByteData(i2c_handle, 0x63, 0x01) < 0) return -1; // NHDR
    if (i2cWriteByteData(i2c_handle, 0x64, 0x01) < 0) return -1; // NCLR
    if (i2cWriteByteData(i2c_handle, 0x65, 0x00) < 0) return -1; // FDLR

    // Configure Electrode Enable (Enable all 12 electrodes)
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) return -1; // ELE0_EN
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0F) < 0) return -1; // ELE1_EN
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x0F) < 0) return -1; // ELE2_EN

    // Set Operation Mode to Run
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) return -1; // ELE0_EN
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0F) < 0) return -1; // ELE1_EN
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x0F) < 0) return -1; // ELE2_EN

    return 0;
}

// Read touch data from MPR121
int read_touch_data(int *touch_data) {
    char buf[24];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 24) < 0) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        touch_data[i] = ((int)buf[2 * i + 1] << 8) | (int)buf[2 * i];
    }
    return 0;
}

// Map touch data to frequency (logarithmic scale)
float map_touch_to_frequency(int touch_data) {
    float frequency;
    if (touch_data == 0) {
        frequency = 220.0; // Minimum frequency
    } else {
        frequency = 220.0 * pow(2.0, (float)touch_data / 4095.0 * 6.0); // Logarithmic mapping
        if (frequency > 880.0) {
            frequency = 880.0; // Maximum frequency
        }
    }
    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int range = 1000000; // PWM range
    int duty_cycle = range / 2; // 50% duty cycle
    int period = 1000000 / frequency; // Period in microseconds

    gpioSetPWMfrequency(PWM_GPIO, 1000000 / period); // Set PWM frequency
    gpioSetPWMrange(PWM_GPIO, range); // Set PWM range
    gpioPWM(PWM_GPIO, duty_cycle); // Set PWM duty cycle
}

// Stop tone
void stop_tone() {
    gpioPWM(PWM_GPIO, 0); // Set duty cycle to 0 to stop the tone
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        return -1;
    }

    printf("Received: %s\n", buffer);

    // Check for motion detection message
    if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
        // Extract the secret key
        char *secret_key = buffer + strlen(MOTION_DETECTED_PREFIX);

        // Verify the secret key
        if (strcmp(secret_key, SHARED_SECRET) == 0) {
            printf("Motion detected and secret key verified!\n");

            // Play tones for 5 seconds
            for (int i = 0; i < 250; i++) { // 250 * 20ms = 5 seconds
                int touch_data[12];
                if (read_touch_data(touch_data) == 0) {
                    int max_touch = 0;
                    for (int j = 0; j < 12; j++) {
                        if (touch_data[j] > max_touch) {
                            max_touch = touch_data[j];
                        }
                    }
                    float frequency = map_touch_to_frequency(max_touch);
                    play_tone(frequency);

                    // Log frequency to file
                    fprintf(log_file, "%.2f\n", frequency);
                    fflush(log_file); // Ensure data is written to file immediately
                } else {
                    fprintf(stderr, "Error reading touch data during playback\n");
                }
                gpioDelay(20000); // 20ms delay
            }
            stop_tone();
        } else {
            fprintf(stderr, "Error: Incorrect secret key\n");
        }
    }

