    if (!fp) {
        perror("Error opening PWM period file");
        return -1;
    }
    fprintf(fp, "%d", period_ns);
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/enable", chip, channel);
    fp = fopen(path, "w");
    if (!fp) {
        perror("Error opening PWM enable file");
        return -1;
    }
    fprintf(fp, "0"); // Disable PWM initially
    fclose(fp);

    return 0;
}

// Magnetometer configuration function
int configure_magnetometer(int fd) {
    uint8_t config = 0x18; // 10 Hz continuous conversion
    if (write(fd, &config, 1) != 1) {
        perror("Error writing to CTRL_REG1_M");
        return -1;
    }
    return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Magnitude calculation function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf(x * x + y * y + z * z);
}

// LED brightness control function
int set_led_brightness(int gpio_fd, int brightness) {
    if (brightness > 0) {
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO line high");
            return -1;
        }

        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
        FILE *fp = fopen(path, "w");
        if (!fp) {
            perror("Error opening PWM duty_cycle file");
            return -1;
        }
        fprintf(fp, "%d", brightness);
        fclose(fp);

        snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        fp = fopen(path, "w");
        if (!fp) {
            perror("Error opening PWM enable file");
            return -1;
        }
        fprintf(fp, "1"); // Enable PWM
        fclose(fp);

    } else {
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Error setting GPIO line low");
            return -1;
        }

        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        FILE *fp = fopen(path, "w");
        if (!fp) {
            perror("Error opening PWM enable file");
            return -1;
        }
        fprintf(fp, "0"); // Disable PWM
        fclose(fp);
    }
    return 0;
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LSM303_ADDR);
    if (i2c_fd < 0) {
        log_error("I2C initialization failed");
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, GPIO_PIN) < 0) {
        log_error("GPIO initialization failed");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Initialize PWM
    if (init_pwm(PWM_CHIP, PWM_CHANNEL, PWM_PERIOD_NS) < 0) {
        log_error("PWM initialization failed");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer(i2c_fd) < 0) {
        log_error("Magnetometer configuration failed");
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        FILE *fp = fopen(path, "w");
        if (fp) {
            fprintf(fp, "0");
            fclose(fp);
        }
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    float magnitude;
    int brightness;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Map magnitude to brightness (0-100%)
            brightness = (int)(magnitude / 1000.0 * 100.0); // Assuming max magnitude is around 1000
            if (brightness < 0) brightness = 0;
            if (brightness > 100) brightness = 100;

            // Set LED brightness
            if (set_led_brightness(i2c_fd, brightness) < 0) {
                log_error("Failed to set LED brightness");
            }
        } else {
            log_error("Failed to read magnetometer data");
        }

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/%s/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

