#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus
#define I2C_BUS 1

// Number of samples for hard-iron offset calculation
#define OFFSET_SAMPLES 100

// Offset correction interval (ms)
#define OFFSET_INTERVAL 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    int32_t x_offset;
    int32_t y_offset;
    int32_t z_offset;
} hard_iron_offsets_t;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configuration Register A: 8 samples averaged, 15 Hz output rate
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configuration Register B: Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate hard-iron offsets
hard_iron_offsets_t calculate_offsets(magnetometer_data_t *data, int num_samples) {
    hard_iron_offsets_t offsets = {0, 0, 0};
    for (int i = 0; i < num_samples; i++) {
        offsets.x_offset += data[i].x;
        offsets.y_offset += data[i].y;
        offsets.z_offset += data[i].z;
    }
    offsets.x_offset /= num_samples;
    offsets.y_offset /= num_samples;
    offsets.z_offset /= num_samples;
    return offsets;
}

// Function to apply hard-iron offsets to raw data
magnetometer_data_t apply_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets) {
    magnetometer_data_t corrected_data;
    corrected_data.x = raw_data.x - offsets.x_offset;
    corrected_data.y = raw_data.y - offsets.y_offset;
    corrected_data.z = raw_data.z - offsets.z_offset;
    return corrected_data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    magnetometer_data_t raw_data[OFFSET_SAMPLES];
    int sample_index = 0;
    hard_iron_offsets_t offsets = {0, 0, 0};

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_data[sample_index]) < 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate offsets every OFFSET_SAMPLES readings
        if (sample_index == OFFSET_SAMPLES - 1) {
            offsets = calculate_offsets(raw_data, OFFSET_SAMPLES);
        }

        // Apply offsets to the latest reading
        magnetometer_data_t corrected_data = apply_offsets(raw_data[sample_index], offsets);

        // Print corrected data
        printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);

        // Increment sample index, wrapping around
        sample_index = (sample_index + 1) % OFFSET_SAMPLES;

        // Wait for OFFSET_INTERVAL milliseconds
        gpioDelay(OFFSET_INTERVAL);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

