#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x31
#define INT1_DURATION 0x32
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define WHO_AM_I 0x0F

// GPIO pin for interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Sampling rate (Hz)
#define SAMPLING_RATE 100

// Interrupt threshold (mg)
#define INTERRUPT_THRESHOLD 2000

// Interrupt duration (ms)
#define INTERRUPT_DURATION 0

// Acceleration sensitivity (mg/LSB)
#define ACCEL_SENSITIVITY 0.061

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int init_gpio(int gpio_pin);
int init_lsm303d();
int read_register(int reg, uint8_t *value);
int write_register(int reg, uint8_t value);
int read_accelerometer_data(accelerometer_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data);
void dump_buffer(circular_buffer_t *buffer);
void interrupt_handler(int gpio_pin, int level, struct timeval timestamp);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *device) {
    i2c_fd = open(device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_EV_RISING_EDGE;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
        return -1;
    }

    return 0;
}

// LSM303D initialization function
int init_lsm303d() {
    uint8_t who_am_i;
    if (read_register(WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 50 Hz ODR, all axes enabled
    if (write_register(CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 register\n");
        return -1;
    }

    // Configure accelerometer: +/- 2g full-scale
    if (write_register(CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4 register\n");
        return -1;
    }

    // Configure interrupt: any-axis-high event
    if (write_register(INT1_CFG, 0x2A) < 0) {
        fprintf(stderr, "Error writing INT1_CFG register\n");
        return -1;
    }

    // Set interrupt threshold
    if (write_register(INT1_THS, INTERRUPT_THRESHOLD / 16) < 0) {
        fprintf(stderr, "Error writing INT1_THS register\n");
        return -1;
    }

    // Set interrupt duration
    if (write_register(INT1_DURATION, INTERRUPT_DURATION) < 0) {
        fprintf(stderr, "Error writing INT1_DURATION register\n");
        return -1;
    }

    return 0;
}

// Function to read a single register
int read_register(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
