#include <time.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *solenoid1_line;
struct gpiod_line *solenoid2_line;

// Function prototypes
int set_gpio_value(struct gpiod_line *line, int value);
int delay_ms(int milliseconds);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set solenoid pins LOW
    set_gpio_value(solenoid1_line, 0);
    set_gpio_value(solenoid2_line, 0);

    // Release GPIO lines
    if (solenoid1_line) {
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_release(solenoid2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to delay execution
int delay_ms(int milliseconds) {
    struct timespec req;
    req.tv_sec = 0;
    req.tv_nsec = milliseconds * 1000000L;
    return nanosleep(&req, NULL);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID2_PIN, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(solenoid1_line, "solenoid1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID1_PIN, strerror(-ret));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(solenoid2_line, "solenoid2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID2_PIN, strerror(-ret));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Solenoid 1 ON
        if (set_gpio_value(solenoid1_line, 1) != 0) {
            break;
        }
        delay_ms(500);

        // Solenoid 1 OFF, Solenoid 2 ON
        if (set_gpio_value(solenoid1_line, 0) != 0) {
            break;
