#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define unlock duration (seconds)
#define UNLOCK_DURATION 2

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Global variables for UART file descriptors
int uart1_fd = -1;
int uart2_fd = -1;

// Function prototypes
int init_uart(const char *port);
int read_code(int fd, char *code);
int constant_time_compare(const char *a, const char *b);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    lock_doors(); // Ensure doors are locked on exit
    if (uart1_fd != -1) {
        close(uart1_fd);
    }
    if (uart2_fd != -1) {
        close(uart2_fd);
    }
    gpioTerminate();
    exit(0);
}

// Initialize UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s\n", port);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s\n", port);
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Error setting baud rate for %s\n", port);
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s\n", port);
        close(fd);
        return -1;
    }

    return fd;
}

// Read code from UART port
int read_code(int fd, char *code) {
    ssize_t bytes_read = read(fd, code, 6);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout
        } else {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
    } else if (bytes_read == 0) {
        return 0; // No data
    } else {
        code[bytes_read] = '\0'; // Null-terminate the string
        // Validate that the code contains only digits
        for (int i = 0; i < bytes_read; i++) {
            if (code[i] < '0' || code[i] > '9') {
                fprintf(stderr, "Invalid character received: %c\n", code[i]);
                return -1; // Invalid character
            }
        }
        return bytes_read;
    }
}

// Constant-time string comparison
int constant_time_compare(const char *a, const char *b) {
    int result = 0;
    for (int i = 0; i < 6; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

// Unlock doors
void unlock_doors() {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK1_GPIO);
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK2_GPIO);
    }
    printf("Doors unlocked for %d seconds\n", UNLOCK_DURATION);
    gpioDelay(UNLOCK_DURATION * 1000000); // Delay in microseconds
}

// Lock doors
void lock_doors() {
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK1_GPIO);
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LOCK2_GPIO);
    }
    printf("Doors locked\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Initialize UART ports
    uart1_fd = init_uart(UART1_PORT);
    if (uart1_fd == -1) {
        gpioTerminate();
        return 1;
    }

    uart2_fd = init_uart(UART2_PORT);
    if (uart2_fd == -1) {
        close(uart1_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code1[7] = {0}; // +1 for null terminator
    char code2[7] = {0}; // +1 for null terminator
    int code1_len, code2_len;

    // Main loop
    while (1) {
        code1_len = read_code(uart1_fd, code1);
        code2_len = read_code(uart2_fd, code2);

        if (code1_len > 0 && code2_len > 0) {
            printf("Code 1: %s\n", code1);
            printf("Code 2: %s\n", code2);

            if (constant_time_compare(code1, code2) && constant_time_compare(code1, EXPECTED_CODE)) {
                printf("Codes match and are correct!\n");
                unlock_doors();
                lock_doors();
            } else {
                printf("Codes do not match or are incorrect.\n");
            }
        }

        gpioDelay(10000); // Delay 10ms to avoid busy-waiting
    }

    return 0;
}

