#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *pir_line;
struct gpiod_line *relay_line;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
void handle_motion(void);
void failsafe_check(void);
void signal_handler(int sig);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: gpiochip0");
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line: %d", PIR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get RELAY line: %d", RELAY_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    struct gpiod_line_request_config pir_config;
    pir_config.consumer = "motion_sensor";
    pir_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &pir_config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    struct gpiod_line_request_config relay_config;
    relay_config.consumer = "door_strike";
    relay_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay_line, &relay_config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request RELAY line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        syslog(LOG_ERR, "Failed to set relay state: %d", state);
        return -1;
    }
    return 0;
}

// Handle motion detection
void handle_motion(void) {
    syslog(LOG_INFO, "Motion detected!");
    if (control_relay(1) == 0) {
        usleep(STRIKE_DURATION_MS * 1000); // 1 second
        if (control_relay(0) != 0) {
            syslog(LOG_ERR, "Failed to de-energize relay after strike.");
        }
    }
}

// Failsafe check
void failsafe_check(void) {
    static time_t last_motion_time = 0;
    time_t current_time = time(NULL);

    int pir_value = read_pir_sensor();
    if (pir_value > 0) {
        last_motion_time = current_time;
    }

    if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT_S) {
        syslog(LOG_WARNING, "Failsafe triggered: PIR sensor HIGH for %d seconds.", FAILSAFE_TIMEOUT_S);
        control_relay(0);
        terminate = 1;
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");
    if (relay_line) {
        control_relay(0); // Ensure relay is off
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    syslog(LOG_INFO, "GPIO cleanup complete.");
}

int main(void) {
    openlog("motion_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting motion sensor program...");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor();
        if (pir_value > 0) {
            handle_motion();
        }
        failsafe_check();
        usleep(POLL_INTERVAL_MS * 1000); // 50ms
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

