#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define activation and deactivation durations (in seconds)
#define ACTIVATION_DURATION 300
#define DEACTIVATION_DURATION 0 // Deactivation is immediate for active-low relays

// Define pause duration (in seconds)
#define PAUSE_DURATION 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the state machine states
typedef enum {
    RELAY1_ON,
    RELAY2_ON,
    RELAY3_ON,
    RELAY4_ON,
    PAUSE
} state_t;

