#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <math.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Scaling factor for accelerometer data
#define ACCEL_SCALE 16384.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Sysfs path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel"

// Global variables
int i2c_fd = -1;
int timer_fd = -1;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t buffer;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int mpu6050_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void buffer_add(circular_buffer_t *buffer, float x, float y, float z);
int buffer_get_latest(circular_buffer_t *buffer, float *x, float *y, float *z);
void signal_handler(int sig);
int create_sysfs_interface();
int remove_sysfs_interface();
void timer_callback(union sigval sv);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_bytes(fd, ACCEL_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((data[0] << 8) | data[1]);
    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;

    return 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer get latest function
int buffer_get_latest(circular_buffer_t *buffer, float *x, float *y, float *z) {
    if (buffer->count == 0) {
        return -1; // Buffer is empty
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *x = buffer->x[index];
    *y = buffer->y[index];
    *z = buffer->z[index];
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;
}

// Create sysfs interface function
int create_sysfs_interface() {
    char path[256];
    FILE *fp;

    // Create directory
    if (mkdir(SYSFS_PATH, 0755) == -1 && errno != EEXIST) {
        perror("Failed to create sysfs directory");
        return -1;
    }

    // Create latest file
    snprintf(path, sizeof(path), "%s/latest", SYSFS_PATH);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to create sysfs file");
        return -1;
    }
    fclose(fp);

    return 0;
}

// Remove sysfs interface function
int remove_sysfs_interface() {
    char path[256];

    // Remove latest file
    snprintf(path, sizeof(path), "%s/latest", SYSFS_PATH);
    if (unlink(path) == -1) {
        perror("Failed to remove sysfs file");
        return -1;
    }

    // Remove directory
    if (rmdir(SYSFS_PATH) == -1) {
        perror("Failed to remove sysfs directory");
        return -1;
    }

    return 0;
}

// Timer callback function
void timer_callback(union sigval sv) {
    float x, y, z;

    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
        buffer_add(&buffer, x, y, z);
    }
}

int main() {
    struct itimerspec timer_spec;
    struct sigevent sev;
    char path[256];
    FILE *fp;
    float x, y, z;

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sysfs interface
    if (create_sysfs_interface() < 0) {
        fprintf(stderr, "Failed to create sysfs interface, continuing without it.\n");
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        goto cleanup;
    }

    // Create timer
    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        goto cleanup;
    }

    // Configure timer
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = timer_callback;
    sev.sigev_notify_attributes = NULL;
    sev.sigev_value.sival_ptr = &timer_fd;
    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        goto cleanup;
    }

    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 10000000; // 10ms
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 10000000; // 10ms

    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer interval");
        goto cleanup;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Update sysfs file
        if (buffer_get_latest(&buffer, &x, &y, &z) == 0) {
            snprintf(path, sizeof(path), "%s/latest", SYSFS_PATH);
            fp = fopen(path, "w");
            if (fp != NULL) {
                fprintf(fp, "%.4f,%.4f,%.4f\n", x, y, z);
                fclose(fp);
            } else {
                perror("Failed to open sysfs file for writing");
            }
        }
        usleep(10000); // 10ms
    }

cleanup:
    // Cleanup
    if (timer_fd != -1) {
        close(timer_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    remove_sysfs_interface();

    printf("Exiting.\n");
    return 0;
}

