#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals for each relay (in seconds)
#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int gpio_init(void);
void relay_on(struct gpiod_line *line);
void relay_off(struct gpiod_line *line);
void toggle_relay(struct gpiod_line *line);
void cleanup(int signal);

// Signal handler for SIGINT and SIGTERM
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    relay_off(relay1_line);
    relay_off(relay2_line);
    relay_off(relay3_line);
    relay_off(relay4_line);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Release GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Initialize GPIO chip and lines
int gpio_init(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        if(relay1_line) gpiod_line_release(relay1_line);
        if(relay2_line) gpiod_line_release(relay2_line);
        if(relay3_line) gpiod_line_release(relay3_line);
        if(relay4_line) gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "relay2", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "relay3", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting GPIO line for output");
        if(relay1_line) gpiod_line_release(relay1_line);
        if(relay2_line) gpiod_line_release(relay2_line);
        if(relay3_line) gpiod_line_release(relay3_line);
        if(relay4_line) gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Turn a relay on
void relay_on(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value to 1");
    }
}

// Turn a relay off
void relay_off(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value to 0");
    }
}

// Toggle a relay
void toggle_relay(struct gpiod_line *line) {
    int current_value = gpiod_line_get_value(line);
    if (current_value < 0) {
        perror("Error getting GPIO line value");
        return;
    }
    if (gpiod_line_set_value(line, !current_value) < 0) {
        perror("Error toggling GPIO line value");
    }
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
