        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Relay 1
        struct timespec ts1, ts2, ts3, ts4;
        clock_gettime(CLOCK_MONOTONIC, &ts1);
        long long start1 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        long long current1 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        while ((current1 - start1) / 1000000000LL < RELAY1_INTERVAL) {
            clock_gettime(CLOCK_MONOTONIC, &ts2);
            current1 = ts2.tv_sec * 1000000000LL + ts2.tv_nsec;
        }
        toggle_relay(relay1_line);

        // Relay 2
        clock_gettime(CLOCK_MONOTONIC, &ts1);
        long long start2 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        long long current2 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        while ((current2 - start2) / 1000000000LL < RELAY2_INTERVAL) {
            clock_gettime(CLOCK_MONOTONIC, &ts2);
            current2 = ts2.tv_sec * 1000000000LL + ts2.tv_nsec;
        }
        toggle_relay(relay2_line);

        // Relay 3
        clock_gettime(CLOCK_MONOTONIC, &ts1);
        long long start3 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        long long current3 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        while ((current3 - start3) / 1000000000LL < RELAY3_INTERVAL) {
            clock_gettime(CLOCK_MONOTONIC, &ts2);
            current3 = ts2.tv_sec * 1000000000LL + ts2.tv_nsec;
        }
        toggle_relay(relay3_line);

        // Relay 4
        clock_gettime(CLOCK_MONOTONIC, &ts1);
        long long start4 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        long long current4 = ts1.tv_sec * 1000000000LL + ts1.tv_nsec;
        while ((current4 - start4) / 1000000000LL < RELAY4_INTERVAL) {
            clock_gettime(CLOCK_MONOTONIC, &ts2);
            current4 = ts2.tv_sec * 1000000000LL + ts2.tv_nsec;
        }
        toggle_relay(relay4_line);
    }

    return 0;
}

