#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define alarm duration (seconds)
#define ALARM_DURATION 3

// Define debounce time (seconds)
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static volatile time_t last_alarm_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int control_relay(int state);
int log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_relay(0); // Turn off relay
    gpioTerminate();   // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Control relay state
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening alarm_log.txt");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s\n", s);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_alarm_time) >= DEBOUNCE_TIME) {
                printf("Sound detected! Activating relay.\n");
                control_relay(1); // Turn on relay
                log_alarm();       // Log the alarm
                gpioDelay(ALARM_DURATION * 1000); // Wait for alarm duration
                control_relay(0); // Turn off relay
                last_alarm_time = current_time;
                printf("Relay deactivated.\n");
            } else {
                printf("Sound detected, but debouncing. Ignoring.\n");
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(0); // Turn off relay
    gpioTerminate();   // Terminate pigpio

    return 0;
}

