// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// GPIO pin for LED
#define LED_PIN 17

// I2C file descriptor
int i2c_fd;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Circular buffer
CircularBuffer gyro_buffer;

// Callback function type
typedef void (*callback_func)(float x, float y, float z);

// Callback function pointer
callback_func threshold_callback = NULL;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
bool check_threshold(float x, float y, float z, float threshold);
void default_callback(float x, float y, float z);
void signal_handler(int signal);

// Initialize I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = wiringPiI2CReadReg8(fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    raw_x = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_XOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_XOUT_L));
    raw_y = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_YOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_YOUT_L));
    raw_z = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_ZOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_ZOUT_L));

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if angular velocity exceeds threshold
bool check_threshold(float x, float y, float z, float threshold) {
    float magnitude = sqrt(x * x + y * y + z * z);
    return magnitude > threshold;
}

// Default callback function
void default_callback(float x, float y, float z) {
    printf("Threshold exceeded: X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
    digitalWrite(LED_PIN, HIGH);
    delay(500);
    digitalWrite(LED_PIN, LOW);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    close(i2c_fd);
    digitalWrite(LED_PIN, LOW);
    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set default callback function
    threshold_callback = default_callback;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Check if threshold is exceeded
            if (check_threshold(x, y, z, ANGULAR_VELOCITY_THRESHOLD)) {
                // Call callback function
                threshold_callback(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Delay
        delay(10);
    }

    return 0;
}

