#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_COMMAND_LENGTH 9
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define TIMEOUT_MS 1000
#define RETRY_DELAY_MS 10
#define LOG_INTERVAL_SEC 5

// Global variables for signal handling
static volatile int running = 1;
static int uart_handle = -1;
static FILE *co2_log_fp = NULL;
static FILE *error_log_fp = NULL;

// Structure to hold sensor data
typedef struct {
    int co2_ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_uart();
int read_co2_data(unsigned char *data);
int validate_checksum(const unsigned char *data);
sensor_data_t process_co2_data(const unsigned char *data);
int log_data(const sensor_data_t *data);
void error_log(const char *message);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to get ISO 8601 timestamp with microseconds
char* get_iso8601_timestamp() {
    struct timeval tv;
    struct tm tm;
    char *timestamp = malloc(30 * sizeof(char)); // Allocate memory for the timestamp

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm);

    sprintf(timestamp, "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, tv.tv_usec);

    return timestamp;
}

// Function to initialize the UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        error_log("Failed to open UART");
        return -1;
    }
    return 0;
}

// Function to read CO2 data from the sensor
int read_co2_data(unsigned char *data) {
    unsigned char command[] = READ_COMMAND;
    int bytes_written, bytes_read;
    int total_bytes_read = 0;
    struct timeval start_time, current_time;
    long elapsed_time_ms;

    gettimeofday(&start_time, NULL);

    while (total_bytes_read < 9) {
        bytes_written = serWrite(uart_handle, (char *)command, READ_COMMAND_LENGTH);
        if (bytes_written != READ_COMMAND_LENGTH) {
            error_log("Failed to write read command to UART");
            return -1;
        }

        gpioDelay(100); // Wait 100ms

        while (serDataAvailable(uart_handle) > 0) {
            bytes_read = serRead(uart_handle, (char *)data + total_bytes_read, 9 - total_bytes_read);
            if (bytes_read > 0) {
                total_bytes_read += bytes_read;
            } else {
                error_log("Error reading from UART");
                return -1;
            }
        }

        gettimeofday(&current_time, NULL);
        elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;

        if (elapsed_time_ms > TIMEOUT_MS) {
            error_log("Timeout reading CO2 data");
            return -1;
        }

        gpioDelay(RETRY_DELAY_MS); // Small delay before retrying
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != data[8]) {
        error_log("Checksum mismatch");
        return -1;
    }
    return 0;
}

// Function to process the CO2 data
sensor_data_t process_co2_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    sensor_data.error_flag = 0;

    if (validate_checksum(data) != 0) {
        sensor_data.co2_ppm = -1; // Indicate error
        sensor_data.error_flag = 1;
        return sensor_data;
    }

    sensor_data.co2_ppm = (data[2] << 8) | data[3];
    return sensor_data;
}

// Function to log the data to a file
int log_data(const sensor_data_t *data) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        error_log("Failed to get timestamp");
        return -1;
    }

    fprintf(co2_log_fp, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, data->co2_ppm, data->error_flag);
    fflush(co2_log_fp);
    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, data->co2_ppm, data->error_flag);
    free(timestamp);
    return 0;
}

// Function to log errors to a file
void error_log(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for error log\n");
        return;
    }

    fprintf(error_log_fp, "%s: %s\n", timestamp, message);
    fflush(error_log_fp);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    free(timestamp);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    unsigned char co2_data[9];
    sensor_data_t sensor_data;
    struct timespec sleep_time;
    sleep_time.tv_sec = LOG_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        fprintf(stderr, "Failed to open CO2 log file\n");
        gpioTerminate();
        return 1;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(co2_log_fp);
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        fclose(co2_log_fp);
        fclose(error_log_fp);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_co2_data(co2_data) == 0) {
            sensor_data = process_co2_data(co2_data);
            if (log_data(&sensor_data) != 0) {
                error_log("Failed to log data");
            }
        } else {
            error_log("Failed to read CO2 data");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    serClose(uart_handle);
    fclose(co2_log_fp);
    fclose(error_log_fp);
    gpioTerminate();

    return 0;
}

