#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Heading deviation threshold
#define HEADING_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// Hard-iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int configure_hmc5883l(int i2c_handle);
int read_hmc5883l_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void control_gpio(float heading);
void update_heading_buffer(float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to configure the HMC5883L
int configure_hmc5883l(int i2c_handle) {
    // Configure CONFIG_A register (0x00)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configure CONFIG_B register (0x01)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Configure MODE register (0x02) for continuous measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the HMC5883L
int read_hmc5883l_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes starting from register 0x03
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading_rad = atan2((float)y - Y_OFFSET, (float)x - X_OFFSET);
    float heading_deg = heading_rad * 180.0 / M_PI;

    // Normalize to 0-360 degrees
    if (heading_deg < 0) {
        heading_deg += 360.0;
    }

    return heading_deg;
}

// Function to control the GPIO pin
void control_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);

    // Normalize deviation to 0-180 degrees
    if (deviation > 180.0) {
        deviation = 360.0 - deviation;
    }

    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Function to update the circular buffer
void update_heading_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read data from HMC5883L
        if (read_hmc5883l_data(i2c_handle, &x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Control GPIO pin
            control_gpio(heading);

            // Update heading buffer
            update_heading_buffer(heading);

            // Print heading (for debugging)
            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Failed to read HMC5883L data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (configure_hmc5883l(i2c_handle) < 0) {
                    fprintf(stderr, "HMC5883L re-configuration failed\n");
                    terminate = 1;
                }
            }
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

