#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address for BH1750 sensor
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50.0
#define LUX_THRESHOLD_GREEN 150.0
#define LUX_THRESHOLD_BLUE 300.0

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    // Initialize relays to OFF state
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Failed to configure BH1750: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    unsigned char buffer[2];
    int result;

    // Wait for at least 120 ms for the first conversion
    gpioDelay(120000); // 120 ms

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data from BH1750: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Control relay states based on lux value
void control_relays(float lux) {
    if (lux < LUX_THRESHOLD_RED) {
        gpioWrite(RED_RELAY_PIN, 1);
        gpioWrite(GREEN_RELAY_PIN, 0);
        gpioWrite(BLUE_RELAY_PIN, 0);
    } else if (lux >= LUX_THRESHOLD_RED && lux < LUX_THRESHOLD_GREEN) {
        gpioWrite(RED_RELAY_PIN, 0);
        gpioWrite(GREEN_RELAY_PIN, 1);
        gpioWrite(BLUE_RELAY_PIN, 0);
    } else if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
        gpioWrite(RED_RELAY_PIN, 0);
        gpioWrite(GREEN_RELAY_PIN, 0);
        gpioWrite(BLUE_RELAY_PIN, 1);
    } else {
        gpioWrite(RED_RELAY_PIN, 1);
        gpioWrite(GREEN_RELAY_PIN, 1);
        gpioWrite(BLUE_RELAY_PIN, 1);
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    int red_state = gpioRead(RED_RELAY_PIN);
    int green_state = gpioRead(GREEN_RELAY_PIN);
    int blue_state = gpioRead(BLUE_RELAY_PIN);

    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off all relays
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        float lux = read_lux();

        if (lux >= 0) {
            // Control relays
            control_relays(lux);

            // Log data
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading lux value. Skipping relay control and logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

