        gpioWrite(GREEN_RELAY_PIN, 1);
        gpioWrite(BLUE_RELAY_PIN, 0);
    } else if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
        gpioWrite(RED_RELAY_PIN, 0);
        gpioWrite(GREEN_RELAY_PIN, 0);
        gpioWrite(BLUE_RELAY_PIN, 1);
    } else {
        gpioWrite(RED_RELAY_PIN, 1);
        gpioWrite(GREEN_RELAY_PIN, 1);
        gpioWrite(BLUE_RELAY_PIN, 1);
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    int red_state = gpioRead(RED_RELAY_PIN);
    int green_state = gpioRead(GREEN_RELAY_PIN);
    int blue_state = gpioRead(BLUE_RELAY_PIN);

    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off all relays
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        float lux = read_lux();

        if (lux >= 0) {
            // Control relays
            control_relays(lux);

            // Log data
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading lux value. Skipping relay control and logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

