// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Function prototypes
int map_distance_to_pwm(int distance);
void set_motor_direction(int motor, int direction, int pwm_value);
void control_motor(int motor, int distance);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);

    // Stop both motors
    set_motor_direction(0, 0, 0); // Motor A, stop
    set_motor_direction(1, 0, 0); // Motor B, stop

    gpioTerminate();
    exit(0);
}

// Function to map distance to PWM duty cycle
int map_distance_to_pwm(int distance) {
    int pwm_value = 255 - (distance - 10) * 255 / 90; // Linear mapping
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 255) {
        pwm_value = 255;
    }
    return pwm_value;
}

// Function to set motor direction and PWM duty cycle
void set_motor_direction(int motor, int direction, int pwm_value) {
    int in1, in2;

    if (motor == 0) { // Motor A
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else { // Motor B
        in1 = MOTOR_B_IN3;
        in2 = MOTOR_B_IN4;
    }

    if (direction == 1) { // Forward
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioPWM(in2, pwm_value);
    } else if (direction == -1) { // Backward
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
        gpioPWM(in2, pwm_value);
    } else { // Stop
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
        gpioPWM(in2, 0);
    }
}

// Function to control motor based on distance
void control_motor(int motor, int distance) {
    int pwm_value = map_distance_to_pwm(distance);
    int direction = (distance < 50) ? 1 : -1; // Forward if < 50cm, backward otherwise
    set_motor_direction(motor, direction, pwm_value);
}

int main(int argc, char *argv[]) {
    int distance_a, distance_b;

    // Check for correct number of command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Validate distance values
    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control pins
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        control_motor(0, distance_a); // Control Motor A
        control_motor(1, distance_b); // Control Motor B
        gpioDelay(100); // Delay for 100 ms
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    set_motor_direction(0, 0, 0); // Motor A, stop
    set_motor_direction(1, 0, 0); // Motor B, stop
    gpioTerminate();
    return 0;
}

