#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define MPU6050_ADDR 0x68
#define SDA_GPIO 2
#define SCL_GPIO 3
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000000 // 20ms (50Hz)
#define ACCEL_SCALE 16384.0  // Sensitivity scale factor for +/- 2g range
#define GYRO_SCALE 131.0     // Sensitivity scale factor for +/- 250 deg/s range
#define TILT_THRESHOLD 10.0  // Degrees
#define SERVO_CENTER_PULSE_WIDTH 1500000 // 1.5ms (90 degrees)
#define SERVO_MIN_PULSE_WIDTH 1000000   // 1ms (0 degrees)
#define SERVO_MAX_PULSE_WIDTH 2000000   // 2ms (180 degrees)
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define SERVO_ANGLE_RANGE 180.0
#define MAX_RETRIES 5

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, float *pitch, float *roll);
int init_pwm(int chip, int num);
int set_pwm_duty_cycle(int fd, int duty_cycle);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int sig);
int exponential_backoff(int (*func)(int, uint8_t, uint8_t*, int), int fd, uint8_t reg, uint8_t *data, int len, int max_retries);

// I2C read function with exponential backoff
int exponential_backoff(int (*func)(int, uint8_t, uint8_t*, int), int fd, uint8_t reg, uint8_t *data, int len, int max_retries) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < max_retries) {
        result = func(fd, reg, data, len);
        if (result == 0) {
            return 0; // Success
        }

        fprintf(stderr, "I2C error: %s (errno: %d). Retry %d/%d\n", strerror(errno), errno, retries + 1, max_retries);
        retries++;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
    }

    fprintf(stderr, "I2C error: Max retries reached. Giving up.\n");
    return -1; // Failure
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
