#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the transition duration (seconds)
#define TRANSITION_DURATION 1800

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 0 = off, 1 = on
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static FILE *schedule_file = NULL;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t *schedule, int max_entries);
int parse_time(const char *time_str, int *hour, int *minute, int *second);
int parse_relay_state(const char *state_str, int *relay_number, int *state);
int set_relay_state(int relay_number, int state);
int fade_lamp(int relay_number, int target_state, int duration);
void signal_handler(int signal);

// Function to read the schedule from the file
int read_schedule(const char *filename, schedule_entry_t *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), fp) != NULL && count < max_entries) {
        // Remove trailing newline character
        line[strcspn(line, "\n")] = 0;

        int hour, minute, second, relay_number, state;
        if (parse_time(line, &hour, &minute, &second) != 0) {
            fprintf(stderr, "Error parsing time in line: %s\n", line);
            continue;
        }

        if (parse_relay_state(line + 8, &relay_number, &state) != 0) {
            fprintf(stderr, "Error parsing relay state in line: %s\n", line);
            continue;
        }

        schedule[count].hour = hour;
        schedule[count].minute = minute;
        schedule[count].second = second;
        schedule[count].relay_number = relay_number;
        schedule[count].state = state;

        count++;
    }

    fclose(fp);
    return count;
}

// Function to parse the time string
int parse_time(const char *time_str, int *hour, int *minute, int *second) {
    if (sscanf(time_str, "%d:%d:%d", hour, minute, second) != 3) {
        return -1;
    }
    return 0;
}

// Function to parse the relay state string
int parse_relay_state(const char *state_str, int *relay_number, int *state) {
    if (strncmp(state_str, "relay", 5) != 0) {
        return -1;
    }

    if (sscanf(state_str + 5, "%d,%d", relay_number, state) != 2) {
        return -1;
    }

    if (*relay_number < 1 || *relay_number > 4) {
        return -1;
    }

    if (*state != 0 && *state != 1) {
        return -1;
    }

    return 0;
}

