#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 30.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 500000   // 0.5 seconds
#define MEASUREMENT_GAP_MS 60 // 60 ms

// Global variables
static volatile int running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float measure_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that rising edge has been received
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Reset flag after falling edge
    }
}

// Function to measure the distance using the HC-SR04 sensor
float measure_distance() {
    start_tick = 0;
    end_tick = 0;
    echo_received = 0;

    trigger_sensor();

    uint32_t start_time = gpioTick();
    while (echo_received == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (end_tick == 0 || start_tick == 0) {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 58.0; // Speed of sound in cm/us / 2

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    int range = 1000; // PWM range
    int duty_cycle = (int)(range * frequency / MAX_FREQUENCY); // Calculate duty cycle

    gpioPWM(BUZZER_PIN, duty_cycle);
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();        // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(BUZZER_PIN, 1000);
    gpioSetPWMfrequency(BUZZER_PIN, 10000); // Set a base frequency

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
        } else {
            gpioPWM(BUZZER_PIN, 0); // Silence the buzzer on error
        }

        gpioDelay(20); // 20 ms delay (50 Hz loop)
        usleep(MEASUREMENT_GAP_MS * 1000); // 60 ms gap
    }

    cleanup();
    return 0;
}

