#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, red) != 0) {
        fprintf(stderr, "Error setting red PWM value\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Error setting green PWM value\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) != 0) {
        fprintf(stderr, "Error setting blue PWM value\n");
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RED_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GREEN_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting BLUE_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    double time = 0.0;
    while (!terminate) {
        // Calculate proximity value (sine wave)
        double proximity = 0.5 * (1.0 + sin(time));

        // Map proximity value to RGB color space
        int red, green, blue;

        if (proximity < 0.33) {
            // Red to Green transition
            red = (int)(255 * (proximity / 0.33));
            green = (int)(255 * ((1.0 - proximity) / 0.33));
            blue = 0;
        } else if (proximity < 0.66) {
            // Green to Blue transition
            red = 0;
            green = (int)(255 * ((proximity - 0.33) / 0.33));
            blue = (int)(255 * ((1.0 - proximity) / 0.33));
        } else {
            // Blue to Red transition
            red = (int)(255 * ((proximity - 0.66) / 0.34));
            green = 0;
            blue = (int)(255 * ((1.0 - proximity) / 0.34));
        }

        // Set LED color
        if (set_led_color(red, green, blue) != 0) {
            fprintf(stderr, "Error setting LED color, exiting...\n");
            break;
        }

        // Increment time
        time += 0.01;

        // Delay
