#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SCALE_FACTOR 131.0

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global file descriptor for I2C device
int i2c_fd = -1;

// Global file pointer for log file
FILE *log_fp = NULL;

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Close I2C device if open
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file if open
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    uint8_t buf[2];

    // Wake up the MPU-6050 (set PWR_MGMT_1 to 0)
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[1];
    uint8_t data[6];

    // Set the register to read from (GYRO_XOUT_H)
    buf[0] = GYRO_XOUT_H;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to set gyro register");
        return -1;
    }

    // Read 6 bytes of gyroscope data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read gyro data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to convert raw data to degrees/second
void convert_to_degrees(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / GYRO_SCALE_FACTOR;
    *y_dps = (float)y / GYRO_SCALE_FACTOR;
    *z_dps = (float)z / GYRO_SCALE_FACTOR;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    return 0;
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to degrees/second
            convert_to_degrees(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            if (log_data(log_fp, gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, but continuing...\n");
        }

        // Wait 100ms
        usleep(100000);
    }

    return 0;
}

