#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequencies in Hz)
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t running = 1;
volatile int button_pressed = 0;
volatile int melody_playing = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Button interrupt handler function
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        button_pressed = 1;
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody() {
    melody_playing = 1;
    for (int i = 0; i < melody_length && melody_playing; ++i) {
        gpioHardwarePWM(BUZZER_PIN, melody[i], 500000); // 50% duty cycle
        gpioDelay(200); // Play each note for 200ms
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the tone
        gpioDelay(50); // Short pause between notes
    }
    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    melody_playing = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the tone
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical Doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            if (melody_playing) {
                stop_melody();
            } else {
                play_melody();
            }
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

