#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT 1000
#define EARTHQUAKE_THRESHOLD 3
#define EARTHQUAKE_WINDOW_SIZE 5

// Structure to hold vibration event data
typedef struct {
    struct timespec timestamp;
    int value;
} VibrationEvent;

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static VibrationEvent event_window[EARTHQUKE_WINDOW_SIZE];
static int window_index = 0;
static int window_count = 0;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
int read_sensor(void);
char* get_iso8601_timestamp(void);
int log_event(const char *timestamp, int value);
int check_earthquake(void);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
