#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// Magnetometer Registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Calibration Offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass Directions
const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float calibrated_x, float calibrated_y);
const char *map_heading_to_direction(float heading);
int log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_h, x_l, z_h, z_l, y_h, y_l;

    if (i2c_read_reg(fd, OUT_X_H_M, &x_h) != 0) return -1;
    if (i2c_read_reg(fd, OUT_X_L_M, &x_l) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_H_M, &z_h) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_L_M, &z_l) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_H_M, &y_h) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_L_M, &y_l) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *z = (int16_t)((z_h << 8) | z_l);
    *y = (int16_t)((y_h << 8) | y_l);

    return 0;
}

// Function to calibrate magnetometer data
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Function to calculate compass heading
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2f(calibrated_y, calibrated_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to map heading to compass direction
const char *map_heading_to_direction(float heading) {
    int index = (int)(heading / 45) % 8;
    return directions[index];
}

// Function to log data to CSV file
int log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading) < 0) {
        perror("Failed to write to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z, heading;
    const char *direction;
    char filename[] = "mag_log.csv";
    int file_exists = 0;

    // Check if the file exists
    if (access(filename, F_OK) == 0) {
        file_exists = 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize magnetometer (Continuous conversion mode, 15 Hz output data rate)
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    if (!file_exists) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate compass heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to compass direction
            direction = map_heading_to_direction(heading);

            // Log data to CSV file
            if (log_data(csv_file, calibrated_x, calibrated_y, calibrated_z, heading) != 0) {
                program_running = 0; // Stop if logging fails
            }

            // Print compass direction and heading
            printf("Direction: %s, Heading: %.2f\n", direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

