    char filename[] = "mag_log.csv";
    int file_exists = 0;

    // Check if the file exists
    if (access(filename, F_OK) == 0) {
        file_exists = 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize magnetometer (Continuous conversion mode, 15 Hz output data rate)
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    if (!file_exists) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate compass heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to compass direction
            direction = map_heading_to_direction(heading);

            // Log data to CSV file
            if (log_data(csv_file, calibrated_x, calibrated_y, calibrated_z, heading) != 0) {
                program_running = 0; // Stop if logging fails
            }

            // Print compass direction and heading
            printf("Direction: %s, Heading: %.2f\n", direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

