#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 200 // milliseconds

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the relay state to a JSON file
int log_relay_state(int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return -1;
    }

    if (log_file == NULL) {
        log_file = fopen("relay_log.json", "a");
        if (log_file == NULL) {
            perror("Failed to open relay_log.json");
            free(timestamp);
            return -1;
        }
    }

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    if (log_relay_state(relay_state) != 0) {
        fprintf(stderr, "Error logging relay state.\n");
    }
}

// Interrupt service routine (ISR) for the touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();
    if (level == 1 && (current_time - last_touch_time) > (DEBOUNCE_DELAY * 1000)) { // Convert ms to us
        toggle_relay();
        last_touch_time = current_time;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    log_relay_state(0); // Log the final OFF state
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    log_relay_state(0);

    // Set up interrupt service routine for the touch sensor
    if (gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, touch_callback) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Relay control program running. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

