#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the activation duration (seconds)
#define ACTIVATION_DURATION 5

// Define the delay between activations (seconds)
#define ACTIVATION_DELAY 1

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay1_line = NULL;
struct gpiod_line *relay2_line = NULL;
struct gpiod_line *relay3_line = NULL;
struct gpiod_line *relay4_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_relay_state(int pin, int state);
int get_moisture_level();
int log_irrigation_event(int relay_number, int moisture_level);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up and exiting...\n");
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO chip and lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get the GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    // Request the GPIO lines as outputs with initial value 1 (OFF)
    ret = gpiod_line_request_output(relay1_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY1_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY2_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY3_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY4_PIN, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to set the state of a relay
int set_relay_state(int pin, int state) {
    struct gpiod_line *line;
    int ret;

    if (pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Invalid relay pin: %d\n", pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d to value %d: %s\n", pin, state, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to generate a simulated soil moisture level
int get_moisture_level() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to log irrigation events to a file
int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Get the simulated moisture level
        moisture_level = get_moisture_level();

        // Check if irrigation is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stderr, "Moisture level is low (%d), activating relays.\n", moisture_level);

            // Activate relays sequentially
            for (i = 1; i <= 4; i++) {
                if (set_relay_state(RELAY1_PIN, 0) != 0) {
                    fprintf(stderr, "Error setting relay %d state.\n", i);
                }
                log_irrigation_event(i, moisture_level);
                sleep(ACTIVATION_DURATION);
                if (set_relay_state(RELAY1_PIN, 1) != 0) {
                    fprintf(stderr, "Error setting relay %d state.\n", i);
                }
                sleep(ACTIVATION_DELAY);
            }
        } else {
            fprintf(stderr, "Moisture level is sufficient (%d). No irrigation needed.\n", moisture_level);
        }

        // Wait for 10 seconds
        sleep(10);
    }

    return 0;
}

