#define NOZZLE_ANGLES {0, 45, 90, 135, 180}

// Define watering sequence parameters
#define WATERING_STEP_DELAY 2 // seconds
#define WATERING_HOLD_DELAY 5 // seconds

// Define moisture sensor readings
#define MOISTURE_READINGS {20, 40, 60, 80, 100}

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set servo pulse width with retry
int set_servo_pulse_width(int gpio, int pulse_width)
{
    int result, retries = 0;
    while (retries < 3) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retry %d/3\n", gpio, result, retries + 1);
            retries++;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Critical error: Failed to set servo pulse width for GPIO %d after 3 retries.\n", gpio);
    return -1; // Failure
}

// Function to open the water valve
int open_valve()
{
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (SERVO_90_DEGREES * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);
    if (set_servo_pulse_width(VALVE_SERVO_PIN, pulse_width) != 0) {
        return -1; // Failure
    }
    gpioDelay(500); // Allow servo to move
    return 0; // Success
}

// Function to close the water valve
int close_valve()
{
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (SERVO_0_DEGREES * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);
    if (set_servo_pulse_width(VALVE_SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to close valve.\n");
        return -1; // Failure
    }
    gpioDelay(500); // Allow servo to move
    return 0; // Success
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle)
{
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);
    if (set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set nozzle angle to %d degrees.\n", angle);
        return -1; // Failure
    }
    gpioDelay(500); // Allow servo to move
    return 0; // Success
}

// Function to perform the watering sequence
void perform_watering_sequence()
{
    int angles[] = NOZZLE_ANGLES;
    int num_angles = sizeof(angles) / sizeof(angles[0]);

    if (open_valve() != 0) {
        fprintf(stderr, "Error: Failed to open valve, aborting watering sequence.\n");
        return;
    }

    for (int i = 0; i < num_angles; i++) {
        if (set_nozzle_angle(angles[i]) != 0) {
            fprintf(stderr, "Error: Failed to set nozzle angle to %d degrees, continuing to next angle.\n", angles[i]);
            continue; // Continue to the next angle
        }
        gpioDelay(WATERING_STEP_DELAY * 1000); // Wait for watering step delay
    }

    gpioDelay(WATERING_HOLD_DELAY * 1000); // Hold at the last angle

    if (close_valve() != 0) {
        fprintf(stderr, "Error: Failed to close valve after watering sequence.\n");
    }
}

