    signal(SIGTERM, signal_handler);

    // Main loop
    int moisture_readings[] = MOISTURE_READINGS;
    int num_readings = sizeof(moisture_readings) / sizeof(moisture_readings[0]);
    int reading_index = 0;

    while (!terminate) {
        int moisture_level = moisture_readings[reading_index];
        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold, initiating watering sequence.\n");
            perform_watering_sequence();
        } else {
            printf("Moisture level above threshold, skipping watering.\n");
        }

        reading_index = (reading_index + 1) % num_readings; // Cycle through moisture readings
        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    set_servo_pulse_width(VALVE_SERVO_PIN, 0); // Close valve
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0); // Stop nozzle
    gpioTerminate(); // Terminate pigpio
    return 0;
}

