#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// File to log data to
#define LOG_FILE "gyro_log.txt"

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    uint8_t buf[2];

    // Wake up the MPU-6050
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t buf[14];
    int16_t raw_x, raw_y, raw_z;

    // Read all gyroscope data registers in one go
    buf[0] = GYRO_XOUT_H;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H");
        data.x = data.y = data.z = NAN; // Indicate error with NaN
        return data;
    }

    if (read(i2c_fd, buf, 14) != 14) {
        perror("Error reading gyroscope data");
        data.x = data.y = data.z = NAN; // Indicate error with NaN
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees/second
    data.x = (float)raw_x / GYRO_SCALE;
    data.y = (float)raw_y / GYRO_SCALE;
    data.z = (float)raw_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_fp, "%.6f,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = 100000000; // 10 Hz (100 ms)

    while (!terminate) {
        gyro_data_t data = read_gyro_data();

        if (!isnan(data.x) && !isnan(data.y) && !isnan(data.z)) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading gyro data, skipping logging.\n");
        }

        nanosleep(&req, &rem);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

