#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 500 // 50 cm in mm
#define POLLING_INTERVAL 100 // milliseconds

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;
    unsigned char model_id, revision_id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (unsigned char)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading revision ID: %d\n", status);
        return -1;
    }
    revision_id = (unsigned char)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Reset the sensor
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure for short-range mode
    status = i2cWriteByteData(i2c_handle, 0x0080, 0x01); // Start ranging
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    int status;
    unsigned char range_status;
    unsigned char msb, lsb;

    // Check for data ready
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", status);
        return -1;
    }
    range_status = (unsigned char)status;

    if (!(range_status & 0x01)) {
        // Data not ready
        return -1;
    }

    // Read distance
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", status);
        return -1;
    }
    msb = (unsigned char)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", status);
        return -1;
    }
    lsb = (unsigned char)status;

    *distance = (msb << 8) | lsb;

    return 0;
}

// Relay control function
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Open door
        printf("Distance: %d mm, Door: OPEN\n", distance);
    } else {
        gpioWrite(GPIO_RELAY, 0); // Close door
        printf("Distance: %d mm, Door: CLOSED\n", distance);
    }
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is initially off

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            control_relay(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(POLLING_INTERVAL * 1000); // Delay for polling interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

