#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor (131.0 LSB/dps)
#define GYRO_SENSITIVITY 131.0

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for multi-read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading multiple bytes from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error setting gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_regs(fd, GYRO_XOUT_H, buf, 6) != 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw data to degrees/second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / GYRO_SENSITIVITY;
    *y_dps = (float)y / GYRO_SENSITIVITY;
    *z_dps = (float)z / GYRO_SENSITIVITY;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully\n");

    // Main loop
    while (1) {
        int16_t x, y, z;
        float x_dps, y_dps, z_dps;

        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Convert to degrees/second
            convert_to_dps(x, y, z, &x_dps, &y_dps, &z_dps);

            // Log the data
            printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100ms
        usleep(100000);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    close(i2c_fd);
    return 0;
}

