#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define watering interval (seconds)
#define WATERING_INTERVAL 86400

// Define relay activation duration (seconds)
#define RELAY_DURATION 5

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_watering_event(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay1_line, &config, 1) < 0 ||
        gpiod_line_request(relay2_line, &config, 1) < 0 ||
        gpiod_line_request(relay3_line, &config, 1) < 0 ||
        gpiod_line_request(relay4_line, &config, 1) < 0) {
        perror("Error requesting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Set all relays to HIGH (inactive)
    gpiod_line_set_value(relay1_line, 1);
    gpiod_line_set_value(relay2_line, 1);
    gpiod_line_set_value(relay3_line, 1);
    gpiod_line_set_value(relay4_line, 1);

    return 0;
}

// Activate a relay
void activate_relay(int relay_pin) {
    struct gpiod_line *line;

    if (relay_pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (relay_pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (relay_pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (relay_pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Invalid relay pin: %d\n", relay_pin);
        return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Deactivate a relay
void deactivate_relay(int relay_pin) {
    struct gpiod_line *line;

    if (relay_pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (relay_pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (relay_pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (relay_pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Invalid relay pin: %d\n", relay_pin);
        return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Log watering event
void log_watering_event(void) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s: Watering cycle started\n", buf);
    fclose(log_file);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY4_PIN);

        // Log watering event
        log_watering_event();

        // Wait for the next watering interval
        sleep(WATERING_INTERVAL);
    }

    return 0;
}

