    } else {
        fprintf(stderr, "Invalid relay pin: %d\n", relay_pin);
        return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Deactivate a relay
void deactivate_relay(int relay_pin) {
    struct gpiod_line *line;

    if (relay_pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (relay_pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (relay_pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (relay_pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Invalid relay pin: %d\n", relay_pin);
        return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Log watering event
void log_watering_event(void) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s: Watering cycle started\n", buf);
    fclose(log_file);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        sleep(RELAY_DURATION);
        deactivate_relay(RELAY4_PIN);

        // Log watering event
        log_watering_event();

        // Wait for the next watering interval
        sleep(WATERING_INTERVAL);
    }

    return 0;
}

