#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0f

// Structure to hold gyroscope data and timestamp
typedef struct {
    float x;
    float y;
    float z;
    struct timespec timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Set sample rate divider
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
        if (status < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
            retries--;
            gpioDelay(1000);
            continue;
        }

        // Set gyroscope configuration
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            retries--;
            gpioDelay(1000);
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I: %d\n", who_am_i);
            retries--;
            gpioDelay(1000);
            continue;
        }

        if (who_am_i != 0x68) {
            fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x68\n", who_am_i);
            retries--;
            gpioDelay(1000);
            continue;
        }

        printf("MPU-6050 initialized successfully\n");
        return 0; // Initialization successful
    }

    fprintf(stderr, "MPU-6050 initialization failed after multiple retries\n");
    return -1; // Initialization failed
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_threshold(float x, float y, float z) {
    if (fabs(x) > 250.0f || fabs(y) > 250.0f || fabs(z) > 250.0f) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before re-initializing
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() != 0) {
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(50000); // 50 ms delay (20 Hz sampling rate)
    }

    return 0;
}

