            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() != 0) {
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(50000); // 50 ms delay (20 Hz sampling rate)
    }

    return 0;
}

