        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Chip select initialization function
int cs_init(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
