int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];
    struct spi_ioc_transfer tr;
    int retries = RETRY_COUNT;

    // Construct the transmit buffer (address + dummy data for reading)
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read bit set
    for (int i = 1; i < 7; i++) {
        tx_buf[i] = 0x00; // Dummy data
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 7;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    while (retries > 0) {
        gpiod_line_set_value(cs_line, 0); // Assert CS
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
            perror("Error sending SPI message");
            gpiod_line_set_value(cs_line, 1); // Deassert CS
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }
        gpiod_line_set_value(cs_line, 1); // Deassert CS

        // Combine high and low bytes for each axis
        *x_rate = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
        *y_rate = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
        *z_rate = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

        return 0; // Success
    }

    log_error("Failed to read gyro data after multiple retries.");
    return -1; // Failure
