    // Initialize resources
    spi_fd = spi_init();
    if (spi_fd < 0) {
        log_error("SPI initialization failed");
        return EXIT_FAILURE;
    }

    if (cs_init() < 0) {
        log_error("Chip select initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("Error opening error log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate_raw, &y_rate_raw, &z_rate_raw) == 0) {
            x_rate_dps = convert_to_dps(x_rate_raw);
            y_rate_dps = convert_to_dps(y_rate_raw);
