            if (log_data(x_rate_dps, y_rate_dps, z_rate_dps) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read gyro data");
        }

        usleep(10000); // 10 ms delay
    }

    // Clean up and exit
    cleanup();
    return EXIT_SUCCESS;
}

