#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_word(int fd, unsigned char reg);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(FILE *fp, int ambient_light, int proximity);
void signal_handler(int sig);

// I2C read word function with retries
int i2c_read_word(int fd, unsigned char reg) {
    int retries = 3;
    int result = -1;
    unsigned char buf[2];

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register address) failed");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        if (read(fd, buf, 2) == 2) {
