#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADXRS290 register addresses
#define ADXRS290_X_RATE_REG 0x02
#define ADXRS290_Y_RATE_REG 0x04

// Define ADXRS290 sensitivity
#define ADXRS290_SENSITIVITY 200.0 // LSB/deg/s

// Define data file name
#define DATA_FILE "gyro_data.csv"

// Global variables
int spi_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int initialize_spi();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    int retries = 3;
    while (retries > 0) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle >= 0) {
            printf("SPI initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing SPI (attempt %d): %d\n", 4 - retries, spi_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize SPI after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char tx_buffer[3];
    char rx_buffer[3];

    // Read X axis data
    tx_buffer[0] = ADXRS290_X_RATE_REG | 0x80; // Set read bit
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error reading X axis data.\n");
        data.x_rate = 0; // Indicate error
    } else {
        data.x_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[2]);
    }

    // Read Y axis data
    tx_buffer[0] = ADXRS290_Y_RATE_REG | 0x80; // Set read bit
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error reading Y axis data.\n");
        data.y_rate = 0; // Indicate error
    } else {
        data.y_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[2]);
    }

    return data;
}

// Function to log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(data_file, "%lf,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(data_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "w");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to data file
    fprintf(data_file, "timestamp,X_rate,Y_rate\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup
    printf("Closing SPI...\n");
    spiClose(spi_handle);

    printf("Closing data file...\n");
    fclose(data_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

