#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define seismic event duration threshold (in milliseconds)
#define SEISMIC_DURATION 500

// Global variables
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static volatile unsigned long start_time = 0;
static volatile int seismic_event = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, unsigned int tick, void *userdata);
void sensor2_callback(int gpio, int level, unsigned int tick, void *userdata);
void trigger_alert();
void log_seismic_event();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int state;
    void (*callback)(int, int, unsigned int, void*);
} sensor_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *userdata) {
    sensor1_state = level;
    if (sensor1_state == 1 && sensor2_state == 1) {
        if (start_time == 0) {
            start_time = tick;
        }
    } else {
        start_time = 0;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *userdata) {
    sensor2_state = level;
    if (sensor1_state == 1 && sensor2_state == 1) {
        if (start_time == 0) {
            start_time = tick;
        }
    } else {
        start_time = 0;
    }
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
    gpioDelay(2000);         // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
}

// Function to log a seismic event
void log_seismic_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    gpioTerminate();         // Terminate pigpio

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register callbacks for sensor 1 and sensor 2
    if (gpioSetAlertFuncEx(SENSOR1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(SENSOR2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (sensor1_state == 1 && sensor2_state == 1) {
            if (start_time != 0) {
                unsigned long current_time = gpioTick();
                if ((current_time - start_time) >= SEISMIC_DURATION * 1000) {
                    if (!seismic_event) {
                        trigger_alert();
                        log_seismic_event();
                        seismic_event = 1; // Prevent multiple triggers for the same event
                    }
                }
            }
        } else {
            start_time = 0;
            seismic_event = 0; // Reset seismic event flag
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

