#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// LED GPIO
#define LED_GPIO 17

// Angular Velocity Threshold
#define ANGULAR_VELOCITY_THRESHOLD 20.0

// Circular Buffer Configuration
#define BUFFER_SIZE 100

// Structure for storing timestamped angular rate
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} AngularRateData;

// Circular Buffer Structure
typedef struct {
    AngularRateData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global Variables
int spi_handle;
CircularBuffer angular_rate_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_spi();
int read_gyro_data(int *x_rate);
float convert_to_dps(int16_t raw_rate);
void add_to_buffer(CircularBuffer *cb, struct timespec timestamp, float angular_rate);
int get_latest_reading(CircularBuffer *cb, AngularRateData *data);
void control_led(float angular_rate);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Initialize Circular Buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read Gyro Data
int read_gyro_data(int *x_rate) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Read RATE_XL
    tx_buffer[0] = RATE_XL | 0x80; // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 2) {
        fprintf(stderr, "Error reading RATE_XL\n");
        return -1;
    }
    int16_t rate_xl = rx_buffer[1];

    // Read RATE_XH
    tx_buffer[0] = RATE_XH | 0x80; // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 2) {
        fprintf(stderr, "Error reading RATE_XH\n");
        return -1;
    }
    int16_t rate_xh = rx_buffer[1];

    *x_rate = (rate_xh << 8) | rate_xl;
    return 0;
}

// Convert to Degrees Per Second
float convert_to_dps(int16_t raw_rate) {
    return (float)raw_rate / 200.0;
}

// Add to Circular Buffer
void add_to_buffer(CircularBuffer *cb, struct timespec timestamp, float angular_rate) {
    cb->buffer[cb->head].timestamp = timestamp;
    cb->buffer[cb->head].angular_rate = angular_rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

// Get Latest Reading
int get_latest_reading(CircularBuffer *cb, AngularRateData *data) {
    if (cb->count == 0) {
        return -1; // Buffer is empty
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *data = cb->buffer[index];
    return 0;
}

// Control LED
void control_led(float angular_rate) {
    if (fabs(angular_rate) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize Circular Buffer
    init_circular_buffer(&angular_rate_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_rate;
        if (read_gyro_data(&raw_rate) == 0) {
            float angular_rate = convert_to_dps(raw_rate);

            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);

            add_to_buffer(&angular_rate_buffer, ts, angular_rate);

            control_led(angular_rate);

            printf("Angular Rate: %.2f deg/s\n", angular_rate);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

