#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration_seconds) {
    int i;
    int num_steps = 256; // Number of PWM steps
    int delay_us = (duration_seconds * 1000000) / num_steps; // Delay between steps in microseconds

    for (i = 255; i >= 0; i--) {
        if (!program_running) return; // Check for termination signal
        set_lamp_brightness(gpio, i);
        usleep(delay_us);
    }
}

int main(int argc, char *argv[]) {
    int duration_seconds;

    // Check if the correct number of command-line arguments is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the command-line argument to an integer
    duration_seconds = atoi(argv[1]);

    // Validate the duration
    if (duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency to 100 Hz
    gpioSetPWMfrequency(LAMP1_GPIO, 100);
    gpioSetPWMfrequency(LAMP2_GPIO, 100);
    gpioSetPWMfrequency(LAMP3_GPIO, 100);

    // Set PWM range to 255
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Sunset Simulator started. Duration: %d seconds\n", duration_seconds);

    // Fade each lamp sequentially
    fade_lamp(LAMP1_GPIO, duration_seconds);
    if (!program_running) {
        printf("Lamp 1 fade interrupted.\n");
        goto cleanup;
    }
    printf("Lamp 1 fade complete.\n");

    fade_lamp(LAMP2_GPIO, duration_seconds);
    if (!program_running) {
        printf("Lamp 2 fade interrupted.\n");
        goto cleanup;
    }
    printf("Lamp 2 fade complete.\n");

    fade_lamp(LAMP3_GPIO, duration_seconds);
    if (!program_running) {
        printf("Lamp 3 fade interrupted.\n");
        goto cleanup;
    }
    printf("Lamp 3 fade complete.\n");

    printf("Smart Sunset Simulator complete.\n");

cleanup:
    // Turn off all lamps
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

