#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>

// Define GPIO pins for the traffic light
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the number of lines (relays)
#define NUM_LINES 4

// Define the signal handler function prototype
typedef void (*signal_handler_t)(int);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_LINES] = {NULL, NULL, NULL, NULL};

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_state(int pin, int value) {
    int ret;
    struct gpiod_line *line;

    // Find the line corresponding to the pin
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i] != NULL && gpiod_line_get_offset(lines[i]) == pin) {
            line = lines[i];
            break;
        }
        line = NULL; // Ensure line is initialized
    }

    if (line == NULL) {
        fprintf(stderr, "Error: GPIO line for pin %d not found.\n", pin);
        return -1;
    }

    // Set the value of the line
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set value for pin %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to run the traffic light sequence
void run_traffic_light() {
    // Red
    printf("Red\n");
    if (set_gpio_state(RED_PIN, 0) < 0) return;
    if (set_gpio_state(YELLOW_PIN, 1) < 0) return;
    if (set_gpio_state(GREEN_PIN, 1) < 0) return;
    if (set_gpio_state(BLUE_PIN, 1) < 0) return;
    sleep(10);

    // Red + Yellow
    printf("Red + Yellow\n");
    if (set_gpio_state(RED_PIN, 0) < 0) return;
