#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *flame_sensor_line;
struct gpiod_line *buzzer_line;
struct gpiod_line *led_line;

// Global variable for log file
FILE *log_file;

// Function prototypes
int read_flame_sensor(struct gpiod_line *line);
void activate_buzzer(struct gpiod_line *line);
void deactivate_buzzer(struct gpiod_line *line);
void activate_led(struct gpiod_line *line);
void deactivate_led(struct gpiod_line *line);
void log_flame_detection(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read the flame sensor with debouncing
int read_flame_sensor(struct gpiod_line *line) {
    int value1, value2, value3;
    struct timespec delay = {0, 50000000}; // 50ms

    value1 = gpiod_line_get_value(line);
    if (value1 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    nanosleep(&delay, NULL);

    value2 = gpiod_line_get_value(line);
    if (value2 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    nanosleep(&delay, NULL);

    value3 = gpiod_line_get_value(line);
    if (value3 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    return (value1 == 0 && value2 == 0 && value3 == 0) ? 1 : 0; // Flame detected if all reads are LOW
}

// Function to activate the buzzer
void activate_buzzer(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
    }
}

// Function to activate the LED
void activate_led(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error activating LED: %s\n", strerror(errno));
    }
}

// Function to deactivate the LED
void deactivate_led(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error deactivating LED: %s\n", strerror(errno));
    }
}

// Function to log flame detection events
void log_flame_detection(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

