void deactivate_buzzer(struct gpiod_line *line);
void activate_led(struct gpiod_line *line);
void deactivate_led(struct gpiod_line *line);
void log_flame_detection(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read the flame sensor with debouncing
int read_flame_sensor(struct gpiod_line *line) {
    int value1, value2, value3;
    struct timespec delay = {0, 50000000}; // 50ms

    value1 = gpiod_line_get_value(line);
    if (value1 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    nanosleep(&delay, NULL);

    value2 = gpiod_line_get_value(line);
    if (value2 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    nanosleep(&delay, NULL);

    value3 = gpiod_line_get_value(line);
    if (value3 < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    return (value1 == 0 && value2 == 0 && value3 == 0) ? 1 : 0; // Flame detected if all reads are LOW
}

// Function to activate the buzzer
void activate_buzzer(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
    }
}

