// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Define delay between dispenses (seconds)
#define DISPENSE_DELAY 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin);
int deactivate_solenoid(int pin);
int dispense();
int log_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to perform the dispensing sequence
int dispense() {
    if (activate_solenoid(SOLENOID_1_PIN) != 0) return 1;
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Convert ms to microseconds
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) return 1;

    if (activate_solenoid(SOLENOID_2_PIN) != 0) return 1;
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Convert ms to microseconds
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) return 1;

    return 0;
}

// Function to log dispense events to a file
int log_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
            timestamp, solenoid1_pin, solenoid2_pin, duration_ms);

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense() != 0) {
            fprintf(stderr, "Dispense failed\n");
        }

        if (log_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(DISPENSE_DELAY * 1000000); // Convert seconds to microseconds
    }

    // Cleanup before exiting
    printf("Cleaning up...\n");
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

