#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_motor_speed(int motor, int speed);
float calculate_pid(float error, float *integral, float *previous_error);
float simulate_tilt_error();
float simulate_distance();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void stop_motors();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable motors (H-bridge enable pins HIGH)
    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    return 0;
}

// Set motor speed and direction
void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin;

    if (motor == 0) { // Motor A
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else { // Motor B
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    }
}

// Calculate PID output
float calculate_pid(float error, float *integral, float *previous_error) {
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Simulate tilt error
float simulate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Simulate distance sensor
float simulate_distance() {
    return ((float)rand() / RAND_MAX) * 380.0 + 2.0;
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Stop motors
void stop_motors() {
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    float tilt_error, distance, pid_output;
    int motor_a_speed, motor_b_speed;
    float integral = 0.0, previous_error = 0.0;

    // Main loop
    while (program_running) {
        // Simulate sensor readings
        tilt_error = simulate_tilt_error();
        distance = simulate_distance();

        // Calculate PID output
        pid_output = calculate_pid(tilt_error, &integral, &previous_error);

        // Obstacle avoidance
        if (distance < 20.0) {
            motor_a_speed = 128;
            motor_b_speed = 128;
        } else {
            // Map PID output to motor speeds
            motor_a_speed = (int)pid_output;
            motor_b_speed = (int)pid_output;

            // Clamp motor speeds to +/- 255
            if (motor_a_speed > 255) motor_a_speed = 255;
            if (motor_a_speed < -255) motor_a_speed = -255;
            if (motor_b_speed > 255) motor_b_speed = 255;
            if (motor_b_speed < -255) motor_b_speed = -255;
        }

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Stop motors and close log file
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

