#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    return 0; // Indicate success
}

// Read touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Toggle relay
            toggle_relay();
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

