#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // 16-bit
#define FRAME_SIZE 1024

// Define PWM range
#define PWM_RANGE 255

// Define default sensitivity
#define DEFAULT_SENSITIVITY 1.0

// Define color transition points
#define LOW_AMPLITUDE_THRESHOLD 500
#define HIGH_AMPLITUDE_THRESHOLD 2000

// Global variables
snd_pcm_t *pcm_handle;
double sensitivity = DEFAULT_SENSITIVITY;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int read_audio_data(snd_pcm_t *pcm_handle, short *buffer, int frame_size);
double calculate_rms(const short *buffer, int frame_size);
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue);
int set_led_color(int red, int green, int blue);
void signal_handler(int sig);
void cleanup(snd_pcm_t *pcm_handle);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, FRAME_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Read audio data from ALSA
int read_audio_data(snd_pcm_t *pcm_handle, short *buffer, int frame_size) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, frame_size)) != frame_size) {
        fprintf(stderr, "Error reading audio data: %s\n", snd_strerror(err));
        if (err == -EPIPE) {
            fprintf(stderr, "Recovering from EPIPE...\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Recovering from ESTRPIPE...\n");
            snd_pcm_resume(pcm_handle);
        } else {
            return -1;
        }
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int frame_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < frame_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    double mean_square = sum_of_squares / frame_size;
    return sqrt(mean_square);
}

// Map amplitude to RGB color values
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue) {
    double normalized_amplitude = amplitude / HIGH_AMPLITUDE_THRESHOLD;
    if (normalized_amplitude > 1.0) {
        normalized_amplitude = 1.0;
    }

    if (amplitude < LOW_AMPLITUDE_THRESHOLD) {
        // Cool colors (blue to green)
        *red = (int)(normalized_amplitude * 255);
        *green = (int)((1.0 - normalized_amplitude) * 255);
        *blue = 255;
    } else if (amplitude > HIGH_AMPLITUDE_THRESHOLD) {
        // Warm colors (red to yellow)
        *red = 255;
        *green = (int)(normalized_amplitude * 255);
        *blue = (int)((1.0 - normalized_amplitude) * 255);
    } else {
        // Transition between cool and warm colors
        double midpoint = (LOW_AMPLITUDE_THRESHOLD + HIGH_AMPLITUDE_THRESHOLD) / 2.0;
        double transition_point = (amplitude - LOW_AMPLITUDE_THRESHOLD) / (midpoint - LOW_AMPLITUDE_THRESHOLD);

        if (amplitude < midpoint) {
            // Cool to warm transition
            *red = (int)(transition_point * 255);
            *green = (int)((1.0 - transition_point) * 255);
            *blue = 255;
        } else {
            // Warm to cool transition
            *red = 255;
            *green = (int)(transition_point * 255);
            *blue = (int)((1.0 - transition_point) * 255);
        }
    }
}

// Set LED color using pigpio
int set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
    return 0;
}

// Cleanup resources
void cleanup(snd_pcm_t *pcm_handle) {
    fprintf(stderr, "Cleaning up resources...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default: %f\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Allocate buffer for audio data
    short *audio_buffer = (short *)malloc(FRAME_SIZE * SAMPLE_SIZE);
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for audio buffer\n");
        cleanup(pcm_handle);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio data
        if (read_audio_data(pcm_handle, audio_buffer, FRAME_SIZE) != 0) {
            fprintf(stderr, "Error reading audio data, exiting...\n");
            break;
        }

        // Calculate RMS amplitude
        double rms_amplitude = calculate_rms(audio_buffer, FRAME_SIZE);

        // Scale amplitude by sensitivity
        rms_amplitude *= sensitivity;

        // Map amplitude to RGB color values
        int red, green, blue;
        map_amplitude_to_color(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print status message
        printf("RMS Amplitude: %f, RGB: (%d, %d, %d)\n", rms_amplitude, red, green, blue);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup resources
    cleanup(pcm_handle);
    free(audio_buffer);

    return 0;
}

