#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725()
{
    // Enable power and RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time to 154ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read RGBC data from the sensor
int read_tcs34725(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue)
{
    char buffer[8];

    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8) != 8) {
        fprintf(stderr, "Error reading RGBC data: %s\n", strerror(errno));
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Function to log data to a CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue)
{
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", now, clear, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
    }
    rewind(fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;

    // Main loop
    while (!terminate) {
        // Read RGBC data
        if (read_tcs34725(&clear, &red, &green, &blue) == 0) {
            // Log the data
            if (log_data(clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, setting values to 0\n");
            clear = 0;
            red = 0;
            green = 0;
            blue = 0;
            log_data(clear, red, green, blue);
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

