#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <math.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the number of lamps
#define NUM_LAMPS 4

// Define the number of seconds in each phase
#define SUNRISE_DURATION 3600  // 1 hour
#define DAYTIME_DURATION 21600 // 6 hours
#define SUNSET_DURATION 3600   // 1 hour
#define NIGHTTIME_DURATION 57600 // 14.4 hours

// Define the number of toggle steps for sunrise/sunset
#define NUM_TOGGLES 100

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_LAMPS];

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);

    // Turn off all relays
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpiod_line_set_value(lines[i], 1); // Set to HIGH (off for active-low)
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

// Function to set the state of a relay (0 = on, 1 = off)
int set_relay_state(int relay_pin, int state) {
    int line_index = -1;
    if (relay_pin == RELAY1_PIN) line_index = 0;
    else if (relay_pin == RELAY2_PIN) line_index = 1;
    else if (relay_pin == RELAY3_PIN) line_index = 2;
    else if (relay_pin == RELAY4_PIN) line_index = 3;

    if (line_index == -1) {
        fprintf(stderr, "Error: Invalid relay pin: %d\n", relay_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(lines[line_index], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", relay_pin, gpiod_line_name(lines[line_index]));
        return -1;
    }
    return 0;
}

// Function to simulate sunrise
int sunrise() {
    for (int i = 0; i < NUM_TOGGLES; i++) {
        // Calculate the duty cycle (0-100)
        int duty_cycle = (int)(((float)i / (float)(NUM_TOGGLES - 1)) * 100.0);

        // Calculate the number of on and off cycles
        int on_cycles = (int)(((float)duty_cycle / 100.0) * NUM_LAMPS);
        int off_cycles = NUM_LAMPS - on_cycles;

        // Set the relays on and off
        for (int j = 0; j < on_cycles; j++) {
            if (set_relay_state(RELAY1_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY2_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY3_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY4_PIN, 0) < 0) return -1;
            usleep(10000); // 10ms
        }
        for (int j = 0; j < off_cycles; j++) {
            if (set_relay_state(RELAY1_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY2_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY3_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY4_PIN, 1) < 0) return -1;
            usleep(10000); // 10ms
        }
    }
    return 0;
}

// Function to simulate sunset
int sunset() {
    for (int i = NUM_TOGGLES - 1; i >= 0; i--) {
        // Calculate the duty cycle (0-100)
        int duty_cycle = (int)(((float)i / (float)(NUM_TOGGLES - 1)) * 100.0);

        // Calculate the number of on and off cycles
        int on_cycles = (int)(((float)duty_cycle / 100.0) * NUM_LAMPS);
        int off_cycles = NUM_LAMPS - on_cycles;

        // Set the relays on and off
        for (int j = 0; j < on_cycles; j++) {
            if (set_relay_state(RELAY1_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY2_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY3_PIN, 0) < 0) return -1;
            if (set_relay_state(RELAY4_PIN, 0) < 0) return -1;
            usleep(10000); // 10ms
        }
        for (int j = 0; j < off_cycles; j++) {
            if (set_relay_state(RELAY1_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY2_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY3_PIN, 1) < 0) return -1;
            if (set_relay_state(RELAY4_PIN, 1) < 0) return -1;
            usleep(10000); // 10ms
        }
    }
    return 0;
}

// Function to simulate daytime (all lamps on)
int daytime() {
    if (set_relay_state(RELAY1_PIN, 0) < 0) return -1;
    if (set_relay_state(RELAY2_PIN, 0) < 0) return -1;
    if (set_relay_state(RELAY3_PIN, 0) < 0) return -1;
    if (set_relay_state(RELAY4_PIN, 0) < 0) return -1;
    return 0;
}

// Function to simulate nighttime (all lamps off)
int nighttime() {
    if (set_relay_state(RELAY1_PIN, 1) < 0) return -1;
    if (set_relay_state(RELAY2_PIN, 1) < 0) return -1;
    if (set_relay_state(RELAY3_PIN, 1) < 0) return -1;
    if (set_relay_state(RELAY4_PIN, 1) < 0) return -1;
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, gpiod_strerror(gpiod_errno()));
        return 1;
    }

    // Get the GPIO lines for each relay
    int relay_pins[NUM_LAMPS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for pin %d: %s\n", relay_pins[i], gpiod_strerror(gpiod_errno()));
            // Release any previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line as an output
        struct gpiod_line_request_config config;
        config.consumer = "sunrise_sunset";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        int ret = gpiod_line_request(lines[i], &config, 1); // Initial value is 1 (off)
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", relay_pins[i], gpiod_strerror(gpiod_errno()));
            // Release any previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Sunrise
        if (sunrise() < 0) {
            fprintf(stderr, "Error during sunrise, exiting...\n");
            break;
        }
        sleep(SUNRISE_DURATION);

        // Daytime
        if (daytime() < 0) {
            fprintf(stderr, "Error during daytime, exiting...\n");
            break;
        }
        sleep(DAYTIME_DURATION);

        // Sunset
        if (sunset() < 0) {
            fprintf(stderr, "Error during sunset, exiting...\n");
            break;
        }
        sleep(SUNSET_DURATION);

        // Nighttime
        if (nighttime() < 0) {
            fprintf(stderr, "Error during nighttime, exiting...\n");
            break;
        }
        sleep(NIGHTTIME_DURATION);
    }

    // Cleanup (in case of error)
    signal_handler(0);

    return 0;
}

