#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_DELAY 200 // milliseconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to generate a filename for the video
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 50, "%Y%m%d_%H%M%S.h264", timeinfo);
    return filename;
}

// Function to record a video using raspivid
int record_video(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s%s -t 5000", VIDEO_DIR, filename);

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log a motion event
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Active low signal
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp.\n");
            return;
        }

        char *filename = generate_filename();
        if (filename == NULL) {
            fprintf(stderr, "Failed to generate filename.\n");
            free(timestamp);
            return;
        }

        if (record_video(filename) == 0) {
            if (log_motion(timestamp) != 0) {
                fprintf(stderr, "Failed to log motion event.\n");
            }
        } else {
            fprintf(stderr, "Failed to record video.\n");
        }

        free(timestamp);
        free(filename);

        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

