#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor (degrees/second per LSB)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degps(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps);
int log_data(float x_degps, float y_degps, float z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (status %d). Retrying...\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set sample rate divider to 125 (1000Hz / (125 + 1) = 100Hz)
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x7D);
        if (status < 0) {
            fprintf(stderr, "Error: Could not set sample rate divider (status %d). Retrying...\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range (status %d). Retrying...\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: MPU-6050 initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data (status %d)\n", status);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_degps(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps) {
    *x_degps = (float)x / GYRO_SENSITIVITY;
    *y_degps = (float)y / GYRO_SENSITIVITY;
    *z_degps = (float)z / GYRO_SENSITIVITY;
}

// Log data to CSV file
int log_data(float x_degps, float y_degps, float z_degps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x_degps, y_degps, z_degps) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    float x_degps, y_degps, z_degps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            convert_to_degps(x_raw, y_raw, z_raw, &x_degps, &y_degps, &z_degps);

            // Log data
            if (log_data(x_degps, y_degps, z_degps) != 0) {
                fprintf(stderr, "Error: Failed to log data. Continuing...\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Re-initializing...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus (error code %d)\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_mpu6050() != 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialization failed.\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

