    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_degps(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps) {
    *x_degps = (float)x / GYRO_SENSITIVITY;
    *y_degps = (float)y / GYRO_SENSITIVITY;
    *z_degps = (float)z / GYRO_SENSITIVITY;
}

// Log data to CSV file
int log_data(float x_degps, float y_degps, float z_degps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x_degps, y_degps, z_degps) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    float x_degps, y_degps, z_degps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            convert_to_degps(x_raw, y_raw, z_raw, &x_degps, &y_degps, &z_degps);

            // Log data
            if (log_data(x_degps, y_degps, z_degps) != 0) {
                fprintf(stderr, "Error: Failed to log data. Continuing...\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Re-initializing...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus (error code %d)\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_mpu6050() != 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialization failed.\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

