#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Scale factor (LSB/g)
#define SCALE_FACTOR 256.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_adxl345();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall_event(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it's low initially

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;
    int freefall_count = 0;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g-force
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Detect freefall
            if (detect_freefall(x_g, y_g, z_g)) {
                freefall_count++;
                if (freefall_count >= 2) {
                    // Confirmed freefall
                    trigger_alarm();
                    log_freefall_event(x_g, y_g, z_g);
                    freefall_count = 0; // Reset counter
                }
            } else {
                freefall_count = 0; // Reset counter if not in freefall
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Set data format register to full resolution and +/-2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw value to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / SCALE_FACTOR;
}

// Detect freefall
int detect_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD);
}

// Trigger alarm
void trigger_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(5000000);      // Wait 5 seconds
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Log freefall event
void log_freefall_event(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

