#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define SENSITIVITY 16384.0 // LSB/g

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure LIS3DH accelerometer
int config_lis3dh() {
    // Set data rate to 100 Hz and enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw acceleration value to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / SENSITIVITY;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate the buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                freefall_threshold = atof(optarg);
                break;
            case 'i':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g, magnitude;
    int retries;

    printf("Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
                x_g = convert_to_g(raw_x);
                y_g = convert_to_g(raw_y);
                z_g = convert_to_g(raw_z);
                magnitude = calculate_magnitude(x_g, y_g, z_g);

                if (magnitude < freefall_threshold) {
                    printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                    if (magnitude < impact_threshold) {
                        printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                        activate_buzzer();
                    }
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/3)\n", retries + 1);
                retries++;
                gpioDelay(10); // Small delay before retrying
            }
        }

        if (retries == 3) {
            fprintf(stderr, "I2C read failed after 3 retries. Exiting.\n");
            break; // Exit main loop if retries exhausted
        }

        gpioDelay(10); // Delay to avoid overwhelming the CPU
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

