#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_LOG_FILE "/var/log/high_acceleration.log"

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
char *server_ip = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;
char *log_file = DEFAULT_LOG_FILE;
int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int configure_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
int check_threshold(double x, double y, double z, double threshold);
int log_event(double x, double y, double z);
int send_udp_message(double x, double y, double z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Configure LIS3DH
int configure_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100 Hz, High-resolution mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±2g range, High-resolution mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0; *y = 0; *z = 0; // Set to zero to avoid using uninitialized values
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw value to g
double convert_to_g(int16_t raw_value) {
    return (double)(raw_value >> 4) * 0.0009765625;
}

// Check if acceleration exceeds threshold
int check_threshold(double x, double y, double z, double threshold) {
    return (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold);
}

// Log event to file
int log_event(double x, double y, double z) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.4f g, Y: %.4f g, Z: %.4f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
    return 0;
}

// Send UDP message
int send_udp_message(double x, double y, double z) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "X: %.4f, Y: %.4f, Z: %.4f", x, y, z);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:i:p:l:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtod(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            case 'i':
                server_ip = optarg;
                break;
            case 'p':
                server_port = atoi(optarg);
                break;
            case 'l':
                log_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-i server_ip] [-p server_port] [-l log_file]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    double x_g, y_g, z_g;

    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Check threshold
            if (check_threshold(x_g, y_g, z_g, threshold)) {
                printf("Threshold exceeded! X: %.4f g, Y: %.4f g, Z: %.4f g\n", x_g, y_g, z_g);

                // Log event
                if (log_event(x_g, y_g, z_g) < 0) {
                    fprintf(stderr, "Error logging event\n");
                }

                // Send UDP message
                if (send_udp_message(x_g, y_g, z_g) < 0) {
                    fprintf(stderr, "Error sending UDP message\n");
                }

                // Shutdown system
                system("sudo shutdown -h now");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup (never reached in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

