#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define MEASURE_REG 0xC1
#define DATA_REG 0xC0
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define TIMEOUT_MS 5000
#define POLL_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(int *raw_field);
float convert_to_mT(int raw_field);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int raw_field;
    float field_mT;
    int relay_state;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor(int *raw_field) {
    int result;
    int attempts = 0;

    // Start measurement
    result = i2cWriteByteData(i2c_handle, MEASURE_REG, 0x01);
    if (result < 0) {
        log_event("Error writing to MEASURE_REG");
        return -1;
    }

    // Poll for completion
    while (attempts < MAX_POLL_ATTEMPTS) {
        result = i2cReadByteData(i2c_handle, MEASURE_REG);
        if (result < 0) {
            log_event("Error reading MEASURE_REG");
            return -1;
        }
        if (result == 0) break; // Measurement complete
        gpioDelay(POLL_INTERVAL_MS);
        attempts++;
    }

    if (attempts >= MAX_POLL_ATTEMPTS) {
        log_event("Timeout waiting for measurement");
        return -1;
    }

    // Read data
    result = i2cReadByteData(i2c_handle, DATA_REG);
    if (result < 0) {
        log_event("Error reading LSB from DATA_REG");
        return -1;
    }
    int lsb = result;

    result = i2cReadByteData(i2c_handle, DATA_REG + 1);
    if (result < 0) {
        log_event("Error reading MSB from DATA_REG");
        return -1;
    }
    int msb = result;

    *raw_field = (msb << 8) | lsb;
    return 0;
}

// Function to convert raw data to milliTesla
float convert_to_mT(int raw_field) {
    return (float)raw_field * 25.0 / 1000.0;
}

// Function to control the relay
int control_relay(int state) {
    int result = gpioWrite(RELAY_GPIO, state);
    if (result != 0) {
        log_event("Error writing to GPIO");
        return -1;
    }
    return 0;
}

// Function to log events
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int raw_field;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_sensor(&raw_field) == 0) {
            field_mT = convert_to_mT(raw_field);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Raw: %d, mT: %.2f", raw_field, field_mT);
            log_event(log_message);

            if (field_mT > THRESHOLD_MT && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_event("Relay ON");
                }
            } else if (field_mT <= THRESHOLD_MT && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_event("Relay OFF");
                }
            }
        } else {
            log_event("Sensor read failed, retrying...");
            control_relay(0); // Ensure relay is off on error
            relay_state = 0;
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

