#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int create_socket();
int bind_socket(int socket_fd);
int listen_socket(int socket_fd);
int accept_connection(int socket_fd);
int receive_command(int client_fd, char *buffer, int buffer_size);
int process_command(const char *command);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    return 0;
}

// Function to create a socket
int create_socket() {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Socket creation failed");
        return -1;
    }
    return socket_fd;
}

// Function to bind the socket to a specific port
int bind_socket(int socket_fd) {
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Socket bind failed");
        return -1;
    }
    return 0;
}

// Function to listen for incoming connections
int listen_socket(int socket_fd) {
    if (listen(socket_fd, 3) < 0) {
        perror("Socket listen failed");
        return -1;
    }
    return 0;
}

// Function to accept an incoming connection
int accept_connection(int socket_fd) {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int client_fd = accept(socket_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
    if (client_fd < 0) {
        perror("Socket accept failed");
        return -1;
    }
    return client_fd;
}

// Function to receive a command from the client
int receive_command(int client_fd, char *buffer, int buffer_size) {
    ssize_t bytes_received = recv(client_fd, buffer, buffer_size - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return -1;
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
        return 0;
    }
    buffer[bytes_received] = '\0';
    return bytes_received;
}

// Function to process the received command
int process_command(const char *command) {
    char *trimmed_command = strdup(command);
    if (trimmed_command == NULL) {
        perror("strdup failed");
        return -1;
    }

    // Trim trailing whitespace
    size_t len = strlen(trimmed_command);
    while (len > 0 && isspace((unsigned char)trimmed_command[len - 1])) {
        len--;
    }
    trimmed_command[len] = '\0';

    // Convert to uppercase
    for (size_t i = 0; i < len; i++) {
        trimmed_command[i] = toupper((unsigned char)trimmed_command[i]);
    }

    int state = -1;
    if (strcmp(trimmed_command, "ON") == 0) {
        state = 1;
    } else if (strcmp(trimmed_command, "OFF") == 0) {
        state = 0;
    } else {
        fprintf(stderr, "Invalid command: %s\n", command);
        free(trimmed_command);
        return -1;
    }

    free(trimmed_command);
    return state;
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(GPIO_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function to release resources
void cleanup() {
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Create socket
    server_fd = create_socket();
    if (server_fd == -1) {
        cleanup();
        return 1;
    }

    // Bind socket
    if (bind_socket(server_fd) != 0) {
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen_socket(server_fd) != 0) {
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (program_running) {
        // Accept connection
        int client_fd = accept_connection(server_fd);
        if (client_fd == -1) {
            if (program_running) {
                fprintf(stderr, "Error accepting connection, but program is still running. Continuing...\n");
            }
            continue; // Continue listening even if accept fails
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received;

        // Receive and process commands
