#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0 / 1500.0
#define START_MEASUREMENT_CMD1 0x36
#define START_MEASUREMENT_CMD2 0x08
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr, int flags);
int send_start_measurement(int handle);
int read_flow_data(int handle, int16_t *raw_flow);
uint8_t calculate_crc8(const uint8_t *data, int len);
float convert_to_ml_min(int16_t raw_flow);
int control_relay(int gpio, int state);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr, int flags) {
    int handle = i2cOpen(bus, addr, flags);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Send start measurement command
int send_start_measurement(int handle) {
    char cmd[2] = {START_MEASUREMENT_CMD1, START_MEASUREMENT_CMD2};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow data from sensor
int read_flow_data(int handle, int16_t *raw_flow) {
    char buffer[3];
    int result = i2cReadDevice(handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow data: %d\n", result);
        return -1;
    }

    uint8_t crc = calculate_crc8((uint8_t *)buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, buffer[2]);
        return -1;
    }

    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Convert raw flow data to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow * SCALE_FACTOR;
}

// Control relay state
int control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Log flow data to file
int log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%.3f,%.3f\n", timestamp_ms, flow1, flow2);
    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    control_relay(RELAY_GPIO, 0); // De-energize relay

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    gpioTerminate();
    fprintf(stderr, "Shutdown complete\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Send start measurement command to both sensors
    if (send_start_measurement(i2c_handle1) != 0 || send_start_measurement(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(RELAY_GPIO, 0); // Initialize relay to de-energized state

    // Main loop
    while (!terminate) {
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Read flow data from sensor 1
        if (read_flow_data(i2c_handle1, &raw_flow1) == 0) {
            flow1 = convert_to_ml_min(raw_flow1);
        } else {
            flow1 = -1.0; // Indicate error
        }

        // Read flow data from sensor 2
        if (read_flow_data(i2c_handle2, &raw_flow2) == 0) {
            flow2 = convert_to_ml_min(raw_flow2);
        } else {
            flow2 = -1.0; // Indicate error
        }

        // Control relay based on flow rates
        if (flow1 >= 0.0 && flow1 < FLOW_THRESHOLD && flow2 >= 0.0 && flow2 < FLOW_THRESHOLD) {
            control_relay(RELAY_GPIO, 0); // De-energize
        } else {
            control_relay(RELAY_GPIO, 1); // Energize
        }

        // Log flow data
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            log_flow_data(flow1, flow2);
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

