#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run duration
#define MOTOR_RUN_DURATION_MS 5000

// Define rain sensor debounce time
#define RAIN_DEBOUNCE_POLLS 3

// Global variables
static volatile int running = 1;
static int rain_detected = 0;
static int consecutive_dry_polls = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void close_window();
void stop_motor();
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Received signal, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN as input");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN as output");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Close the window
void close_window() {
    log_message(LOG_INFO, "Closing window...");

    if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN HIGH");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN HIGH");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
    }

    gpioDelay(MOTOR_RUN_DURATION_MS * 1000); // Convert ms to us

    stop_motor();
}

// Stop the motor
void stop_motor() {
    log_message(LOG_INFO, "Stopping motor...");

    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN LOW");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN LOW");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
    }
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    log_message(LOG_INFO, "Starting rain window controller...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting...");
        closelog();
        return 1;
    }

    int last_rain_state = 1; // Initialize to dry (HIGH)

