#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to handle the lock button press
void handle_lock_button() {
    if (gpioRead(LOCK_BUTTON_PIN) == 0) { // Button is pressed (low)
        if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to lock the door.\n");
        } else {
            printf("Door locked.\n");
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

// Function to handle the unlock button press
void handle_unlock_button() {
    if (gpioRead(UNLOCK_BUTTON_PIN) == 0) { // Button is pressed (low)
        if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to unlock the door.\n");
        } else {
            printf("Door unlocked.\n");
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo position to locked
    if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to set initial servo position.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        handle_lock_button();
        handle_unlock_button();
        gpioDelay(1000); // Small delay to avoid high CPU usage
    }

    // Clean up and exit
    if (set_servo_pulse_width(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to stop servo.\n");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

