#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define ACTIVATION_DURATION 60 // seconds
#define POLL_INTERVAL 100      // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *timestamp, double duration);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the LED
int control_led(int state) {
    return gpioWrite(LED_PIN, state);
}

// Function to log events to a file
int log_event(const char *event_type, const char *timestamp, double duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (event_type != NULL && strcmp(event_type, "activation") == 0) {
        fprintf(log_file, "%s - Motion detected, Floodlight activated\n", timestamp);
    } else if (event_type != NULL && strcmp(event_type, "deactivation") == 0) {
        fprintf(log_file, "%s - Floodlight deactivated, Duration: %.2f seconds\n", timestamp, duration);
    } else {
        fprintf(stderr, "Invalid event type\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    time_t start_time, end_time;
    double duration;
    char timestamp[30];
    struct tm *tm_info;

    printf("Smart Security Light running...\n");

    while (running) {
        // Read the PIR sensor
        if (read_pir_sensor() == 1) {
            // Motion detected
            time(&start_time);
            tm_info = localtime(&start_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

            // Log the activation event
            if (log_event("activation", timestamp, 0.0) != 0) {
                fprintf(stderr, "Failed to log activation event\n");
            }

            // Activate the LED
            if (control_led(1) != 0) {
                fprintf(stderr, "Failed to activate LED\n");
            }

            // Wait for the activation duration
            gpioDelay(ACTIVATION_DURATION * 1000000); // Convert seconds to microseconds

            // Deactivate the LED
            if (control_led(0) != 0) {
                fprintf(stderr, "Failed to deactivate LED\n");
            }

            // Log the deactivation event
            time(&end_time);
            duration = difftime(end_time, start_time);
            if (log_event("deactivation", timestamp, duration) != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
            }
        }

        // Poll at a 100ms interval
        gpioDelay(POLL_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

