#include <time.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define DEBOUNCE_DELAY_MS 200

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_on(int gpio);
void relay_off(int gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x06) < 0) {
        fprintf(stderr, "Error: MPR121 baseline filtering config failed\n");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x06) < 0) {
        fprintf(stderr, "Error: MPR121 debounce config failed\n");
        return -1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) {
        fprintf(stderr, "Error: MPR121 FFI/SFI/CDT config failed\n");
        return -1;
    }

    // Configure auto-config
    if (i2cWriteByteData(i2c_handle, 0x7B, 0x01) < 0) {
        fprintf(stderr, "Error: MPR121 auto-config 1 failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x01) < 0) {
        fprintf(stderr, "Error: MPR121 auto-config 2 failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x00) < 0) {
        fprintf(stderr, "Error: MPR121 auto-config 3 failed\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: MPR121 electrode enable failed\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        fprintf(stderr, "Error: MPR121 enter run mode failed\n");
        return -1;
    }

    return 0;
}

