#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <errno.h>
#include <stdarg.h>

// Configuration
#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define SERVO_MIN_PULSE_WIDTH_US 1000
#define SERVO_MAX_PULSE_WIDTH_US 2000
#define LOG_FILE "security.log"

// Global variables (minimize usage)
static volatile int running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static int server_fd = -1;
static FILE *log_file = NULL;
static pthread_t pwm_thread;

// Function prototypes
void log_message(int priority, const char *format, ...);
int init_gpio(void);
void cleanup_gpio(void);
void *pwm_control_thread(void *arg);
int handle_servo_command(int angle);
int handle_pir_command(void);
void handle_client(int client_fd);
void signal_handler(int signum);
int setup_socket(void);
void cleanup_socket(void);
void cleanup_logging(void);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fflush(log_file);
    }

    va_end(args);
}

// GPIO initialization
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo-control", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir-control") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    return 0;
}

// GPIO cleanup
void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// PWM control thread
void *pwm_control_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        // Calculate pulse width based on global angle (replace with actual angle)
        // For now, just use a fixed pulse width for demonstration
        int pulse_width_us = 1500; // Example pulse width

        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set servo line high: %s\n", strerror(errno));
            running = 0; // Stop the thread on error
            break;
        }
        usleep(pulse_width_us);

        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set servo line low: %s\n", strerror(errno));
            running = 0; // Stop the thread on error
            break;
        }
        usleep(PWM_PERIOD_US - pulse_width_us);
    }
    return NULL;
}

// Servo command handler
int handle_servo_command(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width_us = SERVO_MIN_PULSE_WIDTH_US + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH_US - SERVO_MIN_PULSE_WIDTH_US));

    // Set the pulse width (this is a placeholder, actual PWM implementation is in the thread)
    // In a real implementation, you would pass the pulse_width_us to the PWM thread.
    // For now, we just log the command.
    log_message(LOG_INFO, "Received servo command: angle=%d, pulse_width=%d\n", angle, pulse_width_us);

    return 0;
}

// PIR command handler
int handle_pir_command(void) {
    int pir_value = gpiod_line_get_value(pir_line);
    if (pir_value < 0) {
        log_message(LOG_ERR, "Failed to read PIR value: %s\n", strerror(errno));
        return -1;
    }

    log_message(LOG_INFO, "PIR sensor value: %d\n", pir_value);
    return pir_value;
}

// Client handling function
void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s\n", buffer);

        if (strncmp(buffer, "SERVO ", 6) == 0) {
            int angle = atoi(buffer + 6);
            if (handle_servo_command(angle) != 0) {
                send(client_fd, "ERROR: Invalid servo command\n", strlen("ERROR: Invalid servo command\n"), 0);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int pir_value = handle_pir_command();
            if (pir_value >= 0) {
                char response[32];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                send(client_fd, response, strlen(response), 0);
            } else {
                send(client_fd, "ERROR: Failed to read PIR sensor\n", strlen("ERROR: Failed to read PIR sensor\n"), 0);
            }
        } else {
            send(client_fd, "ERROR: Invalid command\n", strlen("ERROR: Invalid command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s\n", strerror(errno));
    }

    close(client_fd);
    log_message(LOG_INFO, "Client disconnected\n");
}

// Signal handler
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...\n", signum);
    running = 0;
}

// Socket setup
int setup_socket(void) {
    int fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Socket cleanup
void cleanup_socket(void) {
    if (server_fd != -1) {
        close(server_fd);
    }
}

// Logging cleanup
void cleanup_logging(void) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s\n", strerror(errno));
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.\n");
        cleanup_logging();
        return EXIT_FAILURE;
    }

    // Create PWM thread
    if (pthread_create(&pwm_thread, NULL, pwm_control_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s\n", strerror(errno));
        cleanup_gpio();
        cleanup_logging();
        return EXIT_FAILURE;
    }

    // Setup socket
    server_fd = setup_socket();
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket setup failed. Exiting.\n");
        cleanup_gpio();
        pthread_join(pwm_thread, NULL);
        cleanup_logging();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Server listening on port %d\n", PORT);

    // Main loop
    while (running) {
        struct sockaddr_in client_address;
        int client_fd;
        socklen_t client_len = sizeof(client_address);

        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (running) {
                log_message(LOG_ERR, "Accept failed: %s\n", strerror(errno));
            }
            break; // Exit loop if accept fails and running is still true
        }

        log_message(LOG_INFO, "Client connected\n");
        handle_client(client_fd);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...\n");
    cleanup_socket();
    cleanup_gpio();
    pthread_join(pwm_thread, NULL);
    cleanup_logging();

    return EXIT_SUCCESS;
}

