            int pir_value = handle_pir_command();
            if (pir_value >= 0) {
                char response[32];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                send(client_fd, response, strlen(response), 0);
            } else {
                send(client_fd, "ERROR: Failed to read PIR sensor\n", strlen("ERROR: Failed to read PIR sensor\n"), 0);
            }
        } else {
            send(client_fd, "ERROR: Invalid command\n", strlen("ERROR: Invalid command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s\n", strerror(errno));
    }

    close(client_fd);
    log_message(LOG_INFO, "Client disconnected\n");
}

// Signal handler
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...\n", signum);
    running = 0;
}

// Socket setup
int setup_socket(void) {
    int fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Socket cleanup
void cleanup_socket(void) {
    if (server_fd != -1) {
        close(server_fd);
    }
}

// Logging cleanup
void cleanup_logging(void) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s\n", strerror(errno));
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.\n");
        cleanup_logging();
        return EXIT_FAILURE;
    }

    // Create PWM thread
    if (pthread_create(&pwm_thread, NULL, pwm_control_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s\n", strerror(errno));
        cleanup_gpio();
        cleanup_logging();
        return EXIT_FAILURE;
    }

    // Setup socket
    server_fd = setup_socket();
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket setup failed. Exiting.\n");
        cleanup_gpio();
        pthread_join(pwm_thread, NULL);
        cleanup_logging();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Server listening on port %d\n", PORT);

    // Main loop
    while (running) {
        struct sockaddr_in client_address;
        int client_fd;
        socklen_t client_len = sizeof(client_address);

        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (running) {
                log_message(LOG_ERR, "Accept failed: %s\n", strerror(errno));
            }
            break; // Exit loop if accept fails and running is still true
        }

        log_message(LOG_INFO, "Client connected\n");
        handle_client(client_fd);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...\n");
    cleanup_socket();
    cleanup_gpio();
    pthread_join(pwm_thread, NULL);
    cleanup_logging();

    return EXIT_SUCCESS;
}

