#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL 2 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle, float *lux);
void control_grow_light(int gpio_pin, float lux, float threshold);
void log_data(FILE *log_file, float lux);
void signal_handler(int signal);

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x20; // One-Time High-Resolution Mode
    char buffer[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, config_cmd);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            log_data(log_file, -1.0); // Log error
            gpioDelay(100); // Wait before retrying
            retries++;
            continue;
        }

        gpioDelay(120); // Wait for measurement (at least 120ms)

        result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            log_data(log_file, -1.0); // Log error
            gpioDelay(100); // Wait before retrying
            retries++;
            continue;
        }

        unsigned int raw_value = (buffer[0] << 8) | buffer[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the grow light
void control_grow_light(int gpio_pin, float lux, float threshold) {
    if (lux < threshold) {
        gpioWrite(gpio_pin, 1); // Activate grow light
        printf("Grow light activated (Lux: %.2f)\n", lux);
    } else {
        gpioWrite(gpio_pin, 0); // Deactivate grow light
        printf("Grow light deactivated (Lux: %.2f)\n", lux);
    }
}

// Function to log data to file
void log_data(FILE *log_file, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (lux >= 0) {
        fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
        printf("%s, Lux: %.2f\n", timestamp, lux);
    } else {
        fprintf(log_file, "%s, Error reading sensor\n", timestamp);
        printf("%s, Error reading sensor\n", timestamp);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for grow light control
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;

    // Main loop
    while (!terminate) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            control_grow_light(GROW_LIGHT_GPIO, lux, LUX_THRESHOLD);
            log_data(log_file, lux);
        } else {
            log_data(log_file, -1.0); // Log error
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate grow light
    gpioTerminate();

    return 0;
}

