#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define NUM_READINGS 5
#define TARE_READINGS 10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *solenoid_line;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static double tare_offset = 0.0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hx711(int dout_pin, int sck_pin);
double average_readings(int dout_pin, int sck_pin, int num_readings);
double calculate_weight(long raw_value, double tare_offset, double scale);
void control_solenoid(int solenoid_pin, int duration_ms);
void tare_sensor(int dout_pin, int sck_pin, int num_readings);
void signal_handler(int sig);
void cleanup();

// Function to read a single value from the HX711
int read_hx711(int dout_pin, int sck_pin) {
    int data = 0;
    int timeout = 0;

    // Wait for DOUT to go LOW
    while (gpiod_line_get_value(dout_line) == 1) {
        usleep(1000); // 1 ms delay
        timeout++;
        if (timeout > 1000) { // 1 second timeout
            syslog(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
            return -1; // Indicate error
        }
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1); // Small delay for clock stability
        data = data << 1;
        if (gpiod_line_get_value(dout_line)) {
            data++;
        }
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpiod_line_set_value(sck_line, 1);
    usleep(1);
    gpiod_line_set_value(sck_line, 0);
    usleep(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to average multiple readings from the HX711
double average_readings(int dout_pin, int sck_pin, int num_readings) {
    long sum = 0;
    for (int i = 0; i < num_readings; i++) {
        int reading = read_hx711(dout_pin, sck_pin);
        if (reading == -1) {
            syslog(LOG_ERR, "Error reading HX711, skipping reading");
            return -1.0; // Indicate error
        }
        sum += reading;
        usleep(1000); // Small delay between readings
    }
    return (double)sum / num_readings;
}

// Function to calculate weight from raw value
double calculate_weight(long raw_value, double tare_offset, double scale) {
    return (raw_value - tare_offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, int duration_ms) {
    gpiod_line_set_value(solenoid_line, 1); // Activate solenoid
    usleep(duration_ms * 1000); // Delay for specified duration
    gpiod_line_set_value(solenoid_line, 0); // Deactivate solenoid
}

// Function to perform a startup tare
void tare_sensor(int dout_pin, int sck_pin, int num_readings) {
    double avg = average_readings(dout_pin, sck_pin, num_readings);
    if (avg == -1.0) {
        syslog(LOG_ERR, "Tare failed due to reading errors");
        exit(EXIT_FAILURE);
    }
    tare_offset = avg;
    syslog(LOG_INFO, "Tare offset set to: %lf", tare_offset);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release GPIO resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0); // Ensure solenoid is off
        gpiod_line_release(solenoid_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        perror("gpiod_chip_open_by_name");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Get GPIO lines
    dout_line = gpiod_chip_get_line(chip, HX711_DOUT);
    sck_line = gpiod_chip_get_line(chip, HX711_SCK);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines for output/input
    if (gpiod_line_request_output(solenoid_line, "weight_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid line as output");
        perror("gpiod_line_request_output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(sck_line, "weight_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK line as output");
        perror("gpiod_line_request_output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout_line, "weight_monitor") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT line as input");
        perror("gpiod_line_request_input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Perform startup tare
    tare_sensor(HX711_DOUT, HX711_SCK, TARE_READINGS);

    // Main loop
    while (!terminate) {
        double avg_raw = average_readings(HX711_DOUT, HX711_SCK, NUM_READINGS);
        if (avg_raw == -1.0) {
            syslog(LOG_ERR, "Error averaging readings, skipping iteration");
            usleep(500000); // Wait 500ms
            continue;
        }

        double weight = calculate_weight(avg_raw, tare_offset, scale);
        syslog(LOG_INFO, "Raw: %lf, Weight: %lf grams", avg_raw, weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight above threshold, activating solenoid");
            control_solenoid(SOLENOID_PIN, duration);
        }

        usleep(500000); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

