#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Function to set the relay state
int set_relay_state(int state) {
    int result = gpioWrite(GPIO_PIN, state);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to set relay state: %d", result);
        return -1;
    }
    return 0;
}

// Callback function for MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    syslog(LOG_INFO, "Received message on topic: %s", message->topic);

    if (message->payloadlen == 0) {
        syslog(LOG_ERR, "Empty payload received");
        return;
    }

    char *payload = (char *)message->payload;

    if (strcmp(payload, "ON") == 0) {
        if (set_relay_state(1) != 0) {
            syslog(LOG_ERR, "Failed to turn relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (set_relay_state(0) != 0) {
            syslog(LOG_ERR, "Failed to turn relay OFF");
        }
    } else {
        syslog(LOG_ERR, "Invalid payload received: %s", payload);
    }
}

// Callback function for MQTT connect
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_strerror(result));
    }
}

// Callback function for MQTT disconnect
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "Disconnected unexpectedly, reconnecting...");
    } else {
        syslog(LOG_INFO, "Disconnected cleanly");
    }
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    // Initialize mosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1);
        if (loop_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(loop_result));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

