    // Set PWM frequency and range for each servo pin
    if (gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for SERVO1_PIN\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(SERVO1_PIN, PWM_RANGE);

    if (gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for SERVO2_PIN\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(SERVO2_PIN, PWM_RANGE);

    if (gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for SERVO3_PIN\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);

    if (gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for SERVO4_PIN\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(SERVO4_PIN, PWM_RANGE);

    if (gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for SERVO5_PIN\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(SERVO5_PIN, PWM_RANGE);

    // Set servo positions
    gpioPWM(SERVO1_PIN, SERVO1_PULSE_WIDTH);
    gpioPWM(SERVO2_PIN, SERVO2_PULSE_WIDTH);
    gpioPWM(SERVO3_PIN, SERVO3_PULSE_WIDTH);
    gpioPWM(SERVO4_PIN, SERVO4_PULSE_WIDTH);
    gpioPWM(SERVO5_PIN, SERVO5_PULSE_WIDTH);

    // Hold the positions for 3 seconds
    sleep(3);

    // Stop PWM and release resources
