#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A definitions
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B definitions
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A definitions
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B definitions
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// PI controller parameters
#define KP 0.5
#define KI 0.05

// PWM frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Encoder stall detection time (seconds)
#define ENCODER_STALL_TIME 2.0

// Control loop period (milliseconds)
#define CONTROL_LOOP_PERIOD 100

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double motor_a_integral = 0.0;
double motor_b_integral = 0.0;
int running = 1;
time_t last_encoder_a_tick = 0;
time_t last_encoder_b_tick = 0;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
void set_motor_a_pwm(int pwm_value);
void set_motor_b_pwm(int pwm_value);
void set_motor_a_direction(int direction);
void set_motor_b_direction(int direction);
double calculate_rpm(int encoder_count, double time_elapsed);
int pi_control(double setpoint, double actual_value, double *integral, double Kp, double Ki);
void signal_handler(int signal);
void check_encoder_stall();

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int b_level = gpioRead(ENCODER_A_B);
    if (level == 1) {
        if (b_level == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    } else {
        if (b_level == 0) {
            encoder_a_count--;
        } else {
            encoder_a_count++;
        }
    }
    last_encoder_a_tick = time(NULL);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int b_level = gpioRead(ENCODER_B_B);
    if (level == 1) {
        if (b_level == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    } else {
        if (b_level == 0) {
            encoder_b_count--;
        } else {
            encoder_b_count++;
        }
    }
    last_encoder_b_tick = time(NULL);
}

// Set motor A PWM
void set_motor_a_pwm(int pwm_value) {
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > 255) pwm_value = 255;
    gpioPWM(MOTOR_A_PWM, pwm_value);
}

// Set motor B PWM
void set_motor_b_pwm(int pwm_value) {
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > 255) pwm_value = 255;
    gpioPWM(MOTOR_B_PWM, pwm_value);
}

// Set motor A direction
void set_motor_a_direction(int direction) {
    gpioWrite(MOTOR_A_DIR, direction);
}

// Set motor B direction
void set_motor_b_direction(int direction) {
    gpioWrite(MOTOR_B_DIR, direction);
}

// Calculate RPM
double calculate_rpm(int encoder_count, double time_elapsed) {
    return (double)encoder_count / time_elapsed * 60.0 / 64.0; // ticks/revolution * revolutions/minute
}

// PI controller
int pi_control(double setpoint, double actual_value, double *integral, double Kp, double Ki) {
    double error = setpoint - actual_value;
    *integral += error;

    // Anti-windup clamping
    if (*integral > 255) *integral = 255;
    if (*integral < 0) *integral = 0;

    double output = Kp * error + Ki * (*integral);

    // Clamp output to [0, 255]
    if (output > 255) output = 255;
    if (output < 0) output = 0;

    return (int)output;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    set_motor_a_pwm(0);
    set_motor_b_pwm(0);
