#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

// Configuration structure
typedef struct {
    float calibration_factor;
    char server_ip[20];
    int server_port;
} Config;

// Global variables
int data_pin = 23;
int sck_pin = 24;
int servo_pin = 18;
int server_socket = -1;
int client_socket = -1;
FILE *log_file = NULL;
Config config;

// Function prototypes
int read_hx711();
float calibrate_weight(int raw_value);
int map_weight_to_pulsewidth(float target_weight);
int set_servo_pulsewidth(int pulsewidth);
int handle_client(int client_socket);
int log_event(float target_weight, float actual_weight, const char *error_message);
void signal_handler(int signal);
int load_config(const char *filename, Config *config);

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for DATA pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // 1 us delay
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout: DATA pin HIGH for too long.\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1 us delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Calibration function
float calibrate_weight(int raw_value) {
    return (float)raw_value / config.calibration_factor;
}

// Weight to pulsewidth mapping function
int map_weight_to_pulsewidth(float target_weight) {
    // Assuming a reasonable range for target weight (e.g., 0-1000g)
    // Map 0-1000g to 1000-2000us
    int pulsewidth = (int)(1000 + (target_weight / 1000.0) * 1000.0);
    if (pulsewidth < 1000) pulsewidth = 1000;
    if (pulsewidth > 2000) pulsewidth = 2000;
    return pulsewidth;
}

// Servo control function
int set_servo_pulsewidth(int pulsewidth) {
    if (gpioServo(servo_pin, pulsewidth) != 0) {
        fprintf(stderr, "Error setting servo pulsewidth: %d\n", pulsewidth);
        return -1;
    }
    return 0;
}

// Client handling function
int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;
    float target_weight;
    int raw_value;
    float actual_weight;
    char error_message[256] = "";

    // Receive target weight from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data from client");
        strcpy(error_message, "Error receiving data from client");
        log_event(-1, -1, error_message);
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Parse target weight
    target_weight = atof(buffer);
    if (target_weight <= 0) {
        fprintf(stderr, "Invalid target weight received: %f\n", target_weight);
        strcpy(error_message, "Invalid target weight");
        log_event(target_weight, -1, error_message);
        send(client_socket, error_message, strlen(error_message), 0);
        return -1;
    }

    // Dispense ingredient
    int pulsewidth = map_weight_to_pulsewidth(target_weight);
    if (set_servo_pulsewidth(pulsewidth) != 0) {
        strcpy(error_message, "Error setting servo pulsewidth");
        log_event(target_weight, -1, error_message);
        send(client_socket, error_message, strlen(error_message), 0);
        return -1;
    }

    gpioDelay(1000000); // Wait 1 second for load cell to stabilize

    // Read actual weight
    raw_value = read_hx711();
    if (raw_value == -1) {
        strcpy(error_message, "Error reading HX711");
        log_event(target_weight, -1, error_message);
        send(client_socket, error_message, strlen(error_message), 0);
        return -1;
    }
    actual_weight = calibrate_weight(raw_value);

    // Send actual weight back to client
    char weight_str[20];
    snprintf(weight_str, sizeof(weight_str), "%.2f", actual_weight);
    send(client_socket, weight_str, strlen(weight_str), 0);

    // Log event
    log_event(target_weight, actual_weight, error_message);

    return 0;
}

// Logging function
int log_event(float target_weight, float actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    cJSON *root = cJSON_CreateObject();
    cJSON_AddStringToObject(root, "timestamp", timestamp);
    cJSON_AddNumberToObject(root, "target_weight", target_weight);
    cJSON_AddNumberToObject(root, "actual_weight", actual_weight);
    cJSON_AddStringToObject(root, "error_message", error_message);

    char *json_string = cJSON_PrintUnformatted(root);
    if (json_string == NULL) {
        fprintf(stderr, "Failed to create JSON string\n");
        cJSON_Delete(root);
        return -1;
    }

    fprintf(log_file, "%s\n", json_string);
    fflush(log_file);

    cJSON_Delete(root);
    free(json_string);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close socket
    if (client_socket != -1) {
        close(client_socket);
    }
    if (server_socket != -1) {
        close(server_socket);
    }

    // Stop servo
    gpioServo(servo_pin, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Load configuration from file
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file, using defaults.\n");
        config->calibration_factor = 1.0; // Default calibration factor
        strcpy(config->server_ip, "127.0.0.1"); // Default server IP
        config->server_port = 12345; // Default server port
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                config->calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(config->server_ip, value, sizeof(config->server_ip) - 1);
                config->server_ip[sizeof(config->server_ip) - 1] = '\0'; // Ensure null termination
            } else if (strcmp(key, "server_port") == 0) {
                config->server_port = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    // Load configuration
    if (load_config("config.ini", &config) != 0) {
        // Use default values if config file is missing or invalid
        config.calibration_factor = 1.0;
        strcpy(config.server_ip, "127.0.0.1");
        config.server_port = 12345;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(servo_pin, PI_OUTPUT);

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
