#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

static volatile int running = 1;
static int debounce_time_ms = 50;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int stable_level = gpioRead(TOUCH_SENSOR_GPIO);
    int count = 0;
    int i;

    for (i = 0; i < 5; i++) {
        gpioDelay(debounce_time_ms * 1000); // Convert ms to microseconds
        if (gpioRead(TOUCH_SENSOR_GPIO) == stable_level) {
            count++;
        }
    }

    return (count == 5) ? stable_level : -1; // Return -1 if not stable
}

// Function to toggle the relay state
void toggle_relay(int current_state) {
    int new_state = !current_state;
    if (gpioWrite(RELAY_GPIO, new_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_GPIO);
    }
    return new_state;
}

// Function to log the relay state change
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_time_ms = atoi(optarg);
                if (debounce_time_ms <= 0) {
                    fprintf(stderr, "Invalid debounce time. Using default 50ms.\n");
                    debounce_time_ms = 50;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_time_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // Initial relay state (OFF)
    gpioWrite(RELAY_GPIO, relay_state);
    log_relay_state(relay_state);

    // Main loop
    while (running) {
        int touch_level = read_touch_sensor();
        if (touch_level == 1) {
            relay_state = toggle_relay(relay_state);
            log_relay_state(relay_state);
        }
        gpioDelay(10000); // Check every 10ms
    }

    // Clean up and exit
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    gpioTerminate();
    return 0;
}

