#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90
#define PWM_FREQUENCY 50

static volatile int running = 1;
static struct termios old_term, new_term;

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d). Must be between %d and %d.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Signal handler for SIGINT (Ctrl-C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to restore terminal settings
void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_term);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save current terminal settings
    if (tcgetattr(STDIN_FILENO, &old_term) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Configure terminal for raw input
    new_term = old_term;
    new_term.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_term) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int angle = DEFAULT_ANGLE;
    set_servo_angle(angle);
    printf("Servo angle: %d\n", angle);

    // Main loop
    while (running) {
        int input = getchar();

        if (input == '+') {
            angle += 10;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        } else if (input == '-') {
            angle -= 10;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        } else if (input == 'q') {
            running = 0;
        } else {
            continue; // Ignore other inputs
        }

        if (set_servo_angle(angle) == 0) {
            printf("Servo angle: %d\n", angle);
        }
    }

    // Stop PWM and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();

    // Restore terminal settings
    restore_terminal_settings();

    return 0;
}

