    // Save current terminal settings
    if (tcgetattr(STDIN_FILENO, &old_term) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Configure terminal for raw input
    new_term = old_term;
    new_term.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_term) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int angle = DEFAULT_ANGLE;
    set_servo_angle(angle);
    printf("Servo angle: %d\n", angle);

    // Main loop
    while (running) {
        int input = getchar();

        if (input == '+') {
            angle += 10;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        } else if (input == '-') {
            angle -= 10;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        } else if (input == 'q') {
            running = 0;
        } else {
            continue; // Ignore other inputs
        }

        if (set_servo_angle(angle) == 0) {
            printf("Servo angle: %d\n", angle);
        }
    }

    // Stop PWM and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();

    // Restore terminal settings
    restore_terminal_settings();

    return 0;
}

