#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_NS 2000000 // 2 ms in nanoseconds
#define SAMPLE_INTERVAL_SEC 5

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile unsigned long pulse_count = 0;
static struct timespec last_event_time;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(unsigned long pulse_count) {
    return (double)pulse_count / SAMPLE_INTERVAL_SEC * 60.0;
}

// Function to log RPM data to a file
int log_rpm_data(const char *timestamp, double rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle GPIO events
void handle_gpio_event(struct gpiod_line *line, struct timespec ts) {
    struct timespec time_diff;
    time_diff.tv_sec = ts.tv_sec - last_event_time.tv_sec;
    time_diff.tv_nsec = ts.tv_nsec - last_event_time.tv_nsec;
    if (time_diff.tv_nsec < 0) {
        time_diff.tv_sec--;
        time_diff.tv_nsec += 1000000000;
    }

    if (time_diff.tv_sec == 0 && time_diff.tv_nsec < DEBOUNCE_NS) {
        return; // Debounce
    }

    pulse_count++;
    last_event_time = ts;
}

int main() {
    struct gpiod_line_event event;
    int ret;
    char *timestamp;
    double rpm;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input with pull-up bias
    ret = gpiod_line_request_input_flags(line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Initialize last event time
    clock_gettime(CLOCK_MONOTONIC, &last_event_time);

    // Main loop
    while (keep_running) {
        // Wait for rising edge event
        ret = gpiod_line_event_wait(line, NULL); // Wait indefinitely
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        // Get event time
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Handle the event
        handle_gpio_event(line, ts);
    }

    // Calculate and log RPM data every SAMPLE_INTERVAL_SEC seconds
    while (keep_running) {
        sleep(SAMPLE_INTERVAL_SEC);

        rpm = calculate_rpm(pulse_count);
        timestamp = get_iso8601_timestamp();

        if (timestamp != NULL) {
            if (log_rpm_data(timestamp, rpm) == 0) {
                printf("Timestamp: %s, RPM: %.2f\n", timestamp, rpm);
            } else {
                fprintf(stderr, "Error logging RPM data.\n");
            }
            free(timestamp);
        } else {
            fprintf(stderr, "Failed to get timestamp.\n");
        }

        pulse_count = 0; // Reset pulse count for the next interval
    }

    // Clean up
    printf("Cleaning up...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

