#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define failsafe timeout in seconds
#define FAILSAFE_TIMEOUT 10

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t last_touch_time = 0;
int failsafe_active = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void handle_signal(int signal);
void log_error(const char *message);

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        log_error("Failed to set TOUCH_SENSOR_PIN as input");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set RELAY_PIN as output");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value == PI_BAD_GPIO) {
        log_error("Failed to read TOUCH_SENSOR_PIN");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        log_error("Failed to write to RELAY_PIN");
        return 1;
    }
    return 0;
}

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_value = read_touch_sensor();
        if (touch_value == -1) {
            // Error reading sensor, exit loop
            break;
        }

        if (touch_value == 1) {
            // Touch detected
            time_t current_time = time(NULL);

            if (failsafe_active) {
                // Failsafe active, ignore touch
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                continue;
            }

            if (last_touch_time == 0) {
                // First touch, start timer
                last_touch_time = current_time;
            } else {
                // Check for failsafe timeout
                if (difftime(current_time, last_touch_time) >= FAILSAFE_TIMEOUT) {
                    // Failsafe timeout reached, force relay OFF
                    printf("Failsafe timeout reached! Forcing relay OFF.\n");
                    control_relay(0);
                    relay_state = 0;
                    failsafe_active = 1;
                    last_touch_time = 0; // Reset timer
                    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                    continue;
                }
            }

            // Toggle relay state
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                // Error controlling relay, exit loop
                break;
            }
            printf("Relay toggled to state: %d\n", relay_state);

            // Reset timer
            last_touch_time = current_time;
        } else {
            // No touch detected
            last_touch_time = 0; // Reset timer
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();   // Terminate pigpio

    printf("Program finished.\n");
    return 0;
}

