#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PULSES_PER_LITER 450.0
#define SAMPLING_INTERVAL_MS 100
#define KP 1.0
#define PWM_FREQUENCY 1000 // Hz

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count);
int control_valve(double current_flow_rate, double target_flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * (60000.0 / SAMPLING_INTERVAL_MS);
}

// Function to control the valve using a proportional controller
int control_valve(double current_flow_rate, double target_flow_rate)
{
    double error = target_flow_rate - current_flow_rate;
    int valve_position = (int)(KP * error);

    // Clamp valve position to [0, 255]
    if (valve_position < 0)
    {
        valve_position = 0;
    }
    else if (valve_position > 255)
    {
        valve_position = 255;
    }

    gpioPWM(VALVE_PWM_PIN, valve_position);
    return valve_position;
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, shutting down...\n", signal);

    // Disable valve
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[])
{
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1)
    {
        switch (opt)
        {
        case 't':
            target_flow_rate = atof(optarg);
            if (target_flow_rate <= 0)
            {
                fprintf(stderr, "Error: Target flow rate must be a positive number.\n");
                return 1;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
            return 1;
        }
    }

    if (target_flow_rate == 0.0)
    {
        fprintf(stderr, "Error: Target flow rate is required.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);

    // Enable valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Reset pulse count
        pulse_count = 0;

        // Wait for sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds

