#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
#define TAG_LENGTH 10

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define lock activation time (in seconds)
#define LOCK_ACTIVATION_TIME 5

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag_data);
int is_valid_tag(const unsigned char *tag_data);
int is_button_pressed();
void activate_locks();
void deactivate_locks();
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag data from SPI
int read_rfid_tag(unsigned char *tag_data) {
    int i;
    unsigned char buffer[10];

    // Read 10 bytes from SPI
    for (i = 0; i < 10; i++) {
        buffer[i] = spiReadByte(spi_handle);
    }

    // Check for SPI read errors
    if (buffer[0] == 0xFF) {
        log_event("SPI_ERROR", "SPI read failed.");
        return -1; // Indicate failure
    }

    // Copy the read data to the provided buffer
    memcpy(tag_data, buffer, 10);

    return 0; // Indicate success
}

// Function to validate the RFID tag
int is_valid_tag(const unsigned char *tag_data) {
    return (memcmp(tag_data, valid_tag, TAG_LENGTH) == 0);
}

// Function to check if the button is pressed
int is_button_pressed() {
    static int last_button_state = 1; // Initialize to released state (pull-up)
    static unsigned long last_debounce_time = 0;
    int current_button_state = gpioRead(BUTTON_PIN);
    unsigned long now = gpioTick();

    if (current_button_state != last_button_state) {
        last_debounce_time = now;
    }

    if ((now - last_debounce_time) > (DEBOUNCE_TIME * 1000)) { // Convert ms to us
        if (current_button_state != last_button_state) {
            last_button_state = current_button_state;
            if (current_button_state == 0) { // Button pressed (active-low)
                return 1;
            }
        }
    }

    return 0;
}

// Function to activate the locks
void activate_locks() {
    gpioWrite(LOCK1_PIN, 1); // Engage lock 1
    gpioWrite(LOCK2_PIN, 1); // Engage lock 2
    gpioDelay(LOCK_ACTIVATION_TIME * 1000000); // Wait for activation time (in microseconds)
}

// Function to deactivate the locks
void deactivate_locks() {
    gpioWrite(LOCK1_PIN, 0); // Disengage lock 1
    gpioWrite(LOCK2_PIN, 0); // Disengage lock 2
    gpioDelay(LOCK_ACTIVATION_TIME * 1000000); // Wait for activation time (in microseconds)
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s [%s]: %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Release locks to engaged state
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    unsigned char rfid_tag[TAG_LENGTH];
    int rfid_read_result;
    int button_pressed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read RFID tag
        rfid_read_result = read_rfid_tag(rfid_tag);

        if (rfid_read_result == 0) {
            // Validate RFID tag
            if (is_valid_tag(rfid_tag)) {
                log_event("RFID_SUCCESS", "Valid RFID tag read.");

                // Check for button press
                button_pressed = is_button_pressed();

                if (button_pressed) {
                    log_event("BUTTON_PRESSED", "Button pressed after valid RFID tag.");

                    // Activate locks
                    deactivate_locks();
                    log_event("LOCKS_DEACTIVATED", "Locks deactivated.");

                    // Wait for a short period (e.g., 5 seconds)
                    gpioDelay(5000000); // 5 seconds

                    // Release locks
                    activate_locks();
                    log_event("LOCKS_ACTIVATED", "Locks activated.");
                } else {
                    log_event("BUTTON_NOT_PRESSED", "Button not pressed after valid RFID tag.");
                }
            } else {
                log_event("RFID_INVALID", "Invalid RFID tag read.");
            }
        } else {
            // Log SPI read failure (already done in read_rfid_tag)
        }

        gpioDelay(100000); // Delay 100ms to avoid busy-waiting
    }

    return 0;
}

