#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPM
#define TARGET_RPM 60.0

// PWM Frequency
#define PWM_FREQUENCY 100

// Sample Time (ms)
#define SAMPLE_TIME 100

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
double motor1_speed = 0.0;
double motor2_speed = 0.0;
double motor1_pid_output = 0.0;
double motor2_pid_output = 0.0;
double motor1_p = 0.0;
double motor1_i = 0.0;
double motor1_d = 0.0;
double motor2_p = 0.0;
double motor2_i = 0.0;
double motor2_d = 0.0;
FILE *log_file = NULL;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
int running = 1;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
double calculate_rpm(int encoder_count);
double pid_control(double target_rpm, double current_rpm, double *integral, double *previous_error, double dt);
void set_motor_speed(int motor, double speed);
void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output);
void signal_handler(int signal);

// Encoder 1 ISR
void encoder1_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER1_B);
    if (b_level == 0) {
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count++;
        pthread_mutex_unlock(&encoder1_mutex);
    } else {
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count--;
        pthread_mutex_unlock(&encoder1_mutex);
    }
}

// Encoder 2 ISR
void encoder2_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER2_B);
    if (b_level == 0) {
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count++;
        pthread_mutex_unlock(&encoder2_mutex);
    } else {
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count--;
        pthread_mutex_unlock(&encoder2_mutex);
    }
}

// Encoder Thread 1
void *encoder1_thread(void *arg)
{
    gpioSetISRFuncEx(ENCODER1_A, BOTH_EDGES, 0, encoder1_isr, NULL);
    while (running) {
        gpioDelay(1000); // Check every 1ms
    }
    return NULL;
}

// Encoder Thread 2
void *encoder2_thread(void *arg)
{
    gpioSetISRFuncEx(ENCODER2_A, BOTH_EDGES, 0, encoder2_isr, NULL);
    while (running) {
        gpioDelay(1000); // Check every 1ms
    }
    return NULL;
}

// Calculate RPM
double calculate_rpm(int encoder_count)
{
    // Assuming 600 pulses per revolution
    double revolutions = (double)encoder_count / 600.0;
    double rpm = (revolutions / (SAMPLE_TIME / 1000.0)) * 60.0;
    return rpm;
}

// PID Control
double pid_control(double target_rpm, double current_rpm, double *integral, double *previous_error, double dt)
{
    double error = target_rpm - current_rpm;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Set Motor Speed
void set_motor_speed(int motor, double speed)
{
    int ena_pin, in1_pin, in2_pin;
    if (motor == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    }

    // Limit speed to 0-100
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;

    // Calculate PWM duty cycle (0-1000000)
    int duty_cycle = (int)(speed * 10000.0);

    // Set motor direction and PWM
    if (speed > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, duty_cycle / 10000); // pigpio PWM range is 0-1000
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, 0);
    }
}

// Log Data
void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor2_rpm, motor1_p, motor1_i, motor1_d, motor1_output, motor2_p, motor2_i, motor2_d, motor2_output);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Release GPIO lines
