#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define POLL_INTERVAL_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void relay_control(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x80, 0x63);
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed: %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering
    status = i2cWriteByteData(i2c_handle, 0x5C, 0x10); // MHD_R = 0x10
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 MHD_R config failed: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5D, 0x04); // NHD_R = 0x04
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 NHD_R config failed: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x01); // NCL_R = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 NCL_R config failed: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5F, 0x01); // FDL_R = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 FDL_R config failed: %d\n", status);
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        status = i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30); // Touch threshold
        if (status < 0) {
            fprintf(stderr, "Error: MPR121 touch threshold config failed for electrode %d: %d\n", i, status);
            return -1;
        }
        status = i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10); // Release threshold
        if (status < 0) {
            fprintf(stderr, "Error: MPR121 release threshold config failed for electrode %d: %d\n", i, status);
            return -1;
        }
    }

    // Enable run mode
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x01); // ELEPROX_EN = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 ELEPROX_EN config failed: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x0F); // ELEPROX_EN = 0x0F
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 ELEPROX_EN config failed: %d\n", status);
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error: MPR121 touch status read failed: %d\n", status);
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Relay control function
void relay_control(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log relay state function
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    uint16_t touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                // Activate relay if not already active
                if (relay_state == 0) {
                    relay_control(1);
                    relay_state = 1;
                    log_relay_state(relay_state);
                }
            } else {
                // Deactivate relay if not already inactive
                if (relay_state == 1) {
                    relay_control(0);
                    relay_state = 0;
                    log_relay_state(relay_state);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status\n");
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    relay_control(0); // Ensure relay is off on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

