#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve pause durations (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *valve1_line, *valve2_line;

// Function prototypes
int initialize_gpio(void);
void activate_valve(int gpio_pin, int duration_ms);
void pause_execution(int duration_s);
void log_event(int gpio_pin, int duration_ms);
void cleanup_gpio(void);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting Valve 1 GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting Valve 2 GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        perror("Error requesting Valve 1 GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        perror("Error requesting Valve 2 GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    return 0;
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    struct gpiod_line *line;

    if (gpio_pin == VALVE1_GPIO) {
        line = valve1_line;
    } else if (gpio_pin == VALVE2_GPIO) {
        line = valve2_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin specified: %d\n", gpio_pin);
        return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value to 1");
        return;
    }

    log_event(gpio_pin, duration_ms);

    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value to 0");
        return;
    }
}

// Function to pause execution for a specified duration
void pause_execution(int duration_s) {
    sleep(duration_s);
}

// Function to log valve activation events to a file
void log_event(int gpio_pin, int duration_ms) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fp = fopen("valve_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening valve_log.txt");
        return;
    }

    fprintf(fp, "%s - Valve %d activated for %d ms\n", timestamp, gpio_pin, duration_ms);

    if (fclose(fp) != 0) {
        perror("Error closing valve_log.txt");
    }
}

// Function to release GPIO lines and close the chip
void cleanup_gpio(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Valve control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);
        pause_execution(VALVE1_PAUSE);
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);
        pause_execution(VALVE2_PAUSE);
    }

    return 0;
}

