#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the range for the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the range for the duration of each step (in milliseconds)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the range for the PWM duty cycle
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global volatile flag for graceful shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    shutdown_flag = 1;
    fprintf(stderr, "\nCaught SIGINT, shutting down gracefully...\n");
}

// Function to generate a random integer within a specified range
int generate_random_int(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        motor1_duty_cycles[i] = generate_random_int(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        motor2_duty_cycles[i] = generate_random_int(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        durations[i] = generate_random_int(MIN_DURATION, MAX_DURATION);
    }
    return 0; // Indicate success
}

// Function to play a haptic feedback pattern
int play_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_PIN, motor2_duty_cycles[i]);
        gpioDelay(durations[i] * 1000); // Convert milliseconds to microseconds
    }
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to generate and play haptic feedback patterns
    while (!shutdown_flag) {
        // Generate a random number of steps for the pattern
        int num_steps = generate_random_int(MIN_STEPS, MAX_STEPS);

        // Allocate memory for the pattern data
        int *motor1_duty_cycles = (int *)malloc(num_steps * sizeof(int));
        int *motor2_duty_cycles = (int *)malloc(num_steps * sizeof(int));
        int *durations = (int *)malloc(num_steps * sizeof(int));

        if (motor1_duty_cycles == NULL || motor2_duty_cycles == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            shutdown_flag = 1; // Exit the loop if memory allocation fails
            break;
        }

        // Generate the haptic feedback pattern
        if (generate_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, num_steps) != 0) {
            fprintf(stderr, "Failed to generate pattern\n");
            shutdown_flag = 1;
            break;
        }

        // Play the haptic feedback pattern
        if (play_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, num_steps) != 0) {
            fprintf(stderr, "Failed to play pattern\n");
            shutdown_flag = 1;
            break;
        }

        // Free the allocated memory
        free(motor1_duty_cycles);
        free(motor2_duty_cycles);
        free(durations);
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

