#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000 // 0.5 seconds in microseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Calibration data
static float scale_factor = DEFAULT_SCALE_FACTOR;
static float offset = DEFAULT_OFFSET;

// Function prototypes
int read_hx711();
float calibrate_hx711();
float convert_to_weight(int raw_value);
void control_solenoid(float weight);
void log_weight(float weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;
    long start_time = gpioTick();

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low (start of transmission)
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_time > READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 read timeout\n");
            return -1; // Timeout
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the HX711
float calibrate_hx711() {
    int i;
    long sum = 0;
    int raw_value;

    printf("Calibrating HX711...\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Calibration failed: HX711 read timeout\n");
            return -1.0; // Indicate calibration failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = (float)sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %f\n", offset);
    return offset;
}

// Function to convert raw value to weight
float convert_to_weight(int raw_value) {
    return (float)(raw_value - offset) / scale_factor;
}

// Function to control the solenoid
void control_solenoid(float weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage lock
        printf("Weight above threshold. Lock engaged.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release lock
        printf("Weight below threshold. Lock released.\n");
    }
}

// Function to log weight data
void log_weight(float weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%f %f", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Error reading calibration data. Using defaults.\n");
            scale_factor = DEFAULT_SCALE_FACTOR;
            offset = DEFAULT_OFFSET;
        }
        fclose(fp);
        printf("Calibration data loaded: scale_factor = %f, offset = %f\n", scale_factor, offset);
    } else {
        printf("Calibration file not found. Using defaults.\n");
        scale_factor = DEFAULT_SCALE_FACTOR;
        offset = DEFAULT_OFFSET;
    }
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp != NULL) {
        fprintf(fp, "%f %f", scale_factor, offset);
        fclose(fp);
        printf("Calibration data saved.\n");
    } else {
        fprintf(stderr, "Error saving calibration data.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int raw_value;
    float weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Calibrate HX711
    if (calibrate_hx711() == -1.0) {
        fprintf(stderr, "HX711 calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Save calibration data
    save_calibration_data();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        raw_value = read_hx711();
        if (raw_value != -1) {
            weight = convert_to_weight(raw_value);
            printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);
            control_solenoid(weight);
            log_weight(weight);
        } else {
            fprintf(stderr, "Skipping iteration due to HX711 timeout.\n");
        }
        gpioDelay(500); // 500 ms delay
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Release solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

