#define SOLENOID_ACTIVATION_TIME 5

// Define HX711 timeout (in microseconds)
#define HX711_TIMEOUT 100000 // 100ms

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float calculate_weight(int raw_value);
void activate_solenoid();
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;
    long start_time;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    start_time = gpioTick();
    while (gpioRead(HX711_DT) == 1) {
        if (gpioTick() - start_time > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout waiting for data ready.\n");
            return -1; // Timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay for clock stability
        data = data << 1;
        if (gpioRead(HX711_DT) == 1) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1);
    }

    // Pulse SCK 25th time to set the HX711 for the next reading
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

