float calculate_weight(int raw_value) {
    // This is a placeholder.  You MUST calibrate your HX711.
    // The calibration involves determining the raw value for a known weight.
    // Then, you can use the formula: weight = (raw_value - offset) / scale_factor
    // where offset is the raw value for 0g and scale_factor is the raw value change per gram.
    // Example (replace with your calibration values):
    float offset = 0.0;  // Raw value for 0g
    float scale_factor = 1.0; // Raw value change per gram

