    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ingredient stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read raw value from HX711
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 value.\n");
            log_event("Error: Failed to read HX711 value.");
        } else {
            // Calculate weight
            weight = calculate_weight(raw_value);

            printf("Raw Value: %d, Weight: %.2f g\n", raw_value, weight);

            // Check if weight is below threshold
            if (weight < WEIGHT_THRESHOLD) {
                printf("Weight below threshold. Activating solenoid.\n");
                activate_solenoid();
                log_event("Solenoid activated.");
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

