#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0;

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value);
int control_solenoid(int state);
int log_event(double weight);
int calibrate_load_cell();
int read_calibration_factor();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;
    long start_time = gpioTick();

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Error: HX711 timeout\n");
            return -1; // Timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid lock
int control_solenoid(int state) {
    if (gpioWrite(SOLENOID_PIN, state) != 0) {
        fprintf(stderr, "Error: Failed to write to solenoid pin\n");
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Weight exceeded threshold: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);

    fclose(fp);
    return 0;
}

// Function to calibrate the load cell
int calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input\n");
        return -1;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return -1;
    }

    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);

    printf("Calibration factor: %lf\n", calibration_factor);
    return 0;
}

// Function to read the calibration factor from file
int read_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for reading. Calibrating...\n");
        if (calibrate_load_cell() != 0) {
            fprintf(stderr, "Error: Calibration failed\n");
            return -1;
        }
        return 0; // Calibration successful
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Could not read calibration factor from file. Calibrating...\n");
        fclose(fp);
        if (calibrate_load_cell() != 0) {
            fprintf(stderr, "Error: Calibration failed\n");
            return -1;
        }
        return 0; // Calibration successful
    }

    fclose(fp);
    printf("Calibration factor loaded: %lf\n", calibration_factor);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Read calibration factor
    if (read_calibration_factor() != 0) {
        fprintf(stderr, "Error: Failed to read calibration factor. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value\n");
            continue; // Continue to the next iteration
        }

        double weight = convert_to_kg(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded!\n");
            if (log_event(weight) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
            if (control_solenoid(1) != 0) {
                fprintf(stderr, "Error: Failed to lock solenoid\n");
            }
            gpioDelay(SOLENOID_DURATION * 1000); // Wait for 5 seconds
            if (control_solenoid(0) != 0) {
                fprintf(stderr, "Error: Failed to unlock solenoid\n");
            }
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio

    return 0;
}

