#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *relay_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int toggle_relay(struct gpiod_line *line);
int log_event(const char *timestamp, int relay_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value;
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to toggle the relay state
int toggle_relay(struct gpiod_line *line) {
    int current_value = gpiod_line_get_value(line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading relay value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    int new_value = !current_value; // Toggle the value
    int ret = gpiod_line_set_value(line, new_value);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return new_value;
}

// Function to log the event to a file
int log_event(const char *timestamp, int relay_state) {
    FILE *fp = fopen("relay_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fprintf(fp, "%s, Relay State: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay line %d: %s\n", RELAY_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request sensor line as input
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "ir_sensor";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    input_config.flags = 0;

    if (gpiod_line_request(sensor_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request relay line as output
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "relay_control";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    output_config.flags = 0;

    if (gpiod_line_request(relay_line, &output_config, 0) < 0) {
        fprintf(stderr, "Error requesting relay line as output: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        int sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break; // Exit loop on error
        }

        // Check for obstacle detection (sensor is active low)
        if (sensor_value == 0) {
            // Toggle relay state
            int relay_state = toggle_relay(relay_line);
            if (relay_state < 0) {
                fprintf(stderr, "Error toggling relay, exiting...\n");
                break; // Exit loop on error
            }

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            // Log the event
            if (log_event(timestamp, relay_state) < 0) {
                fprintf(stderr, "Error logging event, exiting...\n");
                break; // Exit loop on error
            }
        }

        // Delay for 100 milliseconds
        struct timespec delay = {0, 100000000}; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup resources before exiting
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

