#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t terminate = 0;
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSignal received, shutting down...\n");
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the line
    char *key = strtok(line, "=");
    char *value_str = strtok(NULL, "=");

    if (key == NULL || value_str == NULL) {
        fprintf(stderr, "Error parsing config file %s: Invalid format\n", filename);
        return -1;
    }

    // Convert the value to an integer
    char *endptr;
    long value = strtol(value_str, &endptr, 10);

    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error parsing config file %s: Invalid value\n", filename);
        return -1;
    }

    if (value < 1 || value > 3600) {
        fprintf(stderr, "Error parsing config file %s: Duration out of range (1-3600)\n", filename);
        return -1;
    }

    *duration = (int)value;
    return 0;
}

// Function to control the solenoid valve
int control_valve(struct gpiod_line *line, int duration) {
    int ret;

    // Turn the valve ON
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(-ret));
        return -1;
    }
    printf("Valve ON for %d seconds\n", duration);

    // Sleep for the specified duration
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < duration && !terminate) {
        sleep(1); // Sleep for 1 second at a time
    }

    // Turn the valve OFF
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(-ret));
        return -1;
    }
    printf("Valve OFF\n");

    return 0;
}

int main() {
    int duration;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration. Exiting.\n");
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Control the valve
    if (control_valve(line, duration) != 0) {
        fprintf(stderr, "Error controlling valve. Exiting.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering cycle complete.\n");

    return 0;
}

