#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_FORWARD 22
#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio);
void set_motor_speed(int left_forward, int left_backward, int right_forward, int right_backward, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to set motor speed
void set_motor_speed(int left_forward, int left_backward, int right_forward, int right_backward, int speed) {
    if (speed > 0) {
        gpioWrite(left_forward, 1);
        gpioWrite(left_backward, 0);
        gpioWrite(right_forward, 1);
        gpioWrite(right_backward, 0);
        gpioPWM(left_forward, speed);
        gpioPWM(right_forward, speed);
    } else if (speed < 0) {
        gpioWrite(left_forward, 0);
        gpioWrite(left_backward, 1);
        gpioWrite(right_forward, 0);
        gpioWrite(right_backward, 1);
        gpioPWM(left_backward, -speed);
        gpioPWM(right_backward, -speed);
    } else {
        stop_motors();
    }
}

// Function to stop motors
void stop_motors() {
    gpioWrite(LEFT_MOTOR_FORWARD, 0);
    gpioWrite(LEFT_MOTOR_BACKWARD, 0);
    gpioWrite(RIGHT_MOTOR_FORWARD, 0);
    gpioWrite(RIGHT_MOTOR_BACKWARD, 0);
    gpioPWM(LEFT_MOTOR_FORWARD, 0);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0);
    gpioPWM(RIGHT_MOTOR_FORWARD, 0);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0);
}

// Function to log data
