#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_POSITION 1000
#define UNLOCK_POSITION 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track servo position
int servo_position = 0; // 0: unlocked, 1: locked

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handlers for buttons
    gpioSetAlertFunc(LOCK_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON_PIN, button_callback);

    return 0; // Indicate success
}

// Lock the door
void lock_door() {
    if (servo_position != 1) {
        gpioServo(SERVO_PIN, LOCK_POSITION);
        servo_position = 1;
        printf("Door locked\n");
    }
}

// Unlock the door
void unlock_door() {
    if (servo_position != 0) {
        gpioServo(SERVO_PIN, UNLOCK_POSITION);
        servo_position = 0;
        printf("Door unlocked\n");
    }
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    // Check if the button is pressed (active low)
    if (level == 0) {
        if (gpio == LOCK_BUTTON_PIN) {
            lock_door();
        } else if (gpio == UNLOCK_BUTTON_PIN) {
            unlock_door();
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running)
    while (1) {
        gpioDelay(100); // Small delay to prevent CPU hogging
    }

    return 0;
}

