#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define pulse durations in milliseconds
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *motor1_line;
struct gpiod_line *motor2_line;

// Function prototypes
int initialize_gpio(void);
void pulse_motor(int pin, int duration_ms);
void run_feedback_loop(void);
void signal_handler(int sig);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for motor 1
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Error getting GPIO line for motor 1");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for motor 2
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Error getting GPIO line for motor 2");
        gpiod_chip_close(chip);
        gpiod_line_release(motor1_line);
        return -1;
    }

    // Request GPIO line for motor 1 as output
    ret = gpiod_line_request_output(motor1_line, "motor1", 0);
    if (ret < 0) {
