#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>
#include <jansson.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUBSCRIBE_ENDPOINT "tcp://localhost:5555"

// Define message topic
#define MESSAGE_TOPIC "SOUND_ALERTS"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *sound_sensor_line = NULL;
struct gpiod_line *alarm_led_line = NULL;

// Global variable for ZeroMQ context and socket
void *zmq_context = NULL;
void *zmq_socket = NULL;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
int init_zmq(void);
void cleanup_zmq(void);
void sound_sensor_mode(void);
void alarm_node_mode(void);
void signal_handler(int sig);
void publish_alert(const char *message);
void subscribe_and_trigger(void);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    cleanup_zmq();
    exit(0);
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sound sensor line
    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor line");
        return -1;
    }

    // Request sound sensor line for input
    ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting sound sensor line for input");
        return -1;
    }

    // Get alarm LED line
    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED line");
        return -1;
    }

    // Request alarm LED line for output
    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Error requesting alarm LED line for output");
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Initialize ZeroMQ
int init_zmq(void) {
    // Create ZeroMQ context
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Error creating ZeroMQ context");
        return -1;
    }

    // Create ZeroMQ socket
    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        perror("Error creating ZeroMQ socket");
        return -1;
    }

    // Bind socket to endpoint
    int ret = zmq_bind(zmq_socket, ZMQ_ENDPOINT);
    if (ret < 0) {
        perror("Error binding ZeroMQ socket");
        return -1;
    }

    return 0;
}

// Cleanup ZeroMQ
void cleanup_zmq(void) {
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
}

// Publish alert message
void publish_alert(const char *message) {
    // Create JSON object
    json_t *root = json_object();
    json_object_set_new(root, "topic", json_string(MESSAGE_TOPIC));
    json_object_set_new(root, "message", json_string(message));

    // Serialize JSON object to string
    char *json_str = json_dumps(root, JSON_REAL_PRECISION(10));
    if (!json_str) {
        fprintf(stderr, "Error creating JSON string\n");
        json_decref(root);
        return;
    }

    // Send message
    int ret = zmq_send(zmq_socket, json_str, strlen(json_str), 0);
    if (ret < 0) {
        perror("Error sending message");
    }

    // Clean up
    json_decref(root);
    free(json_str);
}

// Subscribe to alerts and trigger alarm
void subscribe_and_trigger(void) {
    // Create ZeroMQ socket
    void *sub_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!sub_socket) {
        perror("Error creating ZeroMQ socket");
        return;
    }

    // Connect socket to endpoint
    int ret = zmq_connect(sub_socket, ZMQ_SUBSCRIBE_ENDPOINT);
    if (ret < 0) {
        perror("Error connecting ZeroMQ socket");
        zmq_close(sub_socket);
        return;
    }

    // Subscribe to topic
    ret = zmq_setsockopt(sub_socket, ZMQ_SUBSCRIBE, MESSAGE_TOPIC, strlen(MESSAGE_TOPIC));
    if (ret < 0) {
        perror("Error subscribing to topic");
        zmq_close(sub_socket);
        return;
    }

    // Receive message
    char buffer[256];
    ret = zmq_recv(sub_socket, buffer, sizeof(buffer), 0);
    if (ret < 0) {
        perror("Error receiving message");
        zmq_close(sub_socket);
        return;
    }
    buffer[ret] = '\0';

    // Parse JSON
    json_error_t error;
    json_t *root = json_loads(buffer, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        zmq_close(sub_socket);
        return;
    }

    json_t *topic = json_object_get(root, "topic");
    json_t *message = json_object_get(root, "message");

    if (!json_is_string(topic) || !json_is_string(message)) {
        fprintf(stderr, "Error: topic or message is not a string\n");
        json_decref(root);
        zmq_close(sub_socket);
        return;
    }

    const char *topic_str = json_string_value(topic);
    const char *message_str = json_string_value(message);

    if (strcmp(topic_str, MESSAGE_TOPIC) == 0) {
        printf("Received alert: %s\n", message_str);

        // Trigger alarm
        ret = gpiod_line_set_value(alarm_led_line, 1);
        if (ret < 0) {
            perror("Error setting alarm LED high");
        } else {
            sleep(1);
            ret = gpiod_line_set_value(alarm_led_line, 0);
            if (ret < 0) {
                perror("Error setting alarm LED low");
            }
        }
    }

    // Clean up
    json_decref(root);
    zmq_close(sub_socket);
}

// Sound sensor mode
void sound_sensor_mode(void) {
    struct timespec sleep_time = {0, 10000000}; // 10 ms
    int sound_detected;

    while (1) {
        sound_detected = gpiod_line_get_value(sound_sensor_line);
        if (sound_detected < 0) {
            perror("Error reading sound sensor value");
            break;
        }

        if (sound_detected == 0) {
            // Sound detected
            publish_alert("Sound detected!");
        }

        nanosleep(&sleep_time, NULL);
    }
}

// Alarm node mode
void alarm_node_mode(void) {
    subscribe_and_trigger();
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "Mode: sound_sensor or alarm_node\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (init_zmq() < 0) {
        cleanup_gpio();
        return 1;
    }

    // Run in selected mode
    if (strcmp(argv[1], "sound_sensor") == 0) {
        sound_sensor_mode();
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_mode();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        cleanup_gpio();
        cleanup_zmq();
        return 1;
    }

    // Clean up (should not reach here in normal operation)
    cleanup_gpio();
    cleanup_zmq();

    return 0;
}

