// Configuration
#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100
#define MAX_PULSE_WIDTH 20000 // microseconds

// NEC Protocol Timing (microseconds)
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 200 // Tolerance for timing variations

// Global Variables
static volatile int pulse_index = 0;
static volatile uint32_t pulse_widths[PULSE_BUFFER_SIZE];
static volatile int decoding = 0;
static volatile uint32_t last_tick = 0;
static MQTTClient client;
static int running = 1;

// Function Prototypes
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulse_widths, int pulse_count, uint8_t *address, uint8_t *command);
int validate_checksum(uint8_t address, uint8_t command, uint8_t checksum);
int publish_mqtt(uint8_t address, uint8_t command);
void signal_handler(int signal);
int mqtt_connect();
void mqtt_disconnect();

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// IR receiver callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    uint32_t pulse_width;

    if (level == 0) { // Falling edge
        pulse_width = tick - last_tick;
        last_tick = tick;

        if (pulse_index < PULSE_BUFFER_SIZE) {
            pulse_widths[pulse_index++] = pulse_width;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_index = 0; // Reset buffer
        }
    }
}

// NEC decoding function
int decode_nec(uint32_t *pulse_widths, int pulse_count, uint8_t *address, uint8_t *command) {
    if (pulse_count < 68) { // NEC frames have at least 68 pulses (32 bits + header)
        syslog(LOG_WARNING, "Not enough pulses for NEC decoding: %d", pulse_count);
        return -1;
    }

    // Check for valid header
    if (pulse_widths[0] < NEC_HDR_MARK - NEC_TOLERANCE || pulse_widths[0] > NEC_HDR_MARK + NEC_TOLERANCE ||
        pulse_widths[1] < NEC_HDR_SPACE - NEC_TOLERANCE || pulse_widths[1] > NEC_HDR_SPACE + NEC_TOLERANCE) {
        syslog(LOG_WARNING, "Invalid NEC header");
        return -1;
    }

    uint32_t data = 0;
    for (int i = 2; i < pulse_count; i += 2) {
        if (i + 1 >= pulse_count) break; // Ensure we don't go out of bounds

        if (pulse_widths[i] < NEC_BIT_MARK - NEC_TOLERANCE || pulse_widths[i] > NEC_BIT_MARK + NEC_TOLERANCE) {
            syslog(LOG_WARNING, "Invalid bit mark at pulse %d", i);
            return -1;
        }

        if (pulse_widths[i + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && pulse_widths[i + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            data = (data << 1) | 1;
        } else if (pulse_widths[i + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && pulse_widths[i + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            data = (data << 1) | 0;
        } else {
            syslog(LOG_WARNING, "Invalid bit space at pulse %d", i + 1);
            return -1;
        }
    }

    *address = (uint8_t)(data >> 24);
    *command = (uint8_t)(data >> 16);

    return 0;
}

// Checksum validation function
int validate_checksum(uint8_t address, uint8_t command, uint8_t checksum) {
    uint8_t calculated_checksum = address ^ command;
    return (calculated_checksum == checksum);
}

// MQTT connection function
int mqtt_connect() {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
        return -1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker");
    return 0;
}

// MQTT disconnection function
void mqtt_disconnect() {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    syslog(LOG_INFO, "Disconnected from MQTT broker");
}

// MQTT publish function
int publish_mqtt(uint8_t address, uint8_t command) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[50];
    int rc;

    snprintf(payload, sizeof(payload), "{\"address\": %d, \"command\": %d}", address, command);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message, return code %d", rc);
        return -1;
    }

    syslog(LOG_INFO, "Published message: %s", payload);
    return 0;
}

int main() {
    int rc;
    uint8_t address, command;

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode and pull-up resistor
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    // Register callback function
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

