    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    while (running) {
        if (pulse_index > 30) { // Check if enough pulses have been received
            if (!decoding) {
                decoding = 1;
                if (decode_nec(pulse_widths, pulse_index, &address, &command) == 0) {
                    // Validate checksum (using address and command for simplicity)
                    if (validate_checksum(address, command, (uint8_t)(address ^ command))) {
                        syslog(LOG_INFO, "Decoded address: 0x%02X, command: 0x%02X", address, command);
                        publish_mqtt(address, command);
                    } else {
                        syslog(LOG_WARNING, "Checksum validation failed");
                    }
                } else {
                    syslog(LOG_WARNING, "NEC decoding failed");
                }
                decoding = 0;
                pulse_index = 0; // Reset pulse index after processing
            }
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    mqtt_disconnect();
    gpioTerminate();
    closelog();

    return 0;
}

