#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define SENSOR_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define MULTICAST_ADDRESS "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define CONVERSION_FACTOR 1.2
#define SLEEP_SECONDS 1

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fds[NUM_SENSORS];

// Function prototypes
int init_i2c(int address);
float read_bh1750(int fd);
char* format_data(float lux_values[NUM_SENSORS]);
int send_udp_packet(const char* data);
void signal_handler(int signum);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

// Initialize I2C bus
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from BH1750 sensor
float read_bh1750(int fd) {
    unsigned char data[2];
    int ret;

    // Send measurement command
    ret = write(fd, &BH1750_ONE_TIME_HIGH_RES_MODE, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    usleep(180000); // 180ms

    // Read 2 bytes of data
    ret = read(fd, data, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return NAN;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / CONVERSION_FACTOR;
}

// Format data into a string
char* format_data(float lux_values[NUM_SENSORS]) {
    static char buffer[256]; // Static buffer to avoid memory allocation issues
    char temp[32];
    int i;

    buffer[0] = '\0'; // Initialize the buffer

    for (i = 0; i < NUM_SENSORS; i++) {
        if (isnan(lux_values[i])) {
            snprintf(temp, sizeof(temp), "%d,NaN", i + 1);
        } else {
            snprintf(temp, sizeof(temp), "%d,%.1f", i + 1, lux_values[i]);
        }
        strcat(buffer, temp);
        if (i < NUM_SENSORS - 1) {
            strcat(buffer, ";");
        }
    }

    return buffer;
}

// Send UDP multicast packet
int send_udp_packet(const char* data) {
    int sockfd;
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Configure multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDRESS);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr*)&addr, addrlen) < 0) {
        perror("Error sending data");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Cleanup resources
void cleanup() {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] > 0) {
            close(i2c_fds[i]);
        }
    }
}

int main() {
    float lux_values[NUM_SENSORS];
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C buses
    int sensor_addresses[] = SENSOR_ADDRESSES;
    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize I2C for sensor %d\n", i + 1);
            program_running = 0; // Stop the program if initialization fails
        }
    }

    // Main loop
    while (program_running) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] > 0) {
                lux_values[i] = read_bh1750(i2c_fds[i]);
                if (isnan(lux_values[i])) {
                    fprintf(stderr, "Error reading sensor %d\n", i + 1);
                }
            } else {
                lux_values[i] = NAN; // Mark as NaN if I2C initialization failed
            }
        }

        char* data = format_data(lux_values);
        if (send_udp_packet(data) != 0) {
            fprintf(stderr, "Error sending UDP packet\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    cleanup();

    return 0;
}

