#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define AWM7300V_ADDR 0x28
#define FLOW_SCALE_FACTOR 0.1
#define FLOW_OFFSET 3277
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

// Function to read airflow data from the sensor
int read_airflow(int fd) {
    unsigned char buffer[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send zero-length write to initiate read
        if (write(fd, "", 0) != 0) {
            perror("I2C write (initiate read) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Read 2 bytes from the sensor
        bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            // Combine the two bytes into a 14-bit value
            int raw_value = ((buffer[0] << 8) | buffer[1]) & 0x3FFF;
            return raw_value;
        } else {
            perror("I2C read failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read airflow after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert raw value to SLPM
float convert_to_slpm(int raw_value) {
    return (raw_value - FLOW_OFFSET) * FLOW_SCALE_FACTOR;
}

// Function to log the flow rate to a file
void log_flow_rate(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Flow Rate: %.2f SLPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int raw_value = read_airflow(i2c_fd);
        if (raw_value != -1) {
            float flow_rate = convert_to_slpm(raw_value);
            log_flow_rate(log_file, flow_rate);
        } else {
            fprintf(stderr, "Failed to read airflow, skipping logging.\n");
        }

        sleep(1); // Sample once per second
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

