#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_ATIME 0x81
#define AS7341_CFG0 0x70
#define AS7341_F1DATAH 0x60
#define AS7341_F8DATAL 0x73
#define AS7341_STATUS 0x73

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
} sensor_data_t;

// Function prototypes
int init_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_lux(sensor_data_t data);
int log_data(sensor_data_t data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the AS7341 sensor
int init_sensor() {
    int status;
    uint8_t who_am_i;

    // Check WHO_AM_I register
    status = i2cReadByteData(i2c_handle, AS7341_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    who_am_i = (uint8_t)status;
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x19\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed.\n");

    // Power on the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); //PON = 1, AEN = 1
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait for power-on (10ms)

    // Configure SMUX for spectral readings
    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %d\n", status);
        return -1;
    }

    // Enable spectral measurement
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); //PON = 1, AEN = 1, SP_EN = 1
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Set integration time (ATIME)
    status = i2cWriteByteData(i2c_handle, AS7341_ATIME, 0x64); // 100ms integration time
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set gain (CFG0)
    status = i2cWriteByteData(i2c_handle, AS7341_CFG0, 0x00); // Default gain
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG0 register: %d\n", status);
        return -1;
    }

    printf("Sensor initialization complete.\n");
    return 0;
}

// Read spectral data from the sensor
int read_sensor_data(sensor_data_t *data) {
    int status;
    uint8_t buffer[20];

    // Read all spectral data in one go
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 20);
    if (status < 0) {
        fprintf(stderr, "Error reading spectral data: %d\n", status);
        return -1;
    }

    // Extract data from buffer
    data->f1 = (buffer[1] << 8) | buffer[0];
    data->f2 = (buffer[3] << 8) | buffer[2];
    data->f3 = (buffer[5] << 8) | buffer[4];
    data->f4 = (buffer[7] << 8) | buffer[6];
    data->f5 = (buffer[9] << 8) | buffer[8];
    data->f6 = (buffer[11] << 8) | buffer[10];
    data->f7 = (buffer[13] << 8) | buffer[12];
    data->f8 = (buffer[15] << 8) | buffer[14];
    data->clear = (buffer[17] << 8) | buffer[16];
    data->nir = (buffer[19] << 8) | buffer[18];

    return 0;
}

// Calculate a simplified lux approximation
float calculate_lux(sensor_data_t data) {
    // This is a very basic approximation and should be replaced with a proper lux calculation
    // based on the AS7341 datasheet and calibration data.
    float lux = (float)(data.f1 + data.f2 + data.f3 + data.f4 + data.f5 + data.f6 + data.f7 + data.f8) / 8.0;
    return lux;
}

// Log data to CSV file
int log_data(sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8, data.clear, data.nir, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    sensor_data_t sensor_data;
    float lux;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate lux
            lux = calculate_lux(sensor_data);

            // Log data
            log_data(sensor_data, lux);

            printf("F1: %u, F2: %u, F3: %u, F4: %u, F5: %u, F6: %u, F7: %u, F8: %u, Clear: %u, NIR: %u, Lux: %.2f\n",
                   sensor_data.f1, sensor_data.f2, sensor_data.f3, sensor_data.f4, sensor_data.f5, sensor_data.f6, sensor_data.f7, sensor_data.f8, sensor_data.clear, sensor_data.nir, lux);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

