#define ACCEL_REGISTER 0x28
#define NUM_BYTES 6
#define SCALE_FACTOR 0.000244

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int i2c_address = DEFAULT_I2C_ADDR;
int interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(sensor_data_t *data);
void convert_to_g(sensor_data_t *data, float *x_g, float *y_g, float *z_g);
int log_data(float x_g, float y_g, float z_g);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[NUM_BYTES];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_REGISTER, buffer, NUM_BYTES);
        if (bytes_read == NUM_BYTES) {
            data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data->z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C read failed: %d retries remaining", retries);
            log_error(error_message);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    return -1; // Failure after retries
}

// Function to convert raw data to g
void convert_to_g(sensor_data_t *data, float *x_g, float *y_g, float *z_g) {
    *x_g = data->x * SCALE_FACTOR;
    *y_g = data->y * SCALE_FACTOR;
    *z_g = data->z * SCALE_FACTOR;
}

