    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

