#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    unsigned char init_cmd = 0x01; // Power on
    unsigned char mode_cmd = CONTINUOUS_HIGH_RES_MODE;

    if (write(fd, &init_cmd, 1) != 1) {
        perror("Failed to send power-on command");
        return -1;
    }
    usleep(10000); // Wait 10ms

    if (write(fd, &mode_cmd, 1) != 1) {
        perror("Failed to send continuous high-resolution mode command");
        return -1;
    }
    usleep(10000); // Wait 10ms

    return 0;
}

// Function to read light intensity from the BH1750 sensor
int read_light_intensity(int fd, unsigned short *raw_value) {
    unsigned char buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read light intensity");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    int ttl = TTL;
    char buffer[32];

    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL) failed");
        return -1;
    }

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto() failed");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Retrying in 1 second.\n");
        close(i2c_fd);
        sleep(1);
        i2c_fd = open(I2C_DEVICE, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            return 1;
        }
        if (init_bh1750(i2c_fd) < 0) {
            fprintf(stderr, "Failed to initialize BH1750 sensor after retry.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short raw_value;
        float lux_value;

        // Read light intensity
        if (read_light_intensity(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Failed to read light intensity. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_value);

        // Send over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    close(i2c_fd);
    close(udp_socket);

    return 0;
}

