#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256
#define TIMEOUT_SEC 2

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;    // Read at least 0 characters
    tty.c_cc[VTIME] = 5;   // 0.5 seconds timeout (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main() {
    char buffer[BUFFER_SIZE];
    int buffer_index = 0;
    fd_set readfds;
    struct timeval timeout;
    int retval;
    char *line;
    char timestamp_str[32];
    struct tm *tm_info;
    time_t timestamp;
    float range;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("open");
        return 1;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return 1;
    }

    printf("UART configured successfully. Reading data...\n");

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = 0;

        retval = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("select");
            break;
        } else if (retval) {
            // Data is available
            ssize_t bytes_read = read(uart_fd, buffer + buffer_index, BUFFER_SIZE - buffer_index - 1);
            if (bytes_read == -1) {
                perror("read");
                break;
            } else if (bytes_read == 0) {
                fprintf(stderr, "UART closed.\n");
                break;
            }

            buffer_index += bytes_read;
            buffer[buffer_index] = '\0';

            // Process the buffer
            char *token = strtok(buffer, "\n");
            while (token != NULL) {
                // Attempt to parse the line
                char *comma = strchr(token, ',');
                if (comma != NULL) {
                    *comma = '\0'; // Null-terminate the timestamp part
                    char *range_str = comma + 1; // Point to the range part

                    timestamp = strtoul(token, NULL, 10);
                    range = strtof(range_str, NULL);

                    if (errno == ERANGE) {
                        fprintf(stderr, "Error: Invalid timestamp or range value.\n");
                    } else {
                        // Format the timestamp
                        tm_info = localtime(&timestamp);
                        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

                        // Print the formatted output
                        printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
                    }
                } else {
                    fprintf(stderr, "Error: Invalid data format (missing comma).\n");
                }

                token = strtok(NULL, "\n");
            }

            // Remove processed data from the buffer
            memmove(buffer, buffer + strlen(buffer) + 1, buffer_index - strlen(buffer));
            buffer_index = strlen(buffer);
        } else {
            // Timeout occurred
            //printf("Timeout waiting for data.\n");
        }
    }

    close(uart_fd);
    printf("UART closed. Exiting.\n");
    return 0;
}

