#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int serial_fd = -1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
int send_emergency_stop();
void signal_handler(int signal);
int setup_serial_port();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Setup serial port
    if (setup_serial_port() != 0) {
        fprintf(stderr, "Failed to setup serial port. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_values;
        sensor_values.left = read_sensor(LEFT_SENSOR);
        sensor_values.middle = read_sensor(MIDDLE_SENSOR);
        sensor_values.right = read_sensor(RIGHT_SENSOR);

        // Log sensor data
        log_sensor_data(sensor_values.left, sensor_values.middle, sensor_values.right);

        // Check for emergency stop condition
        if (sensor_values.left == 0 && sensor_values.middle == 0 && sensor_values.right == 0) {
            send_emergency_stop();
        }

        // Delay for 100ms (10Hz loop rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    return 0;
}

// Read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Send emergency stop message via serial port
int send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));

    if (bytes_written < 0) {
        perror("Error writing to serial port");
        return 1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup serial port
int setup_serial_port() {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return 1;
    }

    struct termios options;
    tcgetattr(serial_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    tcsetattr(serial_fd, TCSANOW, &options);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    gpioTerminate();
}
